		public void TestJE_ApplicationCode_ReadOnly()
		{
			var customsInterface = new LocalCountryCustomsInterface();
			customsInterface.RecipientID = "RecipientID";
			customsInterface.SubmissionType = DeclarationApplicationCodeList.Codes.Builtin;
			using (CustomsDataRegistry.Instance.LocalCountryCustomsInterface.SetTemporaryValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, customsInterface))
			{
				var declaration = Factory.New<JobDeclaration>();
				declaration.JE_MessageType = JobMessageTypeList.Codes.Export;
				AssertEquals("EXP - BLT - JE_ApplicationCode", DeclarationApplicationCodeList.Codes.Builtin, declaration.JE_ApplicationCode);
				AssertEquals("EXP - BLT - JE_ApplicationCodeInfo.ReadOnly", true, declaration.JE_ApplicationCodeInfo.ReadOnly);
				AssertEquals("EXP - BLT - ApplicationCodeList", "BLT, ITF", declaration.Lookups.ApplicationCodeList.CodesAsString);

				declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
				AssertEquals("IMP - BLT - JE_ApplicationCode", JobApplicationCodeList.Codes.ACE, declaration.JE_ApplicationCode);
				AssertEquals("IMP - BLT - JE_ApplicationCodeInfo.ReadOnly", false, declaration.JE_ApplicationCodeInfo.ReadOnly);
				AssertEquals("IMP - BLT - ApplicationCodeList", "ACE, ACS", declaration.Lookups.ApplicationCodeList.CodesAsString);
			}
			customsInterface.SubmissionType = DeclarationApplicationCodeList.Codes.Interfaced;
			using (CustomsDataRegistry.Instance.LocalCountryCustomsInterface.SetTemporaryValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, customsInterface))
			{
				var declaration = Factory.New<JobDeclaration>();
				declaration.JE_MessageType = JobMessageTypeList.Codes.Export;
				AssertEquals("EXP - ITF - JE_ApplicationCode", DeclarationApplicationCodeList.Codes.Interfaced, declaration.JE_ApplicationCode);
				AssertEquals("EXP - ITF - JE_ApplicationCodeInfo.ReadOnly", true, declaration.JE_ApplicationCodeInfo.ReadOnly);
				AssertEquals("EXP - ITF - ApplicationCodeList", "BLT, ITF", declaration.Lookups.ApplicationCodeList.CodesAsString);

				declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
				AssertEquals("IMP - ITF - JE_ApplicationCode", DeclarationApplicationCodeList.Codes.Interfaced, declaration.JE_ApplicationCode);
				AssertEquals("IMP - ITF - JE_ApplicationCodeInfo.ReadOnly", true, declaration.JE_ApplicationCodeInfo.ReadOnly);
				AssertEquals("IMP - ITF - ApplicationCodeList", "ACE, ACS, ITF", declaration.Lookups.ApplicationCodeList.CodesAsString);
			}
		}

