			Factory.Save();
			var usDeclaration = declaration.USDeclaration;
			AssertEquals(declaration.PK, usDeclaration.USD_JE);
			AssertEquals(true, usDeclaration.IsInDatabase);
			AssertEquals(1, usDeclaration.USD_ClusterKey);
			var newFactory = new BusinessObjectFactory();
			declaration = newFactory.Load<JobDeclaration>(declaration.PK);
			usDeclaration = declaration.USDeclaration;
			AssertEquals(declaration.PK, usDeclaration.USD_JE);
