		public void TestDoNotCopyJE_GS_NKCusAgentWhenRegistryIsTrue()
		{
			var company = Factory.New<GlbCompany>();
			company.GC_Code = "USB";
			company.GC_RN_NKCountryCode = "US";

			var branch = company.Branches.AddNew();
			branch.GB_BranchName = "USB";
			branch.GB_GC = company.PK;

			var staffAA = Factory.New<GlbStaff>();
			staffAA.GS_Code = "TAA";
			staffAA.GS_EmailAddress = "TestAA@mail.com";
			staffAA.GS_WorkPhone = "5566337";
			staffAA.GS_IsSystemAccount = false;
			staffAA.GS_LoginName = "TAA";
			staffAA.GS_GB_HomeBranch = branch.PK;

			var staffBB = Factory.New<GlbStaff>();
			staffBB.GS_Code = "TBB";
			staffBB.GS_EmailAddress = "TestBB@mail.com";
			staffBB.GS_WorkPhone = "7788990";
			staffBB.GS_IsSystemAccount = false;
			staffBB.GS_LoginName = "TBB";
			Factory.Save();

			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACE;
			declaration.US_CargoReleaseType = CargoReleaseTypeList.Codes.ACE;
			declaration.US_EntryFilerCode = "XJ5";
			declaration.US_EnableENS = true;
			declaration.JE_GS_NKCusAgent = ZString.Empty;
			var invoice = declaration.Invoices.AddNew();
			invoice.JZ_InvoiceNumber = "INV8";
			var invoiceLine = invoice.JobComInvoiceLines.AddNew();
			invoiceLine.JI_Description = "ILN8";

			using (Env.SetTemporaryUserContext(staffBB.GS_LoginName, Env.CurrentBranch.PK, Env.CurrentDepartment.PK))
			{
				using (USCustomsDataRegistry.Instance.EntryDeclarant.SetTemporaryValue(Guid.Empty, GlbBranch.CurrentBranch.PK.ToGuid(), Guid.Empty, true))
				{
					Factory.Save();
					var clonedDec = (JobDeclaration)declaration.TemplateCopy();
					AssertEquals("Should not default Broker field", ZString.Empty, clonedDec.JE_GS_NKCusAgent);

					clonedDec = (JobDeclaration)declaration.Clone();
					AssertEquals("Should not default Broker field", ZString.Empty, clonedDec.JE_GS_NKCusAgent);
					clonedDec.JE_DeclarationReference = Guid.NewGuid().ToString("N");
				}

				using (USCustomsDataRegistry.Instance.EntryDeclarant.SetTemporaryValue(Guid.Empty, GlbBranch.CurrentBranch.PK.ToGuid(), Guid.Empty, false))
				{
					Factory.Save();

					var clonedDec = (JobDeclaration)declaration.TemplateCopy();
					AssertEquals("Current Login User TBB is on Broker field", staffBB.GS_Code, clonedDec.JE_GS_NKCusAgent);

					clonedDec = (JobDeclaration)declaration.Clone();
					AssertEquals("Broker field is empty when default message type is Export", ZString.Empty, clonedDec.JE_GS_NKCusAgent);

					clonedDec.JE_MessageType = JobMessageTypeList.Codes.Import;
					clonedDec.JE_DeclarationReference = Guid.NewGuid().ToString("N");
					Factory.Save();
					AssertEquals("Current Login User TBB is on Broker field", staffBB.GS_Code, clonedDec.JE_GS_NKCusAgent);
				}
			}
		}

		public override void TestSetDefaultCusAgentOnSaving()
		{
			var saveCurrentUserCode = GlbStaff.CurrentUser.GS_Code;
			var rememberSystemAccount = GlbStaff.CurrentUser.GS_IsSystemAccount;
			try
			{
				GlbStaff.CurrentUser.GS_Code = "XZX";
				GlbStaff.CurrentUser.GS_IsSystemAccount = false;
				using (USCustomsDataRegistry.Instance.EntryDeclarant.SetTemporaryValue(Guid.Empty, GlbBranch.CurrentBranch.PK.ToGuid(), Guid.Empty, false))
				{
					var declaration = Factory.New<JobDeclaration>();
					declaration.JE_GS_NKCusAgent = "";
					Factory.Save();
					AssertEquals("default JE_GS_NKCusAgent on first saving", "XZX", declaration.JE_GS_NKCusAgent);

					declaration = Factory.New<JobDeclaration>();
					declaration.JE_GS_NKCusAgent = "AAA";
					Factory.Save();
					AssertEquals("no default JE_GS_NKCusAgent on first saving if not empty", "AAA", declaration.JE_GS_NKCusAgent);
				}

				using (USCustomsDataRegistry.Instance.EntryDeclarant.SetTemporaryValue(Guid.Empty, GlbBranch.CurrentBranch.PK.ToGuid(), Guid.Empty, true))
				{
					var declaration = Factory.New<JobDeclaration>();
					declaration.JE_GS_NKCusAgent = "AAA";
					Factory.Save();
					AssertEquals("do not default JE_GS_NKCusAgent after first saving ", "AAA", declaration.JE_GS_NKCusAgent);

					declaration = Factory.New<JobDeclaration>();
					declaration.JE_GS_NKCusAgent = "";
					Factory.Save();
					AssertEquals("do not default JE_GS_NKCusAgent after first saving ", "", declaration.JE_GS_NKCusAgent);
				}
			}
			finally
			{
				GlbStaff.CurrentUser.GS_Code = saveCurrentUserCode;
				GlbStaff.CurrentUser.GS_IsSystemAccount = rememberSystemAccount;
			}
		}

