			var invoice = declaration.Invoices.AddNew();
			invoice.JobComInvoiceLines.AddNew();
			AssertEquals(string.Empty, declaration.ResetDutyCalculationDate());
			AssertNull(declaration.Logs.MostRecentLogByEventTime(Events.ResetEntryMessageItemFunction));
			declaration.DoMerge();
			var ensEntry = declaration.ActiveEntryHeaders.EntrySummaryEntry;
			AssertEquals("Duty Calculation Date has been changed from () to (13-OCT-18).", declaration.ResetDutyCalculationDate());
			var rstLog1 = declaration.Logs.MostRecentLogByEventTime(Events.ResetEntryMessageItemFunction);
			AssertEquals("DUTY CALC DATE CHANGED  TO 13-OCT-18", rstLog1.SL_Reference);

			AssertEquals("No change to Duty Calculation Date (13-OCT-18) has been found.", declaration.ResetDutyCalculationDate());
			AssertEquals(rstLog1, declaration.Logs.MostRecentLogByEventTime(Events.ResetEntryMessageItemFunction));

			declaration.US_EstimatedEntryDate = new ZDateTime(2018, 10, 15);
			AssertEquals("Duty Calculation Date has been changed from (13-OCT-18) to (15-OCT-18).", declaration.ResetDutyCalculationDate());
			var rstLog2 = declaration.Logs.MostRecentLogByEventTime(Events.ResetEntryMessageItemFunction, new ZQuery(StmALogSchema.PK, SQLComparisonOperator.NotEqual, rstLog1.PK));
			AssertEquals("DUTY CALC DATE CHANGED 13-OCT-18 TO 15-OCT-18", rstLog2.SL_Reference);
		}

