		public void TestBrokerCodeFilledOnMisc()
		{
			var company = Factory.New<GlbCompany>();
			company.GC_RN_NKCountryCode = "US";

			var branch = company.Branches.AddNew();

			var supplier = Factory.NewWithValidTestData<OrgHeader>();
			supplier.OH_Code = "OrgImp";
			supplier.OH_FullName = "Org Importer";

			var staffAA = Factory.New<GlbStaff>();
			staffAA.GS_Code = "TAA";
			staffAA.GS_EmailAddress = "TestAA@mail.com";
			staffAA.GS_WorkPhone = "5566337";
			staffAA.GS_LoginName = "TAA";

			var staffBB = Factory.New<GlbStaff>();
			staffBB.GS_Code = "TBB";
			staffBB.GS_EmailAddress = "TestBB@mail.com";
			staffBB.GS_WorkPhone = "7788990";
			staffBB.GS_LoginName = "TBB";

			var serviceTaskUser = Factory.LoadFromNaturalKey<GlbStaff>(GlbStaffSchema.GS_Code, User.ServiceUserCode);

			Factory.Save();

			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_OH_Importer = supplier.PK;
			declaration.JE_GB = branch.PK;
			declaration.JE_CustomsOffice = "Office";
			declaration.JE_GS_NKCusAgent = staffAA.GS_Code;

			using (USCustomsDataRegistry.Instance.EntryDeclarant.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			{
				using (Env.SetTemporaryUserContext(staffBB.GS_LoginName, Env.CurrentBranch.PK, Env.CurrentDepartment.PK))
				{
					declaration.LogCustomsCommencedIfNeeded();
					AssertEquals("Do not update With Current User if overridden value is true.", staffAA.GS_Code, declaration.JE_GS_NKCusAgent);
				}

				using (Env.SetTemporaryUserContext(serviceTaskUser.PK.ToGuid(), Env.CurrentBranch.PK, Env.CurrentDepartment.PK))
				{
					declaration.JE_GS_NKCusAgent = staffAA.GS_Code;
					declaration.LogCustomsCommencedIfNeeded();
					AssertEquals("Do not update if current user is the service user.", staffAA.GS_Code, declaration.JE_GS_NKCusAgent);
				}
			}

			using (USCustomsDataRegistry.Instance.EntryDeclarant.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, false))
			{
				using (Env.SetTemporaryUserContext(staffBB.GS_LoginName, Env.CurrentBranch.PK, Env.CurrentDepartment.PK))
				{
					declaration.LogCustomsCommencedIfNeeded();
					AssertEquals("Update With Current User.", staffBB.GS_Code, declaration.JE_GS_NKCusAgent);
				}

				using (Env.SetTemporaryUserContext(serviceTaskUser.PK.ToGuid(), Env.CurrentBranch.PK, Env.CurrentDepartment.PK))
				{
					declaration.JE_GS_NKCusAgent = staffAA.GS_Code;
					declaration.LogCustomsCommencedIfNeeded();
					AssertEquals("Do Not update if current user is the service user.", staffAA.GS_Code, declaration.JE_GS_NKCusAgent);
				}
			}
		}

