		public void TestIsDeactivatedContextMenuForExport()
		{
			var declaration1 = Factory.New<JobDeclaration>();
			declaration1.JE_MessageType = JobMessageTypeList.Codes.Export;
			declaration1.ShowDeactivatedEntries = false;

			EntryHeaderWithDeactivatedCollection collection = declaration1.EntryHeadersWithOptionalDeactivated;
			AssertEquals(0, collection.Count);
			var entry1 = declaration1.CustomsEntryHeaders.AddNew();
			entry1.CH_MessageType = CusEntryHeaderMessageTypeList.Codes.Export;
			AssertEquals(1, collection.Count);
			AssertEquals(entry1, collection[0]);

			var entry2 = declaration1.CustomsEntryHeaders.AddNew();
			entry2.CH_MessageType = CusEntryHeaderMessageTypeList.Codes.Export;
			AssertEquals(2, collection.Count);
			AssertCollectionContains(entry1, collection);
			AssertCollectionContains(entry2, collection);

			var entry3 = declaration1.CustomsEntryHeaders.AddNew();
			entry3.CH_MessageType = CusEntryHeaderMessageTypeList.Codes.Export;
			AssertEquals(3, collection.Count);
			AssertCollectionContains(entry1, collection);
			AssertCollectionContains(entry2, collection);
			AssertCollectionContains(entry3, collection);

			entry2.CH_Status = AESDirectCustomsEntryStatus.Codes.OriginalSEDClear;
			entry2.US_IsDeactivated = true;
			AssertEquals(2, collection.Count);
			AssertCollectionContains(entry1, collection);
			AssertCollectionContains(entry3, collection);

			declaration1.ShowDeactivatedEntries = true;
			AssertEquals(3, collection.Count);
			AssertCollectionContains(entry1, collection);
			AssertCollectionContains(entry2, collection);
			AssertCollectionContains(entry3, collection);
		}

		public void TestDefaultConsigneeAndShipToFromImporter()
		{
			var deliverTo = Factory.NewWithValidTestData<OrgHeader>();
			deliverTo.MainAddress.OA_RN_NKCountryCode = Core.Constants.CountryCodes.UnitedStates;
			deliverTo.OH_FullName = "FULLNAME";
			var deliverToAddress = deliverTo.Addresses.AddNew();
			deliverToAddress.OA_Address1 = "TEST ADDRESS FULL NAME";

			var consigneeOrg = Factory.NewWithValidTestData<OrgHeader>();
			consigneeOrg.MainAddress.OA_RN_NKCountryCode = Core.Constants.CountryCodes.UnitedStates;
			consigneeOrg.OH_FullName = "ORGONE 1";
			var consigneeAddress = consigneeOrg.Addresses.AddNew();
			consigneeAddress.OA_Address1 = "TEST ADDRESS 1";

			var usImporterOrg = Factory.NewWithValidTestData<OrgHeader>();
			usImporterOrg.MainAddress.OA_RN_NKCountryCode = Core.Constants.CountryCodes.UnitedStates;
			usImporterOrg.OH_FullName = "US IMPORTER 1";
			usImporterOrg.MainAddress.OA_Address1 = "TEST US ADDRESS IMPORTER 1";

			var caImporterOrg = Factory.NewWithValidTestData<OrgHeader>();
			caImporterOrg.MainAddress.OA_RN_NKCountryCode = Core.Constants.CountryCodes.Canada;
			caImporterOrg.OH_FullName = "CA IMPORTER 1";
			caImporterOrg.MainAddress.OA_Address1 = "TEST CA ADDRESS IMPORTER 1";

			var usImporterWrapper = OrgHeaderWrapper.New(usImporterOrg);
			usImporterWrapper.ZO_OA_ConsigneeAddress = consigneeAddress.PK;
			usImporterWrapper.ZO_OA_ShipToAddress = deliverToAddress.PK;

			var caImporterWrapper = OrgHeaderWrapper.New(caImporterOrg);
			caImporterWrapper.ZO_OA_ConsigneeAddress = deliverToAddress.PK;
			caImporterWrapper.ZO_OA_ShipToAddress = consigneeAddress.PK;
			Factory.Save();

			var declaration = Factory.NewWithValidTestData<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.US_EntryFilerCode = "XJ5";
			declaration.US_EnableENS = true;
			declaration.ImportEntryNumber = "12345678";
			declaration.Invoices.AddNew();
			declaration.InvoiceLines.AddNew();
			declaration.JE_OA_ShipToPartyAddress = ZGuid.Empty;
			declaration.JE_OA_ConsigneeAddress = ZGuid.Empty;

			AssertEquals(ZGuid.Empty, declaration.JE_OH_Importer);
			AssertEquals(ZGuid.Empty, declaration.JE_OA_ConsigneeAddress);
			AssertEquals(ZGuid.Empty, declaration.JE_OA_ShipToPartyAddress);

			declaration.JE_OH_Importer = usImporterOrg.PK;
			AssertEquals(consigneeAddress.PK, declaration.JE_OA_ConsigneeAddress);
			AssertEquals(deliverToAddress.PK, declaration.JE_OA_ShipToPartyAddress);

			declaration.JE_OH_Importer = caImporterOrg.PK;
			declaration.JE_MessageType = JobMessageTypeList.Codes.Export;
			AssertEquals(ZGuid.Empty, declaration.JE_OA_ConsigneeAddress);
			AssertEquals(ZGuid.Empty, declaration.JE_OA_ShipToPartyAddress);

			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			AssertEquals(deliverToAddress.PK, declaration.JE_OA_ConsigneeAddress);
			AssertEquals(consigneeAddress.PK, declaration.JE_OA_ShipToPartyAddress);
		}

		public void TestHumanReadableShortcutNameInJobDeclaration()
		{
			var organisation = Factory.NewWithValidTestData<OrgHeader>();
			organisation.OH_FullName = "IMPORTERFULLNAME";
			Factory.Save();

			var jobDeclaration = Factory.New<JobDeclaration>();
			jobDeclaration.JE_DeclarationReference = "BSSSSSS";
			jobDeclaration.JE_OH_Importer = organisation.PK;
			jobDeclaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			jobDeclaration.JE_TransportMode = TransportTypeList.Codes.Sea;

			AssertEquals("Job# ImportFullName", jobDeclaration.JE_DeclarationReference, jobDeclaration.HumanReadableShortcutName);

			jobDeclaration.JE_MasterBill = "APLU";
			AssertEquals("Job# ImportFullName", "BSSSSSS - MBL: APLU", jobDeclaration.HumanReadableShortcutName);

			jobDeclaration.JE_MessageType = JobMessageTypeList.Codes.Export;
			AssertEquals("Job# ImportFullName", "BSSSSSS - MBL: APLU", jobDeclaration.HumanReadableShortcutName);

			jobDeclaration.US_TransportReference = "T0000001";
			AssertEquals("BSSSSSS - TRF: T0000001", jobDeclaration.HumanReadableShortcutName);

			var entry = jobDeclaration.CustomsEntryHeaders.AddNew();
			entry.CH_MessageType = CusEntryHeaderMessageTypeList.Codes.Export;
