			AssertEquals("TID2342", jobDeclaration.DeclarationNumber);
			AssertEquals("BSSSSSS - TRF: T0000001 ITN: TID2342", jobDeclaration.HumanReadableShortcutName);

			jobDeclaration.US_TransportReference = string.Empty;
			AssertEquals("BSSSSSS - ITN: TID2342", jobDeclaration.HumanReadableShortcutName);
		}

