		public void TestGetReasonForNotAbleToUpdateCore()
		{
			var dec = Factory.NewWithValidTestData<JobDeclaration>();
			dec.JE_DeclarationReference = "BX00001";
			dec.JE_MessageType = JobMessageTypeList.Codes.Export;
			var invoiceHeader = dec.Invoices.AddNew();
			invoiceHeader.Messages.AddNew(typeof(MQEDIMessage));
			AssertEquals("", dec.GetReasonForNotAbleToUpdate());

			dec.JE_MessageType = JobMessageTypeList.Codes.FTZ;
			AssertEquals("", dec.GetReasonForNotAbleToUpdate());

			var dec2 = Factory.NewWithValidTestData<JobDeclaration>();
			dec2.JE_DeclarationReference = "BX00002";
			dec2.JE_MessageType = JobMessageTypeList.Codes.Import;
			dec2.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			dec2.US_EntryFilerCode = "XJ5";
			dec2.US_EnableENS = true;
			dec2.ImportEntryNumber = "12345678";
			dec2.Invoices.AddNew();
			dec2.InvoiceLines.AddNew();
			var entrySummaryEntry = dec2.ActiveEntryHeaders.AddNew();
			entrySummaryEntry.Messages.AddNew(typeof(MQEDIMessage));
			AssertEquals("", dec2.GetReasonForNotAbleToUpdate());

			var dec3 = Factory.NewWithValidTestData<JobDeclaration>();
			dec3.JE_DeclarationReference = "BX00003";
			dec3.JE_MessageType = JobMessageTypeList.Codes.Import;
			dec3.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			var invoice = dec3.Invoices.AddNew();
			var invoiceLine = invoice.JobComInvoiceLines.AddNew();
			var ensEntry = Factory.NewMoq<CusEntryHeader>();
			ensEntry.Object.CH_MessageType = CusEntryHeaderMessageTypeList.Codes.EntrySummary;
			ensEntry.Object.CH_JE = dec3.PK;
			ensEntry.Object.CH_Status = ImportMessageStatusList.Codes.ClearEntrySummaryOriginal;
			ensEntry.Object.Messages.AddNew(typeof(MQEDIMessage));
			dec3.CustomsEntryHeaders.Add(ensEntry.Object);
			invoiceLine.AdditionalEntryLineLinks.AddLinkIfNoneExists(ensEntry.Object.MergedLines.AddNew());
			AssertEquals("The communication process with Customs has started for this Declaration. Job Number: BX00003", dec3.GetReasonForNotAbleToUpdate());

			var dec4 = Factory.NewWithValidTestData<JobDeclaration>();
			dec4.JE_DeclarationReference = "BX00004";
			dec4.JE_MessageType = JobMessageTypeList.Codes.Import;
			dec4.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			var invoice2 = dec4.Invoices.AddNew();
			var invoiceLine2 = invoice2.JobComInvoiceLines.AddNew();
			var entry = dec4.ActiveEntryHeaders.AddNew();
			entry.CH_MessageType = CusEntryHeaderMessageTypeList.Codes.EntrySummary;
			entry.Messages.AddNew(typeof(MQEDIMessage));
			AssertEquals("The communication process with Customs has started for this Declaration. Job Number: BX00004", dec4.GetReasonForNotAbleToUpdate());

			var birdDec = Factory.NewWithValidTestData<JobDeclaration>();
			birdDec.JE_DeclarationReference = "BX00005";
			birdDec.JE_MessageType = JobMessageTypeList.Codes.Import;
			birdDec.JE_ApplicationCode = JobApplicationCodeList.Codes.ACE;
			var birdInvoice = birdDec.Invoices.AddNew();
			var birdInvoiceLine = birdInvoice.JobComInvoiceLines.AddNew();
			var birdEntry = birdDec.ActiveEntryHeaders.AddNew();
			birdEntry.CH_MessageType = CusEntryHeaderMessageTypeList.Codes.EntrySummary;
			var birdMessage = birdEntry.Messages.AddNew(typeof(MQEDIMessage));
			birdMessage.EM_MessageType = ACEApplicationIdentifierCodeList.Codes.ACEBIRDTransaction;
			AssertEquals(ZString.Empty, birdDec.GetReasonForNotAbleToUpdate());

			var crlEntry = birdDec.ActiveEntryHeaders.AddNew();
			crlEntry.CH_MessageType = CusEntryHeaderMessageTypeList.Codes.CargoRelease;
			var crlMessage = crlEntry.Messages.AddNew(typeof(MQEDIMessage));
			crlMessage.EM_MessageType = ACEApplicationIdentifierCodeList.Codes.CargoRelease;
			AssertEquals(ZString.Empty, birdDec.GetReasonForNotAbleToUpdate());
		}

