			fTZStmNum.SN_Owner = iOR.PK;
			Factory.Save();

			TestDec dec = Factory.New<TestDec>();
			dec.JE_OH_Importer = iOR.PK;
			dec.JE_MessageType = JobMessageTypeList.Codes.FTZ;
			dec.IOROrgPK = iOR.PK;
			dec.FTZZoneID = "1234567";
			AssertEquals(true, dec.FTZControlNumberIsAutoAllocated);
			dec.AllocateFTZControlNumberOnSaving = true;
			dec.ThrowExceptionOnSaving = true;
			try
			{
				Factory.Save();
			}
			catch { }

			AssertEquals("Control number is rolled back", ZString.Empty, dec.FTZControlNumber);

			dec.ThrowExceptionOnSaving = false;
