		public void TestWhenCargoReleaseTypeChangesToACS()
		{
			var tariff = Factory.New<USCTariff>();
			tariff.UE_Tariff = "00000000";
			tariff.UE_DateFrom = ZDateTime.BrettsBirthday;
			tariff.UE_DateTo = ZDateTime.MaxSmallDateTime;
			tariff.UE_OGACodes = "FD2";
			tariff.UE_PGACodes = "FD2DT2";
			Factory.Save();

			var dec = Factory.NewWithValidTestData<JobDeclaration>();
			dec.JE_MessageType = JobMessageTypeList.Codes.Import;
			dec.JE_ApplicationCode = JobApplicationCodeList.Codes.ACE;
			dec.US_EnableENS = true;
			dec.US_CargoReleaseType = CargoReleaseTypeList.Codes.ACE;

			var invoice = dec.Invoices.AddNew();
			var invoiceLine = dec.InvoiceLines.AddNew();
			invoiceLine.JI_Tariff = tariff.UE_Tariff;
			AssertEquals(OGAIndicatorList.Codes.Declared, invoiceLine.US_FDAIndicator);
			AssertEquals(OGAIndicatorList.Codes.Declared, invoiceLine.US_NHTSAIndicator);

			invoiceLine.US_FCCIndicator = OGAIndicatorList.Codes.Declared;
			invoiceLine.US_FSISInd = OGAIndicatorList.Codes.Declared;

			invoiceLine.ACE_FDALines.AddNew();
			invoiceLine.NHTSALines.AddNew();
			invoiceLine.FCCs.AddNew();
			invoiceLine.FSISLines.AddNew();

			dec.US_CargoReleaseType = CargoReleaseTypeList.Codes.ACS;
			AssertEquals("FDA indicator field is shared by both OGA and PGA", OGAIndicatorList.Codes.Declared, invoiceLine.US_FDAIndicator);
			AssertEquals("NHTSA cannot be reported in ACS", ZString.Empty, invoiceLine.US_NHTSAIndicator);
			AssertEquals("DOT indicator is NOT defaulted", ZString.Empty, invoiceLine.US_DOTIndicator);
			AssertEquals("FCC is both OGA and PGA", OGAIndicatorList.Codes.Declared, invoiceLine.US_FCCIndicator);
			AssertEquals("FSIS indicator can be set to D in ACS for document printing purpose", OGAIndicatorList.Codes.Declared, invoiceLine.US_FSISInd);

			AssertEquals("ACE FDA is no longer relevant", 0, invoiceLine.ACE_FDALines.Count);
			AssertEquals("NHTSALines is no longer relevant", 0, invoiceLine.NHTSALines.Count);
			AssertEquals(1, invoiceLine.FCCs.Count);
			AssertEquals(1, invoiceLine.FSISLines.Count);

			invoiceLine.FDAs.AddNew();
			invoiceLine.DOTs.AddNew();
			dec.US_CargoReleaseType = CargoReleaseTypeList.Codes.ACE;
			AssertEquals("FDA indicator field is shared by both OGA and PGA", OGAIndicatorList.Codes.Declared, invoiceLine.US_FDAIndicator);
			AssertEquals("DOT is no longer relevant in ACE", ZString.Empty, invoiceLine.US_DOTIndicator);
			AssertEquals("FCC is both OGA and PGA", OGAIndicatorList.Codes.Declared, invoiceLine.US_FCCIndicator);
			AssertEquals("FSIS indicator can be set to D in ACS for document printing purpose", OGAIndicatorList.Codes.Declared, invoiceLine.US_FSISInd);
			AssertEquals("ACS FDA is no longer relevant", 0, invoiceLine.FDAs.Count);
			AssertEquals("DOT is no longer relevant", 0, invoiceLine.DOTs.Count);
			AssertEquals(1, invoiceLine.FCCs.Count);
			AssertEquals(1, invoiceLine.FSISLines.Count);
		}

