		}

		public void TestFTZShowDeveloperExceptionWithNoControlNumber()
		{
			var mockDeclaration = Factory.NewMoq<JobDeclaration>();
			mockDeclaration.Setup(m => m.FTZControlNumberIsAutoAllocated).Returns(true);

			var declaration = mockDeclaration.Object;
			declaration.JE_MessageType = JobMessageTypeList.Codes.FTZ;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACE;
			declaration.FTZZoneID = "1234567";
			declaration.FTZYear = "17";
			declaration.FTZControlNumber = ZString.Empty;

			var invoice = declaration.Invoices.AddNew();
			var invoiceLine = invoice.InvoiceLines.AddNew();

			declaration.DoMerge(new SendsMessagesToCustomsShutterUpperer());

			var ftzMessageSendingObject = new FTZMessageSendingObject(declaration, UpdateActionCode.Add);
			var builder = new FTZMessageBuilder(ftzMessageSendingObject, ftzMessageSendingObject.ActionCode);
			var message = builder.PopulateMessage();
			var placeHolderFiller = (ICBPEDIMessageMessageTextNumberPlaceHolderFiller)declaration;

			ErrorReporter.Clear();
			try
			{
				placeHolderFiller.Fill(message);

				string msgExpected = "<CN*PLC> should be replaced by FTZControlNumber.";
				AssertContains(msgExpected, ErrorReporter.LastMessageReported);
				var f10Block = message.MessageBlock.MessageBlocks.FirstOrDefault(x => x is Messaging.Business.MessageBuildingBlocks.Input.FTZFT10_01);
				AssertEquals("10A1234567  17<CN*PLC>N    NXJ5                                                 ", f10Block.Serialise());
			}
			finally
			{
				ErrorReporter.Clear();
			}
		}

		public void TestFindAndCloseRelatedPermits()
		{
			// - create FTZ declaration
			var declaration1 = CreateFTZWeeklyEstimateDeclaration(Factory, "40000007");
			var declaration2 = CreateFTZWeeklyEstimateDeclaration(Factory, "40000008");
			Factory.Save();
			// - create permits
			declaration1.JE_EntryAuthorisationDate = new ZDateTime(2017, 10, 14);
			declaration2.JE_EntryAuthorisationDate = new ZDateTime(2017, 10, 14);
			Factory.Save();
			AssertEquals(1, declaration1.FindRelatedPermits().Count);
			AssertEquals(1, declaration2.FindRelatedPermits().Count);

			var permit1 = declaration1.FindRelatedPermits()[0];
			var permit2 = declaration2.FindRelatedPermits()[0];

			// - both permits are still open
			AssertEquals(false, permit1.CPH_IsClosed);
			AssertEquals(false, permit2.CPH_IsClosed);

			// - close permits for only one declaration
			declaration1.CloseRelatedPermits();

			// - one permit is closed and event is logged
			AssertEquals(true, permit1.CPH_IsClosed);
			Assert("has closed log entry", permit1.Logs.HasLogWith(
				l => l.SL_SE_NKEvent == "PCL" && l.SL_Reference == "Permit closed"
			));

			// - another permit remains open
			AssertEquals(false, permit2.CPH_IsClosed);
		}

		public void TestCusPermitHeaderIsCreatedOnlyOnce()
		{
			// - create FTZ declaration
			var declaration = CreateFTZWeeklyEstimateDeclaration(Factory, "40000007");

			// - no permits were created yet
			AssertEquals(0, declaration.FindRelatedPermits().Count);

			// - permit should be created when JE_EntryAuthorisationDate is changed from Empty to non-Empty //
			declaration.JE_EntryAuthorisationDate = new ZDateTime(2017, 10, 14);
			Factory.Save();
			AssertEquals(1, declaration.FindRelatedPermits().Count);

			// - no new permits should be created or deleted when JE_EntryAuthorisationDate changes from non-Empty to Empty
			declaration.JE_EntryAuthorisationDate = ZDateTime.Empty;
			AssertEquals(1, declaration.FindRelatedPermits().Count);

			// - no new permits should be created when JE_EntryAuthorisationDate changes from Empty to non-Empty when there is already a permit
			declaration.JE_EntryAuthorisationDate = new ZDateTime(2017, 10, 14);
			AssertEquals(1, declaration.FindRelatedPermits().Count);
		}

