		public void TestDISDocumentIDList()
		{
			var declaration = Factory.New<JobDeclaration>();
			var requiredDocument = declaration.DocsAndCartage.RequiredDocuments.AddNew();
			requiredDocument.EQ_DocType = Core.Constants.RefDocTypes.CommercialInvoice;
			var eDoc = ((IDocManagerSupport)declaration).DocManagerInfo.AddFileOrDocument(new byte[] { 1, 2, 3 }, "Test", Core.Constants.RefDocTypes.CommercialInvoice);
			eDoc.Description = "SOME DESCRIPTION";
			var disWrapper = ObjectFactory.Get<IDISHostWrapper>("IDISHostWrapper", new object[] { declaration });
			var document1 = (Integration.Customs.US.DIS.IDISDocument)disWrapper.DISDocuments.AddNew();
			document1.IDSuffix = 1;
			document1.DocumentDescription = "BOB THE BUILDER";
			document1.EDocsDocumentPK = eDoc.UniqueKey;
			var document2 = (Integration.Customs.US.DIS.IDISDocument)disWrapper.DISDocuments.AddNew();
			document2.IDSuffix = 2;
			document2.DocumentDescription = "WENDY THE DESTROYER";
			document2.EDocsDocumentPK = eDoc.UniqueKey;

			Factory.Save();

			var list = declaration.DISDocumentIDList;
			AssertEquals(2, list.Count);
			AssertEquals("BOB THE BUILDER", list.GetDescriptionFromCode(document1.DocumentID));
			AssertEquals("WENDY THE DESTROYER", list.GetDescriptionFromCode(document2.DocumentID));

			var document3 = (Integration.Customs.US.DIS.IDISDocument)disWrapper.DISDocuments.AddNew();
			document3.IDSuffix = 3;
			document3.DocumentDescription = "JACK THE PEACEMARKER";
			document3.EDocsDocumentPK = eDoc.UniqueKey;

			Factory.Save();

			list = declaration.DISDocumentIDList;
			AssertEquals(2, list.Count);
			AssertEquals("BOB THE BUILDER", list.GetDescriptionFromCode(document1.DocumentID));
			AssertEquals("WENDY THE DESTROYER", list.GetDescriptionFromCode(document2.DocumentID));

			declaration.Validation.ValidateAll();
			list = declaration.DISDocumentIDList;
			AssertEquals(3, list.Count);
			AssertEquals("BOB THE BUILDER", list.GetDescriptionFromCode(document1.DocumentID));
			AssertEquals("WENDY THE DESTROYER", list.GetDescriptionFromCode(document2.DocumentID));
			AssertEquals("JACK THE PEACEMARKER", list.GetDescriptionFromCode(document3.DocumentID));
		}

