		public void TestHasFTZTransactionsWithCustoms()
		{
			var declaration = Factory.NewWithValidTestData<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.FTZ;
			declaration.FTZAdmissionNumber = "1530001|14|0001234";
			AssertEquals(false, declaration.HasFTZTransactionsWithCustoms);
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			AssertEquals("", declaration.FTZAdmissionNumber);

			declaration.JE_MessageType = JobMessageTypeList.Codes.FTZ;
			var addOn = Factory.NewWithValidTestData<GenAddOnColumn>();
			addOn.XA_ParentID = declaration.PK;
			addOn.XA_ParentTableCode = JobDeclarationSchema.Constants.Prefix;
			addOn.XA_Name = "US_FTZAdmissionStatus";
			addOn.XA_Type = AddOnColumnDataType.Codes.String;
			addOn.XA_Data = FTZMessageStatusList.Codes.AwaitingFTZAdmissionAdd;
			Factory.Save();
			AssertEquals(true, declaration.HasFTZTransactionsWithCustoms);

			addOn.XA_Data = FTZMessageStatusList.Codes.ErrorFTZAdmissionDelete;
			Factory.Save();
			AssertEquals(false, declaration.HasFTZTransactionsWithCustoms);

			addOn.XA_Data = FTZMessageStatusList.Codes.ClearFTZAdmissionDelete;
			Factory.Save();
			AssertEquals(true, declaration.HasFTZTransactionsWithCustoms);

			addOn.XA_Data = FTZMessageStatusList.Codes.ErrorFTZAdmissionDelete;
			Factory.Save();
			AssertEquals(false, declaration.HasFTZTransactionsWithCustoms);

			declaration = Factory.NewWithValidTestData<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.FTZ;
			IStatusList list = new FTZMessageStatusList();
			declaration.LogManager.AddAClearLogIfNecessary(FTZMessageStatusList.Codes.AwaitingFTZAdmissionAdd, FTZMessageStatusList.Codes.ClearFTZAdmissionAddWithWarnings, list);
			AssertEquals(true, declaration.HasFTZTransactionsWithCustoms);
		}

		public void TestAreSplitDetailsRelevant()
		{
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.FTZ;
			declaration.JE_TransportMode = TransportTypeList.Codes.Air;
			Assert(!declaration.AreSplitDetailsRelevant);
			declaration.US_F_AdmissionType = FTZAdmissionTypeCodeList.Codes.RegularAdmission;
			Assert(declaration.AreSplitDetailsRelevant);

			var bill = declaration.Bills.AddNew();
			bill.US_SESplitShip = true;
			var splitDetail1 = bill.ITAndSplitDetails.AddNew();
			splitDetail1.US_FlightNumber = "QF345";

			declaration.JE_TransportMode = TransportTypeList.Codes.Sea;
			Assert(!declaration.AreSplitDetailsRelevant);
			Assert("GUI makes fields invisible. should be unticked", !bill.US_SESplitShip);
			AssertEquals(ZString.Empty, splitDetail1.US_FlightNumber);

			declaration.JE_TransportMode = TransportTypeList.Codes.Air;
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACE;
			declaration.US_EnableENS = true;
			declaration.US_CargoReleaseType = CargoReleaseTypeList.Codes.ACE;
			Assert(declaration.AreSplitDetailsRelevant);

			declaration.US_SESplitRel = "2";
			bill.US_SESplitShip = true;
			splitDetail1 = bill.ITAndSplitDetails.AddNew();
			splitDetail1.US_FlightNumber = "QF345";

			declaration.US_CargoReleaseType = CargoReleaseTypeList.Codes.ACS;
			Assert(!declaration.AreSplitDetailsRelevant);
			AssertEquals("GUI makes fields invisible. should be reset", ZString.Empty, declaration.US_SESplitRel);
			Assert("GUI makes fields invisible. should be unticked", !bill.US_SESplitShip);
			AssertEquals(ZString.Empty, splitDetail1.US_FlightNumber);

			declaration.US_SESplitRel = "2";
			bill.US_SESplitShip = true;
			splitDetail1 = bill.ITAndSplitDetails.AddNew();
			splitDetail1.US_FlightNumber = "QF345";

			declaration.US_CargoReleaseType = CargoReleaseTypeList.Codes.ACE;
			declaration.JE_MessageType = JobMessageTypeList.Codes.Export;
			Assert(!declaration.AreSplitDetailsRelevant);
			Assert("GUI makes fields invisible. should be unticked", !bill.US_SESplitShip);
			AssertEquals(ZString.Empty, splitDetail1.US_FlightNumber);

			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACE;
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			declaration.US_EnableENS = true;
			declaration.US_CargoReleaseType = CargoReleaseTypeList.Codes.ACE;
			bill.US_SESplitShip = true;
			splitDetail1.US_FlightNumber = "QF345";
			Assert(declaration.AreSplitDetailsRelevant);
			Assert(bill.US_SESplitShip);
			AssertEquals("QF345", splitDetail1.US_FlightNumber);
		}

