		public void TestDocPrintingCustomsDeliveryOrderAndFSISForm9540()
		{
			var oldValue = Globals.IsUserInteractive;
			try
			{
				Globals.IsUserInteractive = false;
				var declaration = Factory.New<JobDeclaration>();
				declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
				declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
				declaration.US_EnableENS = true;
				var menuItem = StmMenuItem.New(Factory);
				menuItem.SU_MenuName = DocumentNames.CustomsDeliveryOrder;
				var shipment = Factory.New<ForwardingShipment>();
				declaration.JE_JS = shipment.PK;
				IDocumentDataStateManager stateManager = declaration;
				AssertEquals(DocumentDataStateManagerResult.Fail, stateManager.Evaluate(menuItem));
				AssertEquals("IsDataStateValid", false, stateManager.IsDataStateValid);
				AssertEquals("DataStateErrorMessage", "No Customs Delivery Order has been marked for printing.", stateManager.DataStateErrorMessage);

				IDocumentDataStateManager shipmentStateManager = shipment;
				AssertEquals(DocumentDataStateManagerResult.Fail, shipmentStateManager.Evaluate(menuItem));
				AssertEquals("IsDataStateValid", false, shipmentStateManager.IsDataStateValid);
				AssertEquals("DataStateErrorMessage", "No Customs Delivery Order has been marked for printing.", shipmentStateManager.DataStateErrorMessage);

				var order = declaration.DeliveryOrderHeaders.AddNew();
				order.US_OrderReference = "ORD23";
				order.US_ShouldPrint = true;
				AssertEquals(DocumentDataStateManagerResult.Pass, stateManager.Evaluate(menuItem));
				AssertEquals("IsDataStateValid", true, stateManager.IsDataStateValid);
				AssertEquals("DataStateErrorMessage", "", stateManager.DataStateErrorMessage);
				AssertEquals(DocumentDataStateManagerResult.Pass, shipmentStateManager.Evaluate(menuItem));
				AssertEquals("IsDataStateValid", true, shipmentStateManager.IsDataStateValid);
				AssertEquals("DataStateErrorMessage", "", shipmentStateManager.DataStateErrorMessage);

				order.US_ShouldPrint = false;
				AssertEquals(DocumentDataStateManagerResult.Fail, stateManager.Evaluate(menuItem));
				AssertEquals("IsDataStateValid", false, stateManager.IsDataStateValid);
				AssertEquals("DataStateErrorMessage", "No Customs Delivery Order has been marked for printing.", stateManager.DataStateErrorMessage);

				AssertEquals(DocumentDataStateManagerResult.Fail, shipmentStateManager.Evaluate(menuItem));
				AssertEquals("IsDataStateValid", false, shipmentStateManager.IsDataStateValid);
				AssertEquals("DataStateErrorMessage", "No Customs Delivery Order has been marked for printing.", shipmentStateManager.DataStateErrorMessage);

				Globals.IsUserInteractive = true;
				AssertEquals(DocumentDataStateManagerResult.NotApplicable, stateManager.Evaluate(menuItem));
				AssertEquals("IsDataStateValid", true, stateManager.IsDataStateValid);
				AssertEquals("DataStateErrorMessage", "", stateManager.DataStateErrorMessage);
			}
			finally
			{
				Globals.IsUserInteractive = oldValue;
			}
		}

