		public void TestChangesToAddInfoSerialisedFineWithHasChangesTurnedOn()
		{
			var filer = new EntryFiler();
			filer.EntryFilerCode = "XJ6";
			GlbDepartment.CurrentDepartment.GE_Import = false;

			USCustomsDataRegistry.Instance.EntryFiler.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, filer);

			var consol = Factory.New<ForwardingConsol>();
			consol.JK_TransportMode = "AIR";
			consol.JK_RL_NKLoadPort = "AUSYD";
			consol.JK_RL_NKDischargePort = "USCHI";

			var consignor = Factory.NewWithValidTestData<OrgHeader>();
			consignor.OH_RL_NKClosestPort = "AUSYD";

			var consignee = Factory.NewWithValidTestData<OrgHeader>();
			consignee.OH_RL_NKClosestPort = "USCHI";

			var shipment = consol.Shipments.AddNew();
			shipment.ConsignorDocumentaryAddress.OrganisationPK = consignor.PK;
			shipment.ConsigneeDocumentaryAddress.OrganisationPK = consignee.PK;

			//a skeleton declaration is created like this in OrderForm > CreateConsolAndShipment and if a buyer's agent matches an org proxy of the current company.
			var declaration = Factory.New<JobDeclaration>();
			AssertEquals("Precondition", JobMessageTypeList.Codes.Export, declaration.JE_MessageType);
			declaration.JE_JS = shipment.PK;

			Factory.Save();

			var factory2 = new BusinessObjectFactory();
			var declarationLoaded = factory2.Load<JobDeclaration>(declaration.PK);

			((Integration.Customs.IJobDeclarationWithShipmentSynchonisation)declarationLoaded).SynchroniseWithShipmentIfNeeded();
			factory2.Save();//should have serialised what's changed in AddInfo to JE_AddInfo including Entry filer code

			var factory3 = new BusinessObjectFactory();
			declarationLoaded = factory3.Load<JobDeclaration>(declaration.PK);
			AssertEquals("IMP", declarationLoaded.JE_MessageType);
			AssertEquals("Defaulted Entry filer code is saved", "XJ6", declarationLoaded.US_EntryFilerCode);
		}

