		public void TestFTZAddressSetFromImporterWarehouseOrg()
		{
			// Verify the Bonded Warehouse (WarehouseDocAddress) (this field is also used as the FTZ Organisation) is set when the Importer organisation has an FTZ/Warehouse default configured.
			// Should only be set when
			//  a) Shipment Type (JE_MessageType) is "FTZ"
			//  b) is a new declaration

			// create importer
			GlbCompany.CurrentCompany.SetCountry(Core.Constants.CountryCodes.UnitedStates);

			var importer = Factory.NewWithValidTestData<OrgHeader>();
			importer.OH_RL_NKClosestPort = "USCHI";

			var warehouseAddr = Factory.New<OrgAddress>();
			var orgCountryDataUS = Factory.New<OrgCountryData>();
			orgCountryDataUS.OV_RN_NKClientCountryRelation = "US";
			orgCountryDataUS.OV_ImportCustomsDefaultAddInfo = "<ImportCustomsDefaultAddInfo><OtherReconIndicator>NA</OtherReconIndicator><Purchased>Y</Purchased></ImportCustomsDefaultAddInfo>";
			orgCountryDataUS.OV_OH_OrgHeader = importer.PK;
			orgCountryDataUS.OV_OA_WarehouseAddress = warehouseAddr.PK;

			// verify setting the importer copies over the address
			var declarationFTZBeforeImporter = Factory.New<JobDeclaration>();
			declarationFTZBeforeImporter.JE_MessageType = JobMessageTypeList.Codes.FTZ;
			AssertEquals("Should not have FTZ Address set", false, declarationFTZBeforeImporter.WarehouseDocAddress.E2_OA_Address.IsValid);

			declarationFTZBeforeImporter.JE_OH_Importer = importer.PK;
			AssertEquals("Should have FTZ Address set from Importer Warehouse Address Details", warehouseAddr.PK, declarationFTZBeforeImporter.WarehouseDocAddress.E2_OA_Address);

			// verify setting the message type copies over the address
			var declarationFTZAfterImporter = Factory.New<JobDeclaration>();
			declarationFTZAfterImporter.JE_MessageType = JobMessageTypeList.Codes.Export;
			declarationFTZAfterImporter.JE_OH_Importer = importer.PK;
			AssertEquals("Should not have FTZ Address set", false, declarationFTZAfterImporter.WarehouseDocAddress.E2_OA_Address.IsValid);

			declarationFTZAfterImporter.JE_MessageType = JobMessageTypeList.Codes.FTZ;
			AssertEquals("Should have FTZ Address set from Importer Warehouse Address Details", warehouseAddr.PK, declarationFTZAfterImporter.WarehouseDocAddress.E2_OA_Address);

			// verify an existing address is overwritten if the importer is changed
			var warehouseAddrExisting = Factory.New<OrgAddress>();
			var declarationExistingFTZAddress = Factory.New<JobDeclaration>();
			declarationExistingFTZAddress.JE_MessageType = JobMessageTypeList.Codes.FTZ;
			declarationExistingFTZAddress.WarehouseDocAddress.E2_OA_Address = warehouseAddrExisting.PK;
			AssertEquals("Bonded Warehouse/FTZ Address should be unchanged", warehouseAddrExisting.PK, declarationExistingFTZAddress.WarehouseDocAddress.E2_OA_Address);

			declarationExistingFTZAddress.JE_OH_Importer = importer.PK;
			AssertEquals("Bonded Warehouse/FTZ Address should be changed", warehouseAddr.PK, declarationExistingFTZAddress.WarehouseDocAddress.E2_OA_Address);
		}

		public void TestBondedWarehouseAddressSetFromImporterWarehouseOrgOnWithdrawlEntry()
		{
			// Verify the Bonded Warehouse (WarehouseDocAddress) (this field is also used as the FTZ Organisation) is set when the Importer organisation has an FTZ/Warehouse default configured.
			// Should only be set when
			//  a) Shipment Type (JE_MessageType) is "Import"
			//  b) Entry Type (US_EntryType) is '21' or '22'
			//  c) is a new declaration

			// create importer
			GlbCompany.CurrentCompany.SetCountry(Core.Constants.CountryCodes.UnitedStates);

			var importer = Factory.NewWithValidTestData<OrgHeader>();
			importer.OH_RL_NKClosestPort = "USCHI";

			var warehouseAddr = Factory.New<OrgAddress>();
			var orgCountryDataUS = Factory.New<OrgCountryData>();
			orgCountryDataUS.OV_RN_NKClientCountryRelation = "US";
			orgCountryDataUS.OV_ImportCustomsDefaultAddInfo = "<ImportCustomsDefaultAddInfo><OtherReconIndicator>NA</OtherReconIndicator><Purchased>Y</Purchased></ImportCustomsDefaultAddInfo>";
			orgCountryDataUS.OV_OH_OrgHeader = importer.PK;
			orgCountryDataUS.OV_OA_WarehouseAddress = warehouseAddr.PK;

			CombineAssertions(() =>
			{
				AssertBondedWarehouseAddressSetForEntryType(importer, warehouseAddr, "06");
				AssertBondedWarehouseAddressSetForEntryType(importer, warehouseAddr, "21");
				AssertBondedWarehouseAddressSetForEntryType(importer, warehouseAddr, "22");
				AssertBondedWarehouseAddressSetForEntryType(importer, warehouseAddr, "31");
				AssertBondedWarehouseAddressSetForEntryType(importer, warehouseAddr, "32");
				AssertBondedWarehouseAddressSetForEntryType(importer, warehouseAddr, "34");
				AssertBondedWarehouseAddressSetForEntryType(importer, warehouseAddr, "38");
			});

			// verify setting the importer forces declaration into Import type
			var declarationEntryType21AfterImporter = Factory.New<JobDeclaration>();
			declarationEntryType21AfterImporter.JE_OH_Importer = importer.PK;
			AssertEquals("Setting the Importer should set the message type to Import", JobMessageTypeList.Codes.Import, declarationEntryType21AfterImporter.JE_MessageType);
			AssertEquals("Should not have the Bonded Warehouse/FTZ Address set", false, declarationEntryType21AfterImporter.WarehouseDocAddress.E2_OA_Address.IsValid);
		}

		void AssertBondedWarehouseAddressSetForEntryType(OrgHeader importer, OrgAddress warehouseAddr, string code)
		{
			var declarationImportAndEntryTypeBeforeImporter = Factory.New<JobDeclaration>();
			declarationImportAndEntryTypeBeforeImporter.JE_MessageType = JobMessageTypeList.Codes.Import;
			declarationImportAndEntryTypeBeforeImporter.US_EntryType = code;
			AssertEquals("Should not have Bonded Warehouse/FTZ Address set for Entry Type " + code, false, declarationImportAndEntryTypeBeforeImporter.WarehouseDocAddress.E2_OA_Address.IsValid);

			// verify setting the importer copies over the address
			declarationImportAndEntryTypeBeforeImporter.JE_OH_Importer = importer.PK;
			AssertEquals("Should have Bonded Warehouse/FTZ Address set from Importer Warehouse Address Details for Entry Type " + code, warehouseAddr.PK, declarationImportAndEntryTypeBeforeImporter.WarehouseDocAddress.E2_OA_Address);
		}

		protected override Type ExpectedMetadataType => typeof(Metadata.Business.USJobDeclaration);

		public void TestImportEntryNumberMutex()
		{
			var factory1 = new BusinessObjectFactory();
			factory1.RefreshEnabled = false;
			var declaration = factory1.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EnableENS = true;
			declaration.US_EntryFilerCode = "XJ5";
			factory1.Save();
			var factory2 = new BusinessObjectFactory();
			factory2.RefreshEnabled = false;
			var decInFactory2 = factory2.Load<JobDeclaration>(declaration.PK);
			AssertEquals(true, decInFactory2.LockImportEntryNumberAllocationMutex);
			AssertEquals(false, declaration.LockImportEntryNumberAllocationMutex);
			AssertEquals("Still locked", true, decInFactory2.LockImportEntryNumberAllocationMutex);
			AssertEquals("Still locked by another session", false, declaration.LockImportEntryNumberAllocationMutex);
			declaration.UnlockImportEntryNumberAllocationMutex();
			AssertEquals("Still locked", true, decInFactory2.LockImportEntryNumberAllocationMutex);
			decInFactory2.UnlockImportEntryNumberAllocationMutex();
			AssertEquals(true, declaration.LockImportEntryNumberAllocationMutex);
			AssertEquals("another session took lock", false, decInFactory2.LockImportEntryNumberAllocationMutex);
			using (var importEntryNumberAllocationMutex = new ZGlobalMutex(MutexIDs.CustomsTransactionIDAllocation, "ENS" + declaration.PK.ToString()))
			{
				AssertEquals(true, importEntryNumberAllocationMutex.IsLocked);
				AssertEquals(false, importEntryNumberAllocationMutex.HasLock);
				factory1.Save();
				AssertEquals("Lock should be released when factory is saved", false, importEntryNumberAllocationMutex.IsLocked);
				AssertEquals(false, importEntryNumberAllocationMutex.HasLock);
				AssertEquals(true, declaration.LockImportEntryNumberAllocationMutex);
				AssertEquals(true, importEntryNumberAllocationMutex.IsLocked);
				AssertEquals(false, importEntryNumberAllocationMutex.HasLock);
				declaration.Delete();
				AssertEquals("Lock should be released when dec is deleted", false, importEntryNumberAllocationMutex.IsLocked);
				AssertEquals(false, importEntryNumberAllocationMutex.HasLock);
			}
		}

		public void TestImportEntryNumberAllocationMutexLockInfo_NullUser()
		{
			var declaration = Factory.New<JobDeclaration>();
			NeedUnlockAfterMergeForTestHelper.NeedUnlockAfterMergeForTest = false;

			using (var mutex = new ZGlobalMutex(MutexIDs.CustomsTransactionIDAllocation, "ENS" + declaration.PK.ToString()))
			{
				Assert(mutex.Lock());
				var lockInfo = "Mutex:" + MutexIDs.CustomsTransactionIDAllocation.Name + ":ENS" + declaration.PK.ToString();
				var emptyGuid = Guid.Empty;
				var sql = $@"UPDATE TOP(1) StmServiceHeartBeat
									SET SV_ParentId = '{emptyGuid}',
										SV_SystemLastEditTimeUtc = GetUtcDate(),
										SV_SystemLastEditUser = 'USR'
									FROM dbo.StmServiceSemaphore
									INNER JOIN dbo.StmServiceHeartBeat ON SS_SV = SV_PK
									WHERE SS_LockInfo LIKE '%{lockInfo}%';";
				TestConnection.ExecuteNonQuery(sql);

				AssertEquals(false, declaration.LockImportEntryNumberAllocationMutex);
				AssertNoExceptionThrown(() => declaration.GetImportEntryNumberAllocationMutexLockInfo());
			}
			NeedUnlockAfterMergeForTestHelper.NeedUnlockAfterMergeForTest = true;
		}

