			declaration.US_EntryType = EntryTypeList.Codes.WarehouseWithdrawalConsumption;
			AssertEquals(true, declaration.BondedWarehouseEditable);
			declaration.JE_MessageType = JobMessageTypeList.Codes.FTZ;
			AssertEquals(true, declaration.BondedWarehouseEditable);
		}

		public void TestIsOutwardBondedWarehousingEnabled()
		{
			var org = Factory.New<OrgHeader>();
			org.CompanyData.OB_IMUsedBondedWhs = true;
			var classification = Factory.New<CusClassification>();
			classification.CC_LookupCode = "LK234";
			classification.CC_TariffNum = "2010304050";
			var part = Factory.New<OrgSupplierPart>();
			part.OP_PartNum = "PART321";
			var orgRel = part.RelatedOrganisations.AddOrganisationIfNotExist(org.PK, OrgPartRelation.RelationshipTypes.Owner);
			var pivot = part.PivotsForBinding.AddNew();
			pivot.CI_ChildType = ClassificationTypeList.Codes.HTI;
			pivot.CI_OH = orgRel.OU_OH;
			pivot.CI_CC = classification.PK;
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_OH_Importer = org.PK;
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EnableENS = true;
			declaration.US_EntryType = EntryTypeList.Codes.WarehouseWithdrawalADDCVD;
			AssertEquals(true, declaration.IsOutwardBondedWarehousingEnabled);
			foreach (var entryType in new[]
				{
					//EntryTypeList.Codes.ConsumptionFTZ, DN: Todo remove this when we know more info
					EntryTypeList.Codes.WarehouseWithdrawalADDCVD,
					EntryTypeList.Codes.WarehouseWithdrawalADDCVDQuotaVisa,
					//EntryTypeList.Codes.AircraftVesselSupplyIE, DN: Todo remove this when we know more info
					EntryTypeList.Codes.WarehouseWithdrawalConsumption,
					EntryTypeList.Codes.WarehouseWithdrawalQuota
				})
			{
				declaration.US_EntryType = "@1";
				AssertEquals(false, declaration.IsOutwardBondedWarehousingEnabled);
				declaration.US_EntryType = entryType;
				AssertEquals(true, declaration.IsOutwardBondedWarehousingEnabled);
			}
			declaration.JE_MessageType = JobMessageTypeList.Codes.Export;
			declaration.US_EnableENS = true;
			AssertEquals(false, declaration.IsOutwardBondedWarehousingEnabled);
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EnableENS = true;
			AssertEquals(true, declaration.IsOutwardBondedWarehousingEnabled);
		}

		public void TestIDISHostImplementation()
		{
			var declaration = Factory.New<JobDeclaration>();
			var disHost = (IDISHost)declaration;

			var company2 = Factory.New<GlbCompany>();
			company2.GC_RN_NKCountryCode = "US";

			var branch = company2.Branches.AddNew();
			declaration.JE_GB = branch.PK;

			AssertEquals(1, disHost.ApplicationCodes.Count());
			AssertEquals(Core.Constants.Customs.DocumentImageSystemIDs.US_DIS, disHost.ApplicationCodes.ElementAt(0));
			AssertEquals(branch.PK, disHost.BranchPK);
			AssertEquals(company2.PK, disHost.CompanyPK);
			AssertEquals(declaration.DocsAndCartage, disHost.RequiredDocumentsProvider);

			int notifiedCount = 0;
			disHost.DISFeatureVisibilityChanged += delegate
			{
				notifiedCount++;
			};
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			AssertEquals(false, disHost.ShowDISFeatures);
			Assert("notified", notifiedCount > 0);

			notifiedCount = 0;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACE;
			AssertEquals(true, disHost.ShowDISFeatures);
			Assert("notified", notifiedCount > 0);

			AssertNotNull(disHost.EDocs);
			AssertEquals(declaration, disHost.ControllerIDProvider);

			declaration.JE_MessageType = JobMessageTypeList.Codes.Export;
			Assert(disHost.ShowDISFeatures);
			AssertEquals(1, disHost.ErrorMessages.Count());
			using (USCustomsDataRegistry.Instance.EntryFiler.SetTemporaryValue(declaration.RegistryCompanyPK, Guid.Empty, Guid.Empty, new EntryFiler() { EntryFilerCode = "SV9" }))
			{
				AssertEquals(0, disHost.ErrorMessages.Count());

				declaration.JE_MessageType = JobMessageTypeList.Codes.FTZ;
				Assert(disHost.ShowDISFeatures);
			}
		}

