		public void TestDecEntryNumber_ReadOnlyForPSC()
		{
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACE;
			declaration.US_EnableENS = true;
			declaration.US_EnableCRL = true;
			declaration.Invoices.AddNew();
			declaration.InvoiceLines.AddNew();
			declaration.DoMerge(new SendsMessagesToCustomsShutterUpperer());

			declaration.US_PSC = true;
			Assert(!declaration.DecEntryNumber_ReadOnly);

			var formalEntry = declaration.FormalEntry;
			formalEntry.CH_Status = ImportMessageStatusList.Codes.AwaitingEntrySummaryOriginal;
			Assert(declaration.DecEntryNumber_ReadOnly);
			formalEntry.CH_Status = ImportMessageStatusList.Codes.ClearEntrySummaryOriginal;
			Assert(declaration.DecEntryNumber_ReadOnly);
			formalEntry.Logs.MostRecentLog.Cancel();
			Assert(!declaration.DecEntryNumber_ReadOnly);

			var seEntry = declaration.ActiveEntryHeaders.SimplifiedEntry;
			seEntry.CH_Status = ImportMessageStatusList.Codes.AwaitingACECargoReleaseAdd;
			Assert(declaration.DecEntryNumber_ReadOnly);
			seEntry.CH_Status = ImportMessageStatusList.Codes.ClearACECargoReleaseAdd;
			Assert(declaration.DecEntryNumber_ReadOnly);
			seEntry.Logs.MostRecentLog.Cancel();
			Assert(!declaration.DecEntryNumber_ReadOnly);
		}

		public void TestStandalonePriorNoticeLines()
		{
			var tariff1 = Factory.New<USCTariff>();
			tariff1.UE_Tariff = "0000000000";
			tariff1.UE_DateFrom = ZDateTime.Today.AddYears(-1);
			tariff1.UE_DateTo = ZDateTime.Today;
			tariff1.UE_OGACodes = "FD3";

			var tariff2 = Factory.New<USCTariff>();
			tariff2.UE_Tariff = "0000000001";
			tariff2.UE_DateFrom = ZDateTime.Today.AddYears(-1);
			tariff2.UE_DateTo = ZDateTime.Today;
			tariff2.UE_OGACodes = "FD2";

			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.JE_MasterBill = "MB123456";
			var invoice = declaration.Invoices.AddNew();
			var invoiceLine1 = invoice.JobComInvoiceLines.AddNew();
			invoiceLine1.JI_Tariff = tariff1.UE_Tariff;
			var fda1 = invoiceLine1.FDAs.AddNew();
			fda1.US_FDAForcePN = true;
			var fda2 = invoiceLine1.FDAs.AddNew();
			fda2.US_PND = true;
			var fda3 = invoiceLine1.FDAs.AddNew();
			fda3.US_PND = false;
			var fda4 = invoiceLine1.FDAs.AddNew();
			fda4.US_PNC = "111";
			fda4.US_FDAForcePN = true;
			var invoiceLine2 = invoice.InvoiceLines.AddNew();
			invoiceLine2.JI_Tariff = tariff2.UE_Tariff;
			var fda5 = invoiceLine2.FDAs.AddNew();
			fda5.US_FDAForcePN = true;
			var standalonePriorNoticeLines = ((IPriorNoticeHeader)declaration).StandalonePriorNoticeLines;
			AssertEquals(3, standalonePriorNoticeLines.Count);
			Assert(standalonePriorNoticeLines.Contains(fda1));
			Assert(standalonePriorNoticeLines.Contains(fda3));
			Assert(standalonePriorNoticeLines.Contains(fda5));

			declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			declaration.JE_TransportMode = "SEA";
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACE;
			declaration.US_EnableENS = true;
			declaration.US_CargoReleaseType = CargoReleaseTypeList.Codes.ACE;
			declaration.JE_MasterBill = "MB12345";

			invoice = declaration.Invoices.AddNew();
			var invoiceLine = declaration.InvoiceLines.AddNew();

			var tariff = Factory.New<USCTariff>();
			tariff.UE_Tariff = "00000000";
			tariff.UE_DateFrom = ZDateTime.Today.AddYears(-1);
			tariff.UE_DateTo = ZDateTime.Today.AddMonths(1);
			tariff.UE_PGACodes = "FD3";
			invoiceLine.JI_Tariff = tariff.UE_Tariff;
			invoiceLine.US_FDAIndicator = OGAIndicatorList.Codes.Declared;

			var ace_fda = invoiceLine.ACE_FDALines.AddNew();
			ace_fda.US_ProgramCode = FDAProgramCodeList.Codes.FOO;
			ace_fda.US_ProcessingCode = FDAProcessingCodeList.Codes.FOO_FEE;

			var declarationWrapper = new ACEPriorNoticeBillWrapper(declaration.PrimaryMasterBill, declaration) as IStandAlonePriorNoticeHeader;
			var aceStandalonePriorNoticeLines = declarationWrapper.ACEStandalonePriorNoticeLines;
			AssertEquals(1, aceStandalonePriorNoticeLines.Count());
			Assert(aceStandalonePriorNoticeLines.Contains(ace_fda));
		}

