		public void TestIStatementDeleteAndAddEntity()
		{
			Declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			Declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			var entry = Declaration.CustomsEntryHeaders.AddNew();
			Declaration.US_SchDEntry = "8888";
			Declaration.US_PaymentType = "2";
			Declaration.US_ClientBranchDesignation = "XX";
			Declaration.US_PreliminaryStatementPrintDate = ZDateTime.Today;
			Declaration.US_PeriodicStatementMM = "02";
			Declaration.JE_EntryAuthorisationDate = new ZDateTime(2013, 03, 01);
			entry.CH_MessageType = CusEntryHeaderMessageTypeList.Codes.EntrySummary;
			Declaration.US_EntryFilerCode = "XJ6";
			entry.EntryNumber = "09784512";
			entry.CH_Status = ImportMessageStatusList.Codes.AwaitingEntrySummaryReplace;

			IStatementDeleteTransaction iEntry = Declaration;

			AssertEquals("EntryNumber", "09784512", iEntry.EntryNumber);
			AssertEquals("EntryFilerCode", "XJ6", iEntry.EntryFilerCode);
			AssertEquals("PortOfEntry", "8888", iEntry.PortOfEntry);
			AssertEquals("Factory", entry.Factory, iEntry.Factory);
			AssertEquals("Branch", Declaration.Branch, iEntry.Branch);
			AssertEquals("PaymentType_getter", "2", iEntry.PaymentType);
			AssertEquals("PreliminaryStatementPrintDate_getter", ZDateTime.Today, iEntry.PreliminaryStatementPrintDate);
			AssertEquals("ClientBranchDesignation_getter", "XX", iEntry.ClientBranchDesignation);
			AssertEquals("PeriodicStatementMonth_getter", "02", iEntry.PeriodicStatementMonth);
			AssertEquals("Release Date", new ZDateTime(2013, 03, 01), iEntry.ReleaseDate);
			AssertEquals("ShouldGenerateACEStatementMessage", true, iEntry.ShouldGenerateACEStatementMessage);

			Declaration.US_EntryMode = EntryModeList.Codes.RLF;
			Declaration.US_PreparerDistrictPort = "3901";
			Declaration.US_PreparerOfficeCode = "22";

			AssertEquals("3901", iEntry.PreparerPort);
