		[TestDate(2018, 3, 15)]
		public void TestFTZAdmissionNumberIsFilledInMessageText()
		{
			var iOR = Factory.NewWithValidTestData<OrgHeader>();
			var iorWrapper = OrgHeaderWrapper.New(iOR);
			var fTZStmNum = Factory.New<OrganisationViewStmNums>();
			fTZStmNum.SN_Type = OrgConstants.NumberFountains.Code.FTZAdmissionControlNumber;
			fTZStmNum.SN_ZoneIDPrefix = "1234567";
			fTZStmNum.SN_ClientPrefix = "AAA";
			fTZStmNum.SN_Owner = iOR.PK;
			Factory.Save();

			DeclarationTestHelper.SetEntryFilerCode("SV9");
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.FTZ;
			declaration.JE_TransportMode = TransportTypeList.Codes.Sea;
			declaration.JE_ContainerMode = ContainerModeList.Codes.NonContainerized;
			declaration.IOROrgPK = iOR.PK;
			var bill1 = declaration.Bills.AddNew();
			bill1.CU_BillType = Customs.Business.BillTypeList.Codes.MasterBill;
			bill1.CU_BillNum = "MB1";
			var bill2 = declaration.Bills.AddNew();
			bill2.CU_BillType = Customs.Business.BillTypeList.Codes.MasterBill;
			bill2.CU_BillNum = "MB2";
			Factory.Save();
			IFTZCommonHeader ftzHeader = declaration;
			AssertEquals("FTZAdmissionNumber", ZString.Empty, ftzHeader.FTZAdmissionNumber);
			AssertEquals("ZoneID", ZString.Empty, ftzHeader.ZoneID);
			AssertEquals("CalendarYear", 18, ftzHeader.CalendarYear);
			AssertEquals("ControlNumber", ZString.Empty, ftzHeader.ControlNumber);

			var message1 = new PTTMessageBuilder(declaration, PTTSendingOption.SendPTTMessage).PopulateMessage();
			declaration.Messages.Add(message1);
			var messageAdmissionNumber = "".PadRight(MQEDIMessage.USFTZAdmissionNumberPlaceHolder.Length);
			var messageNumber = MQEDIMessage.MessageNumberPlaceHolder;
			const string messageText = @"B  8888SV9FZ                                               {1}" +
"102MB1                                F           FI                            " +
"102MB2                                F           FI                            " +
"Y  8888SV9FZ";
			AssertXMLEquals("message1.EM_MessageText", string.Format(messageText, messageAdmissionNumber, messageNumber), message1.EM_MessageText);
			Factory.Save();
			messageNumber = message1.EM_MessageNum.PadRight(MQEDIMessage.MessageNumberPlaceHolder.Length);
			AssertXMLEquals("message1.EM_MessageText", string.Format(messageText, messageAdmissionNumber, messageNumber), message1.EM_MessageText);
			AssertEquals("FTZAdmissionNumber", ZString.Empty, ftzHeader.FTZAdmissionNumber);
			AssertEquals("ZoneID", ZString.Empty, ftzHeader.ZoneID);
			AssertEquals("CalendarYear", 18, ftzHeader.CalendarYear);
			AssertEquals("ControlNumber", ZString.Empty, ftzHeader.ControlNumber);

			declaration.FTZZoneID = "123456G";
			AssertEquals("FTZControlNumberIsAutoAllocated", false, declaration.FTZControlNumberIsAutoAllocated);
			AssertEquals("FTZAdmissionNumber", "123456G18", ftzHeader.FTZAdmissionNumber);
			AssertEquals("ZoneID", "123456G", ftzHeader.ZoneID);
			AssertEquals("CalendarYear", 18, ftzHeader.CalendarYear);
			AssertEquals("ControlNumber", ZString.Empty, ftzHeader.ControlNumber);
			var message2 = new PTTMessageBuilder(declaration, PTTSendingOption.SendPTTMessage).PopulateMessage();
			declaration.Messages.Add(message2);
			messageAdmissionNumber = "123456G18".PadRight(MQEDIMessage.USFTZAdmissionNumberPlaceHolder.Length);
			messageNumber = MQEDIMessage.MessageNumberPlaceHolder;

			var messageText2 = @"B  8888SV9FZ                                               {1}" +
"102MB1                                F           FI                            " +
"11               {0}                                           " +
"102MB2                                F           FI                            " +
"11               {0}                                           " +
"Y  8888SV9FZ";

			AssertXMLEquals("message2.EM_MessageText", string.Format(messageText2, messageAdmissionNumber, messageNumber), message2.EM_MessageText);
			Factory.Save();
			messageNumber = message2.EM_MessageNum.PadRight(MQEDIMessage.MessageNumberPlaceHolder.Length);
			AssertXMLEquals("message2.EM_MessageText", string.Format(messageText2, messageAdmissionNumber, messageNumber), message2.EM_MessageText);
			AssertEquals("FTZControlNumberIsAutoAllocated", false, declaration.FTZControlNumberIsAutoAllocated);
			AssertEquals("FTZAdmissionNumber", "123456G18", ftzHeader.FTZAdmissionNumber);
			AssertEquals("ZoneID", "123456G", ftzHeader.ZoneID);
			AssertEquals("CalendarYear", 18, ftzHeader.CalendarYear);
			AssertEquals("ControlNumber", ZString.Empty, ftzHeader.ControlNumber);

			declaration.FTZZoneID = "1234567";
			AssertEquals("FTZControlNumberIsAutoAllocated", true, declaration.FTZControlNumberIsAutoAllocated);
			AssertEquals("FTZAdmissionNumber", MQEDIMessage.USFTZAdmissionNumberPlaceHolder, ftzHeader.FTZAdmissionNumber);
			AssertEquals("ZoneID", "1234567", ftzHeader.ZoneID);
			AssertEquals("CalendarYear", 18, ftzHeader.CalendarYear);
			AssertEquals("ControlNumber", ZString.Empty, ftzHeader.ControlNumber);
			Factory.Save();
			var message3 = new PTTMessageBuilder(declaration, PTTSendingOption.SendPTTMessage).PopulateMessage();
			declaration.Messages.Add(message3);
			messageAdmissionNumber = MQEDIMessage.USFTZAdmissionNumberPlaceHolder;
			messageNumber = MQEDIMessage.MessageNumberPlaceHolder;
			AssertXMLEquals("message3.EM_MessageText", string.Format(messageText2, messageAdmissionNumber, messageNumber), message3.EM_MessageText);
			Factory.Save();
			AssertNotEquals("ControlNumber", ZString.Empty, ftzHeader.ControlNumber);
			messageAdmissionNumber = ("123456718" + ftzHeader.ControlNumber).PadRight(MQEDIMessage.USFTZAdmissionNumberPlaceHolder.Length);
			messageNumber = message3.EM_MessageNum.PadRight(MQEDIMessage.MessageNumberPlaceHolder.Length);
			AssertXMLEquals("message3.EM_MessageText", string.Format(messageText2, messageAdmissionNumber, messageNumber), message3.EM_MessageText);
			AssertEquals("FTZControlNumberIsAutoAllocated", true, declaration.FTZControlNumberIsAutoAllocated);
			AssertEquals("FTZAdmissionNumber", "123456718" + ftzHeader.ControlNumber, ftzHeader.FTZAdmissionNumber);
			AssertEquals("ZoneID", "1234567", ftzHeader.ZoneID);
			AssertEquals("CalendarYear", 18, ftzHeader.CalendarYear);
		}

		public void TestBillsForFTZ()
		{
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.FTZ;
			declaration.JE_TransportMode = TransportTypeList.Codes.Air;

			var bill1 = declaration.Bills.AddNew();
			bill1.CU_BillType = Customs.Business.BillTypeList.Codes.MasterBill;
			bill1.CU_BillNum = "MB1";
			var house1 = bill1.ChildBills.AddNew();
			house1.CU_BillType = Customs.Business.BillTypeList.Codes.HouseBill;

			var house2 = bill1.ChildBills.AddNew();
			house2.CU_BillType = Customs.Business.BillTypeList.Codes.HouseBill;

			var bill2 = declaration.Bills.AddNew();
			bill2.CU_BillType = Customs.Business.BillTypeList.Codes.MasterBill;
			bill2.CU_BillNum = "MB2";
			var house3 = bill2.ChildBills.AddNew();
			house3.CU_BillType = Customs.Business.BillTypeList.Codes.HouseBill;

			var house4 = bill2.ChildBills.AddNew();
			house4.CU_BillType = Customs.Business.BillTypeList.Codes.HouseBill;

			IFTZCommonHeader ftzHeader = declaration;
			AssertEquals("Lowest Bills for Air", 4, ftzHeader.Bills.Count());
			Assert("HB1", ftzHeader.Bills.Contains(house1));
			Assert("HB4", ftzHeader.Bills.Contains(house4));

			declaration.JE_TransportMode = TransportTypeList.Codes.Sea;
			using (ZZCustomsFunctionalityEffectiveDate.TemporarilySetFunctionality(Enterprise.Customs.Universal.Constants.FunctionalityTypes.TypeAMSHBRE, Core.Constants.CountryCodes.UnitedStates, ZDateTime.Today, true))
			{
				AssertEquals("Master Bills only for Sea", 4, ftzHeader.Bills.Count());
				Assert("HB1", ftzHeader.Bills.Contains(house1));
				Assert("HB2", ftzHeader.Bills.Contains(house2));
				Assert("HB3", ftzHeader.Bills.Contains(house3));
				Assert("HB4", ftzHeader.Bills.Contains(house4));
			}
			using (ZZCustomsFunctionalityEffectiveDate.TemporarilySetFunctionality(Enterprise.Customs.Universal.Constants.FunctionalityTypes.TypeAMSHBRE, Core.Constants.CountryCodes.UnitedStates, ZDateTime.Today, false))
			{
				AssertEquals("Master Bills only for Sea", 2, ftzHeader.Bills.Count());
				Assert("MB1", ftzHeader.Bills.Contains(bill1));
				Assert("MB2", ftzHeader.Bills.Contains(bill2));
			}
		}

