		public void TestFTZRemarks()
		{
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.FTZ;
			declaration.US_F_PTTWOExc = true;

			var masterBill = declaration.Bills.AddNew();
			masterBill.CU_BillType = BillTypeList.Codes.MasterBill;
			masterBill.CU_BillNum = "OB125879461";
			masterBill.US_F_FZ10Remarks = "FZ10 Remarks";
			masterBill.US_F_Remarks = "Normal Remarks";

			AssertEquals("No bill reference for single MB", "FZ10 Remarks", declaration.FTZConcurrenceRemarks);
			AssertEquals("No bill reference for single MB", "Normal Remarks", declaration.FTZPTTRemarks);

			var masterBill2 = declaration.Bills.AddNew();
			masterBill2.CU_BillType = BillTypeList.Codes.MasterBill;
			masterBill2.CU_BillNum = "OB652134568";
			masterBill2.US_F_Remarks = "Some more PTT Remarks";

			var masterBill3 = declaration.Bills.AddNew();
			masterBill3.CU_BillType = BillTypeList.Codes.MasterBill;
			masterBill3.CU_BillNum = "OB920198590";
			masterBill3.US_F_FZ10Remarks = "Another set of merch Remarks";

			var houseBill = declaration.Bills.AddNew();
			houseBill.CU_BillType = BillTypeList.Codes.HouseBill;
			houseBill.CU_BillNum = "HB192034881";
			houseBill.US_F_FZ10Remarks = "SHOULD NOT PRINT - HOUSE BILL";
			houseBill.US_F_Remarks = "SHOULD NOT PRINT - HOUSE BILL";

			AssertEquals("Bill reference for multiple MB", "MB:OB125879461 FZ10 Remarks MB:OB920198590 Another set of merch Remarks", declaration.FTZConcurrenceRemarks);
			AssertEquals("Bill reference for multiple MB", "MB:OB125879461 Normal Remarks MB:OB652134568 Some more PTT Remarks", declaration.FTZPTTRemarks);
		}

