		public void TestShouldRefreshLatestRateDateWhenCRLIsAcceptedForACS()
		{
			var audCurr = Factory.LoadFromNaturalKey<RefCurrency>(RefCurrencySchema.RX_Code, Core.Constants.CurrencyCodes.Australia);
			audCurr.ExchangeRates.DeleteAll();

			SetUpExchangeRates(Core.Constants.CurrencyCodes.Australia, new ZDateTime(2012, 3, 1), 1.05m);
			SetUpExchangeRates(Core.Constants.CurrencyCodes.Australia, new ZDateTime(2012, 3, 2), 1.06m);

			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.JE_ExportDate = new ZDateTime(2012, 3, 3);
			declaration.US_EnableCRL = true;
			declaration.US_CargoReleaseType = "CR";
			declaration.US_EntryFilerCode = "XJ5";

			var invoice = declaration.Invoices.AddNew();
			invoice.JZ_RX_NKInvoice_Currency = Core.Constants.CurrencyCodes.Australia;
			invoice.JobComInvoiceLines.AddNew();
			declaration.ResumeApportionment();
			AssertEquals("Exchange rate is refreshed", 1.06m, invoice.JZ_InvoiceCurrExRate);

			var invoice2 = declaration.Invoices.AddNew();
			invoice2.JZ_RX_NKInvoice_Currency = Core.Constants.CurrencyCodes.Australia;
			invoice2.US_DateOfExport = new ZDateTime(2012, 3, 1);
			declaration.ResumeApportionment();
			AssertEquals("Exchange rate is refreshed", 1.05m, invoice2.JZ_InvoiceCurrExRate);
			invoice2.JobComInvoiceLines.AddNew();

			declaration.DoMerge(new SendsMessagesToCustomsShutterUpperer());

			declaration.ActiveEntryHeaders.CargoReleaseEntry.CH_Status = ImportMessageStatusList.Codes.ClearCargoReleaseOriginal;
			declaration.ResumeApportionment();
			Assert(declaration.ActiveEntryHeaders.CargoReleaseEntry.HasBeenLodgedAtCustoms);

			SetUpExchangeRates(Core.Constants.CurrencyCodes.Australia, new ZDateTime(2012, 3, 3), 1.07m);
			declaration.ResumeApportionment();
			Assert("Now recent rate is available, but should not refresh automatically as it is accepted", !declaration.ShouldRefreshExchangeRatesExposed);

			declaration.DoMerge(new SendsMessagesToCustomsShutterUpperer());
			AssertEquals("Exchange rate should remain the same", 1.06m, invoice.JZ_InvoiceCurrExRate);

			declaration.RefreshExchangeRates();//users selected to refresh
			declaration.ResumeApportionment();
			AssertEquals("Exchange rate is refreshed now", 1.07m, invoice.JZ_InvoiceCurrExRate);
		}

