		public void TestHasAESTIRMessageThatNeedsToBeWithdrawn()
		{
			var dec = Factory.New<JobDeclaration>();
			dec.JE_MessageType = JobMessageTypeList.Codes.Export;
			var collection = dec.CustomsEntryHeaders;
			var entry1Mock = Factory.NewMoq<CusEntryHeader>();
			entry1Mock.Setup(m => m.IsWaitingForResponse).Returns(false);
			entry1Mock.Setup(m => m.HasBeenWithdrawn).Returns(false);
			entry1Mock.Setup(m => m.HasBeenLodgedAtCustoms).Returns(true);
			var entry1 = entry1Mock.Object;
			collection.Add(entry1);
			entry1.CH_MessageType = CusEntryHeaderMessageTypeList.Codes.Export;
			entry1.US_IsDeactivated = false;
			var entry2Mock = Factory.NewMoq<CusEntryHeader>();
			entry2Mock.Setup(m => m.IsWaitingForResponse).Returns(false);
			entry2Mock.Setup(m => m.HasBeenWithdrawn).Returns(false);
			entry2Mock.Setup(m => m.HasBeenLodgedAtCustoms).Returns(true);
			var entry2 = entry2Mock.Object;
			collection.Add(entry2);
			entry2.CH_MessageType = CusEntryHeaderMessageTypeList.Codes.Export;
			entry2.US_IsDeactivated = false;

			AssertEquals(false, dec.HasAESTIRMessageThatNeedsToBeWithdrawn);
			entry2.US_IsDeactivated = true;
			AssertEquals(true, dec.HasAESTIRMessageThatNeedsToBeWithdrawn);

			using (dec.ClearAndSuspendAESTIRMessageThatNeedsToBeWithdrawnFlagging())
			{
				AssertEquals(false, dec.HasAESTIRMessageThatNeedsToBeWithdrawn);
				entry2.US_IsDeactivated = true;
				AssertEquals(false, dec.HasAESTIRMessageThatNeedsToBeWithdrawn);
			}

			var entry3Mock = Factory.NewMoq<CusEntryHeader>();
			entry3Mock.Setup(m => m.IsWaitingForResponse).Returns(false);
			entry3Mock.Setup(m => m.HasBeenWithdrawn).Returns(false);
			entry3Mock.Setup(m => m.HasBeenLodgedAtCustoms).Returns(false);
			entry3Mock.Setup(m => m.CH_MessageType).Returns("");
			var entry3 = entry3Mock.Object;
			collection.Add(entry3);
			entry3.US_IsDeactivated = true;
			AssertEquals(false, entry3.CanSendWithdrawal);
			AssertEquals(false, dec.HasAESTIRMessageThatNeedsToBeWithdrawn);
		}

