		public void TestUS_TransportReferenceForAirHasADash()
		{
			var supplier = Factory.NewWithValidTestData<OrgHeader>();
			supplier.OH_Code = "SUP!!!123";
			supplier.OH_IsConsignor = ZBool.True;
			supplier.OH_RL_NKClosestPort = "USLAX";

			var importer = Factory.NewWithValidTestData<OrgHeader>();
			importer.OH_Code = "IMP!!!123";
			importer.OH_IsConsignor = ZBool.True;
			importer.OH_RL_NKClosestPort = "AUSYD";

			var consol = Factory.New<ForwardingConsol>();
			consol.JK_TransportMode = Core.Constants.TransportModes.Air;
			consol.JK_RL_NKLoadPort = "USLAX";
			consol.JK_RL_NKDischargePort = "AUSYD";
			var shipment = consol.Shipments.AddNew();
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_JS = shipment.PK;
			declaration.ShipmentSynchroniser.SetEnabled(true, false);
			declaration.ShipmentSynchroniser.Synchronise(true);
			shipment.ConsignorPK = supplier.PK;
			shipment.ConsigneePK = importer.PK;
			AssertEquals("JE_MessageType", JobMessageTypeList.Codes.Export, declaration.JE_MessageType);
			AssertEquals("JE_TransportMode", TransportTypeList.Codes.Air, declaration.JE_TransportMode);
			consol.JK_MasterBillNum = "012";
			declaration.ShipmentSynchroniser.Synchronise(true);
			AssertEquals("JE_MasterBill", "012", declaration.JE_MasterBill);
			AssertEquals("US_TransportReference", "012", declaration.US_TransportReference);

			consol.JK_MasterBillNum = "012932342";
			declaration.ShipmentSynchroniser.Synchronise(true);
			AssertEquals("JE_MasterBill", "012932342", declaration.JE_MasterBill);
			AssertEquals("US_TransportReference", "012-932342", declaration.US_TransportReference);

			declaration.JE_OverrideFreightDefaults = ZBool.True;
			declaration.JE_MasterBill = "023-421232";
			declaration.US_TransportReference = "03233234";
			AssertEquals("JE_MasterBill", "023421232", declaration.JE_MasterBill);
			AssertEquals("US_TransportReference", "03233234", declaration.US_TransportReference);
		}

		public void TestSetMasterBillNumberForTruck()
		{
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			declaration.US_EnableENS = true;
			declaration.US_CertifyCargoRelease = false;

			var newFactory = new BusinessObjectFactory();
			var startDate = ZDateTime.UtcToday.Date.AddMonths(-1);
			var endDate = ZDateTime.UtcToday.Date.AddMonths(1);
			var helper = new UniversalReferenceTestDataHelper(newFactory);
			var code = helper.CreateNewOrGetExistingCusCodeList(Core.Constants.CountryCodes.UnitedStates, Core.Constants.Customs.Universal.RefCusCodeListTypes.Codes.CustomsOffice, "2704", "Test Name", startDate, endDate);
			newFactory.Save();

			var coll = new BorderCargoPortCollection();
			var bcPort = coll.AddNew();
			bcPort.PortCode = "2704";
			bcPort.CRProcess = CRProcessList.Codes.OneStep;
			bcPort.Location = LocationList.Codes.South;
			USCustomsDataRegistry.Instance.BorderCargoReleasePorts.SetValue(Guid.Empty, declaration.Branch.PK.ToGuid(), Guid.Empty, coll);
			Factory.Save();

			declaration.JE_TransportMode = TransportTypeList.Codes.Truck;
			declaration.US_EntryFilerCode = "XJ5";
			declaration.US_SchDEntry = "2704";
			declaration.AllocateEntryNumber("000001");
			AssertEquals("XJ5000001", declaration.JE_MasterBill);

			//when Entry Type is Consumption FTZ
			declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.JE_TransportMode = TransportTypeList.Codes.Truck;
			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFTZ;
			declaration.US_EntryFilerCode = "XJ5";
			declaration.US_UC_NKCountryOfExport = "MX";
			declaration.AllocateEntryNumber("000001");
			Factory.Save();
			AssertEquals(ZString.Empty, declaration.JE_MasterBill);

			//when there is a master bill entered already
			declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.JE_TransportMode = TransportTypeList.Codes.Truck;
			declaration.US_EntryFilerCode = "XJ5";
			declaration.US_UC_NKCountryOfExport = "MX";
			declaration.JE_MasterBill = "Master";
			declaration.AllocateEntryNumber("000001");
			AssertEquals("Master", declaration.JE_MasterBill);

			//when transport mode changes
			declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EntryFilerCode = "XJ5";
			declaration.US_SchDEntry = "2704";
			declaration.AllocateEntryNumber("");
			declaration.JE_TransportMode = TransportTypeList.Codes.Truck;
			Factory.Save();
			AssertContains("EntryNumber should be allocated to masterbill", "XJ5", declaration.JE_MasterBill);

			declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.JE_TransportMode = TransportTypeList.Codes.Truck;
			declaration.US_EnableENS = true;
			declaration.US_EntryFilerCode = "XJ5";
			declaration.US_SchDEntry = "2704";
			declaration.Invoices.AddNew();
			declaration.InvoiceLines.AddNew();

			declaration.DoMerge(new SendsMessagesToCustomsShutterUpperer());
			Factory.Save();
			AssertContains("EntryNumber should be allocated to masterbill", "XJ5", declaration.JE_MasterBill);
		}

