		public void TestBrokerAddressOfRecord()
		{
			Declaration.Branch.OrgProxy.OH_FullName = "Proxy Company Name";
			Declaration.Branch.OrgProxy.OH_RL_NKClosestPort = "USNAS";
			Declaration.Branch.OrgProxy.MainAddress.OA_Address1 = "Address Line 1";
			Declaration.Branch.OrgProxy.MainAddress.OA_Address2 = "Address Line 2";
			Declaration.Branch.OrgProxy.MainAddress.OA_City = "Nashville";
			Declaration.Branch.OrgProxy.MainAddress.OA_State = "TN";
			Declaration.Branch.OrgProxy.MainAddress.OA_PostCode = "37211";
			ZString expectedOutput = "PROXY COMPANY NAME\nADDRESS LINE 1\nADDRESS LINE 2\nNASHVILLE TN 37211";
			AssertEquals("BrokerAddressOfRecord from Org Proxy when no AddressOfRecord", expectedOutput, Declaration.BrokerAddressOfRecord);

			var customsAddrOfRecord = Factory.Load<OrgHeader>(Declaration.Branch.GB_OH_OrgProxy);
			customsAddrOfRecord.OH_RL_NKClosestPort = "USNAS";
			customsAddrOfRecord.Addresses[0].OA_CompanyNameOverride = "Customs Brokers and Logistics Worldwide";
			customsAddrOfRecord.Addresses[0].OA_Address1 = "Nashville Branch Office";
			customsAddrOfRecord.Addresses[0].OA_Address2 = "115 JonesTown Street";
			customsAddrOfRecord.Addresses[0].OA_City = "Nashville";
			customsAddrOfRecord.Addresses[0].OA_PostCode = "55555";
			customsAddrOfRecord.Addresses[0].OA_State = "TN";
			customsAddrOfRecord.Addresses[0].OA_Phone = "+1 22 456 789";
			customsAddrOfRecord.Addresses[0].OA_Fax = "+1 22 456 799";
			customsAddrOfRecord.Addresses[0].OA_Email = "test@example.com";
			customsAddrOfRecord.Addresses[0].AddressCapability.SetCapabilityEnabled(OrgConstants.AddressType.CustomsAddressOfRecord);
			expectedOutput = "CUSTOMS BROKERS AND LOGISTICS WORLDWIDE\nNASHVILLE BRANCH OFFICE\n115 JONESTOWN STREET\nNASHVILLE TN 55555";
			AssertEquals("BrokerAddressOfRecord should now default from Branch Proxy - Customs Address of Record", expectedOutput, Declaration.BrokerAddressOfRecord);
			AssertEquals("Phone details should now default from Customs Address of Record also", "+1 22 456 789", Declaration.BrokerAddressOfRecordPhone);
			AssertEquals("Fax details should now default from Customs Address of Record also", "+1 22 456 799", Declaration.BrokerAddressOfRecordFax);

			expectedOutput = "Customs Brokers and Logistics Worldwide\nNashville Branch Office, 115 JonesTown Street\nNashville TN 55555";
			AssertEquals("BrokerAddressOfRecordFor368 needs to format Name, Address 1 & 2, and City/State/Postcode into just 3 lines to fit into document box", expectedOutput, Declaration.BrokerAddressOfRecordFor368);
			customsAddrOfRecord.Addresses[0].OA_Address1 = "115 JonesTown Street";
			customsAddrOfRecord.Addresses[0].OA_Address2 = "";
			expectedOutput = "CUSTOMS BROKERS AND LOGISTICS WORLDWIDE\n115 JONESTOWN STREET\nNASHVILLE TN 55555";
			AssertEquals("BrokerAddressOfRecordFor368 can use system formatting when no address line 2", expectedOutput, Declaration.BrokerAddressOfRecordFor368);
		}

		public void TestEntryDateUpdateOtherProperties()
		{
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.JE_TransportMode = TransportTypeList.Codes.Sea;
			declaration.JE_MasterBill = "342098342";
			declaration.JE_VesselName = Factory.LoadTop1<RefVessel>(new ZQuery()).RV_Code;
			declaration.JE_RL_NKPortOfLoading = "GBTIL";
			declaration.JE_ExportDate = new ZDateTime(2011, 7, 5);
			declaration.JE_RL_NKPortOfArrival = "USPHL";
			declaration.JE_DateOfArrival = new ZDateTime(2011, 7, 20);

			AssertEquals("PreCondition:Origin Details defaulted from Load", new ZDateTime(2011, 7, 5), declaration.JE_DateAtOrigin);
			AssertEquals("PreCondition:Origin Details defaulted from Load", "GBTIL", declaration.JE_RL_NKOrigin);

			declaration.JE_RL_NKFinalDestination = "USPHL";
			AssertEquals("PreCondition:Destination Details defaulted from Discharge", new ZDateTime(2011, 7, 20), declaration.JE_DateAtFinalDestination);

			declaration.US_SchDEntry = "1001";
			declaration.US_EntryDate = new ZDateTime(2011, 7, 25);
			AssertEquals("Destination should be updated", new ZDateTime(2011, 7, 25), declaration.JE_DateAtFinalDestination);
			AssertEquals("Precondition: Deferred Tax Due Date is empty", ZDateTime.Empty, declaration.US_DeferredTaxDueDate);

			declaration.US_TaxDeferIndicator = TaxDeferIndicatorList.Codes.DeferredTaxWithEFT;
			declaration.US_EntryDate = new ZDateTime(2011, 7, 26);
			AssertEquals("Deferred Tax Due Date calculated when US_EntryDate has changed", new ZDateTime(2011, 08, 12), declaration.US_DeferredTaxDueDate);

			declaration.US_FixDefTaxDueDate = true;
			declaration.US_EntryDate = new ZDateTime(2011, 7, 01);
			AssertEquals("Deferred Tax Due Date not recalculated when US_EntryDate has changed, because Def Tax Due Date locked", new ZDateTime(2011, 08, 12), declaration.US_DeferredTaxDueDate);
		}

