			declaration.JE_RL_NKPortOfLoading = "AUSYD";
			AssertEquals("AU", declaration.US_UC_NKCountryOfExport);
			declaration.US_UC_NKCountryOfExport = "NZ";
			AssertEquals("NZ", declaration.US_UC_NKCountryOfExport);
			declaration.JE_RL_NKPortOfLoading = "NZAKL";
			AssertEquals("NZ", declaration.US_UC_NKCountryOfExport);
			declaration.US_UC_NKCountryOfExport = "SG";
			declaration.JE_RL_NKPortOfLoading = "AUSYD";
			AssertEquals("SG", declaration.US_UC_NKCountryOfExport);
			declaration.JE_RL_NKPortOfLoading = "SGSIN";
			AssertEquals("SG", declaration.US_UC_NKCountryOfExport);
			declaration.JE_RL_NKPortOfLoading = "AUSYD";
			AssertEquals("AU", declaration.US_UC_NKCountryOfExport);
			declaration.US_UC_NKCountryOfExport = ZString.Empty;
			AssertEquals("", declaration.US_UC_NKCountryOfExport);
			declaration.US_UC_NKCountryOfExport = "NZ";
			AssertEquals("NZ", declaration.US_UC_NKCountryOfExport);
			declaration.JE_RL_NKPortOfLoading = "AUSYD";
			AssertEquals("NZ", declaration.US_UC_NKCountryOfExport);
			declaration.JE_RL_NKPortOfLoading = "NZAKL";
			AssertEquals("NZ", declaration.US_UC_NKCountryOfExport);
			declaration.US_UC_NKCountryOfExport = ZString.Empty;
			declaration.JE_RL_NKPortOfLoading = "MMAYK";
			AssertEquals("MM", declaration.US_UC_NKCountryOfExport);
			declaration.JE_RL_NKPortOfLoading = "BUMMK";
			AssertEquals("BU", declaration.US_UC_NKCountryOfExport);
			declaration.JE_RL_NKPortOfLoading = "NZAKL";
			AssertEquals("NZ", declaration.US_UC_NKCountryOfExport);

			declaration.JE_MessageType = JobMessageTypeList.Codes.Export;
			AssertEquals("NZ", declaration.US_UC_NKCountryOfExport);
			declaration.JE_RL_NKPortOfLoading = "AUSYD";
			AssertEquals("NZ", declaration.US_UC_NKCountryOfExport);

			USCustomsDataRegistry.Instance.DoDefaultCountriesOfOriginAndExport.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, false);
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_UC_NKCountryOfExport = "";
			declaration.JE_RL_NKPortOfLoading = "AUSYD";
			AssertEquals("", declaration.US_UC_NKCountryOfExport);
			declaration.JE_RL_NKPortOfLoading = "NZAKL";
			AssertEquals("", declaration.US_UC_NKCountryOfExport);
			declaration.US_UC_NKCountryOfExport = "AU";
			AssertEquals("AU", declaration.US_UC_NKCountryOfExport);
			declaration.JE_RL_NKPortOfLoading = "AUMEL";
			AssertEquals("AU", declaration.US_UC_NKCountryOfExport);
			declaration.JE_RL_NKPortOfLoading = "NZAKL";
			AssertEquals("AU", declaration.US_UC_NKCountryOfExport);

			AssertEquals(false, declaration.ShouldSynchroniseWithShipment());
			USCustomsDataRegistry.Instance.DoDefaultCountriesOfOriginAndExport.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, true);
			var shipment = Factory.New<ForwardingShipment>();
			shipment.JS_RL_NKOrigin = "NZAKL";
			shipment.JS_RL_NKDestination = "USLAX";
			var consol = shipment.Consols.AddNew();
			consol.JK_RL_NKLoadPort = "AUSYD";
			consol.JK_RL_NKDischargePort = "USCHI";
			declaration.JE_JS = shipment.PK;
			AssertEquals(true, declaration.ShouldSynchroniseWithShipment());
			declaration.ShipmentSynchroniser.Synchronise(true);
			AssertEquals("AUSYD", declaration.JE_RL_NKPortOfLoading);
			AssertEquals("NZ", declaration.US_UC_NKCountryOfExport);
		}

		public void TestIsWarehouseEntryType()
		{
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Export;
			AssertEquals(false, declaration.IsWarehouseEntryType);

			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			AssertEquals(false, declaration.IsWarehouseEntryType);

			declaration.US_EnableENS = true;
			AssertEquals(false, declaration.IsWarehouseEntryType);

			foreach (var entryType in new[]
				{
					EntryTypeList.Codes.WarehouseFTZ,
					EntryTypeList.Codes.Warehouse,
					EntryTypeList.Codes.ReWarehouse
				})
			{
				declaration.US_EntryType = entryType;
				AssertEquals(true, declaration.IsWarehouseEntryType);
			}

			declaration.US_EnableENS = false;
			AssertEquals(false, declaration.IsWarehouseEntryType);

			declaration.US_EnableENS = true;
			AssertEquals(true, declaration.IsWarehouseEntryType);

			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			AssertEquals(false, declaration.IsWarehouseEntryType);
		}

		public void TestIsConsolidatedMonthlyFilingOverPipeline()
		{
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Export;
			Assert(!declaration.IsConsolidatedMonthlyFilingOverPipeline);
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.JE_TransportMode = TransportTypeList.Codes.FixedTransportInstallations;
			Assert(!declaration.IsConsolidatedMonthlyFilingOverPipeline);
			declaration.US_MonthlyFiling = true;
			Assert(declaration.IsConsolidatedMonthlyFilingOverPipeline);
			declaration.US_PayableMPF = 1000m;
			AssertEquals(1000m, ((IDutyDataLineHeaderProvider)declaration).OverridenTotalMPFPayable);

			declaration.JE_TransportMode = TransportTypeList.Codes.Mail;

			Assert(!declaration.US_MonthlyFiling);
			AssertEquals(ZDecimal.Zero, declaration.US_PayableMPF);
			AssertNull(((IDutyDataLineHeaderProvider)declaration).OverridenTotalMPFPayable);
		}

