		public void TestIsENSFormalImportAndConsumptionFTZ()
		{
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Export;
			AssertEquals(false, declaration.IsENSFormalImportAndConsumptionFTZ);

			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			AssertEquals(false, declaration.IsENSFormalImportAndConsumptionFTZ);

			declaration.US_EnableENS = true;
			AssertEquals(false, declaration.IsENSFormalImportAndConsumptionFTZ);

			var list = new EntryTypeList();
			list.RemoveCode(EntryTypeList.Codes.ConsumptionFTZ);

			foreach (ICodeDescription codeDescription in list)
			{
				declaration.US_EntryType = codeDescription.Code;
				AssertEquals(false, declaration.IsENSFormalImportAndConsumptionFTZ);
