		public void TestGetOriginalFDALineForStandalonePriorNotice()
		{
			// Refer CS00135299
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EnableENS = true;

			var invoice = declaration.Invoices.AddNew();
			var invoiceLine1 = invoice.JobComInvoiceLines.AddNew();
			invoiceLine1.JI_Tariff = USCTariff.FDAPriorNoticeRequiredTariff;
			var fda1 = invoiceLine1.FDAs.AddNew();
			fda1.US_FDALineNo = 2;
			var fda2 = invoiceLine1.FDAs.AddNew();
			fda2.US_FDALineNo = 1;

			var invoiceLine2 = invoice.JobComInvoiceLines.AddNew();
			invoiceLine2.JI_Tariff = USCTariff.FDAPriorNoticeRequiredTariff;
			invoiceLine2.JI_LineNo = 1;
			var fda3 = invoiceLine2.FDAs.AddNew();
			fda3.US_FDALineNo = 3;
			var fda4 = invoiceLine2.FDAs.AddNew();
			fda4.US_FDALineNo = 4;
			var fda5 = invoiceLine2.FDAs.AddNew();
			fda5.US_FDALineNo = 5;
			fda5.US_PND = ZBool.True;
			var fda6 = invoiceLine2.FDAs.AddNew();
			fda6.US_FDALineNo = 6;

			var invoiceLine3 = invoice.JobComInvoiceLines.AddNew();
			invoiceLine3.JI_Tariff = USCTariff.FDAPriorNoticeRequiredTariff;
			var fda7 = invoiceLine3.FDAs.AddNew();
			fda7.US_FDALineNo = 9;

			var invoiceLine4 = invoice.JobComInvoiceLines.AddNew();
			invoiceLine4.JI_Tariff = USCTariff.FDAPriorNoticeRequiredTariff;
			var fda8 = invoiceLine4.FDAs.AddNew();
			fda8.US_FDALineNo = 8;

			var invoiceLine5 = invoice.JobComInvoiceLines.AddNew();
			invoiceLine5.JI_Tariff = USCTariff.FDAPriorNoticeRequiredTariff;
			var fda9 = invoiceLine5.FDAs.AddNew();
			fda9.US_FDALineNo = 7;

			declaration.DoMerge(new SendsMessagesToCustomsShutterUpperer());

			IPriorNoticeHeader priorNoticeHeader = declaration;
			IPriorNoticeProcessor fdaHeader = (IPriorNoticeProcessor)priorNoticeHeader;

			AssertEquals("Should find that fda1 has fda line number 2 from original PN message", fda1, fdaHeader.GetOriginalFDALineToAddConfirmationNumber(2, 0));
			AssertEquals("Should find that fda2 has fda line number 1 from original PN message", fda2, fdaHeader.GetOriginalFDALineToAddConfirmationNumber(1, 0));
			AssertEquals("Should find that fda3 has fda line number 3 from original PN message", fda3, fdaHeader.GetOriginalFDALineToAddConfirmationNumber(3, 0));
			AssertEquals("Should find that fda4 has fda line number 4 from original PN message", fda4, fdaHeader.GetOriginalFDALineToAddConfirmationNumber(4, 0));
			AssertEquals("Should find that fda5 has fda line number 5 from original PN message", fda5, fdaHeader.GetOriginalFDALineToAddConfirmationNumber(5, 0));
			AssertEquals("Should find that fda6 has fda line number 6 from original PN message", fda6, fdaHeader.GetOriginalFDALineToAddConfirmationNumber(6, 0));
			AssertEquals("Should find that fda7 has fda line number 9 from original PN message", fda7, fdaHeader.GetOriginalFDALineToAddConfirmationNumber(9, 0));
			AssertEquals("Should find that fda8 has fda line number 8 from original PN message", fda8, fdaHeader.GetOriginalFDALineToAddConfirmationNumber(8, 0));
			AssertEquals("Should find that fda9 has fda line number 7 from original PN message", fda9, fdaHeader.GetOriginalFDALineToAddConfirmationNumber(7, 0));

			fda1.US_PNC = "PNC001002001";
			fda4.US_PNC = "PNC001002002";
			fda6.US_PNC = "PNC001002003";
			fda7.US_PNC = "PNC001002004";

			fda2.US_FDALineNo = 1;
			fda3.US_FDALineNo = 2;
			fda5.US_FDALineNo = 3;
			fda8.US_FDALineNo = 4;
			fda9.US_FDALineNo = 5;

			Factory.Save();

			priorNoticeHeader = declaration;
