		public void TestGetOriginalFDALineForEntryLine()
		{
			// Refer CS00136740
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EnableENS = true;
			declaration.US_EntryFilerCode = "XJ5";
			declaration.JE_MergeBy = OrgConstants.MergeInvoiceLines.Tariff;

			var invoice = declaration.Invoices.AddNew();

			JobComInvoiceLine line1 = declaration.InvoiceLines.AddNew();
			line1.JI_Tariff = "6206900040";
			line1.US_UC_NKCountryOfOrigin = "TW";
			line1.US_UC_NKCountryOfExport = "TW";
			line1.JI_CustomsSecondQuantity = 500m;
			line1.US_CottonFeeExempt = YesNoDefaultList.Codes.Yes;

			JobComInvoiceLine line2 = declaration.InvoiceLines.AddNew();
			line2.JI_Tariff = "6206900040";
			line2.US_UC_NKCountryOfOrigin = "TW";
			line2.US_UC_NKCountryOfExport = "TW";
			line2.JI_CustomsSecondQuantity = 500m;
			line2.US_CottonFeeExempt = YesNoDefaultList.Codes.Yes;

			var fda1_line1 = line1.FDAs.AddNew();
			fda1_line1.US_FDALineNo = 1;
			var fda2_line1 = line1.FDAs.AddNew();
			fda2_line1.US_FDALineNo = 2;

			var fda1_line2 = line2.FDAs.AddNew();
			fda1_line2.US_FDALineNo = 1;

			var fda2_line2 = line2.FDAs.AddNew();
			fda2_line2.US_FDALineNo = 2;

			var fda3_line2 = line2.FDAs.AddNew();
			fda3_line2.US_FDALineNo = 3;
			fda3_line2.US_PND = ZBool.True;

			declaration.DoMerge(new SendsMessagesToCustomsShutterUpperer());
			AssertEquals("Precondition: should be 2 entry lines after merge, we cannot merge lines with FDA", 2, declaration.ActiveEntryHeaders.EntrySummaryEntry.MergedLines.Count);

			IPriorNoticeHeader priorNoticeHeader = declaration;
			IPriorNoticeProcessor fdaHeader = (IPriorNoticeProcessor)priorNoticeHeader;

			AssertEquals(fda1_line1, fdaHeader.GetOriginalFDALineToAddConfirmationNumber(1, 1));
			AssertEquals(fda2_line1, fdaHeader.GetOriginalFDALineToAddConfirmationNumber(2, 1));
			AssertEquals(fda1_line2, fdaHeader.GetOriginalFDALineToAddConfirmationNumber(1, 2));
			AssertEquals(fda2_line2, fdaHeader.GetOriginalFDALineToAddConfirmationNumber(2, 2));
			AssertEquals(fda3_line2, fdaHeader.GetOriginalFDALineToAddConfirmationNumber(3, 2));

			fda1_line1.US_PNC = "PNC001002001";
			fda2_line2.US_PNC = "PNC001002002";
			Factory.Save();

			priorNoticeHeader = declaration;
			fdaHeader = (IPriorNoticeProcessor)priorNoticeHeader;

			AssertEquals(null, fdaHeader.GetOriginalFDALineToAddConfirmationNumber(1, 1));
			AssertEquals(fda2_line1, fdaHeader.GetOriginalFDALineToAddConfirmationNumber(2, 1));
			AssertEquals(fda1_line2, fdaHeader.GetOriginalFDALineToAddConfirmationNumber(1, 2));
			AssertEquals(null, fdaHeader.GetOriginalFDALineToAddConfirmationNumber(2, 2));
			AssertEquals(fda3_line2, fdaHeader.GetOriginalFDALineToAddConfirmationNumber(3, 2));
		}

