		public void TestPackDetailsDefault()
		{
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.JE_MasterBill = ZString.Empty;
			declaration.JE_HouseBill = ZString.Empty;
			declaration.JE_TotalNoOfPacks = 10;
			declaration.JE_TotalNoOfPacksPackType = "NO";
			AssertEquals(0, declaration.Bills.Count);
			AssertEquals(0, declaration.PackingGroups.Count);
			declaration.JE_HouseBill = "HB1";
			AssertEquals(1, declaration.Bills.Count);
			var houseBill = declaration.PrimaryHouseBill;
			AssertEquals(houseBill, declaration.Bills[0]);
			AssertEquals(10m, houseBill.CU_NoOfPacks);
			AssertEquals("NO", houseBill.CU_PackType);
			declaration.JE_TotalNoOfPacks = 15;
			AssertEquals(15m, houseBill.CU_NoOfPacks);
			AssertEquals("NO", houseBill.CU_PackType);
			declaration.JE_TotalNoOfPacksPackType = "KG";
			AssertEquals(15m, houseBill.CU_NoOfPacks);
			AssertEquals("KG", houseBill.CU_PackType);
			declaration.JE_MasterBill = "MB1";
			AssertEquals(2, declaration.Bills.Count);
			var masterBill = declaration.PrimaryMasterBill;
			AssertCollectionContains(masterBill, declaration.Bills);
			AssertEquals(0m, masterBill.CU_NoOfPacks);
			AssertEquals("", masterBill.CU_PackType);
			AssertEquals(15m, houseBill.CU_NoOfPacks);
			AssertEquals("KG", houseBill.CU_PackType);
			declaration.PrimaryHouseBill.Delete();
			declaration.JE_MasterBill = "MB2";
			AssertEquals(1, declaration.Bills.Count);
			masterBill = declaration.PrimaryMasterBill;
			AssertEquals(masterBill, declaration.Bills[0]);
			AssertEquals(15m, masterBill.CU_NoOfPacks);
			AssertEquals("KG", masterBill.CU_PackType);

			declaration.Bills.RemoveAndDeleteAll();
			declaration.JE_TotalNoOfPacks = 10;
			declaration.JE_TotalNoOfPacksPackType = "NO";
			AssertEquals(0, declaration.Bills.Count);
			AssertEquals(0, declaration.PackingGroups.Count);
			declaration.JE_MasterBillIssuerSCAC = "ABCD";
			AssertEquals("bill is created", 10m, declaration.PrimaryMasterBill.CU_NoOfPacks);
			AssertEquals("bill is created", "NO", declaration.PrimaryMasterBill.CU_PackType);
		}

		public void TestMasterBillRelevant()
		{
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_TransportMode = TransportTypeList.Codes.Air;
			Assert(declaration.IsMasterBillRelevant);

			declaration.JE_TransportMode = TransportTypeList.Codes.Auto;
			Assert(!declaration.IsMasterBillRelevant);

			declaration.JE_TransportMode = TransportTypeList.Codes.Rail;
			Assert(declaration.IsMasterBillRelevant);

			declaration.JE_TransportMode = TransportTypeList.Codes.Road;
			Assert(!declaration.IsMasterBillRelevant);

			declaration.JE_TransportMode = TransportTypeList.Codes.Sea;
			Assert(declaration.IsMasterBillRelevant);

			declaration.JE_TransportMode = TransportTypeList.Codes.Pedestrian;
			Assert(!declaration.IsMasterBillRelevant);

			declaration.JE_TransportMode = TransportTypeList.Codes.PassengerHandCarried;
			Assert(declaration.IsMasterBillRelevant);
		}

