		public void TestInBondRelatedRecordsRebuild()
		{
			var declaration = Factory.New<JobDeclaration>();

			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			var message = Factory.New<MQEDIMessage>();
			message.EM_ApplicationCode = EDIMessage.ApplicationCodes.USCustomsImport;
			declaration.Messages.Add(message);

			var invoice = declaration.Invoices.AddNew();
			var invoiceMessage1 = invoice.Messages.AddNew(typeof(EDIMessage));
			invoiceMessage1.EM_ApplicationCode = EDIMessage.ApplicationCodes.USCustomsImport;
			var invoiceMessage2 = invoice.Messages.AddNew(typeof(EDIMessage));
			invoiceMessage2.EM_ApplicationCode = EDIMessage.ApplicationCodes.USCustomsImport;
			Assert(!declaration.HasInactiveMessages);

			message.EM_Status = EDIMessage.Status.Discarded;
			Assert(declaration.HasInactiveMessages);

			declaration.InBondRelatedRecords.ReBuild(MessagesToShowCollection.MessagesStatus.InactiveOnly);
			AssertEquals(1, declaration.InBondRelatedRecords.Count);
			AssertEquals(1, declaration.InBondRelatedRecords[0].MessagesToShow.Count);

			declaration.InBondRelatedRecords.ReBuild(MessagesToShowCollection.MessagesStatus.ActiveOnly);
			AssertEquals(1, declaration.InBondRelatedRecords.Count);
			AssertEquals(2, declaration.InBondRelatedRecords[0].MessagesToShow.Count);
		}

		public void TestInBondRelatedRecordsIncludeEBondMessageAttacher()
		{
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACE;

			declaration.US_EnableENS = true;
			declaration.US_EntryFilerCode = "XXX";
			declaration.US_CargoReleaseType = CargoReleaseTypeList.Codes.ACE;

			declaration.Invoices.AddNew();
			declaration.InvoiceLines.AddNew();
			declaration.DoMerge(new SendsMessagesToCustomsShutterUpperer());

			var ensEntry = declaration.ActiveEntryHeaders.EntrySummaryEntry;
			var seEntry = declaration.ActiveEntryHeaders.SimplifiedEntry;

			var message = Factory.New<EBondEDIMessage>();
			message.EM_LinkTable = CusEntryHeaderSchema.Constants.TableName;
			message.EM_LinkUniqueID = ensEntry.PK;

			AssertEquals("Precondition", 0, ensEntry.Messages.Count);
			AssertEquals("Precondition", 0, seEntry.Messages.Count);

			declaration.InBondRelatedRecords.ReBuild(MessagesToShowCollection.MessagesStatus.ActiveOnly);

			var wrappers = declaration.InBondRelatedRecords.Cast<MessageActionRelatedRecordWrapper>();

			var recordForEntrySummary = wrappers.First(c => (c.relatedRecord as BusinessObject)?.PK == ensEntry.PK);
			AssertNotNull("Should contains ensEntry as it's a valid EBond message attacher.", recordForEntrySummary);
			AssertCollectionContains("Should contains the EBond message for showing.", message, recordForEntrySummary.MessagesToShow);

			var recordForSimplifiedEntry = wrappers.FirstOrDefault(c => (c.relatedRecord as BusinessObject)?.PK == seEntry.PK);
			AssertNull("Should not contains ensEntry as it's not a valid EBond message attacher.", recordForSimplifiedEntry);
		}

