			var message = Factory.New<MQEDIMessage>();
			message.EM_ApplicationCode = EDIMessage.ApplicationCodes.USCustomsImport;
			declaration.Messages.Add(message);

			var liquidation = declaration.Liquidations.AddNew();
			var message2 = Factory.New<MQEDIMessage>();
			message2.EM_ApplicationCode = EDIMessage.ApplicationCodes.USCustomsImport;
			message2.EM_LinkTable = CusLiquidation.Schema.TableName;
			message2.EM_LinkUniqueID = liquidation.PK;

			declaration.InBondRelatedRecords.ReBuild(MessagesToShowCollection.MessagesStatus.ActiveOnly);
			AssertEquals(2, declaration.InBondRelatedRecords.Count);
			AssertEquals(1, declaration.InBondRelatedRecords[0].MessagesToShow.Count);
			AssertEquals(1, declaration.InBondRelatedRecords[1].MessagesToShow.Count);
		}

