		public void TestBrokerToPayIndicator()
		{
			JobDeclaration declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EnableENS = true;
			declaration.US_EntryFilerCode = "XJ5";

			declaration.JE_PaymentMethod = PaymentPartyCodeDescriptionList.Codes.Importer;
			AssertEquals("Broker To Pay should be NO, because Payment Method is importer", YesNoDefaultList.Codes.No, declaration.BrokerToPayIndicator);

			declaration.JE_PaymentMethod = PaymentPartyCodeDescriptionList.Codes.Broker;
			AssertEquals("Broker To Pay should be YES, because Payment Method is Broker", YesNoDefaultList.Codes.Yes, declaration.BrokerToPayIndicator);

			declaration.JE_PaymentMethod = ZString.Empty;
			AssertEquals("BrokerToPayIndicator should be empty", ZString.Empty, declaration.BrokerToPayIndicator);

			declaration.BrokerToPayIndicator = ZString.Empty;
			AssertEquals("Payment Method should be empty, because empty value set", ZString.Empty, declaration.JE_PaymentMethod);
			AssertEquals("BrokerToPayIndicator should be empty, because empty value set", ZString.Empty, declaration.BrokerToPayIndicator);

			declaration.BrokerToPayIndicator = YesNoDefaultList.Codes.Yes;
			AssertEquals("Payment Method should be Broker, because Yes value set", PaymentPartyCodeDescriptionList.Codes.Broker, declaration.JE_PaymentMethod);
			AssertEquals("BrokerToPayIndicator should be Yes", YesNoDefaultList.Codes.Yes, declaration.BrokerToPayIndicator);

			declaration.BrokerToPayIndicator = YesNoDefaultList.Codes.No;
			AssertEquals("Payment Method should be Importer, because NO value set to the indicator", PaymentPartyCodeDescriptionList.Codes.Importer, declaration.JE_PaymentMethod);
			AssertEquals("BrokerToPayIndicator should be NO, because Payment Method is Importer", YesNoDefaultList.Codes.No, declaration.BrokerToPayIndicator);
		}

