		public void TestDefaultJE_ApplicationCode()
		{
			var declaration = Factory.New<JobDeclaration>();
			AssertEquals(DeclarationApplicationCodeList.Codes.Builtin, declaration.JE_ApplicationCode);

			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			AssertEquals(JobApplicationCodeList.Codes.ACE, declaration.JE_ApplicationCode);

			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.JE_MessageType = JobMessageTypeList.Codes.Drawback;
			AssertEquals(JobApplicationCodeList.Codes.ACE, declaration.JE_ApplicationCode);

			declaration.JE_MessageType = JobMessageTypeList.Codes.Miscellaneous;
			AssertEquals(JobApplicationCodeList.Codes.ACE, declaration.JE_ApplicationCode);

			var customsInterface = new LocalCountryCustomsInterface();
			customsInterface.RecipientID = "RecipientID";
			customsInterface.SubmissionType = DeclarationApplicationCodeList.Codes.Interfaced;
			using (CustomsDataRegistry.Instance.LocalCountryCustomsInterface.SetTemporaryValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, customsInterface))
			{
				declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
				AssertEquals(DeclarationApplicationCodeList.Codes.Interfaced, declaration.JE_ApplicationCode);

				declaration.JE_MessageType = JobMessageTypeList.Codes.Drawback;
				AssertEquals(JobApplicationCodeList.Codes.ACE, declaration.JE_ApplicationCode);

				declaration.JE_MessageType = JobMessageTypeList.Codes.Export;
				AssertEquals(DeclarationApplicationCodeList.Codes.Interfaced, declaration.JE_ApplicationCode);

				declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			}
			declaration.JE_MessageType = JobMessageTypeList.Codes.Miscellaneous;
			AssertEquals(JobApplicationCodeList.Codes.ACS, declaration.JE_ApplicationCode);

			declaration.JE_MessageType = JobMessageTypeList.Codes.FTZ;
			AssertEquals(DeclarationApplicationCodeList.Codes.Builtin, declaration.JE_ApplicationCode);

			declaration.ReconDeclaration = new ReconDeclaration(Factory.New<JobDeclaration>());
			declaration.JE_MessageType = JobMessageTypeList.Codes.Recon;
			AssertEquals(JobApplicationCodeList.Codes.ACE, declaration.JE_ApplicationCode);
		}

		public void TestUltimateConsigneeAddressDetails()
		{
			AssertEquals(null, Declaration.EffectiveUltimateConsigneeWrapperAddressDetails);

			var ultimateConsignee = CreateOrgForAddressTest("Ultimate Consignee", "UC Addr 1", "UC Addr 2", "UC City", "", "UC PC");
			Declaration.JE_OA_ConsigneeAddress = ultimateConsignee.MainAddress.PK;
			AssertEquals("Ultimate Consignee", Declaration.EffectiveUltimateConsigneeWrapperAddressDetails.CompanyName);
			var assertionMessage = " from Main Address";
			AssertEquals("Address 1" + assertionMessage, "UC Addr 1", Declaration.EffectiveUltimateConsigneeWrapperAddressDetails.AddressLine1);
			AssertEquals("Address 2" + assertionMessage, "UC Addr 2", Declaration.EffectiveUltimateConsigneeWrapperAddressDetails.AddressLine2);
			AssertEquals("City" + assertionMessage, "UC City", Declaration.EffectiveUltimateConsigneeWrapperAddressDetails.City);
			AssertEquals("State" + assertionMessage, "", Declaration.EffectiveUltimateConsigneeWrapperAddressDetails.State);
			AssertEquals("Post Code" + assertionMessage, "UC PC", Declaration.EffectiveUltimateConsigneeWrapperAddressDetails.PostCode);
			AssertEquals("Ultimate consignee address details - Line 1", "UC Addr 1", Declaration.EffectiveUltimateConsigneeWrapperAddressDetails.AddressLine1);
			AssertEquals("Ultimate consignee address details - Line 2", "UC Addr 2", Declaration.EffectiveUltimateConsigneeAddressLine2);
			AssertEquals("Ultimate Consignee city / state / postcode / country string", "UC City   UC PC", Declaration.EffectiveUltimateConsigneeCityStatePostCodeCountry);

			AddCustomsAddress(ultimateConsignee, "Customs Address Line 1", "Customs Address Line 2", "Michigan City", "IL", "59650");
			AssertEquals("Ultimate Consignee", Declaration.EffectiveUltimateConsigneeWrapperAddressDetails.CompanyName);
			assertionMessage = " should comes from Customs Address";
			AssertEquals("Address 1" + assertionMessage, "Customs Address Line 1", Declaration.EffectiveUltimateConsigneeWrapperAddressDetails.AddressLine1);
			AssertEquals("Address 2" + assertionMessage, "Customs Address Line 2", Declaration.EffectiveUltimateConsigneeWrapperAddressDetails.AddressLine2);
			AssertEquals("City" + assertionMessage, "Michigan City", Declaration.EffectiveUltimateConsigneeWrapperAddressDetails.City);
			AssertEquals("State" + assertionMessage, "IL", Declaration.EffectiveUltimateConsigneeWrapperAddressDetails.State);
			AssertEquals("Post Code" + assertionMessage, "59650", Declaration.EffectiveUltimateConsigneeWrapperAddressDetails.PostCode);
			AssertEquals("Ultimate consignee address details - Line 1", "Customs Address Line 1", Declaration.EffectiveUltimateConsigneeWrapperAddressDetails.AddressLine1);
			AssertEquals("Ultimate consignee address details - Line 2", "Customs Address Line 2", Declaration.EffectiveUltimateConsigneeAddressLine2);
			AssertEquals("Ultimate Consignee city / state / postcode / country string", "Michigan City   IL   59650   US", Declaration.EffectiveUltimateConsigneeCityStatePostCodeCountry);

			var ultimateConsignee2 = Factory.New<OrgHeader>();
			ultimateConsignee2.FillWithValidTestData();
			ultimateConsignee2.OH_FullName = "Ultimate Consignee 2";

			var invoice = Declaration.Invoices.AddNew();
			var invoiceLine = invoice.InvoiceLines.AddNew();
			invoiceLine.JI_OA_ConsigneeAddress = ultimateConsignee2.MainAddress.PK;
			AssertEquals("Multiple consignees - should still return Declaration Ultimate Consignee", "Ultimate Consignee", Declaration.EffectiveUltimateConsigneeWrapperAddressDetails.CompanyName);
			assertionMessage = "Ultimate consignee address details should still return Declaration Ultimate Consignee details when multiple consignees exist";
			AssertEquals(assertionMessage, "Customs Address Line 1", Declaration.EffectiveUltimateConsigneeWrapperAddressDetails.AddressLine1);
			AssertEquals(assertionMessage, "Customs Address Line 2", Declaration.EffectiveUltimateConsigneeAddressLine2);
			AssertEquals(assertionMessage, "Michigan City   IL   59650   US", Declaration.EffectiveUltimateConsigneeCityStatePostCodeCountry);

			var customsAddress = ultimateConsignee.Addresses.AddressesOfType(OrgConstants.AddressType.CustomsAddressOfRecord)[0];
			customsAddress.OA_Address2 = ZString.Empty;
			AssertEquals("EffectiveUltimateConsigneeAddressLine2 should now show city state postcode line", "Michigan City   IL   59650   US", Declaration.EffectiveUltimateConsigneeAddressLine2);
			AssertEquals("Ultimate Consignee city / state / postcode / country string should be blank as has been move up 1 line", "", Declaration.EffectiveUltimateConsigneeCityStatePostCodeCountry);

			customsAddress.OA_Address2 = "Address line 2";
			customsAddress.OA_City = "";
			customsAddress.OA_PostCode = "59650";
			customsAddress.OA_State = "";
			AssertEquals("Address Line 2", "Address line 2", Declaration.EffectiveUltimateConsigneeAddressLine2);
			AssertEquals("Ultimate Consignee city / state / postcode / country string when no city or state should be trimmed start",
						"59650   US", Declaration.EffectiveUltimateConsigneeCityStatePostCodeCountry);
		}

		OrgHeader CreateOrgForAddressTest(ZString name, ZString adr1, ZString adr2, ZString city, ZString state, ZString postCode)
		{
			var org = Factory.New<OrgHeader>();
			org.FillWithValidTestData();
			org.OH_FullName = name;
			org.MainAddress.OA_Address1 = adr1;
			org.MainAddress.OA_Address2 = adr2;
			org.MainAddress.OA_City = city;
			org.MainAddress.OA_State = state;
			org.MainAddress.OA_PostCode = postCode;
			return org;
		}

		void AddCustomsAddress(OrgHeader header, ZString adr1, ZString adr2, ZString city, ZString state, ZString postCode)
		{
			var impoterCustomsAddress = header.Addresses.AddNew();
			impoterCustomsAddress.AddressCapability.SetCapabilityEnabled(OrgConstants.AddressType.CustomsAddressOfRecord);
			impoterCustomsAddress.OA_Address1 = adr1;
			impoterCustomsAddress.OA_Address2 = adr2;
			impoterCustomsAddress.OA_City = city;
			impoterCustomsAddress.OA_State = state;
			impoterCustomsAddress.OA_PostCode = postCode;
		}

