		void AssertShouldUpdateScreeningStatus(ZGuid oldGuid, ZGuid newGuid, PartyOrAddress decRelatedPartyOrAddress, bool expectedShouldUpdateScreeningStatus)
		{
			var branch = Factory.NewWithValidTestData<GlbBranch>();
			branch.GB_RN_NKCountryCode = "US";

			var declaration = Factory.NewWithValidTestData<JobDeclaration>();
			declaration.JE_GB = branch.PK;

			switch (decRelatedPartyOrAddress)
			{
				case PartyOrAddress.ConsigneeAddress:
					declaration.JE_OA_ConsigneeAddress = oldGuid;
					Factory.Save();
					declaration.JE_OA_ConsigneeAddress = newGuid;
					break;
				case PartyOrAddress.Exporter:
					declaration.JE_OH_Exporter = oldGuid;
					Factory.Save();
					declaration.JE_OH_Exporter = newGuid;
					break;
				case PartyOrAddress.SellerAddress:
					declaration.JE_OA_SellerAddress = oldGuid;
					Factory.Save();
					declaration.JE_OA_SellerAddress = newGuid;
					break;
				case PartyOrAddress.ShipperAddress:
					declaration.JE_OA_ShipperAddress = oldGuid;
					Factory.Save();
					declaration.JE_OA_ShipperAddress = newGuid;
					break;
				case PartyOrAddress.DistributorAddress:
					declaration.JE_OA_DistributorAddress = oldGuid;
					Factory.Save();
					declaration.JE_OA_DistributorAddress = newGuid;
					break;
				case PartyOrAddress.Buyer:
					declaration.JE_OH_Buyer = oldGuid;
					Factory.Save();
					declaration.JE_OH_Buyer = newGuid;
					break;
				case PartyOrAddress.PackagerAddress:
					declaration.JE_OA_PackagerAddress = oldGuid;
					Factory.Save();
					declaration.JE_OA_PackagerAddress = newGuid;
					break;
				case PartyOrAddress.ExternalBroker:
					declaration.JE_OH_ExternalBroker = oldGuid;
					Factory.Save();
					declaration.JE_OH_ExternalBroker = newGuid;
					break;
				case PartyOrAddress.ControllingAgent:
					declaration.JE_OH_ControllingAgent = oldGuid;
					Factory.Save();
					declaration.JE_OH_ControllingAgent = newGuid;
					break;
				case PartyOrAddress.ControllingCustomer:
					declaration.JE_OH_ControllingCustomer = oldGuid;
					Factory.Save();
					declaration.JE_OH_ControllingCustomer = newGuid;
					break;
				case PartyOrAddress.SoldToPartyAddress:
					declaration.JE_OA_SoldToPartyAddress = oldGuid;
					Factory.Save();
					declaration.JE_OA_SoldToPartyAddress = newGuid;
					break;
				case PartyOrAddress.ShipToPartyAddress:
					declaration.JE_OA_ShipToPartyAddress = oldGuid;
					Factory.Save();
					declaration.JE_OA_ShipToPartyAddress = newGuid;
					break;
				case PartyOrAddress.ManufacturerAddress:
					declaration.JE_OA_ManufacturerAddress = oldGuid;
					Factory.Save();
					declaration.JE_OA_ManufacturerAddress = newGuid;
					break;
				case PartyOrAddress.NotifyParty:
					declaration.JE_OH_NotifyParty = oldGuid;
					Factory.Save();
					declaration.JE_OH_NotifyParty = newGuid;
					break;
				default:
					break;
			}

			AssertEquals(expectedShouldUpdateScreeningStatus, (declaration as IShouldUpdateScreeningStatus).ShouldUpdateScreeningStatus);
		}

		enum PartyOrAddress
		{
			ConsigneeAddress,
			Exporter,
			SellerAddress,
			ShipperAddress,
			DistributorAddress,
			Buyer,
			PackagerAddress,
			ExternalBroker,
			ControllingAgent,
			ControllingCustomer,
			SoldToPartyAddress,
			ShipToPartyAddress,
			ManufacturerAddress,
			NotifyParty
		}

