		public void TestChangePickupAddressToUpdateOnInvoiceHeader()
		{
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Export;

			RefUNLOCO unloco = Factory.New<RefUNLOCO>();
			unloco.RL_Code = "USL1%";
			var supplierOrg = Factory.NewWithValidTestData<OrgHeader>();
			supplierOrg.OH_Code = "SUPORG";
			supplierOrg.Addresses.OfType<OrgAddress>().ForEach(x => x.OA_RL_NKRelatedPortCode = Core.Constants.CountryCodes.UnitedStates);

			var consigneeOrg = Factory.NewWithValidTestData<OrgHeader>();
			consigneeOrg.OH_Code = "CONORG";

			var pickupAddressOrg = Factory.New<OrgHeader>();
			pickupAddressOrg.OH_Code = "PCKUPA";
			pickupAddressOrg.OH_RL_NKClosestPort = unloco.RL_Code;
			pickupAddressOrg.MainAddress.OA_Address1 = "USAddress1";
			pickupAddressOrg.MainAddress.OA_RN_NKCountryCode = Core.Constants.CountryCodes.UnitedStates;
			var addresspickup2 = pickupAddressOrg.Addresses.AddNew();
			addresspickup2.OA_RL_NKRelatedPortCode = unloco.RL_Code;
			addresspickup2.OA_State = USStatesList.Codes.Pennsylvania;
			var addresspickup3 = pickupAddressOrg.Addresses.AddNew();
			addresspickup2.OA_RL_NKRelatedPortCode = unloco.RL_Code;
			addresspickup3.OA_State = USStatesList.Codes.Colorado;

			declaration.JE_OH_Importer = consigneeOrg.PK;
			declaration.JE_OH_Supplier = supplierOrg.PK;
			AssertEquals("default by Supplier", supplierOrg.PK, declaration.SupplierPickupAddress.OrganisationPK);
			declaration.SupplierPickupAddress.E2_RN_NKCountryCode = Core.Constants.CountryCodes.UnitedStates;

			var invoice = declaration.Invoices.AddNew();
			invoice.JZ_InvoiceAmount = 1.0m;
			AssertEquals("default when invoiceHeader created", supplierOrg.PK, invoice.US_USPPI.ZO_OH_Organisation);
			AssertEquals("default when invoiceHeader created", supplierOrg.PK, invoice.SupplierPickupAddress.OrganisationPK);

			declaration.SupplierPickupAddress.OrganisationPK = pickupAddressOrg.PK;
			AssertEquals("InvoiceHeader Picup Address has updated when changed pickup address.", pickupAddressOrg.PK, invoice.SupplierPickupAddress.OrganisationPK);
		}

		public void TestGetScreeningParties()
		{
