			AssertEquals("Invoice Intermediate Consignee", intermediateConsignee.OH_Code, Array.Find(deniedCandidates, x => x.Description == "US - Invoice Intermediate Consignee").OrgCode);
			AssertEquals("Invoice Pickup Address", pickupAddress.OH_Code, Array.Find(deniedCandidates, x => x.Description == "US - Invoice Pickup Address").OrgCode);

			AssertEquals(org.OH_Code, Array.Find(deniedCandidates, x => x.Description == "US - Consignee Address").OrgCode);
			AssertEquals(org.OH_Code, Array.Find(deniedCandidates, x => x.Description == "US - Exporter").OrgCode);
			AssertEquals(org.OH_Code, Array.Find(deniedCandidates, x => x.Description == "US - Seller").OrgCode);
			AssertEquals(org.OH_Code, Array.Find(deniedCandidates, x => x.Description == "US - Shipper").OrgCode);
			AssertEquals(org.OH_Code, Array.Find(deniedCandidates, x => x.Description == "US - Distributor").OrgCode);
			AssertEquals(org.OH_Code, Array.Find(deniedCandidates, x => x.Description == "US - Buyer").OrgCode);
			AssertEquals(org.OH_Code, Array.Find(deniedCandidates, x => x.Description == "US - Packager").OrgCode);
			AssertEquals(org.OH_Code, Array.Find(deniedCandidates, x => x.Description == "US - External Broker").OrgCode);
			AssertEquals(org.OH_Code, Array.Find(deniedCandidates, x => x.Description == "US - Controlling Agent").OrgCode);
			AssertEquals(org.OH_Code, Array.Find(deniedCandidates, x => x.Description == "US - Controlling Customer").OrgCode);
			AssertEquals(org.OH_Code, Array.Find(deniedCandidates, x => x.Description == "US - Sold To Party").OrgCode);
			AssertEquals(org.OH_Code, Array.Find(deniedCandidates, x => x.Description == "US - Ship To Party").OrgCode);
			AssertEquals(org.OH_Code, Array.Find(deniedCandidates, x => x.Description == "US - Manufacturer").OrgCode);
			AssertEquals(org.OH_Code, Array.Find(deniedCandidates, x => x.Description == "US - 4811 Party").OrgCode);

			invoice.USPPIDocAddress.E2_AddressOverride = true;
			invoice.UltimateConsigneeDocAddress.E2_AddressOverride = true;
			invoice.IntermediateConsigneeDocAddress.E2_AddressOverride = true;
			invoice.SupplierPickupAddress.E2_AddressOverride = true;

			deniedCandidates = ((IScreeningPartyProvider)declaration).ScreeningParties;
			AssertNotNull(Array.Find(deniedCandidates, x => x.Description == "US - Invoice Ultimate Supplier").OrgCode);
			AssertNotNull(Array.Find(deniedCandidates, x => x.Description == "US - Invoice Ultimate Consignee").OrgCode);
			AssertNotNull(Array.Find(deniedCandidates, x => x.Description == "US - Invoice Intermediate Consignee").OrgCode);
			AssertNotNull(Array.Find(deniedCandidates, x => x.Description == "US - Invoice Pickup Address").OrgCode);
		}

		public void TestGetScreeningStatus()
		{
			var declaration = Factory.NewWithValidTestData<JobDeclaration>();
			Factory.Save();
			AssertEquals(ScreeningStatusesList.Codes.NotScreened, declaration.JE_ScreeningStatus);

			var intermConsignee1 = Factory.NewWithValidTestData<OrgHeader>();
			intermConsignee1.OH_ScreeningStatus = ScreeningStatusesList.Codes.Matched;
			declaration.JE_OH_Consignee = intermConsignee1.PK;
			Factory.Save();
			AssertEquals(ScreeningStatusesList.Codes.Matched, declaration.JE_ScreeningStatus);

			var intermConsignee2 = Factory.NewWithValidTestData<OrgHeader>();
			intermConsignee2.OH_ScreeningStatus = ScreeningStatusesList.Codes.Clear;
			declaration.JE_OH_Consignee = intermConsignee2.PK;
			Factory.Save();
			AssertEquals(ScreeningStatusesList.Codes.Clear, declaration.JE_ScreeningStatus);

			var invoice = declaration.Invoices.AddNew();
			declaration.IntermConsignee.OH_ScreeningStatus = ScreeningStatusesList.Codes.Clear;

			var ultimateSupplier1 = Factory.NewWithValidTestData<OrgHeader>();
			ultimateSupplier1.OH_ScreeningStatus = ScreeningStatusesList.Codes.Unknown;
			invoice.US_USPPI.ZO_OH_Organisation = ultimateSupplier1.PK;
			Factory.Save();
			AssertEquals(ScreeningStatusesList.Codes.Unknown, declaration.JE_ScreeningStatus);

			var ultimateConsignee1 = Factory.NewWithValidTestData<OrgHeader>();
			ultimateConsignee1.OH_ScreeningStatus = ScreeningStatusesList.Codes.NotScreened;
			invoice.US_ExportUltimateConsignee.ZO_OH_Organisation = ultimateConsignee1.PK;
			Factory.Save();
			AssertEquals(ScreeningStatusesList.Codes.NotScreened, declaration.JE_ScreeningStatus);

			var intermediateConsignee1 = Factory.NewWithValidTestData<OrgHeader>();
			intermediateConsignee1.OH_ScreeningStatus = ScreeningStatusesList.Codes.Matched;
			invoice.JZ_OH_Consignee = intermediateConsignee1.PK;
			Factory.Save();
			AssertEquals(ScreeningStatusesList.Codes.Matched, declaration.JE_ScreeningStatus);

			declaration = Factory.NewWithValidTestData<JobDeclaration>();
			invoice = declaration.Invoices.AddNew();
			invoice.USPPIDocAddress.E2_ScreeningStatus = ScreeningStatusesList.Codes.Unknown;
			invoice.USPPIDocAddress.E2_AddressOverride = true;
			Factory.Save();
			AssertEquals(ScreeningStatusesList.Codes.Unknown, declaration.JE_ScreeningStatus);

			invoice.UltimateConsigneeDocAddress.E2_ScreeningStatus = ScreeningStatusesList.Codes.NotScreened;
			invoice.UltimateConsigneeDocAddress.E2_AddressOverride = true;
			Factory.Save();
			AssertEquals(ScreeningStatusesList.Codes.NotScreened, declaration.JE_ScreeningStatus);

			invoice.IntermediateConsigneeDocAddress.E2_ScreeningStatus = ScreeningStatusesList.Codes.Matched;
			invoice.IntermediateConsigneeDocAddress.E2_AddressOverride = true;
			Factory.Save();
			AssertEquals(ScreeningStatusesList.Codes.Matched, declaration.JE_ScreeningStatus);

			invoice.IntermediateConsigneeDocAddress.E2_ScreeningStatus = ScreeningStatusesList.Codes.Clear;
			invoice.SupplierPickupAddress.E2_ScreeningStatus = ScreeningStatusesList.Codes.NotScreened;
			invoice.SupplierPickupAddress.E2_AddressOverride = true;
			invoice.SupplierPickupAddress.E2_Address1 = "ABC ABC";
			Factory.Save();
			AssertEquals(ScreeningStatusesList.Codes.NotScreened, declaration.JE_ScreeningStatus);

			invoice.SupplierPickupAddress.E2_ScreeningStatus = ScreeningStatusesList.Codes.Matched;
			Factory.Save();
			AssertEquals(ScreeningStatusesList.Codes.Matched, declaration.JE_ScreeningStatus);

			var matchedOrg = Factory.NewWithValidTestData<OrgHeader>();
