		public void TestPortOfDischargeDefaultsSchDPortWithPriority1()
		{
			var helper = new UniversalReferenceTestDataHelper(Factory);
			helper.CreateNewOrGetExistingCusCodeType(Core.Constants.Customs.Universal.RefCusCodeListTypes.Codes.CustomsOffice, "CUSOF");
			helper.CreateNewOrGetExistingCusCodeList(Core.Constants.CountryCodes.UnitedStates, Core.Constants.Customs.Universal.RefCusCodeListTypes.Codes.CustomsOffice, "1001", "Test Name", new ZDateTime(1900, 1, 1), new ZDateTime(2079, 6, 6));
			helper.CreateNewOrGetExistingCusCodeList(Core.Constants.CountryCodes.UnitedStates, Core.Constants.Customs.Universal.RefCusCodeListTypes.Codes.CustomsOffice, "1002", "Test Name", new ZDateTime(1900, 1, 1), new ZDateTime(2079, 6, 6));
			helper.CreateNewOrGetExistingCusCodeList(Core.Constants.CountryCodes.UnitedStates, Core.Constants.Customs.Universal.RefCusCodeListTypes.Codes.CustomsOffice, "1003", "Test Name", new ZDateTime(1900, 1, 1), new ZDateTime(2079, 6, 6));
			helper.CreateNewOrGetExistingCusCodeList(Core.Constants.CountryCodes.UnitedStates, Core.Constants.Customs.Universal.RefCusCodeListTypes.Codes.CustomsOffice, "1004", "Test Name", new ZDateTime(1900, 1, 1), new ZDateTime(2079, 6, 6));
			helper.CreateNewOrGetExistingCusCodeList(Core.Constants.CountryCodes.UnitedStates, Core.Constants.Customs.Universal.RefCusCodeListTypes.Codes.CustomsOffice, "1005", "Test Name", new ZDateTime(1900, 1, 1), new ZDateTime(2079, 6, 6));
			helper.CreateNewOrGetExistingCusCodeList(Core.Constants.CountryCodes.UnitedStates, Core.Constants.Customs.Universal.RefCusCodeListTypes.Codes.CustomsOffice, "1006", "Test Name", new ZDateTime(1900, 1, 1), new ZDateTime(2079, 6, 6));
			helper.CreateNewOrGetExistingCusCodeList(Core.Constants.CountryCodes.UnitedStates, Core.Constants.Customs.Universal.RefCusCodeListTypes.Codes.CustomsOffice, "1007", "Test Name", new ZDateTime(1900, 1, 1), new ZDateTime(2079, 6, 6));
			helper.CreateNewOrGetExistingCusCodeList(Core.Constants.CountryCodes.UnitedStates, Core.Constants.Customs.Universal.RefCusCodeListTypes.Codes.CustomsOffice, "1008", "Test Name", new ZDateTime(1900, 1, 1), new ZDateTime(2079, 6, 6));
			Factory.Save();

			string loco1 = "USDD1";
			CreateLocoIfNotExists(loco1, "US");

			var locoMap1001 = CreateLocoMapIfNotExists("1001", loco1, USLocoMapSystemUsageList.Codes.Sea, true);
			var locoMap1002 = CreateLocoMapIfNotExists("1002", loco1, USLocoMapSystemUsageList.Codes.SCD, true);
			var locoMap1003 = CreateLocoMapIfNotExists("1003", loco1, USLocoMapSystemUsageList.Codes.Air, true);
			var locoMap1004 = CreateLocoMapIfNotExists("1004", loco1, USLocoMapSystemUsageList.Codes.Air, false);
			var locoMap1006 = CreateLocoMapIfNotExists("1006", loco1, USLocoMapSystemUsageList.Codes.Air, false);
			var locoMap1007 = CreateLocoMapIfNotExists("1007", loco1, USLocoMapSystemUsageList.Codes.Sea, false);
			var locoMap1008 = CreateLocoMapIfNotExists("1008", loco1, USLocoMapSystemUsageList.Codes.All);

			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_TransportMode = TransportTypeList.Codes.Air;
			declaration.JE_RL_NKPortOfArrival = loco1;
			AssertEquals("Pre-condition: Should be 3 local port mapping code for USDD1", 3, declaration.PortOfArrivalRefLocoMappings.Count);
			AssertEquals("Local scheduleD code for Chicago should NOT default", ZString.Empty, declaration.US_SchDArrival);

			declaration.JE_RL_NKPortOfArrival = ZString.Empty;
			locoMap1006.Delete();
			declaration.JE_RL_NKPortOfArrival = loco1;
			AssertEquals("Pre-condition: Should only be 2 local port mapping code for USDD1", 2, declaration.PortOfArrivalRefLocoMappings.Count);
			AssertEquals("Local scheduleD has multiple ports", "", declaration.US_SchDArrival);

			declaration.JE_RL_NKPortOfArrival = ZString.Empty;
			locoMap1004.Delete();
			declaration.JE_RL_NKPortOfArrival = loco1;
			AssertEquals("Pre-condition: Should only be 1 local port mapping code for USDD1", 1, declaration.PortOfArrivalRefLocoMappings.Count);
			AssertEquals("Local scheduleD code for Chicago should default system definied code", "1003", declaration.US_SchDArrival);
		}

