			var locoMap2772 = CreateLocoMapIfNotExists("2772", "USLAX", USLocoMapSystemUsageList.Codes.SCD, false);
			var locoMap2775 = CreateLocoMapIfNotExists("2775", "USLAX", USLocoMapSystemUsageList.Codes.Air, false);
			var locoMap2791 = CreateLocoMapIfNotExists("2791", "USLAX", USLocoMapSystemUsageList.Codes.Air, false);
			var locoMap2704 = CreateLocoMapIfNotExists("2704", "USLAX", USLocoMapSystemUsageList.Codes.Sea, false);
			var locoMap2776 = CreateLocoMapIfNotExists("2776", "USLAX", USLocoMapSystemUsageList.Codes.Air, false);
			var locoMap2720 = CreateLocoMapIfNotExists("2720", "USLAX", USLocoMapSystemUsageList.Codes.Air, false);
