		public void TestIsNonTransportDeclarationType()
		{
			Declaration.JE_MessageType = JobMessageTypeList.Codes.Export;
			Assert("Export is TransportDeclarationType", !Declaration.IsNonTransportDeclarationType);
			Declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			Declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			Assert("Import is TransportDeclarationType", !Declaration.IsNonTransportDeclarationType);
			Declaration.JE_MessageType = JobMessageTypeList.Codes.Drawback;
			Assert("Drawback is NonTransportDeclarationType", Declaration.IsNonTransportDeclarationType);
			Declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			Declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			Declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFTZ;
			Assert("Import from FTZ is NonTransportDeclarationType", Declaration.IsNonTransportDeclarationType);
			Declaration.US_EntryType = EntryTypeList.Codes.ReWarehouse;
			Assert("Import from ReWarehouse is NonTransportDeclarationType", Declaration.IsNonTransportDeclarationType);
		}

