		public void TestIAutoRatingCustomsInfoEntries()
		{
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EnableENS = true;
			declaration.US_EnableCRL = true;
			declaration.JE_MergeBy = OrgConstants.MergeInvoiceLines.NotMerge;

			var invoice1 = declaration.Invoices.AddNew();
			invoice1.JobComInvoiceLines.AddNew();
			invoice1.JobComInvoiceLines.AddNew();

			var invoice2 = declaration.Invoices.AddNew();
			invoice2.JobComInvoiceLines.AddNew();
			var invoiceLine = invoice2.JobComInvoiceLines.AddNew();
			var secondaryLine = invoiceLine.AddSecondaryInvoiceLine();
			invoice2.JobComInvoiceLines.AddNew();

			declaration.DoMerge(new SendsMessagesToCustomsShutterUpperer());

			var entries = ((IAutoRatingCustomsInfo)declaration.RatingAdapter).Entries;
			AssertEquals("For import, it only take ENS entry summary entry into consideration when auto-rating", 1, entries.Count);

			var entry = entries[0];
			AssertEquals("EntryLine count", 5, entry.EntryLines);
			AssertEquals("InvoiceLines count - disregard secondary lines", 5, entry.InvoiceLines);

			declaration.JE_MessageType = JobMessageTypeList.Codes.Export;
			invoice1.US_HazardousCargo = YesNoDefaultList.Codes.Yes;
			invoice2.US_HazardousCargo = YesNoDefaultList.Codes.No;
			secondaryLine.JI_ParentID = ZGuid.Empty;
			declaration.DoMerge(new SendsMessagesToCustomsShutterUpperer());

			entries = ((IAutoRatingCustomsInfo)declaration.RatingAdapter).Entries;
			AssertEquals("For export", 2, entries.Count);
			var entry1 = entries[0];
			var entry2 = entries[1];
			if (entry1.EntryLines == 4)
			{
				entry1 = entries[1];
				entry2 = entries[0];
			}
			AssertEquals("EntryLine count", 2, entry1.EntryLines);
			AssertEquals("InvoiceLines count", 2, entry1.InvoiceLines);

			AssertEquals("EntryLine count", 4, entry2.EntryLines);
			AssertEquals("InvoiceLines count", 4, entry2.InvoiceLines);
		}

