		public void TestChangingTariffTypeShouldRefreshTariffsForAllLines()
		{
			//reference file is updated
			var helper = new UniversalReferenceTestDataHelper(Factory);
			var cusTariffTypeSB = helper.CreateNewOrGetExistingTariffType(Core.Constants.CountryCodes.UnitedStates, Universal.Constants.TariffTypes.ScheduleB);
			Factory.Save();

			var tariff = helper.LoadOrCreateNewTariff(Core.Constants.CountryCodes.UnitedStates, cusTariffTypeSB.PK, "0000000000", ZDateTime.Today.AddYears(-1), ZDateTime.Today.AddYears(1));
			tariff.ZZ1_Description = "TEST";
			helper.CreateTariffUOM(tariff, "CU1", "KG");

			JobDeclaration declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Export;
			declaration.US_TariffType = TariffTypeList.Codes.HTS;

			declaration.Invoices.AddNew();

			JobComInvoiceLine invoiceLine = declaration.InvoiceLines.AddNew();
			invoiceLine.JI_Tariff = "0000000000";
			AssertEquals("PreCondition", ZString.Empty, invoiceLine.JI_CustomsUnitQty);

			declaration.US_TariffType = TariffTypeList.Codes.ScheduleB;
			AssertEquals("Populated", "KG", invoiceLine.JI_CustomsUnitQty);
		}

