		public void TestIsEntryClear()
		{
			JobDeclaration declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EntryFilerCode = "XJ5";
			declaration.US_EnableENS = true;

			Assert(!declaration.IsEntryClear);
			Assert(!((ILandedCostHeader)declaration).IsJobInLCRunnableState);

			declaration.Invoices.AddNew();
			declaration.InvoiceLines.AddNew();
			Assert(!declaration.IsEntryClear);
			Assert(!((ILandedCostHeader)declaration).IsJobInLCRunnableState);

			declaration.DoMerge(new SendsMessagesToCustomsShutterUpperer());
			Assert(!declaration.IsEntryClear);
			Assert(!((ILandedCostHeader)declaration).IsJobInLCRunnableState);

			declaration.ActiveEntryHeaders.EntrySummaryEntry.CH_Status = ImportMessageStatusList.Codes.AwaitingEntrySummaryOriginal;
			Factory.Save();
			Assert(!declaration.IsEntryClear);
			Assert(!((ILandedCostHeader)declaration).IsJobInLCRunnableState);

			declaration.ActiveEntryHeaders.EntrySummaryEntry.CH_Status = ImportMessageStatusList.Codes.ClearEntrySummaryOriginal;
			Factory.Save();
			Assert(declaration.IsEntryClear);
			Assert(((ILandedCostHeader)declaration).IsJobInLCRunnableState);

			declaration.ActiveEntryHeaders.EntrySummaryEntry.CH_Status = ImportMessageStatusList.Codes.ClearEntrySummaryDelete;
			Factory.Save();
			Assert(!declaration.IsEntryClear);
			Assert(!((ILandedCostHeader)declaration).IsJobInLCRunnableState);
		}

		public void TestDoNotTryToDefaultJE_MessageTypeWhenThereAreCustomsTransactions()
		{
			OrgHeader foreignBasedOrg = Factory.NewWithValidTestData<OrgHeader>();
			foreignBasedOrg.OH_RL_NKClosestPort = "KRSEL";

			OrgHeader foreignBasedOrg2 = Factory.NewWithValidTestData<OrgHeader>();
			foreignBasedOrg2.OH_RL_NKClosestPort = "KRSEL";

			JobDeclaration declaration = Factory.New<JobDeclaration>();
			declaration.JE_OH_Supplier = foreignBasedOrg.PK;
			AssertEquals("PreCondition:Changed to IMP", "IMP", declaration.JE_MessageType);

			declaration.JE_OH_Importer = foreignBasedOrg.PK;
			AssertEquals("PreCondition:Changed to IMP", "EXP", declaration.JE_MessageType);

			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EnableENS = true;
			declaration.US_EntryFilerCode = "XJ5";

			declaration.Invoices.AddNew();
			declaration.InvoiceLines.AddNew();

			declaration.DoMerge(new SendsMessagesToCustomsShutterUpperer());

			AssertNotNull(declaration.ActiveEntryHeaders.EntrySummaryEntry);

			declaration.ActiveEntryHeaders.EntrySummaryEntry.CH_Status = ImportMessageStatusList.Codes.ClearEntrySummaryOriginal;
			Factory.Save();

			Assert("PreCondition", declaration.ActiveEntryHeaders.EntrySummaryEntry.HasTransactionsWithCustoms);

			declaration.JE_OH_Importer = foreignBasedOrg2.PK;
			AssertEquals("Do not change JE_MessageType when there is a message sent to Customs. On the setter of JE_MessageType, there are logics to default/clear various fields. We do not want to run the codes just accidentally", JobMessageTypeList.Codes.Import, declaration.JE_MessageType);
		}

