		public override void TestIsExWarehouse()
		{
			JobDeclaration declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			AssertEquals(false, declaration.IsExWarehouse);

			foreach (var entryType in new[]
				{
					//EntryTypeList.Codes.ConsumptionFTZ, DN: Todo remove this when we know more info
					EntryTypeList.Codes.WarehouseWithdrawalADDCVD,
					EntryTypeList.Codes.WarehouseWithdrawalADDCVDQuotaVisa,
					//EntryTypeList.Codes.AircraftVesselSupplyIE, DN: Todo remove this when we know more info
					EntryTypeList.Codes.WarehouseWithdrawalConsumption,
					EntryTypeList.Codes.WarehouseWithdrawalQuota
				})
			{
				declaration.US_EntryType = entryType;
				AssertEquals(true, declaration.IsExWarehouse);
			}

			declaration.US_EntryType = EntryTypeList.Codes.Warehouse;
			AssertEquals(false, declaration.IsExWarehouse);
		}

		public void TestProcessingDistrictPort()
		{
			var helper = new UniversalReferenceTestDataHelper(Factory);
			helper.CreateNewOrGetExistingCusCodeType(Core.Constants.Customs.Universal.RefCusCodeListTypes.Codes.CustomsOffice, "CUSOF");
			helper.CreateNewOrGetExistingCusCodeList(Core.Constants.CountryCodes.UnitedStates, Core.Constants.Customs.Universal.RefCusCodeListTypes.Codes.CustomsOffice, "2786", "Test Name", new ZDateTime(1900, 1, 1), new ZDateTime(2079, 6, 6));
			helper.CreateNewOrGetExistingCusCodeList(Core.Constants.CountryCodes.UnitedStates, Core.Constants.Customs.Universal.RefCusCodeListTypes.Codes.CustomsOffice, "2720", "Test Name", new ZDateTime(1900, 1, 1), new ZDateTime(2079, 6, 6));
			Factory.Save();

			var coll = new EntryProcessingPortsMappingCollection();
			var mapping = coll.AddNew();
			mapping.EntryPort = "2786";
			mapping.ProcessingPort = "2720";

			USCustomsDataRegistry.Instance.EntryProcessingPortMappings.SetValue(Declaration.Branch.GB_GC.ToGuid(), Guid.Empty, Guid.Empty, coll);
			Declaration.US_SchDEntry = "2786";
			AssertEquals("2720", Declaration.ProcessingDistrictPort);

			Declaration.US_EntryMode = EntryModeList.Codes.RLF;
			AssertEquals("2786", Declaration.ProcessingDistrictPort);

			Declaration.US_EntryMode = "";
			USCustomsDataRegistry.Instance.ProcessingDistrictPortCode.SetValue(Guid.Empty, Declaration.Branch.PK.ToGuid(), Guid.Empty, "1101");
			Declaration.US_SchDEntry = "2904";
			AssertEquals("1101", Declaration.ProcessingDistrictPort);

			USCustomsDataRegistry.Instance.StatementProcessingPortEqualPortofEntryNonRLF.SetValue(Guid.Empty, Declaration.Branch.PK.ToGuid(), Guid.Empty, true);
			AssertEquals("2904", Declaration.ProcessingDistrictPort);

			Declaration.US_SchDEntry = "2786";
			AssertEquals("2720", Declaration.ProcessingDistrictPort);

			Declaration.US_SchDEntry = "2904";
			USCustomsDataRegistry.Instance.StatementProcessingPortEqualPortofEntryNonRLF.SetValue(Guid.Empty, Declaration.Branch.PK.ToGuid(), Guid.Empty, false);
			AssertEquals("1101", Declaration.ProcessingDistrictPort);

			Declaration.US_EntryMode = EntryModeList.Codes.RLF;
			AssertEquals("2904", Declaration.ProcessingDistrictPort);

			Declaration.US_EntryMode = EntryModeList.Codes.Paired;
			Declaration.US_SchDEntry = "";
			Declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			Declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			USCustomsDataRegistry.Instance.StatementProcessingPortEqualPortofEntryNonRLF.SetValue(Guid.Empty, Declaration.Branch.PK.ToGuid(), Guid.Empty, true);
			USCustomsDataRegistry.Instance.ProcessingDistrictPortCode.SetValue(Guid.Empty, declaration.Branch.PK.ToGuid(), Guid.Empty, "1101");
			AssertEquals("1101", Declaration.ProcessingDistrictPort);

			Declaration.JE_MessageType = JobMessageTypeList.Codes.FTZ;
			AssertEquals("1101", Declaration.ProcessingDistrictPort);
			USCustomsDataRegistry.Instance.EntryProcessingPortMappings.SetValue(Declaration.Branch.GB_GC.ToGuid(), Guid.Empty, Guid.Empty, coll);
			Declaration.US_SchDEntry = "2786";
			AssertEquals("1101", Declaration.ProcessingDistrictPort);
		}

		public void TestDefaultFDAContact()
		{
			GlbStaff cusAgentStaffMember = Factory.NewWithValidTestData<GlbStaff>();
			cusAgentStaffMember.GS_Code = "JLB";
			cusAgentStaffMember.GS_FullName = "JIMMY BEAN";
			cusAgentStaffMember.GS_WorkPhone = "+1 738 2956000123456";
			cusAgentStaffMember.GS_EmailAddress = "jimmy.beam@somecompany.somewhere";

			Declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			Declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			Declaration.US_EnableENS = false;
			Declaration.JE_GS_NKCusAgent = cusAgentStaffMember.GS_Code;

			Declaration.DefaultFDAContact();
			AssertEquals("US_FDAContactName should default from Cus Agent as fallback", "JIMMY BEAN", Declaration.US_FDAContactName);
			AssertEquals("US_FDAContactPhoneNo should default from Cus Agent as fallback", "738295600012345", Declaration.US_FDAContactPhoneNo);
			AssertEquals("US_FDAContactEmail should default from Cus Agent as fallback", "jimmy.beam@somecompany.somewhere", Declaration.US_FDAContactEmail);

			GlbBranch testBranch1 = Factory.NewWithValidTestData<GlbBranch>();
			testBranch1.GB_Phone = "+1 495 6283191";
			GlbBranch testBranch2 = Factory.NewWithValidTestData<GlbBranch>();
			testBranch2.GB_Phone = "+1 738 294 5000";

			GlbStaff fdaStaffMember = Factory.NewWithValidTestData<GlbStaff>();
			fdaStaffMember.GS_FullName = "JEREMY JONES";
			fdaStaffMember.GS_WorkPhone = "+1 738 2956005";
			fdaStaffMember.GS_GB_HomeBranch = testBranch2.PK;
			fdaStaffMember.GS_EmailAddress = "jeremy.jones@company.xx";
			Declaration.JE_GB = testBranch2.PK;

			USCustomsDataRegistry.Instance.BranchFDAContact.SetValue(Guid.Empty, testBranch2.PK.ToGuid(), Guid.Empty, fdaStaffMember.PK.ToGuid());

			Declaration.DefaultFDAContact();
			AssertEquals("US_FDAContactName should default from registry value set", "JEREMY JONES", Declaration.US_FDAContactName);
			AssertEquals("US_FDAContactPhoneNo should default from registry value set", "7382956005", Declaration.US_FDAContactPhoneNo);
			AssertEquals("US_FDAContactEmail should default from Cus Agent as fallback", "jeremy.jones@company.xx", Declaration.US_FDAContactEmail);

			fdaStaffMember.GS_WorkPhone = ZString.Empty;
			fdaStaffMember.GS_GB_HomeBranch = testBranch1.PK;
			Declaration.DefaultFDAContact();
			AssertEquals("US_FDAContactName should still default from registry value set", "JEREMY JONES", Declaration.US_FDAContactName);
			AssertEquals("US_FDAContactPhoneNo should default from contact's home branch as staff work phone is empty", "4956283191", Declaration.US_FDAContactPhoneNo);

			fdaStaffMember.GS_GB_HomeBranch = ZGuid.Empty;
			Declaration.DefaultFDAContact();
			AssertEquals("US_FDAContactName should still default from registry value set", "JEREMY JONES", Declaration.US_FDAContactName);
			AssertEquals("US_FDAContactPhoneNo should default from contact's home branch as staff work phone is empty", ZString.Empty, Declaration.US_FDAContactPhoneNo);
		}

