		public void TestICusAddInfoTypeSupporter()
		{
			var declaration = Factory.New<JobDeclaration>();
			Integration.Customs.ICusAddInfoTypeSupporter supporter = declaration;
			supporter.AssertType(typeof(DeliveryOrderHeader), CusAddInfoTypeAttribute.Codes.USDeliveryOrderHeader);
			supporter.AssertType(typeof(PPQForm368Data), CusAddInfoTypeAttribute.Codes.USPPQForm368Data);
			supporter.AssertType(typeof(ITDoc), CusAddInfoTypeAttribute.Codes.USITDoc);
			supporter.AssertType(typeof(OGADispositionData), CusAddInfoTypeAttribute.Codes.USOGADisposition);
			supporter.AssertType(typeof(LinkedEntry), CusAddInfoTypeAttribute.Codes.USLinkedEntry);
			supporter.AssertType(typeof(DispositionData), CusAddInfoTypeAttribute.Codes.USDisposition);
			supporter.AssertType(null, "ZZ!");

			var deliveryHeader = declaration.DeliveryOrderHeaders.AddNew();
			deliveryHeader.US_CusRelAttached = ZBool.True;
			declaration.US_PPQForm368Box13A = "A";
			declaration.US_7512OpenArea = "Open Area";
			var oga = declaration.OGADispositionCodes.AddNew();
			oga.US_Code = "A";
			var linked = declaration.LinkedEntryNumbers.AddNew();
			linked.US_LE_EntryNumber = "A";
			Factory.Save();
			AssertEquals("Open Area", declaration.US_7512OpenArea);

			ZQuery query = new ZQuery(CusAddInfoSchema.B7_ParentID, declaration.PK);
			query.AddToFilter(CusAddInfoSchema.B7_ParentTableCode, "JE");
			query.AddToFilter(CusAddInfoSchema.B7_Type, CusAddInfoTypeAttribute.Codes.USPPQForm368Data);
			var ppqHeader = Factory.LoadTop1<PPQForm368Data>(query);

			var newFactory = new BusinessObjectFactory();
			var addInfo = newFactory.Load<CusAddInfo>(deliveryHeader.PK);
			AssertEquals(typeof(DeliveryOrderHeader), addInfo.GetType());
			addInfo = newFactory.Load<CusAddInfo>(ppqHeader.PK);
			AssertEquals(typeof(PPQForm368Data), addInfo.GetType());
			addInfo = newFactory.Load<CusAddInfo>(oga.PK);
			AssertEquals(typeof(OGADispositionData), addInfo.GetType());
			addInfo = newFactory.Load<CusAddInfo>(linked.PK);
			AssertEquals(typeof(LinkedEntry), addInfo.GetType());
		}

