			var declaration1 = Factory.NewWithValidTestData<JobDeclaration>();
			declaration1.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration1.JE_EntryAuthorisationDate = new ZDate(2020, 2, 5);
			declaration1.US_EntryFilerCode = "SV9";
			declaration1.DecEntryNumber = "123456789";
			declaration1.ActiveEntryHeaders.AddNew().CH_MessageType = "SE";
			var declaration2 = Factory.NewWithValidTestData<JobDeclaration>();
