			declaration2.ActiveEntryHeaders.AddNew().CH_MessageType = "SE";

			Factory.Save();

			Declaration.JE_EntryAuthorisationDate = new ZDate(2020, 3, 5);

			var header1 = Declaration.Invoices.AddNew();
			header1.US_ReleaseEntryNumber = declaration1.US_EntryFilerCode + declaration1.DecEntryNumber;

			var header2 = Declaration.Invoices.AddNew();
