		public void TestHasCargoReleaseBeenCertified()
		{
			JobDeclaration declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			declaration.US_EnableENS = true;
			declaration.US_EnableCRL = true;

			CusEntryHeader ensEntry = declaration.CustomsEntryHeaders.AddNew();
			ensEntry.CH_MessageType = CusEntryHeaderMessageTypeList.Codes.EntrySummary;

			CusEntryHeader crlEntry = declaration.CustomsEntryHeaders.AddNew();
			crlEntry.CH_MessageType = CusEntryHeaderMessageTypeList.Codes.CargoRelease;
			crlEntry.CH_CH_PrimeEntry = ensEntry.PK;

			AssertEquals("HasCargoReleaseBeenCertified", false, declaration.HasCargoReleaseBeenCertified);

			ensEntry.US_CRLCertStatus = CargoReleaseCertificationStatusList.Codes.Certified;
			AssertEquals("HasCargoReleaseBeenCertified", true, declaration.HasCargoReleaseBeenCertified);

			ensEntry.US_CRLCertStatus = "";
			AssertEquals("HasCargoReleaseBeenCertified", false, declaration.HasCargoReleaseBeenCertified);

			crlEntry.US_CRLCertStatus = CargoReleaseCertificationStatusList.Codes.Certified;
			AssertEquals("HasCargoReleaseBeenCertified", true, declaration.HasCargoReleaseBeenCertified);

			JobDeclaration bcrDeclaration = Factory.New<JobDeclaration>();
			bcrDeclaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			bcrDeclaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			bcrDeclaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			bcrDeclaration.US_EnableCRL = true;

			CusEntryHeader bcrEntry = bcrDeclaration.CustomsEntryHeaders.AddNew();
			bcrEntry.CH_MessageType = CusEntryHeaderMessageTypeList.Codes.BorderCargoRelease;

			AssertEquals("Border Cargo Release entry/dec HasCargoReleaseBeenCertified", false, bcrDeclaration.HasCargoReleaseBeenCertified);

			bcrEntry.US_CRLCertStatus = CargoReleaseCertificationStatusList.Codes.Certified;
			AssertEquals("Border Cargo Release entry/dec HasCargoReleaseBeenCertified", true, bcrDeclaration.HasCargoReleaseBeenCertified);
		}

		public void TestCargoReleaseType()
		{
			var newFactory = new BusinessObjectFactory();
			var startDate = ZDateTime.UtcToday.Date.AddMonths(-1);
			var endDate = ZDateTime.UtcToday.Date.AddMonths(1);
			var helper = new UniversalReferenceTestDataHelper(newFactory);
			helper.CreateNewOrGetExistingCusCodeType(Core.Constants.Customs.Universal.RefCusCodeListTypes.Codes.CustomsOffice, "CUSOF");
			helper.CreateNewOrGetExistingCusCodeList(Core.Constants.CountryCodes.UnitedStates, Core.Constants.Customs.Universal.RefCusCodeListTypes.Codes.CustomsOffice, "3901", "TEST NAME", startDate, endDate);
			helper.CreateNewOrGetExistingCusCodeList(Core.Constants.CountryCodes.UnitedStates, Core.Constants.Customs.Universal.RefCusCodeListTypes.Codes.CustomsOffice, "2786", "TEST NAME", startDate, endDate);

			newFactory.Save();

			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EnableENS = true;
			declaration.US_EnableCRL = true;
			AssertEquals("Cargo Release Type should be empty, because not enough data for setting CR Type", "", declaration.US_CargoReleaseType);

			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			AssertEquals("Cargo Release Type should be empty, because not enough data for setting CR Type", "", declaration.US_CargoReleaseType);

			declaration.JE_TransportMode = TransportTypeList.Codes.Truck;
			AssertEquals("Cargo Release Type should be BCR, no ports in registry, but Entry Type is 01 and Transport Mode is truck", CargoReleaseTypeList.Codes.BCR, declaration.US_CargoReleaseType);

			declaration.US_CargoReleaseType = "";
			declaration.US_ITDate = ZDateTime.Today;
			declaration.US_SchDEntry = "2786";
			AssertEquals("Cargo Release Type should be CR, because IT Date exists", CargoReleaseTypeList.Codes.CR, declaration.US_CargoReleaseType);

			declaration.US_CargoReleaseType = "";
			declaration.US_ITDate = ZDateTime.Empty;
			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFTZ;
			AssertEquals("Cargo Release Type should be CR, because ConsumptionFTZ", CargoReleaseTypeList.Codes.CR, declaration.US_CargoReleaseType);

			declaration.US_CargoReleaseType = "";
			var coll = new BorderCargoPortCollection();
			var port = coll.AddNew();
			port.PortCode = "3901";
			port.CRProcess = "1-Step";
			port.Location = "S";
			USCustomsDataRegistry.Instance.BorderCargoReleasePorts.SetValue(Guid.Empty, declaration.Branch.PK.ToGuid(), Guid.Empty, coll);

			declaration.US_SchDEntry = "2787";
			AssertEquals("Cargo Release Type should be CR, because port 2787 not in the registry", CargoReleaseTypeList.Codes.CR, declaration.US_CargoReleaseType);

			declaration.US_CargoReleaseType = "";
			port = coll.AddNew();
			port.PortCode = "2786";
			port.CRProcess = "1-Step";
			port.Location = "S";
			USCustomsDataRegistry.Instance.BorderCargoReleasePorts.SetValue(Guid.Empty, declaration.Branch.PK.ToGuid(), Guid.Empty, coll);

			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			declaration.US_CargoReleaseType = "";
			declaration.US_SchDEntry = "2786";
			AssertEquals("Cargo Release Type should be CR, because port 2786 is in the registry", CargoReleaseTypeList.Codes.BCR, declaration.US_CargoReleaseType);

			declaration.US_CargoReleaseType = "";
			declaration.JE_TransportMode = TransportTypeList.Codes.Sea;
			AssertEquals("Cargo Release Type should be CR, because transport mode is not border movement", CargoReleaseTypeList.Codes.CR, declaration.US_CargoReleaseType);

			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACE;
			declaration.US_CargoReleaseType = CargoReleaseTypeList.Codes.ACE;
			AssertEquals("Cargo Release validation mode should be set", true, declaration.IsCargoReleaseValidationMode);
		}

		public void TestCargoReleaseTypeReadOnly()
		{
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EnableENS = true;
			AssertEquals("CR type should be readonly", true, declaration.US_CargoReleaseType_ReadOnly);

			declaration.US_EnableCRL = true;
			AssertEquals("CR type should not be readonly", false, declaration.US_CargoReleaseType_ReadOnly);

			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACE;
			AssertEquals("CR type should be readonly: Only SE", true, declaration.US_CargoReleaseType_ReadOnly);

			declaration.US_EnableCRL = false;
			AssertEquals("CR type should NOT be readonly: users should be able to select between ACE and ACS", false, declaration.US_CargoReleaseType_ReadOnly);

			declaration.US_EnableENS = false;
			AssertEquals("No messaging enabled", true, declaration.US_CargoReleaseType_ReadOnly);
			Assert(declaration.IsACEJobWithoutENSAndCRL);
			Assert(!declaration.IsACEStandalonePNWithoutENSAndCRL);

			declaration.US_EnableENS = true;
			Assert(!declaration.IsACEJobWithoutENSAndCRL);
			declaration.US_EntryMode = EntryModeList.Codes.RLF;
			AssertEquals("CR type should NOT be readonly for ACE declaration: users should be able to select between ACE and ACS", false, declaration.US_CargoReleaseType_ReadOnly);

			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			AssertEquals("CR type should be readonly for RLF", true, declaration.US_CargoReleaseType_ReadOnly);

			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACE;
			declaration.US_EnableENS = false;
			declaration.US_EnableSPN = true;
			Assert(declaration.IsACEStandalonePNWithoutENSAndCRL);
		}

