		public void TestIsFDAValidationMode()
		{
			AssertEquals(false, Declaration.IsFDAValidationMode);
			Declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			Declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			AssertEquals(false, Declaration.IsFDAValidationMode);
			Declaration.US_EnableCRL = true;
			Declaration.US_CertifyCargoRelease = true;
			AssertEquals(true, Declaration.IsFDAValidationMode);
			Declaration.US_EnableCRL = false;
			Declaration.US_CertifyCargoRelease = false;
			AssertEquals(false, Declaration.IsFDAValidationMode);
			Declaration.ValidationModes = ValidationModes.StandAlonePriorNotice;
			AssertEquals(true, Declaration.IsFDAValidationMode);

			Declaration.US_EnableCRL = true;
			Declaration.US_CertifyCargoRelease = false;
			AssertEquals(true, Declaration.IsFDAValidationMode);

			Declaration.ValidationModes = ValidationModes.EntrySummary;
			Declaration.US_EnableCRL = false;
			Declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACE;
			Declaration.US_CargoReleaseType = CargoReleaseTypeList.Codes.ACS;
			AssertEquals(false, Declaration.IsFDAValidationMode);

			Declaration.US_EnableENS = true;
			Declaration.US_CargoReleaseType = CargoReleaseTypeList.Codes.ACE;
			AssertEquals(true, Declaration.IsFDAValidationMode);
		}

		public void TestFDAValidationMode_CargoReleaseNotifications()
		{
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EntryFilerCode = "XJ5";
			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFTZ;
			declaration.US_EnableENS = false;
			declaration.US_EnableCRL = true;
			declaration.US_CertifyCargoRelease = false;

			var invoice = declaration.Invoices.AddNew();
			var invoiceLine = invoice.InvoiceLines.AddNew();

			var tariff = Factory.LoadTop1<USCTariff>(new ZQuery(USCTariffSchema.UE_Tariff, "6115969020"));
			if (tariff == null)
			{
				tariff = Factory.New<USCTariff>();
				tariff.UE_Tariff = "6115969020";
			}
			tariff.UE_DateFrom = ZDateTime.BrettsBirthday;
			tariff.UE_DateTo = ZDateTime.Today.AddYears(1);

			invoiceLine.JI_Tariff = tariff.UE_Tariff;
			invoiceLine.US_ManifestQty = 10;
			declaration.JE_TotalNoOfPacksPackType = "BAG";
			declaration.DoMerge(new SendsMessagesToCustomsShutterUpperer());

			declaration.RunPreSaveValidation();
			AssertMultilineASCIIEquals("FDA Required notification should be there, because declaration IsFDAValidationMode turned on",
@"Message Error - JI_OA_ConsigneeAddress: You have not entered a Consignee.
Message Error - JI_OA_ManufacturerAddress: You have not entered a Supplier/Manufacturer.
Message Error - US_FDAIndicator: FDA Indicator is required when tariff is an FDA tariff (FD1, FD2, FD3, FD4)
Message Error - US_UC_NKCountryOfOrigin: You have not entered a value.
Warning - US_DateOfExport: You have not entered a value.", invoiceLine.Notifications.ToUniqueMessageListString());
			AssertEquals(true, declaration.IsFDAValidationMode);
		}

