			Declaration.US_US_NKLocationOfGoods = "F234";
			Declaration.JE_MasterBill = "234343";

			Factory.Save();

			IPriorNoticeHeader priorNoticeHeader = Declaration;
			AssertEquals(fdaSubmitter, priorNoticeHeader.Submitter);
			AssertEquals("2904", priorNoticeHeader.PortOfArrival);
			AssertEquals(new ZDateTime(2008, 9, 11), priorNoticeHeader.DateOfArrival);
			AssertEquals("SOMEWHERE", priorNoticeHeader.AnticipatedPortOfCrossing);
