			AssertEquals("", priorNoticeHeader.ImportingAirCarrier3LetterCode);
			AssertEquals(true, priorNoticeHeader.IsSurface);
			AssertEquals("C", priorNoticeHeader.CarrierType);
			AssertEquals("MUDDER", priorNoticeHeader.CarrierName);
			AssertEquals("MY", priorNoticeHeader.CarrierCountry);
			AssertEquals("97823423", priorNoticeHeader.EntryNumberLast8Digits);
			AssertEquals(EntryTypeList.Codes.ConsumptionFTZ, priorNoticeHeader.EntryType);
			AssertEquals(TransportModeCodes.Codes.VesselContainer, priorNoticeHeader.ModeOfTransportationCode);
			AssertEquals("F234", priorNoticeHeader.LocationOfGoodsFIRMSCode);
			AssertEquals("234343", priorNoticeHeader.FTZAdmissionNumber);
			List<IPriorNoticeLine> lines = new List<IPriorNoticeLine>(priorNoticeHeader.StandalonePriorNoticeLines);
			AssertEquals(4, lines.Count);
			AssertEquals(3, lines[0].FDALineNumber);
			AssertEquals(4, lines[1].FDALineNumber);
			AssertEquals(1, lines[2].FDALineNumber);
			AssertEquals(2, lines[3].FDALineNumber);

			Declaration.ImportEntryNumber = ZString.Empty;
			AssertEquals(MQEDIMessage.USEntryNumberPlaceHolder, priorNoticeHeader.EntryNumberLast8Digits);

			Declaration.US_UI_NKCarrierSCAC = "QF";
			Declaration.JE_TransportMode = Core.Constants.TransportModes.Air;
			AssertEquals("QFA", priorNoticeHeader.ImportingAirCarrier3LetterCode);

			Declaration.JE_MessageType = JobMessageTypeList.Codes.FTZ;
			AssertEquals(EntryTypeList.Codes.WarehouseFTZ, priorNoticeHeader.EntryType);
		}

		public void TestGetReasonNotToAllowChangeOnCostDetails()
		{
			AccountingIntegrationOptions options = new AccountingIntegrationOptions();
			options.EnableAccountingIntegration = true;
			CustomsDataRegistry.Instance.EnableAccountingIntegration.SetValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, options);

			JobDeclaration declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			IJobInvoicingPlugIn jobInvoicingParent = declaration;

			AccChargeCode chargeCode1 = Factory.NewWithValidTestData<AccChargeCode>();
			AccChargeCode chargeCode2 = Factory.NewWithValidTestData<AccChargeCode>();
			RatingDataRegistry.Instance.CustomsDisbursementChargeCode.SetValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, chargeCode1.PK.ToGuid());

			Factory.Save();

			declaration.US_PaymentType = PaymentTypeList.Codes.IndividualBasis;
			AssertNull(jobInvoicingParent.InvoicingSupporter.GetReasonNotToAllowChangeOnCostDetails(chargeCode1.PK));
			AssertNull(jobInvoicingParent.InvoicingSupporter.GetReasonNotToAllowChangeOnCostDetails(chargeCode2.PK));

			declaration.US_PaymentType = PaymentTypeList.Codes.BatchedByDailyPrintDateAndFilerCode;
			AssertEquals(JobDeclarationInvoicingSupporter.ShouldNotChangeCostOrPostWhileOnStatement, jobInvoicingParent.InvoicingSupporter.GetReasonNotToAllowChangeOnCostDetails(chargeCode1.PK));
			AssertNull(jobInvoicingParent.InvoicingSupporter.GetReasonNotToAllowChangeOnCostDetails(chargeCode2.PK));

			options.EnableAccountingIntegration = false;
			CustomsDataRegistry.Instance.EnableAccountingIntegration.SetValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, options);
			declaration.US_PaymentType = PaymentTypeList.Codes.BatchedByDailyPrintDateAndFilerCode;
			AssertNull(jobInvoicingParent.InvoicingSupporter.GetReasonNotToAllowChangeOnCostDetails(chargeCode1.PK));

			declaration.JE_MessageType = JobMessageTypeList.Codes.FTZ;
			AssertNull(jobInvoicingParent.InvoicingSupporter.GetReasonNotToAllowChangeOnCostDetails(chargeCode1.PK));
			AssertNull(jobInvoicingParent.InvoicingSupporter.GetReasonNotToAllowChangeOnCostDetails(chargeCode2.PK));
		}

		public void TestGetReasonNotToAllowChangeWhenFinalStatementIsThere()
		{
			AccountingIntegrationOptions options = new AccountingIntegrationOptions();
			options.EnableAccountingIntegration = true;
			CustomsDataRegistry.Instance.EnableAccountingIntegration.SetValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, options);

			AccChargeCode chargeCode1 = Factory.NewWithValidTestData<AccChargeCode>();
			RatingDataRegistry.Instance.CustomsDisbursementChargeCode.SetValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, chargeCode1.PK.ToGuid());

			JobDeclaration declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EntryFilerCode = "XJ5";
			declaration.US_PaymentType = PaymentTypeList.Codes.BatchedByDailyPrintDateAndFilerCode;

			CusEntryHeader entry = declaration.CustomsEntryHeaders.AddNew();
			entry.CH_MessageType = CusEntryHeaderMessageTypeList.Codes.EntrySummary;
			Factory.Save();

			AssertNotEquals(ZString.Empty, entry.EntryNumber);

			IJobInvoicingPlugIn jobInvoicingParent = declaration;
			AssertEquals(JobDeclarationInvoicingSupporter.ShouldNotChangeCostOrPostWhileOnStatement, jobInvoicingParent.InvoicingSupporter.GetReasonNotToAllowChangeOnCostDetails(chargeCode1.PK));

			CusStatementHeader statement = Factory.New<CusStatementHeader>();
			statement.B2_Status = StatementHeaderStatusList.Codes.Final;
			CusStatementLine statementline = statement.StatementLines.AddNew();
			statementline.B3_EntryFilerCode = "XJ5";
			statementline.B3_EntryNum = entry.EntryNumber;
			statementline.B3_Status = StatementLineStatusList.Codes.Active;
			Factory.Save();
			AssertNull(jobInvoicingParent.InvoicingSupporter.GetReasonNotToAllowChangeOnCostDetails(chargeCode1.PK));
		}

