			DispositionData disposition = Declaration.DispositionCodes.AddNew();
			disposition.US_DispositionDate = ZDateTime.Now;

			disposition = Declaration.DispositionCodes.AddNew();
			disposition.US_DispositionDate = ZDateTime.Now.AddDays(1);

			disposition = Declaration.DispositionCodes.AddNew();
			disposition.US_DispositionDate = ZDateTime.Now.AddDays(2);

			AssertEquals(new ZDateTime(2009, 1, 3), Declaration.GetLatestDispositionDate());
		}

