		public void TestDispositionCodesWhenMultiple()
		{
			declaration = null;
			Declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			Declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;

			MQEDIMessage message = CreateMessage(EDIMessage.Direction.Receive, ApplicationIdentifierCodeList.Codes.CargoReleaseProcessingResults);
			Declaration.Messages.Add(message);
			message.EM_MessageText =
"B011102113RR                                                            27444284" +
"R14701113 457149080111-35250130025143832 CMDUXIN DAN DONG        492  110708    " +
"R4            SZ1459194                           00000216CTNS CMDU             " +
"R5110308000805PAPERLESS                                                         " +
"R6FDA    110308000806FDA MAY PROCEED                                            " +
"R6FDA    110308000806FDA MAY PROCEED                  070011001THRU0011001      " +
"Y  1102113LS00002";
			Factory.Save();

			var statusBlocks = message.MessageBlock.MessageBlocks.OfType<CMQR6>();
			foreach (var r6 in statusBlocks)
			{
				ZDateTime dispositionDateTime = ZDateTime.Empty;
				EntryStatusesAndErrors.AddOGADispositionData(r6);
			}

			message = CreateMessage(EDIMessage.Direction.Receive, ApplicationIdentifierCodeList.Codes.CargoReleaseProcessingResults);
			Declaration.Messages.Add(message);
			message.EM_MessageText =
"B011102113RR                                                            27444284" +
"R14701113 457149080111-35250130025143832 CMDUXIN DAN DONG        492  110708    " +
"R4            SZ1459194                           00000216CTNS CMDU             " +
"R5070209083103Pending Intensive Exam                                            " +
"R6FDA    110308000806FDA MAY PROCEED                                            " +
"Y  1102113LS00002";

			Factory.Save();

			statusBlocks = message.MessageBlock.MessageBlocks.OfType<CMQR6>();
			foreach (var r6 in statusBlocks)
			{
				ZDateTime dispositionDateTime = ZDateTime.Empty;
				EntryStatusesAndErrors.AddOGADispositionData(r6);
			}

			AssertEquals(2, Declaration.DispositionCodes.Count);
			AssertEquals(new ZDateTime(2009, 7, 2, 8, 31, 0), Declaration.DispositionCodes[0].US_DispositionDate);
			AssertEquals(new ZDateTime(2008, 11, 3, 0, 8, 0), Declaration.DispositionCodes[1].US_DispositionDate);
			AssertEquals(true, Declaration.DispositionCodes[0].US_DispositionDate > Declaration.DispositionCodes[1].US_DispositionDate);

			if (Declaration.DispositionCodes[0].US_Code == "03")
			{
				AssertEquals(CargoReleaseProcessingResultList.Descriptions.PendingIntenstiveReview, Declaration.DispositionCodes[0].DispositionCodeDesc);
				AssertEquals(CargoReleaseProcessingResultList.Descriptions.PaperlessEntry, Declaration.DispositionCodes[1].DispositionCodeDesc);
				AssertEquals("05", Declaration.DispositionCodes[1].US_Code);
			}
			else
			{
				AssertEquals(CargoReleaseProcessingResultList.Descriptions.PaperlessEntry, Declaration.DispositionCodes[0].DispositionCodeDesc);
				AssertEquals("05", Declaration.DispositionCodes[0].US_Code);
				AssertEquals("03", Declaration.DispositionCodes[1].US_Code);
				AssertEquals(CargoReleaseProcessingResultList.Descriptions.PendingIntenstiveReview, Declaration.DispositionCodes[1].DispositionCodeDesc);
			}
		}

