		public void TestDefaultBondAmountIfRequired()
		{
			Declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			Declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			Declaration.JE_TransportMode = TransportTypeList.Codes.Air;
			Declaration.US_EnableENS = true;
			Declaration.US_BondType = BondTypeList.Codes.ContinuousBond;
			Declaration.US_BondAmount = 1000m;
			Declaration.DefaultBondAmountForSingleTransactionBond();

			CusEntryHeader entry = declaration.ActiveEntryHeaders.AddNew();
			entry.EntryNumber = "ENS123";
			entry.CH_MessageType = CusEntryHeaderMessageTypeList.Codes.EntrySummary;

			AssertEquals("Bond amount should not be calculated for Continuous Bond", 0m, Declaration.US_BondAmount);

			Declaration.US_BondType = BondTypeList.Codes.SingleTransactionBond;
			Declaration.US_BondCalcCode = SEBCalculationList.Codes.MSC;
			Declaration.DefaultBondAmountForSingleTransactionBond();

			AssertEquals("Bond amount should be re-calculated for SingleTransactionBond", 100m, Declaration.US_BondAmount);
		}

		public void TestDefaultBondCalcCodeForKnownEntryTypes()
		{
			Declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			Declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			Declaration.JE_TransportMode = TransportTypeList.Codes.Air;
			Declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			Declaration.US_BondType = BondTypeList.Codes.ContinuousBond;
			AssertEquals("BondCalcCode should not default unless this is a SEB", "", Declaration.US_BondCalcCode);
			AssertEquals("IsTemporaryImportationBond", false, Declaration.IsTemporaryImportationBond);

			Declaration.US_EntryType = EntryTypeList.Codes.TemporaryImportationBond;
			Declaration.US_BondType = BondTypeList.Codes.ContinuousBond;
			AssertEquals("BondCalcCode should not default for Continuous when Entry Type is TIB", ZString.Empty, Declaration.US_BondCalcCode);
			AssertEquals("IsTemporaryImportationBond", true, Declaration.IsTemporaryImportationBond);

			Declaration.US_EntryType = EntryTypeList.Codes.InformalFreeDutiable;
			AssertEquals("BondCalcCode should not default", "", Declaration.US_BondCalcCode);
			AssertEquals("IsTemporaryImportationBond", false, Declaration.IsTemporaryImportationBond);

			Declaration.US_EntryType = EntryTypeList.Codes.TemporaryImportationBond;
			Declaration.US_BondType = BondTypeList.Codes.SingleTransactionBond;
			AssertEquals("BondCalcCode should default for TIB when SEB", SEBCalculationList.Codes.TIB, Declaration.US_BondCalcCode);

			Declaration.US_EntryType = EntryTypeList.Codes.PermanentExhibition;
			Declaration.US_BondType = BondTypeList.Codes.ContinuousBond;
			Declaration.US_BondType = BondTypeList.Codes.SingleTransactionBond;
			AssertEquals("BondCalcCode should default for Exhibition", SEBCalculationList.Codes.EXH, Declaration.US_BondCalcCode);

			Declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			AssertEquals("BondCalcCode should default to default for all other cases", SEBCalculationList.Codes.DEF, Declaration.US_BondCalcCode);
		}

		public void TestDefaultBondCalcCodeOnChangeOfEntryType()
		{
			Declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			Declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			Declaration.JE_TransportMode = TransportTypeList.Codes.Air;
			Declaration.US_EntryType = EntryTypeList.Codes.InformalFreeDutiable;
			Declaration.US_BondType = BondTypeList.Codes.ContinuousBond;
			AssertEquals("BondCalcCode should not default", "", Declaration.US_BondCalcCode);

			Declaration.US_BondType = BondTypeList.Codes.SingleTransactionBond;
			Declaration.US_EntryType = EntryTypeList.Codes.TemporaryImportationBond;
			AssertEquals("BondCalcCode should default to TIB when changed to TIB entry type", SEBCalculationList.Codes.TIB, Declaration.US_BondCalcCode);

			Declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			AssertEquals("BondCalcCode should default to DEF when changing entry type from TIB to something else", SEBCalculationList.Codes.DEF, Declaration.US_BondCalcCode);

			Declaration.US_EntryType = EntryTypeList.Codes.PermanentExhibition;
			AssertEquals("BondCalcCode should default to EXH for Exhibition entry type", SEBCalculationList.Codes.EXH, Declaration.US_BondCalcCode);

			Declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			AssertEquals("BondCalcCode should default to DEF when changing entry type from Exhibition to something else", SEBCalculationList.Codes.DEF, Declaration.US_BondCalcCode);

			Declaration.US_BondAmount = 1575m;
			Declaration.US_EntryType = EntryTypeList.Codes.TradeFair;
			AssertEquals("BondCalcCode should default to MAN for Trade Fair entry type", SEBCalculationList.Codes.MAN, Declaration.US_BondCalcCode);
			AssertEquals("BondAmount should default to zero when entry type changed to Trade Fair", 0m, Declaration.US_BondAmount);
		}

