		public void TestBondDetailsDefault()
		{
			USCustomsDataRegistry.Instance.DoDefaultImporterOfRecord.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, true);

			OrgHeader oSCompany = Factory.New<OrgHeader>();
			oSCompany.FillWithValidTestData();
			oSCompany.OH_RL_NKClosestPort = "SGSIN";

			CusBondDetailCollection bondData = new CusBondDetailCollection(oSCompany);
			CusBondDetail oneBondData = bondData.AddNew();
			oneBondData.PW_ActivityCode = ActivityCodeList.Codes._1;
			oneBondData.PW_BondAmount = 75000m;
			oneBondData.PW_BondEffectiveDate = ZDateTime.Today.AddDays(-10);
			oneBondData.PW_BondNumber = "123456";
			oneBondData.PW_BondType = ImporterBondTypeList.Codes.ContinuousBond;
			oneBondData.PW_SuretyCode = "891";
			oneBondData.PW_BondFiledPort = "3901";
			oneBondData.PW_BondExpiryDate = ZDateTime.Today.AddDays(10);

			CusBondDetail secondBondData = bondData.AddNew();
			secondBondData.PW_ActivityCode = ActivityCodeList.Codes._1;
			secondBondData.PW_BondAmount = 10000m;
			secondBondData.PW_BondEffectiveDate = ZDateTime.Today.AddDays(-10);
			secondBondData.PW_BondNumber = "123777";
			secondBondData.PW_BondType = ImporterBondTypeList.Codes.SingleTransactionBond;
			secondBondData.PW_SuretyCode = "891";
			secondBondData.PW_BondFiledPort = "3901";
			secondBondData.PW_BondExpiryDate = ZDateTime.Today.AddDays(10);
			Factory.Save();

			JobDeclaration declaration = Factory.New<JobDeclaration>();
			declaration.JE_OH_Importer = oSCompany.PK;
			AssertEquals("Bond defaults should be empty as Export job by default with foreign company as Importer", "", declaration.US_BondType);
			AssertEquals("Bond defaults should be empty", 0m, declaration.US_BondAmount);
			AssertEquals("Bond defaults should be empty", "", declaration.US_SuretyCode);
			AssertEquals("Bond defaults should be empty", "", declaration.US_BondProducerAccNo);

			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			AssertEquals("Bond defaults should now default as shipment type changed to Import Job & foreign company is set up with Default Bond Details", ImporterBondTypeList.Codes.ContinuousBond, declaration.US_BondType);
			AssertEquals("US_BondAmount is only relevant for STB", ZDecimal.Zero, declaration.US_BondAmount);
			AssertEquals("Bond defaults should now default", "891", declaration.US_SuretyCode);
			AssertEquals("US_BondProducerAccNo should now default", "123456", declaration.US_BondProducerAccNo);

			declaration.US_BondType = ImporterBondTypeList.Codes.SingleTransactionBond;
			AssertEquals("Bond defaults changed to Single Transaction Bond details", ImporterBondTypeList.Codes.SingleTransactionBond, declaration.US_BondType);
			AssertEquals("Bond defaults changed to Single Transaction Bond details", 10000m, declaration.US_BondAmount);
			AssertEquals("Bond defaults changed to Single Transaction Bond details", "891", declaration.US_SuretyCode);
			AssertEquals("Bond defaults changed to Single Transaction Bond details", "123777", declaration.US_BondProducerAccNo);

			declaration.US_BondType = ImporterBondTypeList.Codes.ContinuousBond;
			AssertEquals("Bond defaults changed to Continuous Bond details", ImporterBondTypeList.Codes.ContinuousBond, declaration.US_BondType);
			AssertEquals("US_BondAmount is only relevant for STB", ZDecimal.Zero, declaration.US_BondAmount);
			AssertEquals("Bond defaults changed to Continuous Bond details", "891", declaration.US_SuretyCode);
			AssertEquals("US_BondProducerAccNo should now default", "123456", declaration.US_BondProducerAccNo);
		}

