		public void TestSetEmptyValueTo_US_CarrierName_IfRequired()
		{
			Declaration.JE_MessageType = JobMessageTypeList.Codes.Export;
			Declaration.JE_TransportMode = TransportTypeList.Codes.Rail;
			Declaration.US_UI_NKCarrierSCAC = "UNKN";

			Declaration.US_CarrierName = "SOME CARRIER";
			Declaration.JE_TransportMode = TransportTypeList.Codes.Truck;
			AssertEquals("Precondition: IsUnknownCarrierSCACForExport", true, Declaration.IsUnknownCarrierSCACForExport);
			AssertEquals("no cleanup expected", "SOME CARRIER", Declaration.US_CarrierName);

			Declaration.US_CarrierName = "SOME CARRIER";
			Declaration.JE_TransportMode = TransportTypeList.Codes.Sea;
			AssertEquals("Precondition: !IsUnknownCarrierSCACForExport", false, Declaration.IsUnknownCarrierSCACForExport);
			AssertEquals("change of JE_TransportMode should trigger cleanup", ZString.Empty, Declaration.US_CarrierName);

			Declaration.JE_TransportMode = TransportTypeList.Codes.Truck;
			Declaration.US_CarrierName = "SOME CARRIER";
			Declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			AssertEquals("Precondition: !IsUnknownCarrierSCACForExport", false, Declaration.IsUnknownCarrierSCACForExport);
			AssertEquals("change of JE_MessageType should trigger cleanup", ZString.Empty, Declaration.US_CarrierName);

			Declaration.JE_MessageType = JobMessageTypeList.Codes.Export;
			Declaration.US_CarrierName = "SOME CARRIER";
			Declaration.US_UI_NKCarrierSCAC = "CMSL";
			AssertEquals("Precondition: !IsUnknownCarrierSCACForExport", false, Declaration.IsUnknownCarrierSCACForExport);
			AssertEquals("change of US_UI_NKCarrierSCAC should trigger cleanup", ZString.Empty, Declaration.US_CarrierName);

			Declaration.US_UI_NKCarrierSCAC = "UNKN";
			Declaration.US_CarrierName = "SOME CARRIER";
			Declaration.JE_OH_ShippingLine = Factory.New<OrgHeader>().PK;
			AssertEquals("Precondition: !IsUnknownCarrierSCACForExport", false, Declaration.IsUnknownCarrierSCACForExport);
			AssertEquals("change of JE_OH_ShippingLine should trigger cleanup", ZString.Empty, Declaration.US_CarrierName);
		}

