		public void TestFDAStatusOnSaving()
		{
			JobDeclaration declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			declaration.US_EnableCRL = true;
			AssertEquals("FDA Status", ZString.Empty, declaration.FDAMsgStatus);

			CusEntryHeader entry = declaration.CustomsEntryHeaders.AddNew();
			entry.CH_MessageType = CusEntryHeaderMessageTypeList.Codes.CargoRelease;
			Factory.Save();
			AssertEquals("FDA Status not yet set", ZString.Empty, declaration.FDAMsgStatus);

			JobComInvoiceHeader invoice = declaration.Invoices.AddNew();
			JobComInvoiceLine invoiceLine = invoice.JobComInvoiceLines.AddNew();
			invoiceLine.JI_Tariff = USCTariff.FDAAdmissibilityReviewRequiredTariff;
			Factory.Save();
			AssertEquals("FDA Status should be set to FDA Required", FDAStatusList.Codes.REQ, declaration.FDAMsgStatus);

			invoiceLine.JI_Tariff = USCTariff.FDAAdmissibilityReviewDONOTSUBMITTariff;
			Factory.Save();
			AssertEquals("Tariff with FDA removed, status no longer required - should be set back to not required", FDAStatusList.Codes.NR, declaration.FDAMsgStatus);
		}

		public void TestOverridenDepartment()
		{
			Declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			Declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			Declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			Declaration.US_EnableENS = true;
			Declaration.JE_TransportMode = TransportTypeList.Codes.Sea;
			AssertEquals("Inward Sea Transport - Dept. s/b CIS", ObjectFactory.Get<IAccounting>().CustomsImportSeaLcl, ((IJobInvoicingPlugIn)Declaration).InvoicingSupporter.OverriddenDepartmentPK);

			Declaration.JE_TransportMode = TransportTypeList.Codes.Mail;
			AssertEquals("Inward Mail Transport - Dept. s/b CPP", ObjectFactory.Get<IAccounting>().CustomsImportPost, ((IJobInvoicingPlugIn)Declaration).InvoicingSupporter.OverriddenDepartmentPK);

			Declaration.JE_TransportMode = TransportTypeList.Codes.BorderWaterBorne;
			AssertEquals("Inward BorderWaterBorne Transport - Dept. s/b COT", ObjectFactory.Get<IAccounting>().CustomsImportOther, ((IJobInvoicingPlugIn)Declaration).InvoicingSupporter.OverriddenDepartmentPK);

			Declaration.JE_TransportMode = TransportTypeList.Codes.Rail;
			AssertEquals("Inward Rail Transport - Dept. s/b CIL", ObjectFactory.Get<IAccounting>().CustomsImportRail, ((IJobInvoicingPlugIn)Declaration).InvoicingSupporter.OverriddenDepartmentPK);

			Declaration.JE_TransportMode = TransportTypeList.Codes.Air;
			AssertEquals("Inward Air Transport - Dept. s/b CIA", ObjectFactory.Get<IAccounting>().CustomsImportAirUld, ((IJobInvoicingPlugIn)Declaration).InvoicingSupporter.OverriddenDepartmentPK);

			Declaration.JE_TransportMode = TransportTypeList.Codes.PassengerHandCarried;
			AssertEquals("Inward Pasenger Hand Carried - Dept. s/b COT", ObjectFactory.Get<IAccounting>().CustomsImportOther, ((IJobInvoicingPlugIn)Declaration).InvoicingSupporter.OverriddenDepartmentPK);

			Declaration.JE_TransportMode = TransportTypeList.Codes.Road;
			AssertEquals("Inward Road Transport - Dept. s/b CIR", ObjectFactory.Get<IAccounting>().CustomsImportRoad, ((IJobInvoicingPlugIn)Declaration).InvoicingSupporter.OverriddenDepartmentPK);

			Declaration.JE_TransportMode = TransportTypeList.Codes.Sea;
			Declaration.JE_ContainerCount = 1;
			AssertEquals("Inward Sea Containerised Transport - Dept. s/b CIS", ObjectFactory.Get<IAccounting>().CustomsImportSeaFcl, ((IJobInvoicingPlugIn)Declaration).InvoicingSupporter.OverriddenDepartmentPK);

			Declaration.JE_MessageType = JobMessageTypeList.Codes.Export;
			Declaration.JE_TransportMode = "";
			Declaration.JE_ContainerCount = 0;
			Declaration.JE_TransportMode = TransportTypeList.Codes.Air;
			AssertEquals("Export Air Transport - Dept. s/b CEA", ObjectFactory.Get<IAccounting>().CustomsExportAirUld, ((IJobInvoicingPlugIn)Declaration).InvoicingSupporter.OverriddenDepartmentPK);

			Declaration.JE_TransportMode = TransportTypeList.Codes.Road;
			AssertEquals("Export Road Transport - Dept. s/b CER", ObjectFactory.Get<IAccounting>().CustomsExportRoad, ((IJobInvoicingPlugIn)Declaration).InvoicingSupporter.OverriddenDepartmentPK);

			Declaration.JE_TransportMode = "";
			AssertEquals("No Transport - Dept. s/b COT", ObjectFactory.Get<IAccounting>().CustomsOther, ((IJobInvoicingPlugIn)Declaration).InvoicingSupporter.OverriddenDepartmentPK);

			Declaration.JE_TransportMode = TransportTypeList.Codes.Sea;
			AssertEquals("Export Sea Transport - Dept. s/b CES", ObjectFactory.Get<IAccounting>().CustomsExportSeaLcl, ((IJobInvoicingPlugIn)Declaration).InvoicingSupporter.OverriddenDepartmentPK);

			Declaration.JE_TransportMode = TransportTypeList.Codes.PassengerHandCarried;
			AssertEquals("Export Pasenger Hand Carried - Dept. s/b COT", ObjectFactory.Get<IAccounting>().CustomsOther, ((IJobInvoicingPlugIn)Declaration).InvoicingSupporter.OverriddenDepartmentPK);

			Declaration.JE_TransportMode = TransportTypeList.Codes.FixedTransportInstallations;
			AssertEquals("Export Pipeline(other) Transport - Dept. s/b COT", ObjectFactory.Get<IAccounting>().CustomsOther, ((IJobInvoicingPlugIn)Declaration).InvoicingSupporter.OverriddenDepartmentPK);

			Declaration.JE_TransportMode = TransportTypeList.Codes.Rail;
			AssertEquals("Export Rail Transport - Dept. s/b CEL", ObjectFactory.Get<IAccounting>().CustomsExportRail, ((IJobInvoicingPlugIn)Declaration).InvoicingSupporter.OverriddenDepartmentPK);

			Declaration.JE_TransportMode = TransportTypeList.Codes.BorderWaterBorne;
			AssertEquals("Export BorderWaterBorne Transport - Dept. s/b COT", ObjectFactory.Get<IAccounting>().CustomsOther, ((IJobInvoicingPlugIn)Declaration).InvoicingSupporter.OverriddenDepartmentPK);

			Declaration.JE_TransportMode = TransportTypeList.Codes.Mail;
			AssertEquals("Export Mail Transport - Dept. s/b CPP", ObjectFactory.Get<IAccounting>().CustomsExportPost, ((IJobInvoicingPlugIn)Declaration).InvoicingSupporter.OverriddenDepartmentPK);

			Declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			Declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			Declaration.US_EntryType = EntryTypeList.Codes.WarehouseWithdrawalConsumption;
			Declaration.JE_TransportMode = TransportTypeList.Codes.Truck;
			AssertEquals("ExWarehouse - Dept. s/b CXB", ObjectFactory.Get<IAccounting>().CustomsExWarehouse, ((IJobInvoicingPlugIn)Declaration).InvoicingSupporter.OverriddenDepartmentPK);
		}

		public void TestUS_EnableCRL_ReadOnly()
		{
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			declaration.US_EnableENS = true;

			declaration.US_EntryMode = EntryModeList.Codes.RLF;
			Assert("US_EnableCRL should be readonly", declaration.US_EnableCRL_ReadOnly);
			declaration.US_EntryMode = "";
			Assert("US_EnableCRL should not be readonly", !declaration.US_EnableCRL_ReadOnly);

			declaration.US_EntryType = EntryTypeList.Codes.ReWarehouse;
			Assert("US_EnableCRL should be readonly for Type 22", declaration.US_EnableCRL_ReadOnly);

			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACE;
			Assert("Entry Type 22 is allowed for ACE", !declaration.US_EnableCRL_ReadOnly);
			Assert("Entry Type 22 is allowed for ACE", !declaration.US_CargoReleaseType_ReadOnly);
		}

		public void TestCRLEnableIsClearedOnChangeOfEntryTypeToNonRelevantType()
		{
			JobDeclaration declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			declaration.US_EnableENS = true;
			declaration.US_EnableCRL = true;
			Assert("US_EnableCRL should not be readonly", !declaration.US_EnableCRL_ReadOnly);
			Assert("US_EnableCRL should be ticked", declaration.US_EnableCRL);

			declaration.US_EntryType = EntryTypeList.Codes.ReWarehouse;
			Assert("US_EnableCRL should be readonly for Type 22", declaration.US_EnableCRL_ReadOnly);
			Assert("US_EnableCRL should have been cleared out", !declaration.US_EnableCRL);
		}

