		public void TestShouldElectronicInvoicesBeVisible()
		{
			JobDeclaration declaration = Factory.New<JobDeclaration>();
			IInvoicesProvider invoicesProvider = declaration;

			declaration.JE_MessageType = JobMessageTypeList.Codes.Export;
			AssertEquals(false, invoicesProvider.ShouldElectronicInvoicesBeVisible);

			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			declaration.US_EnableENS = true;
			AssertEquals(false, invoicesProvider.ShouldElectronicInvoicesBeVisible);

			declaration.US_EnableAII = true;
			AssertEquals(true, invoicesProvider.ShouldElectronicInvoicesBeVisible);

			declaration.JE_MessageType = JobMessageTypeList.Codes.Export;
			AssertEquals(false, invoicesProvider.ShouldElectronicInvoicesBeVisible);

			JobComInvoiceHeader invoice = Factory.New<JobComInvoiceHeader>();
			IInvoicesProvider fakeDeclaration = (IInvoicesProvider)new FakeDeclarationCreatorForInvoice(invoice).HeaderData;
			AssertEquals(false, fakeDeclaration.ShouldElectronicInvoicesBeVisible);

			invoice.JZ_MessageType = JobMessageTypeList.Codes.Import;
			AssertEquals(true, fakeDeclaration.ShouldElectronicInvoicesBeVisible);
		}

		public void TestAttachCoreExporterChangingBetweenACS_ACE()
		{
			JobComInvoiceHeader commInvoice = Factory.New<JobComInvoiceHeader>();
			var exporter = Factory.New<OrgHeader>();
			commInvoice.JZ_InvoiceAmount = 10;
			commInvoice.ExporterOrgPK = exporter.PK;
			commInvoice.RefreshDefaultsWhenInvoiceAttachedToDeclarationRequired = true;

			JobDeclaration declaration = Factory.New<JobDeclaration>();
			declaration.US_EnableENS = true;
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACE;
			declaration.Invoices.Add(commInvoice);

			AssertEquals(exporter.MainAddress.PK, commInvoice.JZ_OA_ExporterAddress);
			AssertEquals(exporter.PK, commInvoice.ExporterOrgPK);

			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;

			AssertEquals(exporter.MainAddress.PK, commInvoice.JZ_OA_ExporterAddress);
			AssertEquals(exporter.PK, commInvoice.ExporterOrgPK);

			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACE;

			AssertEquals(exporter.MainAddress.PK, commInvoice.JZ_OA_ExporterAddress);
			AssertEquals(exporter.PK, commInvoice.ExporterOrgPK);
		}

