		public void TestICargoManifestStatusQueryHeaderActionListForFTZ()
		{
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.FTZ;
			declaration.JE_TransportMode = TransportTypeList.Codes.Truck;

			var cargoManifestStatusQueryHeader = (ICargoManifestStatusQueryHeader)declaration;
			AssertContainsExactElementsInAnyOrder(new string[] { CargoManifestStatusQueryActionList.Codes.OceanRailTruckBill }, cargoManifestStatusQueryHeader.ActionList.GetAllCodes());

			declaration.JE_TransportMode = TransportTypeList.Codes.Air;
			AssertContainsExactElementsInAnyOrder(new string[] { CargoManifestStatusQueryActionList.Codes.AIR, CargoManifestStatusQueryActionList.Codes.MAWB, CargoManifestStatusQueryActionList.Codes.HAWB }, cargoManifestStatusQueryHeader.ActionList.GetAllCodes());
		}

		public void TestAttachCommercialInvoiceMapsACEAndACSLicencePermitsCorrectly()
		{
			var importer = Factory.New<OrgHeader>();
			importer.OH_Code = "IMPORTER";
			importer.OH_IsConsignor = true;
			importer.OH_IsConsignee = true;

			var supplier = Factory.New<OrgHeader>();
			supplier.OH_Code = "SUPPLIER";
			supplier.OH_IsConsignee = true;
			supplier.OH_IsConsignor = true;

			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACE;
			declaration.US_EnableENS = true;
			declaration.US_CargoReleaseType = CargoReleaseTypeList.Codes.ACE;
			declaration.JE_OH_Importer = importer.PK;
			declaration.JE_OH_Supplier = supplier.PK;

			var invoice = Factory.New<JobComInvoiceHeader>();
			invoice.JZ_InvoiceNumber = "INVOICE";
			invoice.JZ_StandAloneInvoiceDirection = JobMessageTypeList.Codes.Import;
			invoice.JZ_OH_Buyer = importer.PK;
			invoice.JZ_OH_Supplier = supplier.PK;

			var invoiceLine = invoice.InvoiceLines.AddNew();
			invoiceLine.US_AgricultureLicNo = "AGLIC";
			invoiceLine.US_WoolLicenceNo = "WOOL";
			invoiceLine.US_CottonCertificateNo = "COTTON";
			invoiceLine.US_CAExportCertificate = "SUGAR";
			invoiceLine.US_CBTPACertificateNo = "CBTPA";

			Factory.Save();

			invoice.RefreshDefaultsWhenInvoiceAttachedToDeclarationRequired = true;
			invoice.JZ_JE = declaration.PK;
			invoice.JZ_ClusterKey = declaration.JE_ClusterKey;

			AssertEquals(1, declaration.Invoices.Count);
			AssertEquals(1, declaration.Invoices[0].InvoiceLines.Count);

			AssertEquals(5, declaration.Invoices[0].InvoiceLines[0].LicenceAndPermits.Count);
			var licenceAndPermits = declaration.Invoices[0].InvoiceLines[0].LicenceAndPermits.Cast<CusCodeData>();
			AssertEquals("AGLIC", licenceAndPermits.First(x => x.CY_Code == LicencePermitTypeList.Codes._14).CY_Data);
			AssertEquals("WOOL", licenceAndPermits.First(x => x.CY_Code == LicencePermitTypeList.Codes._17).CY_Data);
			AssertEquals("COTTON", licenceAndPermits.First(x => x.CY_Code == "??").CY_Data);
			AssertEquals("SUGAR", licenceAndPermits.First(x => x.CY_Code == LicencePermitTypeList.Codes._16).CY_Data);
			AssertEquals("CBTPA", licenceAndPermits.First(x => x.CY_Code == LicencePermitTypeList.Codes._18).CY_Data);

			licenceAndPermits.First(x => x.CY_Code == "??").CY_Code = LicencePermitTypeList.Codes._22;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			AssertEquals(0, declaration.Invoices[0].InvoiceLines[0].LicenceAndPermits.Count);
			AssertEquals("AGLIC", declaration.Invoices[0].InvoiceLines[0].US_AgricultureLicNo);
			AssertEquals("WOOL", declaration.Invoices[0].InvoiceLines[0].US_WoolLicenceNo);
			AssertEquals("COTTON", declaration.Invoices[0].InvoiceLines[0].US_CottonCertificateNo);
			AssertEquals("SUGAR", declaration.Invoices[0].InvoiceLines[0].US_CAExportCertificate);
			AssertEquals("CBTPA", declaration.Invoices[0].InvoiceLines[0].US_CBTPACertificateNo);

			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACE;
			AssertEquals(5, declaration.Invoices[0].InvoiceLines[0].LicenceAndPermits.Count);
			AssertEquals(ZString.Empty, declaration.Invoices[0].InvoiceLines[0].US_AgricultureLicNo);
			AssertEquals(ZString.Empty, declaration.Invoices[0].InvoiceLines[0].US_WoolLicenceNo);
			AssertEquals(ZString.Empty, declaration.Invoices[0].InvoiceLines[0].US_CottonCertificateNo);
			AssertEquals(ZString.Empty, declaration.Invoices[0].InvoiceLines[0].US_CAExportCertificate);
			AssertEquals(ZString.Empty, declaration.Invoices[0].InvoiceLines[0].US_CBTPACertificateNo);
		}

