		public void TestJE_TransportModeAndJE_MasterBill_SingleTransportModeROA()
		{
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACE;
			declaration.JE_TransportMode = TransportTypeList.Codes.Truck;
			declaration.JE_MasterBill = "MMDE1111";

			var transport = declaration.Transports.AddNew();
			transport.JW_TransportMode = Core.Constants.TransportModes.Road;
			transport.JW_TransportType = "MAI";
			AssertEquals("JE_TransportMode won't change", TransportTypeList.Codes.Truck, declaration.JE_TransportMode);
			AssertEquals("JE_MasterBill won't change cause JE_TransportMode not change", "MMDE1111", declaration.JE_MasterBill);

			declaration.JE_TransportMode = TransportTypeList.Codes.Road;
			AssertEquals("JE_MasterBill default", "ROAD, OTHER", declaration.JE_MasterBill);

			declaration.JE_MasterBill = "MMDE1111";
			transport.JW_TransportType = "OTH";
			AssertEquals("JE_TransportMode default to JW_TransportMode", TransportTypeList.Codes.Truck, declaration.JE_TransportMode);
			AssertEquals("JE_MasterBill won't change cause JE_TransportMode is Truck then JE_MasterBill wont be empty", "MMDE1111", declaration.JE_MasterBill);

			transport.JW_TransportMode = Core.Constants.TransportModes.Auto;
			transport.JW_TransportType = "MAI";
			AssertEquals("JE_TransportMode default to JW_TransportMode", TransportTypeList.Codes.Auto, declaration.JE_TransportMode);
			AssertEquals("JE_MasterBill default cause JE_TransportMode changed", "AUTO", declaration.JE_MasterBill);
		}

		public void TestUS_EntryDateFromConsoleWithMultipleLegs()
		{
			CreateLocoMapIfNotExists("3002", "USTIW", USLocoMapSystemUsageList.Codes.Sea);
			CreateLocoMapIfNotExists("2704", "USLAX", USLocoMapSystemUsageList.Codes.Sea);
			CreateLocoMapIfNotExists("5201", "USMIA", USLocoMapSystemUsageList.Codes.Sea);

			var consol = Factory.New<ForwardingConsol>();
			consol.JK_TransportMode = Core.Constants.TransportModes.Sea;
			consol.JK_AgentType = Core.Constants.AgentType.Agent;
			consol.JK_ConsolMode = Core.Constants.ContainerModes.BuyersConsol;
			consol.JK_RL_NKFirstForeignPort = "USTIW";
			consol.JK_RL_NKLastForeignPort = "USLAX";

			var leg1 = consol.Transports.AddNew();
			leg1.JW_TransportType = TransportModeCodeList.Codes.Sea;
			leg1.JW_TransportMode = Core.Constants.TransportModes.Mail;
			leg1.JW_RL_NKLoadPort = "AUSYD";
			leg1.JW_RL_NKDiscPortForBinding = "USTIW";
			leg1.JW_ETDForBinding = ZDateTime.Today.AddDays(-12);
			leg1.JW_ETAForBinding = ZDateTime.Today.AddDays(-10);

			var leg2 = consol.Transports.AddNew();
			leg2.JW_TransportMode = TransportModeCodeList.Codes.Rail;
			leg2.JW_TransportType = Core.Constants.TransportModes.Other;
			leg2.JW_RL_NKLoadPort = "USTIW";
			leg2.JW_RL_NKDiscPortForBinding = "USLAX";
			leg2.JW_ETAForBinding = ZDateTime.Today.AddDays(+10);

			var shipment = consol.Shipments.AddNew();
			shipment.JS_TransportMode = TransportModeCodeList.Codes.Sea;
			shipment.JS_PackingMode = "FCL";
			shipment.JS_ShipmentType = "STD";

			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACE;
			declaration.JE_TransportMode = TransportModeCodeList.Codes.Sea;
			declaration.JE_ContainerMode = ContainerModeList.Codes.Containerized;
			declaration.JE_JS = shipment.PK;
			declaration.JE_OverrideFreightDefaults = false;
			declaration.ShipmentSynchroniser.Synchronise(true);

			declaration.US_SchDEntry = "2704";
			AssertEquals("ZDateTime.Today.AddDays(+10)", leg2.JW_ETAForBinding, declaration.US_EntryDate);
		}

