		public void TestCustomsValue()
		{
			JobDeclaration declaration = Factory.New<JobDeclaration>();
			AssertEquals(ZDecimal.Zero, declaration.CustomsValue);

			JobComInvoiceHeader invoiceHeader1 = declaration.Invoices.AddNew();
			invoiceHeader1.JZ_RX_NKInvoice_Currency = helper.USD.RX_Code;

			JobComInvoiceLine invoiceLine1_1 = invoiceHeader1.JobComInvoiceLines.AddNew();
			invoiceLine1_1.JI_LinePrice = priceForCustomsValueTest1;
			JobComInvoiceLine invoiceLine1_2 = invoiceHeader1.JobComInvoiceLines.AddNew();
			invoiceLine1_2.JI_LinePrice = priceForCustomsValueTest2;

			JobComInvoiceHeader invoiceHeader2 = declaration.Invoices.AddNew();
			invoiceHeader2.JZ_RX_NKInvoice_Currency = helper.USD.RX_Code;

			JobComInvoiceLine invoiceLine2_1 = invoiceHeader2.JobComInvoiceLines.AddNew();
			invoiceLine2_1.JI_LinePrice = priceForCustomsValueTest3;
			JobComInvoiceLine invoiceLine2_2 = invoiceHeader2.JobComInvoiceLines.AddNew();
			invoiceLine2_2.JI_LinePrice = priceForCustomsValueTest4;

			ZDecimal sum = priceForCustomsValueTest1 + priceForCustomsValueTest2 + priceForCustomsValueTest3 + priceForCustomsValueTest4;
			AssertEquals(sum, declaration.CustomsValue);
		}
		const decimal priceForCustomsValueTest1 = 10m;
		const decimal priceForCustomsValueTest2 = 20m;
		const decimal priceForCustomsValueTest3 = 30m;
		const decimal priceForCustomsValueTest4 = 40m;

		public void TestSetDefaultsToUS_Box29IncludeContainers()
