		public void TestSetDefaultsIsHMFApplicable()
		{
			JobDeclaration declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			declaration.US_EnableENS = true;
			declaration.JE_TransportMode = TransportTypeList.Codes.Air;
			AssertEquals("IsHMFApplicable for AIR", "N", declaration.US_IsHMFApplicable);

			declaration.JE_TransportMode = TransportTypeList.Codes.Auto;
			AssertEquals("IsHMFApplicable for AUT", "N", declaration.US_IsHMFApplicable);

			declaration.JE_TransportMode = TransportTypeList.Codes.BorderWaterBorne;
			AssertEquals("IsHMFApplicable for BWB must be Y", "Y", declaration.US_IsHMFApplicable);

			declaration.JE_TransportMode = TransportTypeList.Codes.Mail;
			AssertEquals("IsHMFApplicable for MAI", "N", declaration.US_IsHMFApplicable);

			declaration.JE_TransportMode = TransportTypeList.Codes.Pedestrian;
			AssertEquals("IsHMFApplicable for PED", "N", declaration.US_IsHMFApplicable);

			declaration.JE_TransportMode = TransportTypeList.Codes.Rail;
			AssertEquals("IsHMFApplicable for RAI", "N", declaration.US_IsHMFApplicable);

			declaration.JE_TransportMode = TransportTypeList.Codes.Sea;
			AssertEquals("IsHMFApplicable for SEA", "Y", declaration.US_IsHMFApplicable);

			declaration.JE_TransportMode = TransportTypeList.Codes.Truck;
			AssertEquals("IsHMFApplicable for TRK", "N", declaration.US_IsHMFApplicable);

			declaration.JE_TransportMode = TransportTypeList.Codes.Sea;
			AssertEquals("IsHMFApplicable default to Y", YesNoDefaultList.Codes.Yes, declaration.US_IsHMFApplicable);
			declaration.US_EntryType = EntryTypeList.Codes.InformalFreeDutiable;
			AssertEquals("IsHMFApplicable for SEA when entry type is informal must be N", "N", declaration.US_IsHMFApplicable);

			declaration.US_IsHMFApplicable = YesNoDefaultList.Codes.Yes;
			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFTZ;
			AssertEquals("IsHMFApplicable must be N when entry type is FTZ ", "N", declaration.US_IsHMFApplicable);

			declaration.US_IsHMFApplicable = YesNoDefaultList.Codes.Yes;
			declaration.US_EntryType = EntryTypeList.Codes.WarehouseWithdrawalConsumption;
			AssertEquals("IsHMFApplicable must be N when entry type is in range 30-39", "N", declaration.US_IsHMFApplicable);

			declaration.US_IsHMFApplicable = YesNoDefaultList.Codes.Yes;
			declaration.US_EntryType = EntryTypeList.Codes.NAFTADutyDeferral;
			AssertEquals("IsHMFApplicable must be N when NAFTA duty deferral", "N", declaration.US_IsHMFApplicable);
			declaration.JE_TransportMode = TransportTypeList.Codes.BorderWaterBorne;
			AssertEquals("IsHMFApplicable for BWB must be Y - regardless of entry type", "Y", declaration.US_IsHMFApplicable);
		}

