		public void TestUS_TransactionsRelated()
		{
			JobDeclaration declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			declaration.US_EnableENS = true;
			declaration.JE_TransportMode = TransportTypeList.Codes.Air;

			OrgHeader importer = Factory.New<OrgHeader>();
			importer.OH_RL_NKClosestPort = "CATOR";
			OrgHeader importer2 = Factory.New<OrgHeader>();
			OrgHeader supplier = Factory.New<OrgHeader>();
			OrgSupplierBuyerLink link1 = supplier.BuyerLinks.AddNew(importer);
			link1.OL_RelatedParty = "Y";
			link1.OL_RN_NKImporterCountry = "CA";
			OrgSupplierBuyerLink link2 = supplier.BuyerLinks.AddNew(importer);
			link2.OL_RelatedParty = "N";
			link2.OL_RN_NKImporterCountry = "US";

			declaration.JE_OH_Importer = importer.PK;
			declaration.JE_RL_NKFinalDestination = "MXMXC";
			declaration.JE_OH_Supplier = supplier.PK;
			AssertEquals("Related Party should default", "Y", declaration.US_TransactionsRelated);

			declaration.JE_OH_Supplier = ZGuid.Empty;
			declaration.JE_OH_Importer = importer2.PK;
			declaration.JE_RL_NKFinalDestination = "MXMXC";
			declaration.JE_OH_Supplier = supplier.PK;
			AssertEquals("Related Party if not set should be what it was before", "Y", declaration.US_TransactionsRelated);

			declaration.US_TransactionsRelated = "N";
			declaration.JE_OH_Supplier = ZGuid.Empty;
			declaration.JE_OH_Importer = importer.PK;
			declaration.JE_RL_NKFinalDestination = "MXMXC";
			declaration.JE_OH_Supplier = supplier.PK;
			AssertEquals("Related Party should default", "Y", declaration.US_TransactionsRelated);

			declaration.JE_OH_Supplier = ZGuid.Empty;
			declaration.JE_OH_Importer = importer2.PK;
			declaration.JE_RL_NKFinalDestination = "USLAX";
			declaration.JE_OH_Supplier = supplier.PK;
			AssertEquals("Related Party if not set should be what it was before", "Y", declaration.US_TransactionsRelated);
			declaration.JE_OH_Importer = importer.PK;
			declaration.JE_RL_NKFinalDestination = "USLAX";
			declaration.JE_OH_Supplier = ZGuid.Empty;
			declaration.JE_OH_Supplier = supplier.PK;
			AssertEquals("Related Party should default", "N", declaration.US_TransactionsRelated);

			declaration.US_TransactionsRelated = "";
			declaration.JE_TransportMode = TransportTypeList.Codes.Sea;
			AssertEquals("Related Party shouldn't have changed", "", declaration.US_TransactionsRelated);

			declaration.JE_TransportMode = TransportTypeList.Codes.Air;
			AssertEquals("Related Party shouldn't have changed", "", declaration.US_TransactionsRelated);
		}

