			airLink1.PF_USPortOfLading = "68545";
			airLink1.PF_USPortOfUnLading = "4570";

			var supplierBuyerLink3 = supplier2.BuyerLinks.AddNew(importer2);
			supplierBuyerLink3.OL_RN_NKImporterCountry = Core.Constants.CountryCodes.UnitedStates;
			var buyerSupplierLinkAddInfo = supplierBuyerLink3.GetAddInfo();
			buyerSupplierLinkAddInfo.ZO_NAFTAReconIndicator = true;
			buyerSupplierLinkAddInfo.ZO_OtherReconIndicator = ReconIssueCodeList.Codes.Class9802Recon;

			var airLink = supplierBuyerLink3.OrgSupBuyLinkTrnModes[0];
			airLink.PF_TransportMode = TransportTypeList.Codes.Air;
			airLink.PF_USPortOfLading = "60267";
			airLink.PF_USPortOfUnLading = "2704";

			var seaLink = supplierBuyerLink3.OrgSupBuyLinkTrnModes.AddNew();
			seaLink.PF_TransportMode = TransportTypeList.Codes.Sea;
			seaLink.PF_USPortOfLading = "51100";
			seaLink.PF_USPortOfUnLading = "4103";

			var supplierBuyerLink4 = supplier2.BuyerLinks.AddNew(importer1);
			supplierBuyerLink4.OL_RN_NKImporterCountry = Core.Constants.CountryCodes.Australia;
			var airLink3 = supplierBuyerLink4.OrgSupBuyLinkTrnModes[0];
			airLink3.PF_TransportMode = TransportTypeList.Codes.Air;
			airLink3.PF_USPortOfLading = "6542";
			airLink3.PF_USPortOfUnLading = "75845";
