			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_OH_Supplier = supplier2.PK;
			declaration.JE_OH_Importer = importer2.PK;
			declaration.JE_MessageType = JobMessageTypeList.Codes.Export;
			declaration.JE_TransportMode = TransportTypeList.Codes.Sea;
			AssertNotEquals("51100", declaration.US_SchDLoading);
			AssertNotEquals("4103", declaration.US_SchDArrival);

			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			declaration.US_EnableENS = true;
			Factory.Save();
			AssertEquals("51100", declaration.US_SchDLoading);
			AssertEquals("4103", declaration.US_SchDArrival);
			AssertEquals("Other Recon Indicator should be defaulted", ReconIssueCodeList.Codes.Class9802Recon, declaration.US_OtherReconIndicator);
			AssertEquals("NAFTA Recon should be defaulted", true, declaration.US_NAFTAReconIndicator);

			declaration.JE_TransportMode = TransportTypeList.Codes.Air;
			AssertEquals("60267", declaration.US_SchDLoading);
			AssertEquals("2704", declaration.US_SchDArrival);

			declaration.US_FixRecon = true;
			declaration.JE_OH_Supplier = supplier1.PK;
			AssertEquals("68545", declaration.US_SchDLoading);
			AssertEquals("4570", declaration.US_SchDArrival);

			declaration.JE_OH_Importer = importer1.PK;
			AssertEquals("56879", declaration.US_SchDLoading);
			AssertEquals("3054", declaration.US_SchDArrival);

			AssertEquals("Other Recon Indicator should not be changed, it is locked", ReconIssueCodeList.Codes.Class9802Recon, declaration.US_OtherReconIndicator);
			AssertEquals("NAFTA Recon should not be changed, it is locked", true, declaration.US_NAFTAReconIndicator);

			declaration.JE_OH_Supplier = supplier2.PK;
			declaration.JE_OH_Importer = importer2.PK;
			AssertEquals("60267", declaration.US_SchDLoading);
			AssertEquals("2704", declaration.US_SchDArrival);

			declaration.JE_TransportMode = TransportTypeList.Codes.Road;
			AssertEquals("60267", declaration.US_SchDLoading);
			AssertEquals("2704", declaration.US_SchDArrival);

			declaration.JE_TransportMode = TransportTypeList.Codes.Sea;
			AssertEquals("51100", declaration.US_SchDLoading);
			AssertEquals("4103", declaration.US_SchDArrival);
		}

