		public void TestRecalculateReconIndicatorWhenSupplierIsChanged()
		{
			var declaration = Factory.New<JobDeclaration>();
			var importer = Factory.NewWithValidTestData<OrgHeader>();
			var supplier = Factory.NewWithValidTestData<OrgHeader>();

			var iorWrapper = OrgHeaderWrapper.New(importer);
			iorWrapper.ZO_OtherReconIndicator = ReconIssueCodeList.Codes.ValueRecon;
			declaration.JE_OA_DeclarantAddress = importer.MainAddress.PK;
			Factory.Save();

			declaration.JE_OH_Supplier = supplier.PK;
			declaration.JE_OH_Importer = importer.PK;
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			Factory.Save();

			AssertEquals(ReconIssueCodeList.Codes.ValueRecon, declaration.US_OtherReconIndicator);

			var supplier2 = Factory.NewWithValidTestData<OrgHeader>();

			var iorWrapper2 = OrgHeaderWrapper.New(importer);
			iorWrapper2.ZO_OtherReconIndicator = ReconIssueCodeList.Codes.ClassRecon;
			var supplierBuyerLink = supplier2.BuyerLinks.AddNew(importer);
			Factory.Save();

			declaration.JE_OH_Supplier = supplier2.PK;
			Factory.Save();
			AssertEquals(ReconIssueCodeList.Codes.ClassRecon, declaration.US_OtherReconIndicator);

			iorWrapper.ZO_OtherReconIndicator = ReconIssueCodeList.Codes.ValueRecon;
			Factory.Save();
			AssertEquals(ReconIssueCodeList.Codes.ClassRecon, declaration.US_OtherReconIndicator);

			declaration.JE_OH_Supplier = supplier.PK;
			Factory.Save();
			AssertEquals(ReconIssueCodeList.Codes.ValueRecon, declaration.US_OtherReconIndicator);
		}

