		public void TestTotalNoOfPacksDefaultingToManifestAndPackagingDetails()
		{
			JobDeclaration declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			declaration.US_EnableENS = true;
			declaration.JE_TotalNoOfPacks = 20;
			declaration.JE_TotalNoOfPacksPackType = ABIUnitOfMeasureList.Codes.Pieces;
			AssertEquals(0, declaration.Bills.Count);
			declaration.JE_HouseBill = "HB1";
			AssertEquals(1, declaration.Bills.Count);
			Bill bill = declaration.PrimaryHouseBill;
			AssertEquals(BillTypeList.Codes.HouseBill, bill.CU_BillType);
			AssertEquals(20m, bill.CU_NoOfPacks);
			AssertEquals(ABIUnitOfMeasureList.Codes.Pieces, bill.CU_PackType);
			AssertEquals(1, declaration.Packages.Count);
			Package package = declaration.Packages[0];
			AssertEquals(bill.PK, package.PackingGroup.CR_CU_HouseBill);
			AssertEquals(20, package.CW_PackQty);
			AssertEquals(ABIUnitOfMeasureList.Codes.Pieces, package.CW_PackType);

			declaration.JE_TotalNoOfPacks = 30;
			declaration.JE_TotalNoOfPacksPackType = ABIUnitOfMeasureList.Codes.Pairs;
			AssertEquals(1, declaration.Bills.Count);
			bill = declaration.Bills[0];
			AssertEquals(BillTypeList.Codes.HouseBill, bill.CU_BillType);
			AssertEquals(30m, bill.CU_NoOfPacks);
			AssertEquals(ABIUnitOfMeasureList.Codes.Pairs, bill.CU_PackType);
			AssertEquals(1, declaration.Packages.Count);
			package = declaration.Packages[0];
			AssertEquals(bill.PK, package.PackingGroup.CR_CU_HouseBill);
			AssertEquals(30, package.CW_PackQty);
			AssertEquals(ABIUnitOfMeasureList.Codes.Pairs, package.CW_PackType);

			declaration.Bills.RemoveAndDeleteAll();
			declaration.JE_MasterBill = "OBDSDS";
			declaration.JE_TotalNoOfPacks = 35;
			declaration.JE_TotalNoOfPacksPackType = ABIUnitOfMeasureList.Codes.Pounds;
			AssertEquals(1, declaration.Bills.Count);
			bill = declaration.Bills[0];
			AssertEquals(BillTypeList.Codes.MasterBill, bill.CU_BillType);
			AssertEquals("OBDSDS", bill.CU_BillNum);
			AssertEquals(35m, bill.CU_NoOfPacks);
			AssertEquals(ABIUnitOfMeasureList.Codes.Pounds, bill.CU_PackType);
			package = declaration.Packages[0];
			AssertEquals(bill.PK, package.PackingGroup.CR_CU_HouseBill);
			AssertEquals(35, package.CW_PackQty);
			AssertEquals(ABIUnitOfMeasureList.Codes.Pounds, package.CW_PackType);

			declaration.JE_TotalNoOfPacks = 30;
			declaration.JE_TotalNoOfPacksPackType = ABIUnitOfMeasureList.Codes.Pairs;
			AssertEquals(1, declaration.Bills.Count);
			bill = declaration.Bills[0];
			AssertEquals(BillTypeList.Codes.MasterBill, bill.CU_BillType);
			AssertEquals("OBDSDS", bill.CU_BillNum);
			AssertEquals(30m, bill.CU_NoOfPacks);
			AssertEquals(ABIUnitOfMeasureList.Codes.Pairs, bill.CU_PackType);
			package = declaration.Packages[0];
			AssertEquals(bill.PK, package.PackingGroup.CR_CU_HouseBill);
			AssertEquals(30, package.CW_PackQty);
			AssertEquals(ABIUnitOfMeasureList.Codes.Pairs, package.CW_PackType);

			declaration.Bills.RemoveAndDeleteAll();
			declaration.JE_HouseBill = "HOSDSFD";
			declaration.JE_TotalNoOfPacks = 20;
			declaration.JE_TotalNoOfPacksPackType = ABIUnitOfMeasureList.Codes.QuartsLiquidUsVolume;
			AssertEquals(1, declaration.Bills.Count);
			bill = declaration.Bills[0];
			AssertEquals(BillTypeList.Codes.HouseBill, bill.CU_BillType);
			AssertEquals("HOSDSFD", bill.CU_BillNum);
			AssertEquals(20m, bill.CU_NoOfPacks);
			AssertEquals(ABIUnitOfMeasureList.Codes.QuartsLiquidUsVolume, bill.CU_PackType);
			package = declaration.Packages[0];
			AssertEquals(bill.PK, package.PackingGroup.CR_CU_HouseBill);
			AssertEquals(20, package.CW_PackQty);
			AssertEquals(ABIUnitOfMeasureList.Codes.QuartsLiquidUsVolume, package.CW_PackType);

			Bill bill2 = declaration.Bills.AddNew();
			bill2.CU_BillType = Customs.Business.BillTypeList.Codes.HouseBill;
			bill2.CU_BillNum = "2";
			bill2.CU_PackType = ABIUnitOfMeasureList.Codes.DirectCurrent;
			bill2.CU_NoOfPacks = 10m;

			declaration.JE_TotalNoOfPacks = 30;
			declaration.JE_TotalNoOfPacksPackType = ABIUnitOfMeasureList.Codes.Pairs;
			AssertEquals(2, declaration.Bills.Count);
			AssertEquals(BillTypeList.Codes.HouseBill, bill.CU_BillType);
			AssertEquals("HOSDSFD", bill.CU_BillNum);
			AssertEquals(20m, bill.CU_NoOfPacks);
			AssertEquals(ABIUnitOfMeasureList.Codes.QuartsLiquidUsVolume, bill.CU_PackType);
			package = bill.PackingGroups[0].Packages[0];
			AssertEquals(bill.PK, package.PackingGroup.CR_CU_HouseBill);
			AssertEquals(20, package.CW_PackQty);
			AssertEquals(ABIUnitOfMeasureList.Codes.QuartsLiquidUsVolume, package.CW_PackType);

			AssertEquals(BillTypeList.Codes.HouseBill, bill2.CU_BillType);
			AssertEquals("2", bill2.CU_BillNum);
			AssertEquals(10m, bill2.CU_NoOfPacks);
			AssertEquals(ABIUnitOfMeasureList.Codes.DirectCurrent, bill2.CU_PackType);
			Package package2 = bill2.PackingGroups[0].Packages[0];
			AssertEquals(bill2.PK, package2.PackingGroup.CR_CU_HouseBill);
			AssertEquals(0, package2.CW_PackQty);
			AssertEquals("", package2.CW_PackType);
		}

		public void TestHasLineLevelUltimateConsignees()
		{
			var ultimateConsignee = Factory.New<OrgHeader>();
			var ultimateConsignee2 = Factory.New<OrgHeader>();

			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			declaration.US_EnableENS = true;

			declaration.JE_OA_ConsigneeAddress = ultimateConsignee.MainAddress.PK;

			var invoice = declaration.Invoices.AddNew();
			var invoiceLine1 = declaration.InvoiceLines.AddNew();
			var invoiceLine2 = declaration.InvoiceLines.AddNew();

			AssertEquals(false, declaration.HasLineLevelUltimateConsignees);

			invoice.JZ_OA_ConsigneeAddress = ultimateConsignee2.MainAddress.PK;
			AssertEquals(true, declaration.HasLineLevelUltimateConsignees);

			invoiceLine1.JI_OA_ConsigneeAddress = ultimateConsignee.MainAddress.PK;
			AssertEquals(true, declaration.HasLineLevelUltimateConsignees);

			invoiceLine2.JI_OA_ConsigneeAddress = ultimateConsignee.MainAddress.PK;
			AssertEquals(false, declaration.HasLineLevelUltimateConsignees);
		}

