		public void TestSetDestinationStateFromUC()
		{
			OrgHeader ultimateConsignee = Factory.New<OrgHeader>();
			ultimateConsignee.OH_RL_NKClosestPort = "USCHI";

			JobDeclaration declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			declaration.US_EnableENS = true;
			AssertEquals("", declaration.US_DestinationState);

			declaration.JE_OA_ConsigneeAddress = ultimateConsignee.MainAddress.PK;
			AssertEquals("Destination State should not default with Registry default", "", declaration.US_DestinationState);

			USCustomsDataRegistry.Instance.DefaultDestState.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, true);

			declaration.JE_OA_ConsigneeAddress = ZGuid.Empty;
			declaration.JE_OA_ConsigneeAddress = ultimateConsignee.MainAddress.PK;
			AssertEquals("Destination State should default from Ultimate Consignee - Fall back to main UNLOCO state", "IL", declaration.US_DestinationState);
			AssertNoNotifications(declaration.US_DestinationStateInfo);

			ultimateConsignee.MainAddress.OA_State = "NY";
			declaration.US_DestinationState = "";
			declaration.JE_OA_ConsigneeAddress = ZGuid.Empty;
			declaration.JE_OA_ConsigneeAddress = ultimateConsignee.MainAddress.PK;
			AssertEquals("Destination State should default from Ultimate Consignee - Fall back to main address state", "NY", declaration.US_DestinationState);
			AssertNoNotifications(declaration.US_DestinationStateInfo);

			OrgAddress pickupAddress = ultimateConsignee.Addresses.AddNew(OrgAddressType.PickupAndDelivery, false);
			pickupAddress.OA_State = "New Hampshire";
			declaration.US_DestinationState = "";
			declaration.JE_OA_ConsigneeAddress = ZGuid.Empty;
			declaration.JE_OA_ConsigneeAddress = ultimateConsignee.MainAddress.PK;
			AssertEquals("Destination State should default from Ultimate Consignee - Fall back to pickup address state", "NH", declaration.US_DestinationState);
			AssertNoNotifications(declaration.US_DestinationStateInfo);

			OrgAddress deliveryAddress = ultimateConsignee.Addresses.AddNew(OrgAddressType.Delivery, false);
			deliveryAddress.OA_State = "FL";
			declaration.US_DestinationState = "";
			declaration.JE_OA_ConsigneeAddress = ZGuid.Empty;
			declaration.JE_OA_ConsigneeAddress = ultimateConsignee.MainAddress.PK;
			AssertEquals("Destination State should default from Ultimate Consignee - from delivery address state", "FL", declaration.US_DestinationState);
			AssertNoNotifications(declaration.US_DestinationStateInfo);

			deliveryAddress.OA_State = "FLORDA"; // deliberate typo of state name
			declaration.US_DestinationState = "";
			declaration.JE_OA_ConsigneeAddress = ZGuid.Empty;
			declaration.JE_OA_ConsigneeAddress = ultimateConsignee.MainAddress.PK;
			AssertEquals("Destination State should default from Ultimate Consignee - in this case falling back to UNLOCO State due to typo on organisation address", "IL", declaration.US_DestinationState);
			AssertNoNotifications(declaration.US_DestinationStateInfo);

			deliveryAddress.OA_State = "FR"; // deliberate typo of state abbreviation
			declaration.US_DestinationState = "";
			declaration.JE_OA_ConsigneeAddress = ZGuid.Empty;
			declaration.JE_OA_ConsigneeAddress = ultimateConsignee.MainAddress.PK;
			AssertEquals("Destination State should default from Ultimate Consignee - but show validation error in this case due to typo on organisation address", "FR", declaration.US_DestinationState);
			AssertHasNotifications(declaration.US_DestinationStateInfo);
		}

