		public void TestDefaultJE_GS_CusAgentForImport()
		{
			var rememberSystemAccount = GlbStaff.CurrentUser.GS_IsSystemAccount;
			GlbStaff.CurrentUser.GS_IsSystemAccount = false;
			Declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			Declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			declaration.US_EnableENS = true;

			AssertEquals(GlbStaff.CurrentUser.GS_Code, Declaration.JE_GS_NKCusAgent);

			try
			{
				GlbStaff.CurrentUser.GS_IsSystemAccount = true;
				Declaration.JE_MessageType = "";
				Declaration.JE_GS_NKCusAgent = "";
				Declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
				Declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
				AssertEquals(ZString.Empty, Declaration.JE_GS_NKCusAgent);
