			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;

			declaration.JE_OA_ShipToPartyAddress = shipToPartyPK;
			AssertEquals("should return an effective value", shipToPartyPK, declaration.JE_OA_ShipToPartyAddress);

			USCustomsDataRegistry.Instance.DoDefaultShipTo.SetValue(Guid.Empty, Env.CurrentBranchPK, Guid.Empty, true);
			declaration.JE_OA_ShipToPartyAddress = ZGuid.Empty;
			var ultimateConsignee = Factory.New<OrgHeader>();
			var ultiOrgAddressPK = ultimateConsignee.MainAddress.PK;
			declaration.JE_OA_ConsigneeAddress = ultiOrgAddressPK;
			AssertEquals("should default from Ultimate Consignee", ultiOrgAddressPK, declaration.JE_OA_ShipToPartyAddress);
			declaration.JE_OA_ShipToPartyAddress = shipToPartyPK;
			declaration.JE_OA_ConsigneeAddress = ZGuid.Empty;
