			AssertEquals("should override from Ultimate Consignee", ultiOrgAddressPK, declaration.JE_OA_ShipToPartyAddress);

			USCustomsDataRegistry.Instance.DoDefaultShipTo.SetValue(Guid.Empty, Env.CurrentBranchPK, Guid.Empty, false);
