		public void TestJE_Calc_ReconJob()
		{
			DeclarationTestHelper.SetEntryFilerCode("XJ5");
			var declaration1 = Factory.New<JobDeclaration>();
			declaration1.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration1.US_EntryType = EntryTypeList.Codes.Warehouse;
			declaration1.US_EnableENS = true;
			declaration1.Invoices.AddNew();
			declaration1.InvoiceLines.AddNew();
			declaration1.US_OtherReconIndicator = ReconIssueCodeList.Codes.ClassRecon;
			declaration1.US_FixRecon = true;
			AssertEquals(ReconIssueCodeList.Descriptions.ClassRecon, declaration1.OtherReconIndicatorDescription);
			declaration1.DoMerge(new SendsMessagesToCustomsShutterUpperer());

			var declaration2 = Factory.New<JobDeclaration>();
			declaration2.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration2.US_EntryType = EntryTypeList.Codes.Warehouse;
			declaration2.US_EnableENS = true;
			declaration2.US_OtherReconIndicator = ReconIssueCodeList.Codes.ClassRecon;
			declaration2.US_FixRecon = true;

			var invoice1 = declaration2.Invoices.AddNew();
			invoice1.JobComInvoiceLines.AddNew();

			declaration2.DoMerge(new SendsMessagesToCustomsShutterUpperer());

			Factory.Save();//To generate Entry Numbers

			var reconDeclaration = new ReconDeclaration(Factory.New<JobDeclaration>());
			var reconOriginalEntry = reconDeclaration.OriginalEntries.AddNew();
			reconOriginalEntry.CH_OrigEntryReference = "XJ5" + declaration1.CustomsEntryHeaders[0].EntryNumber;
			var reconOriginalEntry2 = reconDeclaration.OriginalEntries.AddNew();
			reconOriginalEntry2.CH_OrigEntryReference = "XJ5" + declaration2.CustomsEntryHeaders[0].EntryNumber;

			var reconDeclaration2 = new ReconDeclaration(Factory.New<JobDeclaration>());
			var reconOriginalEntry3 = reconDeclaration2.OriginalEntries.AddNew();
			reconOriginalEntry3.CH_OrigEntryReference = "XJ5" + declaration2.CustomsEntryHeaders[0].EntryNumber;

			Factory.Save();//To generate JE_DeclarationReference

			AssertEquals(reconDeclaration.JE_DeclarationReference, declaration1.JE_Calc_ReconJob);

			var reconJobReference = declaration2.JE_Calc_ReconJob;
			AssertEquals(true, reconJobReference.Contains(reconDeclaration.JE_DeclarationReference));
			AssertEquals(true, reconJobReference.Contains(reconDeclaration2.JE_DeclarationReference));
		}

		public void TestCopyReconJob()
		{
			var importer = Factory.New<OrgHeader>();
			importer.FillWithValidTestData();

			ReconDeclaration reconDeclaration = new ReconDeclaration(Factory.New<JobDeclaration>());
			reconDeclaration.JE_OH_Importer = importer.PK;
			reconDeclaration.US_EstimatedEntryDate = ZDateTime.Today;
			reconDeclaration.US_IssueCode = ReconIssueCodeList.Codes.ClassRecon;
			reconDeclaration.ReconWrappedJobDeclaration.US_EntryFilerCode = "XJ5";
			reconDeclaration.US_SuretyCode = "891";
			reconDeclaration.US_PaymentType = PaymentTypeList.Codes.BatchedByDailyPrintDateAndFilerCode;
			reconDeclaration.US_PreliminaryStatementPrintDate = ZDateTime.Today.AddDays(1);
			reconDeclaration.ReconEntry.CH_Status = ReconMessageStatusList.Codes.ClearReconOriginal;
			reconDeclaration.ReconWrappedJobDeclaration.JE_EntryStatus = ReconMessageStatusList.Codes.ClearReconOriginal;
			Factory.Save();
			var copiedReconDeclaration = new ReconDeclaration((JobDeclaration)((ITemplateCopyable)reconDeclaration.ReconWrappedJobDeclaration).TemplateCopy());

			AssertEquals("JE_OH_Importer", reconDeclaration.Importer, copiedReconDeclaration.Importer);
			AssertEquals("US_EstimatedEntryDate should not be copied", ZDateTime.Empty, copiedReconDeclaration.US_EstimatedEntryDate);
			AssertEquals("US_IssueCode", reconDeclaration.US_IssueCode, copiedReconDeclaration.US_IssueCode);
			AssertEquals("US_EntryFilerCode", "XJ5", copiedReconDeclaration.US_EntryFilerCode);
			AssertEquals("US_SuretyCode", reconDeclaration.US_SuretyCode, copiedReconDeclaration.US_SuretyCode);
			AssertEquals("US_PaymentType", reconDeclaration.US_PaymentType, copiedReconDeclaration.US_PaymentType);
			AssertEquals("US_PreliminaryStatementPrintDate should not be copied", ZDateTime.Empty, copiedReconDeclaration.US_PreliminaryStatementPrintDate);
			AssertEquals("MessageStatus should not be copied", ZString.Empty, copiedReconDeclaration.MessageStatus);
			AssertEquals("CustomsStatus should not be copied", ZString.Empty, copiedReconDeclaration.CustomsStatus);
			AssertEquals("EntryNumber should not be copied", ZString.Empty, copiedReconDeclaration.ReconEntryNumber);
		}

