			entry.CH_MessageType = CusEntryHeaderMessageTypeList.Codes.EntrySummary;

			var entry2 = declaration.CustomsEntryHeaders.AddNew();
			entry2.CH_MessageType = CusEntryHeaderMessageTypeList.Codes.EntrySummary;

			var entry3 = declaration.CustomsEntryHeaders.AddNew();
			entry3.CH_MessageType = CusEntryHeaderMessageTypeList.Codes.CargoRelease;

			var entry4 = declaration.CustomsEntryHeaders.AddNew();
			entry4.CH_MessageType = CusEntryHeaderMessageTypeList.Codes.ForeignTradeZone;

			var dutyProvider = (IDutyDataLineHeaderProvider)declaration;

			List<IDutyDataLineHeader> entries = new List<IDutyDataLineHeader>(dutyProvider.EntriesToCalculateDutyFeeTax);
			AssertEquals(3, entries.Count);
			Assert("should only contain entry summary entries", entries.Contains(entry));
			Assert("should only contain entry summary entries", entries.Contains(entry2));
			Assert("should also contain FTZ", entries.Contains(entry4));

			Assert(dutyProvider.IsCustomsChargeRelevantForDecType(Core.Constants.USCustoms.FeeCodes.Mango));
			Assert(dutyProvider.IsCustomsChargeRelevantForDecType(Core.Constants.USCustoms.FeeCodes.HMF));

			declaration.JE_MessageType = JobMessageTypeList.Codes.FTZ;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			Assert(!dutyProvider.IsCustomsChargeRelevantForDecType(Core.Constants.USCustoms.FeeCodes.Mango));
			Assert(dutyProvider.IsCustomsChargeRelevantForDecType(Core.Constants.USCustoms.FeeCodes.HMF));
		}

