		public void TestIsCargoReleaseValidationMode()
		{
			AssertEquals(false, Declaration.IsCargoReleaseValidationMode);

			Declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			Declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			Declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			Declaration.US_EnableENS = false;
			Declaration.US_EnableCRL = true;
			AssertEquals("Cargo Release Validation mode set from US_CertifyCargoRelease setter", true, Declaration.IsCargoReleaseValidationMode);

			Declaration.US_CargoReleaseType = CargoReleaseTypeList.Codes.CR;
			AssertEquals(true, Declaration.IsCargoReleaseValidationMode);

			Declaration.US_EnableENS = true;
			AssertEquals(true, Declaration.IsCargoReleaseValidationMode);

			Declaration.US_EnableCRL = false;
			AssertEquals(true, Declaration.IsCargoReleaseValidationMode);
			Declaration.US_CertifyCargoRelease = false;
			AssertEquals(false, Declaration.IsCargoReleaseValidationMode);

			Declaration.US_CertifyCargoRelease = true;
			AssertEquals(true, Declaration.IsCargoReleaseValidationMode);

			Declaration.JE_TransportMode = TransportTypeList.Codes.Truck;
			Declaration.US_EnableCRL = true;
			Declaration.US_CertifyCargoRelease = true;
			AssertEquals(true, Declaration.IsCargoReleaseValidationMode);
			AssertEquals(false, Declaration.IsACECargoReleaseValidationMode);

			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACE;
			declaration.US_EnableENS = true;
			declaration.US_EnableCRL = true;
			AssertEquals("Should be ACE Cargo Release validation mode", true, declaration.IsACECargoReleaseValidationMode);

			declaration.US_EnableCRL = false;
			declaration.RecalculateValidationModesOnDeclaration();
			AssertEquals("Should not be ACE Cargo Release validation mode", false, declaration.IsACECargoReleaseValidationMode);

			declaration.US_CertifyCargoRelease = true;
			declaration.US_CargoReleaseType = CargoReleaseTypeList.Codes.ACE;
			AssertEquals("Should be ACE Cargo Release validation mode", true, declaration.IsACECargoReleaseValidationMode);
		}

