		public void TestSetterOfJE_ExportDate()
		{
			JobDeclaration declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			declaration.US_EnableENS = true;

			declaration.JE_ExportDate = ZDateTime.BrettsBirthday;

			JobComInvoiceHeader invoice = declaration.Invoices.AddNew();
			invoice.US_DateOfExport = ZDateTime.BrettsBirthday;
			AssertEquals("DateOfExport", ZDateTime.BrettsBirthday, invoice.US_DateOfExport);

			JobComInvoiceHeader invoice2 = declaration.Invoices.AddNew();
			invoice2.US_DateOfExport = ZDateTime.BrettsBirthday.AddDays(1);
			AssertEquals("DateOfExport", ZDateTime.BrettsBirthday.AddDays(1), invoice2.US_DateOfExport);

			declaration.JE_ExportDate = ZDateTime.BrettsBirthday.AddDays(2).AddHours(6).AddMinutes(30);
			AssertEquals("DateOfExport", ZDateTime.BrettsBirthday.AddDays(2), invoice.US_DateOfExport);
			AssertEquals("DateOfExport", ZDateTime.BrettsBirthday.AddDays(1), invoice2.US_DateOfExport);
		}

