		public void TestSetInvoiceHeaderExportCountry()
		{
			JobDeclaration declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			declaration.US_EnableENS = true;

			JobComInvoiceHeader invoice = declaration.Invoices.AddNew();
			JobComInvoiceHeader invoice2 = declaration.Invoices.AddNew();

			declaration.US_UC_NKCountryOfExport = Core.Constants.CountryCodes.SouthAfrica;
			AssertEquals(Core.Constants.CountryCodes.SouthAfrica, invoice.US_UC_NKCountryOfExport);
			AssertEquals(Core.Constants.CountryCodes.SouthAfrica, invoice2.US_UC_NKCountryOfExport);

			declaration.US_UC_NKCountryOfExport = Core.Constants.CountryCodes.Australia;
			AssertEquals(Core.Constants.CountryCodes.Australia, invoice.US_UC_NKCountryOfExport);
			AssertEquals(Core.Constants.CountryCodes.Australia, invoice2.US_UC_NKCountryOfExport);

			invoice2.US_UC_NKCountryOfExport = Core.Constants.CountryCodes.Malaysia;

			declaration.US_UC_NKCountryOfExport = Core.Constants.CountryCodes.Singapore;
			AssertEquals(Core.Constants.CountryCodes.Singapore, invoice.US_UC_NKCountryOfExport);
