		public void TestUS_InbondTypeAndUS_EntryType()
		{
			JobDeclaration declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;

			declaration.JE_VesselName = VesselForTest;
			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			declaration.US_EnableENS = true;
			AssertEquals(VesselForTest, declaration.JE_VesselName);

			declaration.JE_VesselName = VesselForTest;
			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFTZ;
			AssertEquals(VesselForTest, declaration.JE_VesselName);

			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			declaration.US_EnableENS = true;

			declaration.US_InbondType = EntryTypeList.Codes.ImmediateTransportation;
			AssertEquals("US_EnableINB should no longer be enabled by setting US_InBondType", false, declaration.US_EnableINB);

			//for exwarehouse
			declaration.US_EntryType = EntryTypeList.Codes.WarehouseWithdrawalConsumption;

			declaration.JE_VesselName = VesselForTest;
			declaration.JE_TransportMode = TransportTypeList.Codes.Sea;
			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFTZ;
			AssertEquals("Vessel is cleared", ZString.Empty, declaration.JE_VesselName);

			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			declaration.US_EnableENS = true;

			AssertEquals("US_EnableINB enabled", false, declaration.US_EnableINB);
			AssertEquals("US_InbondType is empty", true, declaration.US_InbondType == "");

			AssertEquals("PreCondition", true, declaration.US_EnableENS);
			declaration.US_EnableAII = true;
			declaration.US_EnableCRL = true;
			declaration.US_EnableENS = false;
			AssertEquals("US_EnableENS disabled", false, declaration.US_EnableENS);
			AssertEquals("US_EnableAII disabled", true, declaration.US_EnableAII);
			AssertEquals("US_EnableCRL enabled", true, declaration.US_EnableCRL);

			EntryTypeList entryTypeList = new EntryTypeList();
			for (int i = 0; i < entryTypeList.Count; i++)
			{
				declaration.US_EntryMode = EntryModeList.Codes.RLF;
				declaration.US_EntryType = entryTypeList[i].Code;
				if (EntryTypeList.IsElectronicFilingAllowed(declaration.IsACE, declaration.US_EntryType))
				{
					AssertEquals("Entry Type = " + declaration.US_EntryType, EntryModeList.Codes.RLF, declaration.US_EntryMode);
				}
				else
				{
					AssertEquals("Entry Type = " + declaration.US_EntryType, "", declaration.US_EntryMode);
				}
			}
		}
		const string VesselForTest = "Vessel";

