		public void TestIMessageManageableBizObj()
		{
			JobDeclaration declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Export;

			declaration.Invoices.AddNew();
			declaration.InvoiceLines.AddNew();

			declaration.DoMerge(new SendsMessagesToCustomsShutterUpperer());

			CusEntryHeader exportEntry = declaration.ActiveEntryHeaders[0];

			IBackDoorSavingSupportableBizObj bizObj = declaration;
			AssertEquals("SupportBackDoorForSavingWhenAmendmentDetected", false, bizObj.SupportBackDoorForSavingWhenAmendmentDetected);
			AssertEquals("IsInAStatusAmendmentSendable", false, bizObj.IsInAStatusAmendmentSendable);

			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			declaration.US_EnableENS = true;
			AssertEquals("At this point, system should not deactivate entries because JE_MessageType might have changed accidentally", true, exportEntry.IsActive);

			CusEntryHeader ensEntry = declaration.CustomsEntryHeaders.AddNew();
			ensEntry.CH_MessageType = CusEntryHeaderMessageTypeList.Codes.EntrySummary;

			AssertEquals("SupportBackDoorForSavingWhenAmendmentDetected", true, bizObj.SupportBackDoorForSavingWhenAmendmentDetected);
			AssertEquals("Amendment Detection is turned off", false, bizObj.IsInAStatusAmendmentSendable);
		}

		public void TestIsRelevantFor()
		{
			var declaration = Factory.New<JobDeclaration>();
			declaration.US_EnableAII = true;
			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			declaration.US_EnableENS = true;
			declaration.US_EnableCRL = true;
			declaration.US_EnableINB = true;
			declaration.JE_MessageType = JobMessageTypeList.Codes.Export;
			AssertEquals(false, declaration.IsRelevantFor(CusEntryHeaderMessageTypeList.Codes.CargoRelease));
			AssertEquals(false, declaration.IsRelevantFor(CusEntryHeaderMessageTypeList.Codes.BorderCargoRelease));
			AssertEquals(false, declaration.IsRelevantFor(CusEntryHeaderMessageTypeList.Codes.EntrySummary));
			AssertEquals(true, declaration.IsRelevantFor(CusEntryHeaderMessageTypeList.Codes.Export));
			AssertEquals(false, declaration.IsRelevantFor(CusEntryHeaderMessageTypeList.Codes.InBond));

			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			declaration.US_EnableENS = true;
			declaration.US_EnableCRL = false;
			AssertEquals(false, declaration.IsRelevantFor(CusEntryHeaderMessageTypeList.Codes.CargoRelease));
			AssertEquals(false, declaration.IsRelevantFor(CusEntryHeaderMessageTypeList.Codes.BorderCargoRelease));
			AssertEquals(true, declaration.IsRelevantFor(CusEntryHeaderMessageTypeList.Codes.EntrySummary));
			AssertEquals(false, declaration.IsRelevantFor(CusEntryHeaderMessageTypeList.Codes.Export));
			AssertEquals(true, declaration.IsRelevantFor(CusEntryHeaderMessageTypeList.Codes.InBond));

			declaration.US_EnableCRL = true;
			AssertEquals(true, declaration.IsRelevantFor(CusEntryHeaderMessageTypeList.Codes.CargoRelease));
			AssertEquals(false, declaration.IsRelevantFor(CusEntryHeaderMessageTypeList.Codes.BorderCargoRelease));
			AssertEquals(true, declaration.IsRelevantFor(CusEntryHeaderMessageTypeList.Codes.EntrySummary));
			AssertEquals(false, declaration.IsRelevantFor(CusEntryHeaderMessageTypeList.Codes.Export));
			AssertEquals(true, declaration.IsRelevantFor(CusEntryHeaderMessageTypeList.Codes.InBond));
			AssertEquals(false, declaration.IsRelevantFor(CusEntryHeaderMessageTypeList.Codes.ACECargoRelease));

			declaration.JE_TransportMode = TransportTypeList.Codes.Truck;
			declaration.US_CargoReleaseType = CargoReleaseTypeList.Codes.BCR;
			AssertEquals(false, declaration.IsRelevantFor(CusEntryHeaderMessageTypeList.Codes.CargoRelease));
			AssertEquals(true, declaration.IsRelevantFor(CusEntryHeaderMessageTypeList.Codes.BorderCargoRelease));
			AssertEquals(true, declaration.IsRelevantFor(CusEntryHeaderMessageTypeList.Codes.EntrySummary));
			AssertEquals(false, declaration.IsRelevantFor(CusEntryHeaderMessageTypeList.Codes.Export));
			AssertEquals(true, declaration.IsRelevantFor(CusEntryHeaderMessageTypeList.Codes.InBond));
			AssertEquals(false, declaration.IsRelevantFor(CusEntryHeaderMessageTypeList.Codes.ACECargoRelease));

			declaration.US_CargoReleaseType = CargoReleaseTypeList.Codes.CR;
			AssertEquals(true, declaration.IsRelevantFor(CusEntryHeaderMessageTypeList.Codes.CargoRelease));
			AssertEquals(false, declaration.IsRelevantFor(CusEntryHeaderMessageTypeList.Codes.BorderCargoRelease));
			AssertEquals(true, declaration.IsRelevantFor(CusEntryHeaderMessageTypeList.Codes.EntrySummary));
			AssertEquals(false, declaration.IsRelevantFor(CusEntryHeaderMessageTypeList.Codes.Export));
			AssertEquals(true, declaration.IsRelevantFor(CusEntryHeaderMessageTypeList.Codes.InBond));
			AssertEquals(false, declaration.IsRelevantFor(CusEntryHeaderMessageTypeList.Codes.ForeignTradeZone));
			AssertEquals(false, declaration.IsRelevantFor(CusEntryHeaderMessageTypeList.Codes.ACECargoRelease));

			declaration.JE_MessageType = JobMessageTypeList.Codes.FTZ;
			AssertEquals(false, declaration.IsRelevantFor(CusEntryHeaderMessageTypeList.Codes.CargoRelease));
			AssertEquals(false, declaration.IsRelevantFor(CusEntryHeaderMessageTypeList.Codes.BorderCargoRelease));
			AssertEquals(false, declaration.IsRelevantFor(CusEntryHeaderMessageTypeList.Codes.EntrySummary));
			AssertEquals(false, declaration.IsRelevantFor(CusEntryHeaderMessageTypeList.Codes.Export));
			AssertEquals(true, declaration.IsRelevantFor(CusEntryHeaderMessageTypeList.Codes.InBond));
			AssertEquals(true, declaration.IsRelevantFor(CusEntryHeaderMessageTypeList.Codes.ForeignTradeZone));

			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.US_EnableINB = false;
