		public void TestFlags()
		{
			JobDeclaration declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EnableENS = false;
			declaration.US_EnableCRL = true;
			declaration.US_EntryType = "";
			declaration.US_EnableAII = true;
			AssertEquals("IsCargoReleaseWithoutFormalEntry", true, declaration.IsCargoReleaseWithoutFormalEntry);
			AssertEquals("IsElectronicInvoice", true, declaration.IsElectronicInvoice);

			declaration.US_EnableENS = true;
			AssertEquals("IsCargoReleaseWithoutFormalEntry", false, declaration.IsCargoReleaseWithoutFormalEntry);
			AssertEquals("IsInBondOnly", false, declaration.IsInBondOnly);
			AssertEquals("IsElectronicInvoice", true, declaration.IsElectronicInvoice);

			declaration.US_EnableAII = false;
			AssertEquals("IsCargoReleaseWithoutFormalEntry", false, declaration.IsCargoReleaseWithoutFormalEntry);
			AssertEquals("IsInBondOnly", false, declaration.IsInBondOnly);
			AssertEquals("IsElectronicInvoice", false, declaration.IsElectronicInvoice);

			declaration.US_EnableCRL = false;
			declaration.US_EnableENS = false;
			declaration.US_EnableINB = true;
			AssertEquals("IsInBondOnly", true, declaration.IsInBondOnly);
			AssertEquals("IsElectronicInvoice", false, declaration.IsElectronicInvoice);

			AssertEquals("IsReWarehouse", false, declaration.IsReWarehouse);
			declaration.US_EntryType = EntryTypeList.Codes.ReWarehouse;
			AssertEquals("IsReWarehouse", true, declaration.IsReWarehouse);
		}

		public void TestDeclarationHasAnyPGADataEitherDeclaredOrDisclaimed()
		{
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACE;
			var header = declaration.Invoices.AddNew();
			var line = header.InvoiceLines.AddNew();
			AssertEquals("No Indicator on", false, header.HasAnyPGADataEitherDeclaredOrDisclaimed);

			line.US_VNEInd = OGAIndicatorList.Codes.Declared;
			var vneDetail = line.VehicleLines.AddNew();
			vneDetail.US_BodyDescription = "ABCE";
			AssertEquals("VNE Declared", true, declaration.PGAFlags.HasInvoiceLinesWithVNE);
			AssertEquals("Has PGA Data - VNE Declared", true, header.HasAnyPGADataEitherDeclaredOrDisclaimed);
			line.VehicleLines.RemoveAll();
			line.US_VNEInd = OGAIndicatorList.Codes.Disclaimed;
			AssertEquals("VNE Disclaimed", false, declaration.PGAFlags.HasInvoiceLinesWithVNE);
			AssertEquals("Has PGA Data - VNE Disclaimed", true, header.HasAnyPGADataEitherDeclaredOrDisclaimed);

			line.US_VNEInd = "";
			AssertEquals("VNE Has Not Declared", false, declaration.PGAFlags.HasInvoiceLinesWithVNE);
			AssertEquals("No PGA Data ", false, header.HasAnyPGADataEitherDeclaredOrDisclaimed);
			AssertNoMessageError("No PGA Data, IOR is not required.", declaration.IOROrgPKInfo, "You have not entered an IOR.");

			line.US_FDAIndicator = OGAIndicatorList.Codes.Disclaimed;
			AssertEquals("FDA PGA Disclaimed ", true, header.HasAnyPGADataEitherDeclaredOrDisclaimed);
			declaration.Validation.CheckIOROrgPK(declaration.IOROrgPKInfo);
			AssertHasMessageError("With Any PGA Data, should enter IOR", declaration.IOROrgPKInfo, "You have not entered an IOR.");

			line.US_FDAIndicator = ZString.Empty;
			AssertEquals("HFC PGA Disclaimed ", false, header.HasAnyPGADataEitherDeclaredOrDisclaimed);
			line.US_HFCInd = OGAIndicatorList.Codes.Disclaimed;
			AssertEquals("HFC PGA Disclaimed ", true, header.HasAnyPGADataEitherDeclaredOrDisclaimed);
			line.US_HFCInd = OGAIndicatorList.Codes.Declared;
			AssertEquals("HFC PGA Declared ", true, header.HasAnyPGADataEitherDeclaredOrDisclaimed);
		}

		public void TestDeriveImportDeclarationStatus_()
		{
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			declaration.US_EnableENS = true;
			declaration.MessageInitiator = new SendsMessagesToCustomsShutterUpperer();

			var entryHeader1 = declaration.CustomsEntryHeaders.AddNew();
			entryHeader1.CH_Status = ImportMessageStatusList.Codes.NotSent;
			AssertEquals("declaration's MessageStatus", ImportMessageStatusList.Codes.NotSent, declaration.JE_MessageStatus);

			entryHeader1.CH_Status = ImportMessageStatusList.Codes.ClearExportation;
			var entryHeader2 = declaration.CustomsEntryHeaders.AddNew();
			entryHeader2.CH_Status = ImportMessageStatusList.Codes.ErrorExportation;
			declaration.DeriveDeclarationStatus();
			AssertEquals("declaration's MessageStatus", new SummaryEntryStatusCalculator(declaration).SummaryMessageStatus, declaration.JE_MessageStatus);

			declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.FTZ;
			declaration.MessageInitiator = new SendsMessagesToCustomsShutterUpperer();

			declaration.AdmissionStatus = FTZMessageStatusList.Codes.AwaitingFTZAdmissionAdd;
			declaration.DeriveDeclarationStatus();
			AssertEquals("declaration's MessageStatus (JE_MessageStatus) is not relevant for FTZ", ZString.Empty, declaration.JE_MessageStatus);
		}

