			AssertEquals("New declaration should not copy the FIRMS Code", ZString.Empty, copiedDeclaration.US_US_NKLocationOfGoods);
			AssertEquals("New declaration should not copy Line Prices", ZDecimal.Zero, copiedDeclaration.InvoiceLines[0].JI_LinePrice);
			AssertEquals("New declaration should not copy Invoice Totals", ZDecimal.Zero, copiedDeclaration.Invoices[0].JZ_InvoiceAmount);
			AssertEquals("New declaration should not copy Invoice Charge Amounts", ZDecimal.Zero, copiedDeclaration.Invoices[0].Charges[0].J7_Amount);
			AssertEquals("New declaration should not copy Invoice Charge Amounts", ZDecimal.Zero, copiedDeclaration.Invoices[0].Charges[1].J7_Amount);
		}

