		public void TestTemplateCopyWhenCargoRelease()
		{
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.JE_TransportMode = TransportTypeList.Codes.Sea;
			declaration.US_EnableCRL = false;
			declaration.US_CertifyCargoRelease = true;
			AssertEquals("Pre-condition: ReleaseStatus should have been set", CRLReleaseStatusList.Codes.NRL, declaration.ReleaseStatus);
			Factory.Save();

			var copyDeclaration = (JobDeclaration)declaration.TemplateCopy();
			AssertEquals("ReleaseStatus should have been set on copied declaration also", CRLReleaseStatusList.Codes.NRL, copyDeclaration.ReleaseStatus);

			declaration.US_EnableCRL = false;
			declaration.US_CertifyCargoRelease = false;
			declaration.ReleaseStatus = ZString.Empty;
			Factory.Save();
			var secondCopyDeclaration = (JobDeclaration)declaration.TemplateCopy();
			AssertEquals("US_EnableCRL", false, secondCopyDeclaration.US_EnableCRL);
			AssertEquals("ReleaseStatus should not have been copied on this declaration", ZString.Empty, secondCopyDeclaration.ReleaseStatus);

			declaration.US_EnableCRL = true;
			declaration.US_CertifyCargoRelease = false;
			declaration.ReleaseStatus = CRLReleaseStatusList.Codes.NRL;
			Factory.Save();
			var thirdCopyDeclaration = (JobDeclaration)declaration.TemplateCopy();
			AssertEquals("US_EnableCRL", true, thirdCopyDeclaration.US_EnableCRL);
			AssertEquals("ReleaseStatus copies when certify for cargo release is ticked", ZString.Empty, thirdCopyDeclaration.ReleaseStatus);
		}

		void AssertResetDeclarationValuesOnTemplateCopyAfterClone(JobDeclaration declaration)
		{
			AssertEquals("JE_VesselName", ZString.Empty, declaration.JE_VesselName);
			AssertEquals("JE_VoyageFlightNo", ZString.Empty, declaration.JE_VoyageFlightNo);
			AssertEquals("US_TransportReference", ZString.Empty, declaration.US_TransportReference);
			AssertEquals("JE_OwnerRef", ZString.Empty, declaration.JE_OwnerRef);
			AssertEquals("JE_TotalWeight", ZDecimal.Zero, declaration.JE_TotalWeight);
			AssertEquals("Weight value should be cleared out byt JE_TotalWeightUnit should keep UOM", "NO", declaration.JE_TotalWeightUnit);
			AssertEquals("JE_TotalVolume", ZDecimal.Zero, declaration.JE_TotalVolume);
			AssertEquals("JE_TotalVolumeUnit", ZString.Empty, declaration.JE_TotalVolumeUnit);
			AssertEquals("JE_TotalNoOfPacks", ZInt.Zero, declaration.JE_TotalNoOfPacks);
			AssertEquals("FDAMsgStatus in this case should be empty as there are not declared FDA invoice lines", ZString.Empty, declaration.FDAMsgStatus);
			AssertEquals("US_DestinationState", "CT", declaration.US_DestinationState);
			AssertEquals("ReleaseStatus", ZString.Empty, declaration.ReleaseStatus);
			AssertEquals("US_PaperlessEntry", ZString.Empty, declaration.US_PaperlessEntry);
			AssertEquals("US_AESBGMRefLastUsed", ZString.Empty, declaration.US_AESBGMRefLastUsed);
			AssertEquals("CS00178376:US_Paid", ZString.Empty, declaration.US_Paid);
			AssertEquals("US_PSC", false, declaration.US_PSC);
			AssertEquals("FixPSD", false, declaration.US_FixPSD);
			AssertEquals("US_FixDefTaxDueDate", false, declaration.US_FixDefTaxDueDate);
			AssertEquals("US_DeferredTaxDueDate", ZDateTime.Empty, declaration.US_DeferredTaxDueDate);

			AssertEquals("US_AuditSpiLastLogDate", declaration.US_AuditSpiLastLogDate, ZDateTime.Empty);
