		public void TestTemplateCopyHandleWHSPacksCorrectly()
		{
			var org = Factory.New<OrgHeader>();
			org.OH_Code = "S@#$2d";
			org.CompanyData.OB_IMUsedBondedWhs = true;
			var classification = Factory.New<CusClassification>();
			classification.CC_LookupCode = "LK234";
			classification.CC_TariffNum = "2010304050";
			classification.CC_ClassificationType = CusClassification.ClassificationType.IMP;
			var part = Factory.New<OrgSupplierPart>();
			part.OP_PartNum = "PART321";
			var orgRel = part.RelatedOrganisations.AddOrganisationIfNotExist(org.PK, OrgPartRelation.RelationshipTypes.Owner);
			var pivot = part.PivotsForBinding.AddNew();
			pivot.CI_ChildType = ClassificationTypeList.Codes.HTI;
			pivot.CI_OH = orgRel.OU_OH;
			pivot.CI_CC = classification.PK;

			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_OH_Importer = org.PK;
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EnableENS = true;
			declaration.US_EntryType = EntryTypeList.Codes.Warehouse;

			var invoice = declaration.Invoices.AddNew();
			invoice.JZ_InvoiceNumber = "INV3234";

			var invoiceLine1 = declaration.InvoiceLines.AddNew();
			invoiceLine1.JI_PartNo = part.OP_PartNum;
			invoiceLine1.JI_Description = "D1";
			invoiceLine1.JI_InvoiceQuantity = 1m;

			var invoiceLine2 = declaration.InvoiceLines.AddNew();
			invoiceLine2.JI_PartNo = part.OP_PartNum;
			invoiceLine2.JI_Description = "D2";
			invoiceLine2.JI_InvoiceQuantity = 2m;

			var invoiceLine3 = declaration.InvoiceLines.AddNew();
			invoiceLine3.JI_PartNo = part.OP_PartNum;
			invoiceLine3.JI_Description = "D3";
			invoiceLine3.JI_InvoiceQuantity = 3m;
			invoiceLine3.JI_BondedWhsQuantity = 3m;

			AssertEquals(2, declaration.PackableInvoiceLines.Count);
			var whsPack1 = declaration.WHSPacks.AddNew();
			whsPack1.US_PackageQty = 1;
			var whsPack1Line = declaration.WHSPackLines.AddNew(invoiceLine1);

			var whsPack2 = declaration.WHSPacks.AddNew();
			whsPack2.US_PackageQty = 1;
			var whsPack2Line = declaration.WHSPackLines.AddNew(invoiceLine2);

			Factory.Save();
			var copyDeclaration = (JobDeclaration)declaration.TemplateCopy();
			AssertEquals("copyDeclaration.PackableInvoiceLines.Count", 0, copyDeclaration.PackableInvoiceLines.Count);
			AssertEquals("copyDeclaration.WHSPacks.Count", 0, copyDeclaration.WHSPacks.Count);
			AssertEquals("copyDeclaration.WHSPackLines.Count", 0, copyDeclaration.WHSPackLines.Count);
			AssertEquals("copyDeclaration.InvoiceLines.Count", 3, copyDeclaration.InvoiceLines.Count);
			AssertEquals("JI_BondedWhsQuantity", ZDecimal.Zero, copyDeclaration.InvoiceLines.OfType<JobComInvoiceLine>().First(x => x.JI_Description == "D3").JI_BondedWhsQuantity);
		}

		public void TestTemplateCopyACEDrawback()
		{
			var orgHeader = Factory.New<OrgHeader>();
			orgHeader.FillWithValidTestData();
			orgHeader.OH_RL_NKClosestPort = "USPHL";

			var bondDetailCollection = new CusBondDetailCollection(orgHeader);
			var continuousBond = bondDetailCollection.AddNew();
			continuousBond.PW_ActivityCode = ActivityCodeList.Codes._1a;
			continuousBond.PW_BondAmount = 75000m;
			continuousBond.PW_BondEffectiveDate = ZDateTime.Today.AddDays(-10);
			continuousBond.PW_BondNumber = "123456";
			continuousBond.PW_BondType = ImporterBondTypeList.Codes.ContinuousBond;
			continuousBond.PW_SuretyCode = "891";
			continuousBond.PW_BondFiledPort = "3901";
			continuousBond.PW_BondExpiryDate = ZDateTime.Today.AddDays(10);

			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Drawback;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACE;
			declaration.JE_OH_Importer = orgHeader.PK;
			declaration.US_AcceleratedClaimInd = false;
			Factory.Save();

			var copyDeclaration = (JobDeclaration)declaration.TemplateCopy();
			AssertEquals(JobMessageTypeList.Codes.Drawback, copyDeclaration.JE_MessageType);
			AssertEquals(JobApplicationCodeList.Codes.ACE, copyDeclaration.JE_ApplicationCode);
			AssertEquals(false, copyDeclaration.US_AcceleratedClaimInd);
			AssertEquals(ZString.Empty, copyDeclaration.US_BondType);

			declaration.US_AcceleratedClaimInd = true;
			AssertEquals(ImporterBondTypeList.Codes.ContinuousBond, declaration.US_BondType);
			declaration.US_BondType = ImporterBondTypeList.Codes.SingleTransactionBond;
			Factory.Save();

			copyDeclaration = (JobDeclaration)declaration.TemplateCopy();
			AssertEquals(ImporterBondTypeList.Codes.ContinuousBond, copyDeclaration.US_BondType);
		}

		public override void TestMasterBillLabel()
		{
			JobDeclaration declaration = Factory.New<JobDeclaration>();
			declaration.JE_TransportMode = TransportTypeList.Codes.Truck;
			var databoundBO = new DataBoundBusinessObject(declaration);
			var resourceStringData = DataBoundResourceStrings.GetDataForProperty(declaration.JE_MasterBillInfo, databoundBO);
			AssertEquals("Truck Master Bill Label", "Master Bill", resourceStringData.Caption);

			declaration.JE_TransportMode = declaration.TransportModeSeaCodeForTesting;
			resourceStringData = DataBoundResourceStrings.GetDataForProperty(declaration.JE_MasterBillInfo, databoundBO);
			AssertNotEquals("Sea Master Bill Label", "Master Bill", resourceStringData.Caption);

			declaration.JE_TransportMode = declaration.TransportModeMailCodeForTesting;
			resourceStringData = DataBoundResourceStrings.GetDataForProperty(declaration.JE_MasterBillInfo, databoundBO);
			AssertEquals("Mail Master Bill Label", "Mail Reference", resourceStringData.Caption);

			declaration.JE_MessageType = "IMP";
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACE;
			declaration.JE_TransportMode = TransportTypeList.Codes.FixedTransportInstallations;
			resourceStringData = DataBoundResourceStrings.GetDataForProperty(declaration.JE_MasterBillInfo, databoundBO);
			AssertEquals("ACE Master Bill Label", "Batch/Ticket No.", resourceStringData.Caption);

			declaration.JE_TransportMode = TransportTypeList.Codes.Air;
			declaration.Bills.AddNew();
			declaration.PrimaryMasterBill.US_ExpressTracking = true;
			resourceStringData = DataBoundResourceStrings.GetDataForProperty(declaration.JE_MasterBillInfo, databoundBO);
			AssertEquals("Express Carrier tracking Master Bill Label", "Express Carrier Tracking No.", resourceStringData.Caption);
		}

		public void TestJE_VoyageFlightNoCaption()
		{
			var dec = Factory.New<JobDeclaration>();
			dec.JE_ApplicationCode = JobApplicationCodeList.Codes.ACE;
			dec.JE_MessageType = JobMessageTypeList.Codes.Import;
			var info = dec.JE_VoyageFlightNoInfo;
			dec.JE_TransportMode = Core.Constants.TransportModes.Road;
			AssertEquals("JE_VoyageFlightNoInfo.Description - Road", "Trip ID", info.Description);
			this.AssertDataBoundResourceStringsWithMultipleResourceKey(info, multipleResourceKey: null, "Trip ID", dataBoundBusinessObject: new DataBoundBusinessObject(dec));
			dec.JE_TransportMode = Core.Constants.TransportModes.Rail;
			AssertEquals("JE_VoyageFlightNoInfo.Description - Rail", "Trip ID", info.Description);
			this.AssertDataBoundResourceStringsWithMultipleResourceKey(info, multipleResourceKey: null, "Trip ID", dataBoundBusinessObject: new DataBoundBusinessObject(dec));
			dec.JE_TransportMode = TransportTypeList.Codes.PassengerHandCarried;
			dec.JE_MasterBillIssuerSCAC = "ABC";
			AssertEquals("JE_VoyageFlightNoInfo.Description - PassengerHandCarried - NonAir", "Voyage", info.Description);
			this.AssertDataBoundResourceStringsWithMultipleResourceKey(info, multipleResourceKey: null, "Voyage", dataBoundBusinessObject: new DataBoundBusinessObject(dec));
			dec.JE_MasterBillIssuerSCAC = "AB";
			AssertEquals("JE_VoyageFlightNoInfo.Description - PassengerHandCarried - Air", "Flight/Folio", info.Description);
			this.AssertDataBoundResourceStringsWithMultipleResourceKey(info, multipleResourceKey: null, "Flight/Folio", dataBoundBusinessObject: new DataBoundBusinessObject(dec));
			dec.JE_TransportMode = Core.Constants.TransportModes.Sea;
			AssertEquals("JE_VoyageFlightNoInfo.Description - Sea", "Voyage", info.Description);
			this.AssertDataBoundResourceStringsWithMultipleResourceKey(info, multipleResourceKey: null, "Voyage", dataBoundBusinessObject: new DataBoundBusinessObject(dec));
			dec.JE_TransportMode = Core.Constants.TransportModes.Air;
			AssertEquals("JE_VoyageFlightNoInfo.Description - Air", "Flight/Folio", info.Description);
			this.AssertDataBoundResourceStringsWithMultipleResourceKey(info, multipleResourceKey: null, "Flight/Folio", mediumCaption: "Flight No.", dataBoundBusinessObject: new DataBoundBusinessObject(dec));
			dec.JE_TransportMode = TransportTypeList.Codes.FixedTransportInstallations;
			AssertEquals("JE_VoyageFlightNoInfo.Description - FixedTransportInstallations - ACE", "Trip ID", info.Description);
			this.AssertDataBoundResourceStringsWithMultipleResourceKey(info, multipleResourceKey: null, "Trip ID", dataBoundBusinessObject: new DataBoundBusinessObject(dec));
			dec.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			AssertEquals("JE_VoyageFlightNoInfo.Description - FixedTransportInstallations - ACS", "Voyage / Flight No", info.Description);
			this.AssertDataBoundResourceStringsWithMultipleResourceKey(info, multipleResourceKey: null, "Voyage / Flight No", shortCaption: "Voyage/Flight", fullDescription: "A unique reference assigned by a carrier to identify a specific journey of an aircraft or vessel.", dataBoundBusinessObject: new DataBoundBusinessObject(dec));
		}

