		public void TestUS_7512OpenAreaBillValuesAreClearedIfSame()
		{
			JobDeclaration declaration = Factory.New<JobDeclaration>();
			declaration.US_7512OpenArea = "Document value entered here";

			Bill bill1 = declaration.Bills.AddNew();
			bill1.CU_BillType = BillTypeList.Codes.MasterBill;
			AssertEquals("Document value entered here", bill1.US_7512OpenArea);

			Factory.Save();

			ZQuery query = new ZQuery(CusAddInfoSchema.B7_Type, CusAddInfoTypeAttribute.Codes.USITDoc);
			query.AddToFilter(CusAddInfoSchema.B7_ParentTableCode, CusDecHouseBillSchema.Constants.Prefix);
			query.AddToFilter(CusAddInfoSchema.B7_ParentID, bill1.PK);
			ITDoc result = Factory.LoadTop1<ITDoc>(query);
			AssertNull(result);

			bill1.US_7512OpenArea = "different value entered on M/B";

			Factory.Save();

			AssertEquals("different value entered on M/B", bill1.US_7512OpenArea);
			result = Factory.LoadTop1<ITDoc>(query);
			AssertNotNull(result);

			declaration.US_7512OpenArea = "different value entered on M/B";

			Factory.Save();

			result = Factory.LoadTop1<ITDoc>(query);
			AssertNull(result);
		}

