		public void TestJE_MasterBillForAir()
		{
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.JE_TransportMode = TransportTypeList.Codes.Air;

			var usCarrier = Factory.LoadTop1<USCarrierCombined>(new ZQuery(USCarrierCombinedSchema.UI_Code, "A8"));
			if (usCarrier == null)
			{
				usCarrier = Factory.New<USCarrierCombined>();
				usCarrier.UI_Code = "A8";
				usCarrier.UI_ModeOfTransportation = "40";
				usCarrier.UI_Name = "Test Carrier";
				usCarrier.UI_AirwayBillPrefix = "AMF";
			}

			declaration.JE_MasterBillIssuerSCAC = usCarrier.UI_Code;
			Assert(@"Declaration Master Bill should allow chars in Master Bill prefix for AIR jobs.
MB Prefix should be defaulted from Carrier MB Prefix if master bill number is empty",
					declaration.JE_MasterBill.Equals("AMF"));

			declaration.JE_MasterBillIssuerSCAC = ZString.Empty;
			declaration.JE_MasterBill = "F001456454";
			declaration.JE_MasterBillIssuerSCAC = usCarrier.UI_Code;
			AssertEquals(@"Declaration Master Bill should not be defaulted from Carrier AirwayBillPrefix, if Master Bill has value",
						"F001456454", declaration.JE_MasterBill);

			declaration.JE_MasterBill = ZString.Empty;

			usCarrier = Factory.LoadTop1<USCarrierCombined>(new ZQuery(USCarrierCombinedSchema.UI_Code, "D3"));
			if (usCarrier == null)
			{
				usCarrier = Factory.New<USCarrierCombined>();
				usCarrier.UI_Code = "D3";
				usCarrier.UI_ModeOfTransportation = "40";
				usCarrier.UI_Name = "Test Carrier";
			}
			usCarrier.UI_AirwayBillPrefix = "VAL";

			declaration.JE_MasterBillIssuerSCAC = usCarrier.UI_Code;
			AssertEquals("SCAC changed, MB contains only bill prefix - can be replaced with new AirwayBillPrefix", "VAL", declaration.JE_MasterBill);

			declaration.JE_MasterBillIssuerSCAC = "Z~";
			AssertEquals("No Carrier found, MB contains only bill prefix - should be replaced with empty value", ZString.Empty, declaration.JE_MasterBill);

