		public void TestShippingLineForAir()
		{
			var airline = Factory.LoadTop1<RefAirline>(new ZQuery(RefAirlineSchema.RM_EagleAddedAirlinePrefixOrAccountingCode, "020"));
			if (airline == null)
			{
				airline = Factory.New<RefAirline>();
				airline.RM_EagleAddedAirlinePrefixOrAccountingCode = "020";
			}
			airline.RM_AirlineName1 = "TEST020 AIRLINE";
			airline.RM_TwoCharacterCode = "LH";
			airline.RM_ThreeLetterCode = "LHH";

			var organisation = Factory.NewWithValidTestData<OrgHeader>();
			organisation.OH_FullName = "IMPORTERFULLNAME";

			var carrier = Factory.NewWithValidTestData<OrgHeader>();
			carrier.CustomsCodes.AddNew(OrgCusCode.CodeTypes.CarrierCode, "CAR1", Core.Constants.CountryCodes.UnitedStates);
			carrier.CustomsCodes.AddNew(OrgCusCode.CodeTypes.TruckCarrierCode, "TRU1", Core.Constants.CountryCodes.UnitedStates);

			var airlineKJ = Factory.NewWithValidTestData<RefAirline>();
			airlineKJ.RM_EagleAddedAirlinePrefixOrAccountingCode = "050";
			airlineKJ.RM_AirlineName1 = "TEST050 KJ AIRLINE";
			airlineKJ.RM_TwoCharacterCode = "KJ";
			airlineKJ.RM_ThreeLetterCode = "KJJ";

			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_OH_Importer = organisation.PK;
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_TransportMode = TransportTypeList.Codes.Air;
