			carrier.CustomsCodes.AddNew(OrgCusCode.CodeTypes.CarrierCode, "BBBB", Core.Constants.CountryCodes.UnitedStates);
			carrier.CustomsCodes.AddNew(OrgCusCode.CodeTypes.TruckCarrierCode, "BBCC", Core.Constants.CountryCodes.UnitedStates);
