		public void TestJE_MessageTypeChanged()
		{
			GlbDepartment.CurrentDepartment.GE_Import = true;
			JobDeclaration declaration = Factory.New<JobDeclaration>();
			AssertNotEquals("US_TransactionsRelated", YesNoDefaultList.Codes.No, declaration.US_TransactionsRelated);
			AssertNotEquals("US_HazardousCargo", YesNoDefaultList.Codes.No, declaration.US_HazardousCargo);
			AssertNotEquals("US_RoutedTransaction", YesNoDefaultList.Codes.No, declaration.US_RoutedTransaction);

			declaration.US_DestinationState = "CA";
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			declaration.US_EnableENS = true;
			declaration.US_ConsolACE = true;
			AssertNotEquals("US_TransactionsRelated", YesNoDefaultList.Codes.No, declaration.US_TransactionsRelated);
			AssertNotEquals("US_HazardousCargo", YesNoDefaultList.Codes.No, declaration.US_HazardousCargo);
			AssertNotEquals("US_RoutedTransaction", YesNoDefaultList.Codes.No, declaration.US_RoutedTransaction);
			AssertEquals("US_DestinationState", "CA", declaration.US_DestinationState);
			AssertEquals("US_ConsolACE", ZBool.True, declaration.US_ConsolACE);

			declaration.JE_MessageType = JobMessageTypeList.Codes.Export;
			AssertEquals("US_TransactionsRelated", ZString.Empty, declaration.US_TransactionsRelated);
			AssertEquals("US_HazardousCargo", YesNoDefaultList.Codes.No, declaration.US_HazardousCargo);
			AssertEquals("US_RoutedTransaction", YesNoDefaultList.Codes.No, declaration.US_RoutedTransaction);
			AssertEquals("US_DestinationState should be cleared out", ZString.Empty, declaration.US_DestinationState);
			AssertEquals("US_ConsolACE", ZBool.False, declaration.US_ConsolACE);
		}

