		void AssertJE_OH_SupplierChanged(OrgHeader supplier, ZString resultState, bool expectPositiveAssertion)
		{
			JobDeclaration declaration = Factory.New<JobDeclaration>();
			declaration.DisableMessageTypeChangeOnSupplierChangeForTesting = true;
			declaration.JE_MessageType = JobMessageTypeList.Codes.Export;
			AssertEquals("US_StateOfOrigin", "", declaration.US_StateOfOrigin);

			declaration.JE_OH_Supplier = supplier.PK;
			if (expectPositiveAssertion)
			{
				AssertEquals("US_StateOfOrigin for export", resultState, declaration.US_StateOfOrigin);
			}
			else
			{
				AssertNotEquals("US_StateOfOrigin for export", resultState, declaration.US_StateOfOrigin);
			}

			declaration = Factory.New<JobDeclaration>();
			declaration.DisableMessageTypeChangeOnSupplierChangeForTesting = true;
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			declaration.US_EnableENS = true;
			AssertEquals("US_StateOfOrigin", "", declaration.US_StateOfOrigin);
			declaration.JE_OH_Supplier = supplier.PK;
			AssertEquals("US_StateOfOrigin for import", "", declaration.US_StateOfOrigin);
			declaration.JE_MessageType = JobMessageTypeList.Codes.Export;
			if (expectPositiveAssertion)
			{
				AssertEquals("US_StateOfOrigin for export", resultState, declaration.US_StateOfOrigin);
			}
			else
			{
				AssertNotEquals("US_StateOfOrigin for export", resultState, declaration.US_StateOfOrigin);
			}
			declaration.US_StateOfOrigin = "CA";
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			AssertEquals("", declaration.US_StateOfOrigin);
		}

