		public void TestIsGovernmentImporter()
		{
			OrgHeader importer = Factory.New<OrgHeader>();
			importer.FillWithValidTestData();

			OrgHeader importer2 = Factory.New<OrgHeader>();
			importer2.FillWithValidTestData();

			JobDeclaration declaration = Factory.New<JobDeclaration>();
			declaration.JE_OH_Importer = importer.PK;
			AssertEquals(false, declaration.IsGovernmentImporter);

			declaration.JE_OH_Importer = importer2.PK;
			((OrgImpAddInfo)declaration.Importer.CountryData.ImpAddInfo).ZO_ImporterType = ImporterTypeList.Codes.Corporation;
			AssertEquals(false, declaration.IsGovernmentImporter);

			declaration = Factory.New<JobDeclaration>();
			declaration.JE_OH_Importer = importer.PK;
			((OrgImpAddInfo)declaration.Importer.CountryData.ImpAddInfo).ZO_ImporterType = ImporterTypeList.Codes.StateGovernment;
			AssertEquals(true, declaration.IsGovernmentImporter);

			declaration = Factory.New<JobDeclaration>();
			declaration.JE_OH_Importer = importer.PK;
			((OrgImpAddInfo)declaration.Importer.CountryData.ImpAddInfo).ZO_ImporterType = ImporterTypeList.Codes.Corporation;
			AssertEquals(false, declaration.IsGovernmentImporter);

			declaration = Factory.New<JobDeclaration>();
			declaration.JE_OH_Importer = importer.PK;
			((OrgImpAddInfo)declaration.Importer.CountryData.ImpAddInfo).ZO_ImporterType = ImporterTypeList.Codes.ForeignGovernment;
			AssertEquals(true, declaration.IsGovernmentImporter);
		}

		public void TestIsSoldEnRoute()
		{
			JobDeclaration declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			AssertEquals(false, declaration.IsSoldEnRoute);

			declaration.JE_MessageType = JobMessageTypeList.Codes.Export;
			AssertEquals(false, declaration.IsSoldEnRoute);

			declaration.US_SoldEnRouteIndicator = YesNoDefaultList.Codes.Yes;
