		public void TestHaveAllFDAPNCsBeenReceived()
		{
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			declaration.US_EnableENS = true;
			AssertEquals("default behaviour of this property", true, declaration.HaveAllFDAPNCsBeenReceived);
			Factory.Save();
			var invoiceHeader1 = declaration.Invoices.AddNew();
			var invoice1Line1 = invoiceHeader1.JobComInvoiceLines.AddNew();
			invoice1Line1.JI_Tariff = USCTariff.FDAPriorNoticeRequiredTariff;
			var fdaLine1 = invoice1Line1.FDAs.AddNew();
			AssertEquals(false, declaration.HaveAllFDAPNCsBeenReceived);

			var invoice1Line2 = invoiceHeader1.JobComInvoiceLines.AddNew();
			invoice1Line2.JI_Tariff = USCTariff.FDAPriorNoticeRequiredTariff;
			AssertEquals(false, declaration.HaveAllFDAPNCsBeenReceived);

			var invoiceHeader2 = declaration.Invoices.AddNew();
			var invoice2Line1 = invoiceHeader2.JobComInvoiceLines.AddNew();
			invoice2Line1.JI_Tariff = USCTariff.FDAPriorNoticeRequiredTariff;
			var fdaLine2 = invoice2Line1.FDAs.AddNew();
			AssertEquals(false, declaration.HaveAllFDAPNCsBeenReceived);

			invoice1Line1.US_FDAIndicator = OGAIndicatorList.Codes.Disclaimed;
			invoice1Line2.US_FDAIndicator = OGAIndicatorList.Codes.Disclaimed;
			invoice2Line1.US_FDAIndicator = OGAIndicatorList.Codes.Disclaimed;
			AssertEquals("All FDA lines have been disclaimed - no PNCs expected", true, declaration.HaveAllFDAPNCsBeenReceived);

			invoice1Line1.US_FDAIndicator = OGAIndicatorList.Codes.Declared;
			invoice2Line1.US_FDAIndicator = OGAIndicatorList.Codes.Declared;
			AssertEquals(false, declaration.HaveAllFDAPNCsBeenReceived);

			fdaLine1.US_PNC = "1839485073";
			AssertEquals("Still one FDA line with PNC number", false, declaration.HaveAllFDAPNCsBeenReceived);

			fdaLine2.US_PNC = "2199486145";
			AssertEquals("All declared FDA lines have a PNC number", true, declaration.HaveAllFDAPNCsBeenReceived);

			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACE;
			declaration.US_CargoReleaseType = CargoReleaseTypeList.Codes.ACE;
			invoice1Line1.FDAs.RemoveAndDeleteAll();
			invoice2Line1.FDAs.RemoveAndDeleteAll();

			var tariff = Factory.New<USCTariff>();
			tariff.UE_Tariff = "00000000";
			tariff.UE_DateFrom = ZDateTime.Today.AddYears(-1);
			tariff.UE_DateTo = ZDateTime.Today.AddMonths(1);
			tariff.UE_PGACodes = "FD4";
			invoice1Line1.JI_Tariff = tariff.UE_Tariff;
			invoice2Line1.JI_Tariff = tariff.UE_Tariff;

			var aceFDA = invoice2Line1.ACE_FDALines.AddNew();
			invoice2Line1.US_FDAIndicator = OGAIndicatorList.Codes.Declared;
			AssertEquals(false, declaration.HaveAllFDAPNCsBeenReceived);
			aceFDA.US_PNC = "2199486145";
			AssertEquals(true, declaration.HaveAllFDAPNCsBeenReceived);

			var aceFDA2 = invoice1Line1.ACE_FDALines.AddNew();
			invoice1Line1.US_FDAIndicator = OGAIndicatorList.Codes.Declared;
			AssertEquals(false, declaration.HaveAllFDAPNCsBeenReceived);
			aceFDA2.US_PNC = "0012001214";
			AssertEquals(true, declaration.HaveAllFDAPNCsBeenReceived);
		}

		public void TestTransportMode()
		{
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_TransportMode = TransportTypeList.Codes.Sea;
			AssertEquals("IsSea", true, declaration.IsSea);

			declaration.JE_TransportMode = TransportTypeList.Codes.BorderWaterBorne;
			AssertEquals("IsSea", false, declaration.IsSea);
			AssertEquals("IsHMFApplicable", "Y", declaration.US_IsHMFApplicable);

			declaration.JE_TransportMode = TransportTypeList.Codes.Air;
			AssertEquals("IsAir", true, declaration.IsAir);

			declaration.JE_TransportMode = TransportTypeList.Codes.Rail;
			AssertEquals("IsRail", true, declaration.IsRail);

			declaration.JE_TransportMode = TransportTypeList.Codes.Mail;
			AssertEquals("IsPost", true, declaration.IsPost);

			declaration.JE_TransportMode = TransportTypeList.Codes.Auto;
			AssertEquals("IsRoad", true, declaration.IsRoad);

			declaration.JE_TransportMode = TransportTypeList.Codes.Road;
			AssertEquals("IsRoad", true, declaration.IsRoad);

			declaration.JE_TransportMode = TransportTypeList.Codes.Truck;
			AssertEquals("IsRoad", true, declaration.IsRoad);

			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACE;
			declaration.JE_TransportMode = TransportTypeList.Codes.Air;
			declaration.US_EnableCRL = true;
			var bill = declaration.Bills.AddNew();
			var itNo = bill.ITAndSplitDetails.AddNew();
			itNo.US_ITNumber = "123456";

			var itNo2 = bill.ITAndSplitDetails.AddNew();
			itNo2.US_ITNumber = "98456";
			AssertEquals(2, bill.ITAndSplitDetails.Count);

			declaration.JE_TransportMode = TransportTypeList.Codes.Sea;
			AssertEquals("System will merely remove split details as those columns are hidden. Will leave to users what they want to do with multiple IT details", 2, bill.ITAndSplitDetails.Count);
		}

