		public void TestPortOfExportAndDateOfExportAreDefaulted()
		{
			JobDeclaration declaration = Factory.New<JobDeclaration>();
			AssertEquals("US_RL_NKPortOfExport", "", declaration.US_RL_NKPortOfExport);
			AssertEquals("US_DateOfExport", ZDateTime.Empty, declaration.US_DateOfExport);

			declaration.JE_ExportDate = new ZDateTime(2006, 3, 2);
			AssertEquals("US_RL_NKPortOfExport", "", declaration.US_RL_NKPortOfExport);
			AssertEquals("US_DateOfExport", new ZDateTime(2006, 3, 2), declaration.US_DateOfExport);

			declaration.JE_ExportDate = new ZDateTime(2006, 3, 4);
			AssertEquals("US_RL_NKPortOfExport", "", declaration.US_RL_NKPortOfExport);
			AssertEquals("US_DateOfExport", new ZDateTime(2006, 3, 4), declaration.US_DateOfExport);

			declaration.US_DateOfExport = ZDateTime.Empty;
			declaration.JE_RL_NKPortOfLoading = "AUSYD";
			AssertEquals("US_RL_NKPortOfExport", "AUSYD", declaration.US_RL_NKPortOfExport);
			AssertEquals("US_DateOfExport", new ZDateTime(2006, 3, 4), declaration.US_DateOfExport);

			declaration.JE_RL_NKPortOfLoading = "";
			declaration.US_RL_NKPortOfExport = "";
			declaration.US_DateOfExport = ZDateTime.Empty;
			declaration.JE_RL_NKPortOfLoading = "AUSYD";
			AssertEquals("US_RL_NKPortOfExport", "AUSYD", declaration.US_RL_NKPortOfExport);
			AssertEquals("US_DateOfExport", new ZDateTime(2006, 3, 4), declaration.US_DateOfExport);

			declaration.JE_ExportDate = new ZDateTime(2006, 3, 5);
			AssertEquals("US_RL_NKPortOfExport", "AUSYD", declaration.US_RL_NKPortOfExport);
			AssertEquals("US_DateOfExport", new ZDateTime(2006, 3, 5), declaration.US_DateOfExport);

			((IBusinessObjectInternals)declaration).IsCopying = true;
			declaration.US_RL_NKPortOfExport = "";
			declaration.US_DateOfExport = ZDateTime.Empty;
			declaration.JE_ExportDate = new ZDateTime(2006, 3, 3);
			AssertEquals("US_RL_NKPortOfExport", "", declaration.US_RL_NKPortOfExport);
			AssertEquals("US_DateOfExport", new ZDateTime(2006, 3, 3), declaration.US_DateOfExport);

			declaration.JE_RL_NKPortOfLoading = "AUMEL";
			AssertEquals("US_RL_NKPortOfExport", "", declaration.US_RL_NKPortOfExport);
			AssertEquals("US_DateOfExport", new ZDateTime(2006, 3, 3), declaration.US_DateOfExport);
		}

