			OrgHeader org2 = Factory.NewWithValidTestData<OrgHeader>();
			org2.OH_FullName = "ORGANISATION 2";
			org2.MainAddress.OA_RN_NKCountryCode = ZString.Empty;
			OrgContact org2Contact = org2.Contacts.AddNew();
			org2Contact.OC_ContactName = "CONTACT 2";
			org2Contact.OC_Phone = "+61 (2) 9025 1100";
			OrgDocument org2Document = org2Contact.Documents.AddNew();
			org2Document.OD_DocumentGroup = ContactType.All.ToString();
			org2Document.OD_DefaultContact = true;

			OrgHeader org3 = Factory.NewWithValidTestData<OrgHeader>();
			org3.OH_FullName = "ORGANISATION 3";
			org3.MainAddress.OA_RN_NKCountryCode = ZString.Empty;
			OrgContact org3Contact = org3.Contacts.AddNew();
			org3Contact.OC_ContactName = "CONTACT 3";
			org3Contact.OC_Phone = "+61 (3) 9025 1100";
			OrgDocument org3Document = org3Contact.Documents.AddNew();
			org3Document.OD_DocumentGroup = ContactType.All.ToString();
			org3Document.OD_DefaultContact = true;

			JobDeclaration declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			declaration.US_EnableENS = true;
			declaration.JE_DeclarationReference = "B410005546";
			declaration.JE_OH_Supplier = org1.PK;
			declaration.JE_OH_Importer = org2.PK;
			declaration.JE_OH_Consignee = org3.PK;

			JobComInvoiceHeader newInvoice = declaration.Invoices.AddNew();

			AssertNotEquals("JZ_InvoiceNumber", "B410005546", newInvoice.JZ_InvoiceNumber);

			AssertEquals("US_USPPI.ZO_OH_Organisation", declaration.JE_OH_Supplier, newInvoice.US_USPPI.ZO_OH_Organisation);

			AssertEquals("US_ExportUltimateConsignee.ZO_OH_Organisation", declaration.JE_OH_Importer, newInvoice.US_ExportUltimateConsignee.ZO_OH_Organisation);

			AssertEquals("US_IntermediateConsignee.ZO_OH_Organisation", ZGuid.Empty, newInvoice.US_IntermediateConsignee.ZO_OH_Organisation);

			declaration.JE_MessageType = JobMessageTypeList.Codes.Export;
			org1.OH_RL_NKClosestPort = "US2CW";
			org2.OH_RL_NKClosestPort = "CA2CW";
			org3.OH_RL_NKClosestPort = "CA2CW";
			newInvoice.Delete();
			newInvoice = declaration.Invoices.AddNew();

			AssertEquals("JZ_InvoiceNumber", "B410005546", newInvoice.JZ_InvoiceNumber);
			AssertEquals("US_USPPI.ZO_OH_Organisation", org1.PK, newInvoice.US_USPPI.ZO_OH_Organisation);
			AssertEquals("US_USPPI.ZO_OA_Address", org1.MainAddress.PK, newInvoice.US_USPPI.ZO_OA_Address);
			AssertEquals("US_USPPI.ZO_Contact", "CONTACT 1", newInvoice.US_USPPI.ZO_Contact);
			AssertEquals("US_USPPI.ZO_Phone", "190251100", newInvoice.US_USPPI.ZO_Phone);

			AssertEquals("US_ExportUltimateConsignee.ZO_OH_Organisation", org2.PK, newInvoice.US_ExportUltimateConsignee.ZO_OH_Organisation);
			AssertEquals("US_ExportUltimateConsignee.ZO_OA_Address", org2.MainAddress.PK, newInvoice.US_ExportUltimateConsignee.ZO_OA_Address);
			AssertEquals("US_ExportUltimateConsignee.ZO_Contact", "CONTACT 2", newInvoice.US_ExportUltimateConsignee.ZO_Contact);
			AssertEquals("US_ExportUltimateConsignee.ZO_Phone", "61290251100", newInvoice.US_ExportUltimateConsignee.ZO_Phone);

			AssertEquals("US_IntermediateConsignee.ZO_OH_Organisation", org3.PK, newInvoice.US_IntermediateConsignee.ZO_OH_Organisation);
			AssertEquals("US_IntermediateConsignee.ZO_OA_Address", org3.MainAddress.PK, newInvoice.US_IntermediateConsignee.ZO_OA_Address);
			AssertEquals("US_IntermediateConsignee.ZO_Contact", "CONTACT 3", newInvoice.US_IntermediateConsignee.ZO_Contact);
			AssertEquals("US_IntermediateConsignee.ZO_Phone", "61390251100", newInvoice.US_IntermediateConsignee.ZO_Phone);
		}

		public void TestDeclarationNumber()
		{
			JobDeclaration declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Export;
			AssertEquals("", declaration.DeclarationNumber);
			CusEntryHeader entry1 = declaration.CustomsEntryHeaders.AddNew();
			entry1.CH_MessageType = CusEntryHeaderMessageTypeList.Codes.Export;
			entry1.EntryNumber = "TID2342";
			AssertEquals("TID2342", declaration.DeclarationNumber);
			CusEntryHeader entry2 = declaration.CustomsEntryHeaders.AddNew();
			entry2.CH_MessageType = CusEntryHeaderMessageTypeList.Codes.Export;
			AssertEquals("TID2342", AESDirectCustomsEntryStatus.Descriptions.MultipleEntriesStatus, declaration.DeclarationNumber);
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.ActiveEntryHeaders.DeactivateAll();
			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			declaration.CustomsEntryHeaders.AddNew().EntryNumber = "TID2342";
			AssertEquals("Single entry", "TID2342", declaration.DeclarationNumber);

			declaration.CustomsEntryHeaders.AddNew().EntryNumber = "CRL12345";
			AssertEquals("Two entries", "TID2342, CRL12345", declaration.DeclarationNumber);

			declaration.CustomsEntryHeaders.AddNew().EntryNumber = "INB039048";
			declaration.CustomsEntryHeaders.AddNew().EntryNumber = "CRL00003";
			AssertEquals("Multiple import entries", "TID2342, CRL12345, INB039048, CRL00003", declaration.DeclarationNumber);

			declaration.ImportEntryNumber = "TEST";
			AssertEquals("Pre-Allocated Entry Number", "TEST", declaration.DeclarationNumber);
		}

		public void TestDecEntryNumber()
		{
			DeclarationTestHelper.SetupBranchSpecificInBondNumberRanges();

			JobDeclaration declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EnableENS = true;
			declaration.US_EntryFilerCode = "XJ5";

			declaration.Invoices.AddNew();
			declaration.InvoiceLines.AddNew();

			declaration.DoMerge(new SendsMessagesToCustomsShutterUpperer());
			declaration.CustomsEntryHeaders[0].EntryNumber = "TID2342";
			AssertEquals("Single entry", "TID2342", declaration.DeclarationNumber);
			declaration.US_EnableCRL = true;
			declaration.DoMerge(new SendsMessagesToCustomsShutterUpperer());

			declaration.US_EnableINB = true;
			declaration.DoMerge(new SendsMessagesToCustomsShutterUpperer());
			CusEntryHeader[] inbondEntry = declaration.ActiveEntryHeaders.GetEntryWithType(ImportMessageStatusList.MessageType.InBondDeparture);

			inbondEntry[0].EntryNumber = "INB039048";
			AssertEquals("Multiple import entries - SHOULD NOT include IT Entry Number (ie only ENS type)", "TID2342", declaration.DeclarationNumber);

			declaration.ImportEntryNumber = "TEST";
			AssertEquals("Pre-Allocated Dec Entry Number", "TEST", declaration.DecEntryNumber);

			JobDeclaration nonENSEntryDeclaration = Factory.New<JobDeclaration>();
			nonENSEntryDeclaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			nonENSEntryDeclaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			nonENSEntryDeclaration.US_EnableENS = false;
			nonENSEntryDeclaration.US_EnableINB = true;

			nonENSEntryDeclaration.Invoices.AddNew();
			nonENSEntryDeclaration.InvoiceLines.AddNew();

			nonENSEntryDeclaration.DoMerge(new SendsMessagesToCustomsShutterUpperer());
			nonENSEntryDeclaration.CustomsEntryHeaders[0].EntryNumber = "453095856";
			AssertEquals("Non ENS Dec Entry Number should be blank", "", nonENSEntryDeclaration.DecEntryNumber);
		}

		public void TestDeriveExportDeclarationStatus()
		{
			JobDeclaration declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Export;
			declaration.DeriveDeclarationStatus();
			AssertEquals("JE_EntryStatus", "", declaration.JE_EntryStatus);
			AssertEquals("JE_MessageStatus", "", declaration.JE_MessageStatus);

			CusEntryHeader entry1 = declaration.CustomsEntryHeaders.AddNew();
			entry1.CH_EntryStatus = AESDirectCustomsEntryStatus.Codes.OriginalSEDClear;
			entry1.CH_Status = AESDirectCustomsEntryStatus.Codes.ReplacementSEDRequired;
			declaration.DeriveDeclarationStatus();
			AssertEquals("JE_EntryStatus", AESDirectCustomsEntryStatus.Codes.OriginalSEDClear, declaration.JE_EntryStatus);
			AssertEquals("JE_MessageStatus", AESDirectCustomsEntryStatus.Codes.ReplacementSEDRequired, declaration.JE_MessageStatus);

			CusEntryHeader entry2 = declaration.CustomsEntryHeaders.AddNew();
			entry2.CH_EntryStatus = AESDirectCustomsEntryStatus.Codes.AwaitingOriginalResponse;
			declaration.DeriveDeclarationStatus();
			AssertEquals("JE_EntryStatus should show multiple at this point", AESDirectCustomsEntryStatus.Codes.MultipleEntriesStatus, declaration.JE_EntryStatus);
			AssertEquals("JE_MessageStatus should show multiple at this point", AESDirectCustomsEntryStatus.Codes.MultipleEntriesStatus, declaration.JE_MessageStatus);

			entry1.CH_Status = AESDirectCustomsEntryStatus.Codes.OriginalSEDClear;
			entry2.CH_EntryStatus = AESDirectCustomsEntryStatus.Codes.OriginalSEDClear;
			entry2.CH_Status = AESDirectCustomsEntryStatus.Codes.OriginalSEDClear;
			declaration.DeriveDeclarationStatus();
			AssertEquals("JE_EntryStatus should show appropriate status now (OSC), as all entries have the same status", AESDirectCustomsEntryStatus.Codes.OriginalSEDClear, declaration.JE_EntryStatus);
			AssertEquals("JE_MessageStatus should show appropriate status now (OSC), as all entries have the same status", AESDirectCustomsEntryStatus.Codes.OriginalSEDClear, declaration.JE_MessageStatus);
		}

		public void TestRequiresBGMReferenceGeneration()
		{
			JobDeclaration declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			AssertEquals(false, declaration.RequiresBGMReferenceGeneration);

			declaration.JE_MessageType = JobMessageTypeList.Codes.Export;
			AssertEquals(false, declaration.RequiresBGMReferenceGeneration);

			CusEntryHeader entry1 = declaration.CustomsEntryHeaders.AddNew();
			AssertEquals(true, declaration.RequiresBGMReferenceGeneration);

			entry1.CH_BGMReference = "G0010072121232900";
			AssertEquals(false, declaration.RequiresBGMReferenceGeneration);

			CusEntryHeader entry2 = declaration.CustomsEntryHeaders.AddNew();
			entry2.CH_BGMReference = "G0010072121232901";
			AssertEquals(false, declaration.RequiresBGMReferenceGeneration);

			entry2.CH_EntryStatus = AESDirectCustomsEntryStatus.Codes.DeleteSEDClear;
			entry2.CH_Status = AESDirectCustomsEntryStatus.Codes.DeleteSEDClear;
			AssertEquals(true, declaration.RequiresBGMReferenceGeneration);
		}

