		public void TestCarrierCodeForExport()
		{
			DeclarationTestHelper helper = new DeclarationTestHelper(Factory);
			var airline = Factory.NewWithValidTestData<RefAirline>();
			airline.RM_EagleAddedAirlinePrefixOrAccountingCode = "081";
			airline.RM_AirlineName1 = "TESTING AIRLINE";
			airline.RM_TwoCharacterCode = "TA";
			airline.RM_ThreeLetterCode = "";
			helper.ShippingLine.MiscServ.OM_RM_Airline = airline.PK;

			JobDeclaration declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Export;
			declaration.JE_TransportMode = TransportTypeList.Codes.Air;
			declaration.JE_ContainerMode = Core.Constants.ContainerModes.AIR;
			AssertEquals("CarrierCode", "", declaration.CarrierCode);

			string messageError = (NoResString)string.Format("You have not entered a Carrier.");

			declaration.JE_OH_ShippingLine = helper.ShippingLine.PK;
			AssertEquals("CarrierCode", declaration.ShippingLineSCACCode, declaration.CarrierCode);
			AssertNoMessageError(declaration.US_UI_NKCarrierSCACInfo, messageError);

			declaration.JE_TransportMode = declaration.TransportModeAirCodeForTesting;
			declaration.US_UI_NKCarrierSCAC = ZString.Empty;
			AssertEquals("CarrierCode", airline.RM_TwoCharacterCode, declaration.CarrierCode);

			airline.RM_ThreeLetterCode = "TAR";
			AssertEquals("CarrierCode", airline.RM_TwoCharacterCode, declaration.CarrierCode);
			declaration.US_UI_NKCarrierSCAC = ZString.Empty;
			AssertNoMessageError(declaration.US_UI_NKCarrierSCACInfo, messageError);

			declaration.JE_OH_ShippingLine = ZGuid.Empty;
			AssertEquals("CarrierCode", "", declaration.CarrierCode);
			AssertNoMessageError(declaration.US_UI_NKCarrierSCACInfo, messageError);

			declaration.US_UI_NKCarrierSCAC = ZString.Empty;
			AssertHasMessageError(declaration.US_UI_NKCarrierSCACInfo, messageError);

			declaration.JE_OH_ShippingLine = helper.ShippingLine.PK;
			var list = new TransportTypeList();
			foreach (var transportMode in new[] { TransportTypeList.Codes.Air, TransportTypeList.Codes.BorderWaterBorne, TransportTypeList.Codes.Rail, TransportTypeList.Codes.Sea, TransportTypeList.Codes.Truck })
			{
				list.RemoveCode(transportMode);
				declaration.JE_TransportMode = transportMode;
				AssertNotEquals(ZString.Empty, declaration.CarrierCode);
			}

			declaration.US_UI_NKCarrierSCAC = ZString.Empty;
			foreach (ICodeDescription pair in list)
			{
				declaration.JE_TransportMode = pair.Code;
				AssertEquals(ZString.Empty, declaration.CarrierCode);
			}
		}

		public void TestIsContainerSupported()
		{
			JobDeclaration declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EnableINB = false;
			AssertEquals(false, declaration.IsInBond);
			List<string> transportModeThatSupportContainer = new List<string>();
			transportModeThatSupportContainer.Add(TransportTypeList.Codes.Sea);
			transportModeThatSupportContainer.Add(TransportTypeList.Codes.Truck);
			transportModeThatSupportContainer.Add(TransportTypeList.Codes.Rail);
			transportModeThatSupportContainer.Add(TransportTypeList.Codes.Air);

			foreach (CodeDescriptionPair pair in Factory.GetCachedValue<TransportTypeList>())
			{
				declaration.JE_TransportMode = pair.Code;
				AssertEquals(transportModeThatSupportContainer.Contains(pair.Code), declaration.IsContainerSupported);
			}

			declaration.US_EnableINB = true; // Not sure whether this is correct
			AssertEquals(true, declaration.IsInBond);
			foreach (CodeDescriptionPair pair in Factory.GetCachedValue<TransportTypeList>())
			{
				declaration.JE_TransportMode = pair.Code;
				AssertEquals(true, declaration.IsContainerSupported);
			}
		}

		public void TestContainersAlwaysRequired()
		{
			USCustomsDataRegistry.Instance.EnableNCTAsDefaultContainerModeForAirOrTruckDeclaration.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, false);
			JobDeclaration declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.JE_TransportMode = TransportTypeList.Codes.Sea;
			declaration.JE_ContainerMode = Core.Constants.ContainerModes.Containerised;
			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			declaration.US_EnableENS = true;
			declaration.US_EnableINB = false;
			declaration.US_EnableAII = false;
			AssertEquals(false, declaration.ContainersAlwaysRequired);
			declaration.US_EnableAII = true;
			AssertEquals(true, declaration.ContainersAlwaysRequired);
			declaration.US_EnableAII = false;
			declaration.US_EnableINB = true;
			AssertEquals(true, declaration.ContainersAlwaysRequired);

			declaration.JE_TransportMode = TransportTypeList.Codes.Air;
			declaration.JE_ContainerMode = Core.Constants.ContainerModes.Containerised;
			AssertEquals(false, declaration.ContainersAlwaysRequired);

			declaration.JE_TransportMode = TransportTypeList.Codes.Sea;
			AssertEquals(true, declaration.ContainersAlwaysRequired);

			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFTZ;
			declaration.JE_TransportMode = TransportTypeList.Codes.Sea;
			AssertEquals(false, declaration.ContainersAlwaysRequired);

			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			declaration.JE_TransportMode = TransportTypeList.Codes.Road;
			AssertEquals(false, declaration.ContainersAlwaysRequired);

			declaration.JE_TransportMode = TransportTypeList.Codes.Rail;
			AssertEquals(true, declaration.ContainersAlwaysRequired);

			declaration.JE_TransportMode = TransportTypeList.Codes.Truck;
			AssertEquals(true, declaration.ContainersAlwaysRequired);

			declaration.JE_ContainerMode = Core.Constants.ContainerModes.NonContainerised;
			AssertEquals(false, declaration.ContainersAlwaysRequired);

			declaration.JE_TransportMode = TransportTypeList.Codes.Sea;
			AssertEquals(false, declaration.ContainersAlwaysRequired);

			declaration.JE_TransportMode = TransportTypeList.Codes.Road;
			AssertEquals(false, declaration.ContainersAlwaysRequired);

			declaration.JE_TransportMode = TransportTypeList.Codes.Rail;
			AssertEquals(false, declaration.ContainersAlwaysRequired);

			declaration.JE_TransportMode = TransportTypeList.Codes.Truck;
			AssertEquals(false, declaration.ContainersAlwaysRequired);
		}

		public void TestUpdateTransportReferenceIfApplicable()
		{
			ForwardingShipment shipment = Factory.New<ForwardingShipment>();
			JobDeclaration declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			declaration.JE_TransportMode = TransportTypeList.Codes.Air;
			declaration.JE_OverrideFreightDefaults = true;
			AssertEquals("ShouldSynchroniseWithShipment()", false, declaration.ShouldSynchroniseWithShipment());
			declaration.US_TransportReference = "";
			declaration.JE_MasterBill = "0812321111";
			declaration.JE_HouseBill = "HWB23423";

			AssertEquals("US_TransportReference", "", declaration.US_TransportReference);
			declaration.JE_MessageType = JobMessageTypeList.Codes.Export;
			AssertEquals("US_TransportReference should be formatted Mawb", "081-2321111", declaration.US_TransportReference);

			declaration.JE_HouseBill = "HWB23444";
			AssertEquals("US_TransportReference shouldn't have changed as it wasn't empty", "081-2321111", declaration.US_TransportReference);

			declaration.US_TransportReference = "";
			declaration.JE_HouseBill = "HWB23433";
			AssertEquals("US_TransportReference should have defaulted to formatted MasterBill as it was empty.", "081-2321111", declaration.US_TransportReference);

			declaration.JE_MasterBill = "0812321123";
			AssertEquals("US_TransportReference should default to new formatted masterbill as it masterbill was updated", "081-2321123", declaration.US_TransportReference);

			declaration.US_TransportReference = "";
			declaration.JE_TransportMode = TransportTypeList.Codes.Sea;
			declaration.JE_MasterBill = "OB020928";
			AssertEquals("US_TransportReference should NOT default Ocean Bill for sea", "", declaration.US_TransportReference);

			declaration.US_TransportReference = "432089";
			declaration.JE_MasterBill = "";
			AssertEquals("US_TransportReference should remain even when MasterBill cleared out", "432089", declaration.US_TransportReference);

			declaration.US_TransportReference = "";
			declaration.JE_TransportMode = TransportTypeList.Codes.Air;
			AssertEquals("US_TransportReference should have defaulted to HouseBill as it was empty.", declaration.JE_HouseBill, declaration.US_TransportReference);

			shipment.JS_HouseBill = "HWB23444";
			shipment.JS_TransportMode = Core.Constants.TransportModes.Air;
			declaration.US_TransportReference = "";
			declaration.JE_JS = shipment.PK;
			ErrorReporter.Clear();
			declaration.JE_OverrideFreightDefaults = false;
			AssertEquals("ShouldSynchroniseWithShipment()", true, declaration.ShouldSynchroniseWithShipment());
			AssertEquals("US_TransportReference should have been synchronised with Shipment.", shipment.JS_HouseBill, declaration.US_TransportReference);

			declaration.US_TransportReference = "";
			declaration.JE_HouseBill = "HWB2346";
			AssertEquals("US_TransportReference should not have been changed.", "", declaration.US_TransportReference);

			declaration.JE_OverrideFreightDefaults = true;
			AssertEquals("ShouldSynchroniseWithShipment()", false, declaration.ShouldSynchroniseWithShipment());
			declaration.JE_HouseBill = "HWB2345";
			AssertEquals("US_TransportReference should have defaulted to HouseBill.", declaration.JE_HouseBill, declaration.US_TransportReference);

			declaration.JE_JS = ZGuid.Empty;
			AssertEquals("ShouldSynchroniseWithShipment()", false, declaration.ShouldSynchroniseWithShipment());
			declaration.US_TransportReference = "";
			declaration.JE_HouseBill = "HWB2346";
			AssertEquals("US_TransportReference should have defaulted to HouseBill.", declaration.JE_HouseBill, declaration.US_TransportReference);
		}

		public void TestJE_MessageType()
		{
			var importer = Factory.NewWithValidTestData<OrgHeader>();
			importer.MainAddress.OA_RN_NKCountryCode = "US";
			JobDeclaration declaration = Factory.New<JobDeclaration>();
			declaration.JE_OH_Importer = importer.PK;
			USCustomsDataRegistry.Instance.DoDefaultImporterOfRecord.SetValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, true);
			USCustomsDataRegistry.Instance.DoDefaultSoldToParty.SetValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, true);
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACE;

			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			AssertEquals("FDA Submitter", importer.PK, declaration.JE_OH_FDASubmitter);
			AssertEquals("Ultimate Consignee", importer.MainAddress.PK, declaration.JE_OA_ConsigneeAddress);
			AssertEquals("IOR", importer.PK, declaration.IOROrgPK);
			AssertEquals("Sold To Party", importer.MainAddress.PK, declaration.JE_OA_SoldToPartyAddress);

			declaration.JE_OA_ConsigneeAddress = ZGuid.Empty;
			importer.MainAddress.OA_RN_NKCountryCode = "AU";
			declaration.JE_MessageType = JobMessageTypeList.Codes.Export;
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			Assert("Ultimate Consignee", !declaration.JE_OA_ConsigneeAddress.IsValid);
			declaration.JE_OA_ConsigneeAddress = importer.MainAddress.PK;
			importer.MainAddress.OA_RN_NKCountryCode = "US";

			declaration.JE_MessageType = JobMessageTypeList.Codes.Export;
			Assert("FDA Submitter", !declaration.JE_OH_FDASubmitter.IsValid);
			Assert("Ultimate Consignee", !declaration.JE_OA_ConsigneeAddress.IsValid);
			Assert("IOR", !declaration.IOROrgPK.IsValid);
			Assert("Sold To Party", !declaration.JE_OA_SoldToPartyAddress.IsValid);
		}

