		public void TestSchDUSPortOfEntryForRLF()
		{
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_TransportMode = TransportTypeList.Codes.Sea;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACE;

			var registryItemsCollection = new BranchDistrictPortCollection(new FallbackLevel(declaration.RegistryCompanyPK, Guid.Empty, Guid.Empty), Factory);
			var item1 = registryItemsCollection.AddNew();
			item1.PortCode = "21";
			item1.BranchPK = GlbBranch.CurrentBranch.PK;

			GlbStaff.CurrentUser.GS_GB_HomeBranch = ZGuid.Empty;
			declaration.US_SchDEntry = "3901";
			AssertEquals("Entry Mode should be Empty if Home Port of Staff's branch is not Set", ZString.Empty, declaration.US_EntryMode);
			declaration.US_SchDEntry = "2127";
			AssertEquals("Entry Mode should be Empty if Home Port of Staff's branch is not Set", ZString.Empty, declaration.US_EntryMode);

			GlbStaff.CurrentUser.GS_GB_HomeBranch = GlbBranch.CurrentBranch.PK;
			USCustomsDataRegistry.Instance.BranchDistrictPortRelationship.SetValue(declaration.RegistryCompanyPK, Guid.Empty, Guid.Empty, registryItemsCollection);
			declaration.US_SchDEntry = "3901";
			AssertEquals("Entry Mode should default to RLF if Electronic filing has not been set", EntryModeList.Codes.RLF, declaration.US_EntryMode);

			declaration.US_EntryMode = "";
			USCustomsDataRegistry.Instance.BranchDistrictPortRelationship.SetValue(declaration.RegistryCompanyPK, Guid.Empty, Guid.Empty, registryItemsCollection);
			declaration.US_SchDEntry = "2127";
			AssertEquals("Entry Mode should be Empty if Home Port of Staff IS not the same as Entry port entered", ZString.Empty, declaration.US_EntryMode);

			EntryTypeList entryTypeList = new EntryTypeList();

			for (int i = 0; i < entryTypeList.Count; i++)
			{
				declaration.US_EntryMode = "";
				declaration.US_EntryType = entryTypeList[i].Code;
				declaration.US_SchDEntry = ((i % 2) == 0) ? "3901" : "3902";
				if (EntryTypeList.IsElectronicFilingAllowed(declaration.IsACE, declaration.US_EntryType))
				{
					AssertEquals("Entry Type = " + declaration.US_EntryType, EntryModeList.Codes.RLF, declaration.US_EntryMode);
				}
				else
				{
					AssertEquals("Entry Type = " + declaration.US_EntryType, "", declaration.US_EntryMode);
				}
			}

			for (int i = 0; i < entryTypeList.Count; i++)
			{
				declaration.US_SchDEntry = ((i % 2) == 0) ? "2127" : "2128";
				declaration.US_EntryType = entryTypeList[i].Code;
				AssertEquals("Entry Type = " + declaration.US_EntryType, "", declaration.US_EntryMode);
			}
		}

