		public void TestITNumbersFromLowestBills()
		{
			var declaration = Factory.New<JobDeclaration>();
			var bill1 = declaration.Bills.AddNew();
			bill1.ITNumber = "123456H";
			AssertEquals("Primary IT number", "123456H", declaration.JE_PrimaryITNumber);
			AssertEquals(false, declaration.JE_PrimaryITNumberInfo.ReadOnly);

			declaration.JE_HouseBill = "HB1";
			var bill3 = declaration.Bills.AddNew();
			bill3.ITNumber = "YZ88888";

			Assert(declaration.JE_PrimaryITNumberInfo.ReadOnly);
			Assert("IT numbers", declaration.ITNumbersFromBills.Contains("123456H"));
			Assert("IT numbers", declaration.ITNumbersFromBills.Contains("YZ88888"));
			AssertEquals("Primary IT number", JobDeclaration.Constants.Multiple, declaration.JE_PrimaryITNumber);

			declaration.Bills.RemoveAndDeleteAll();
			bill1 = declaration.Bills.AddNew();
			bill1.CU_BillType = BillTypeList.Codes.MasterBill;

			var bill2 = declaration.Bills.AddNew();
			bill2.CU_BillType = BillTypeList.Codes.HouseBill;
			bill2.CU_CU_ParentBill = bill1.PK;

			bill3 = declaration.Bills.AddNew();
			bill3.CU_BillType = BillTypeList.Codes.HouseBill;
			bill3.CU_CU_ParentBill = bill1.PK;

			var bill4 = declaration.Bills.AddNew();
			bill4.CU_BillType = BillTypeList.Codes.SubHouseBill;
			bill4.CU_CU_ParentBill = bill3.PK;
			AssertEquals("Multiple Lowest Bills without IT numbers", "", declaration.JE_PrimaryITNumber);

			declaration.JE_PrimaryITNumber = "124567851";
			AssertEquals(0, bill1.ITAndSplitDetails.Count);
			AssertEquals(1, bill2.ITAndSplitDetails.Count);
			AssertEquals("124567851", bill2.ITAndSplitDetails[0].US_ITNumber);

			AssertEquals(0, bill3.ITAndSplitDetails.Count);
			AssertEquals(1, bill4.ITAndSplitDetails.Count);
			AssertEquals("124567851", bill4.ITAndSplitDetails[0].US_ITNumber);
			AssertEquals("All IT-s the same - PrimaryITNumber not readonly", false, declaration.JE_PrimaryITNumberInfo.ReadOnly);

			declaration.JE_TransportMode = TransportTypeList.Codes.Sea;
			declaration.US_EnableCRL = true;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACE;
			Assert("IT details are not relevant for ACE Cargo Release, should be removed when application code changed to ACE", declaration.Bills.All(x => ((Bill)x).ITAndSplitDetails.Count == 0 || ((Bill)x).ITAndSplitDetails.Count == 1));

			declaration.US_EnableCRL = false;
			declaration.US_EnableENS = true;
			bill4.ITNumber = "YZ88888";
			AssertEquals(1, bill4.ITAndSplitDetails.Count);
		}

		public void TestLowestBillsWithTransportChanged()
		{
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACE;
			declaration.JE_TransportMode = TransportTypeList.Codes.Sea;
			declaration.JE_ContainerMode = ContainerModeList.Codes.Containerized;
			declaration.US_EnableENS = true;

			var bill1 = declaration.Bills.AddNew();
			bill1.CU_BillNum = "000000";
			bill1.CU_BillType = BillTypeList.Codes.MasterBill;

			var bill2 = declaration.Bills.AddNew();
			bill2.CU_BillNum = "001100";
			bill2.CU_BillType = BillTypeList.Codes.HouseBill;
			bill2.CU_CU_ParentBill = bill1.PK;

			var bill3 = declaration.Bills.AddNew();
			bill3.CU_BillNum = "002200";
			bill3.CU_BillType = BillTypeList.Codes.HouseBill;
			bill3.CU_CU_ParentBill = bill1.PK;

			var bill4 = declaration.Bills.AddNew();
			bill4.CU_BillNum = "002233";
			bill4.CU_BillType = BillTypeList.Codes.SubHouseBill;
			bill4.CU_CU_ParentBill = bill2.PK;

			AssertEquals(2, declaration.LowestBills.Count);
			declaration.JE_TransportMode = TransportTypeList.Codes.Rail;
			AssertEquals(1, declaration.LowestBills.Count);
			AssertNoExceptionThrown(() => declaration.JE_PrimaryITNumber = "124567851");
		}

		public void TestICargoManifestStatusQueryHeaderMembers()
