			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACE;
			declaration.US_EntryFilerCode = "ABC";
			declaration.JE_DeclarationReference = "B89345789";
			declaration.US_EnableENS = true;
			declaration.US_EnableCRL = false;
			declaration.ImportEntryNumber = "12345678";
			var invoice = declaration.Invoices.AddNew();
			var invoiceLine = invoice.JobComInvoiceLines.AddNew();
			declaration.DoMerge(new SendsMessagesToCustomsShutterUpperer());
			var queryData = (ICargoManifestStatusQueryHeader)declaration;
			AssertEquals("Entry Filer Code", "ABC", queryData.EntryFilerCode);
			var queryObject = queryData.ObjectsForQuery.FirstOrDefault();
			AssertNotNull(queryObject);
			AssertEquals(CargoManifestQueryActionType.Entry, queryObject.QueryActionType);
			AssertEquals("12345678", queryObject.EntryOrInBondNumber);

			declaration.US_EnableENS = false;
			declaration.US_EnableCRL = true;
			declaration.DoMerge(new SendsMessagesToCustomsShutterUpperer());
			queryData = declaration;
			AssertEquals("Entry Filer Code", "ABC", queryData.EntryFilerCode);
			queryObject = queryData.ObjectsForQuery.FirstOrDefault();
			AssertNotNull(queryObject);
			AssertEquals(CargoManifestQueryActionType.Entry, queryObject.QueryActionType);
			AssertEquals("12345678", queryObject.EntryOrInBondNumber);
		}

