		public void TestSetImporterUpdatesJZ_OH_BuyerForExport()
		{
			var importer = Factory.NewWithValidTestData<OrgHeader>();
			importer.OH_Code = "MAX1";
			importer.MainAddress.OA_RN_NKCountryCode = "US";

			var importer2 = Factory.NewWithValidTestData<OrgHeader>();
			importer2.OH_Code = "MAX2";
			importer2.MainAddress.OA_RN_NKCountryCode = "US";

			var buyer = Factory.NewWithValidTestData<OrgHeader>();
			buyer.OH_Code = "MAX3";
			buyer.MainAddress.OA_RN_NKCountryCode = "US";

			Declaration.JE_MessageType = JobMessageTypeList.Codes.Export;
			Declaration.JE_OH_Importer = importer.PK;

			var invoice1 = Declaration.Invoices.AddNew();
			var invoice2 = Declaration.Invoices.AddNew();

			Factory.Save();

			AssertEquals("Buyer should be defaulted from Importer", importer.PK, invoice1.JZ_OH_Buyer);
			AssertEquals("Buyer should be defaulted from Importer", importer.PK, invoice2.JZ_OH_Buyer);

			invoice2.JZ_OH_Buyer = buyer.PK;

			Factory.Save();

			Declaration.JE_OH_Importer = importer2.PK;

			AssertEquals("Buyer for invoice1 should be updated from Importer", importer2.PK, invoice1.JZ_OH_Buyer);
			AssertEquals("Buyer for invoice2 should not be updated from Importer", buyer.PK, invoice2.JZ_OH_Buyer);
		}

