		public void TestACECargoReleaseAndBillStatus()
		{
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACE;
			declaration.US_EnableCRL = true;
			AssertEquals("ACE CargoReleaseStatus", ZString.Empty, declaration.CargoReleaseStatus);
			AssertEquals("ACE CargoReleaseStatusDesc", ImportMessageStatusList.Descriptions.NotSent, declaration.CargoReleaseStatusDesc);
			AssertEquals("SimplifiedEntryBillStatus", ZString.Empty, declaration.SimplifiedEntryBillStatus);

			var entry1 = declaration.CustomsEntryHeaders.AddNew();
			entry1.CH_MessageType = CusEntryHeaderMessageTypeList.Codes.ACECargoRelease;
			entry1.CH_Status = ImportMessageStatusList.Codes.ClearACECargoReleaseAdd;
			AssertEquals("ACE CargoReleaseStatus", ImportMessageStatusList.Codes.ClearACECargoReleaseAdd, declaration.CargoReleaseStatus);
			AssertEquals("ACE CargoReleaseStatusDesc", ImportMessageStatusList.Descriptions.ClearACECargoReleaseAdd, declaration.CargoReleaseStatusDesc);

			declaration.simplifiedEntryBillStatus = null;
			var bill = declaration.Bills.AddNew();
			bill.CU_BillNum = "Test1";
			bill.CU_BillType = Customs.Business.BillTypeList.Codes.MasterBill;
			bill.DispositionCodes.AddNewIfNotExist("94", ZDateTime.Today, BillDispositionSourceList.Codes.SO);
			Assert("SimplifiedEntryBillStatus", declaration.SimplifiedEntryBillStatus.Contains("94"));

			declaration.simplifiedEntryBillStatus = null;
			var bill2 = declaration.Bills.AddNew();
			bill2.CU_BillType = Customs.Business.BillTypeList.Codes.MasterBill;
			bill2.CU_BillNum = "Test2";
			bill2.DispositionCodes.AddNewIfNotExist("93", ZDateTime.Today, BillDispositionSourceList.Codes.SO);
			Assert("SimplifiedEntryBillStatus", declaration.SimplifiedEntryBillStatus.Contains("93"));

			declaration.simplifiedEntryBillStatus = null;
			declaration.Bills.RemoveAndDeleteAll();
			var masterBill = declaration.Bills.AddNew();
			var childBill = masterBill.ChildBills.AddNew();
			childBill.DispositionCodes.AddNewIfNotExist("95", ZDateTime.Today, BillDispositionSourceList.Codes.SO);
			AssertEquals("SimplifiedEntryBillStatus", "95", declaration.SimplifiedEntryBillStatus);

			declaration.simplifiedEntryBillStatus = null;
			childBill.DispositionCodes.DeleteAll();
			masterBill.DispositionCodes.AddNewIfNotExist("91", ZDateTime.Today, BillDispositionSourceList.Codes.SO);
			AssertEquals("SimplifiedEntryBillStatus", "91", declaration.SimplifiedEntryBillStatus);

			declaration.simplifiedEntryBillStatus = null;
			masterBill.DispositionCodes.DeleteAll();
			masterBill.DispositionCodes.AddNewIfNotExist("91", ZDateTime.Today, BillDispositionSourceList.Codes.IS);
			AssertEquals("SimplifiedEntryBillStatus - disposition from Cargo Manifect Query should not be shown", ZString.Empty, declaration.SimplifiedEntryBillStatus);

			var helper = new UniversalReferenceTestDataHelper(Factory);
			var dataGrouping = helper.CreateNewOrGetExistingDataGrouping(Core.Constants.CountryCodes.UnitedStates, "US");
			var codeType = helper.CreateNewOrGetExistingCusCodeType(Core.Constants.Customs.Universal.RefCusCodeListTypes.Codes.SO50RecordDispCode, "SO50D", dataGrouping.ZZZ_DataGrouping);
			var date = ZDateTime.UtcNow;
			var startDate = date.AddDays(-10);
			var endDate = date.AddDays(10);
			var code1 = helper.CreateNewOrGetExistingCusCodeList(dataGrouping.ZZZ_DataGrouping, codeType.ZZK_CodeType, "51", "51DESC", startDate, endDate);
			var code2 = helper.CreateNewOrGetExistingCusCodeList(dataGrouping.ZZZ_DataGrouping, codeType.ZZK_CodeType, "52", "52DESC", startDate, endDate);
			var code3 = helper.CreateNewOrGetExistingCusCodeList(dataGrouping.ZZZ_DataGrouping, codeType.ZZK_CodeType, "1G", "1GDESC", startDate, endDate);
			var code4 = helper.CreateNewOrGetExistingCusCodeList(dataGrouping.ZZZ_DataGrouping, codeType.ZZK_CodeType, "1H", "1HDESC", startDate, endDate);
			var code5 = helper.CreateNewOrGetExistingCusCodeList(dataGrouping.ZZZ_DataGrouping, codeType.ZZK_CodeType, "2P", "2PDESC", startDate, endDate);
			var code6 = helper.CreateNewOrGetExistingCusCodeList(dataGrouping.ZZZ_DataGrouping, codeType.ZZK_CodeType, "72", "Inspection/document review hold for CBPA placed at port of discharge", startDate, endDate);
			Factory.Save();

			declaration.simplifiedEntryBillStatus = null;
			declaration.Bills.RemoveAndDeleteAll();
			var bill1 = declaration.Bills.AddNew();
			bill1.CU_MessageStatus = "51/52";
			bill2 = declaration.Bills.AddNew();
			bill2.CU_MessageStatus = "1G/1H/2P";
			Assert(declaration.SimplifiedEntryBillStatus.Contains("51,52,1G,1H,2P"));
			var statusDescription = declaration.SimplifiedEntryBillStatusDescription;
			AssertEquals("SimplifiedEntryBillStatusDescription", "51-51DESC,52-52DESC,1G-1GDESC,1H-1HDESC,2P-2PDESC", statusDescription);

			declaration.simplifiedEntryBillStatus = null;
			declaration.simplifiedEntryBillStatusDescription = null;
			declaration.Bills.RemoveAndDeleteAll();
			bill1 = declaration.Bills.AddNew();
			bill1.CU_MessageStatus = "72";
			statusDescription = declaration.SimplifiedEntryBillStatusDescription;
			AssertEquals("SimplifiedEntryBillStatusDescription", "72-Inspection/document review hold for CBPA placed at port of discharge", statusDescription);

			declaration.simplifiedEntryBillStatus = null;
			declaration.Bills.RemoveAndDeleteAll();
			bill1 = declaration.Bills.AddNew();
			bill1.DispositionCodes.AddNewIfNotExist("95", ZDateTime.Today, BillDispositionSourceList.Codes.SO);
			bill1.DispositionCodes.AddNewIfNotExist("92", ZDateTime.Today, BillDispositionSourceList.Codes.SO);
			bill1.DispositionCodes.AddNewIfNotExist("94", ZDateTime.Today, BillDispositionSourceList.Codes.SO);

			bill2 = declaration.Bills.AddNew();
			bill2.DispositionCodes.AddNewIfNotExist("52", ZDateTime.Today, BillDispositionSourceList.Codes.SO);
			bill2.DispositionCodes.AddNewIfNotExist("91", ZDateTime.Today, BillDispositionSourceList.Codes.SO);
			bill2.DispositionCodes.AddNewIfNotExist("58", ZDateTime.Today, BillDispositionSourceList.Codes.SO);

			Assert(declaration.SimplifiedEntryBillStatus.Contains(ImportEntryStatusList.Codes.MUL));
		}

