		public void TestPaymentDueDate()
		{
			Declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			Declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			Declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			Declaration.US_EnableENS = true;
			AssertEquals("PaymentDueDate should now be calculated in all cases", ZDateTime.Empty, Declaration.US_PaymentDueDate);
			AssertEquals("Precondition: Deferred Tax Due Date is empty", ZDateTime.Empty, Declaration.US_DeferredTaxDueDate);

			Declaration.US_EstimatedEntryDate = new ZDateTime(2009, 06, 05);
			AssertEquals("PaymentDueDate should be Est. Entry Date + 10 working days", new ZDateTime(2009, 06, 19), Declaration.US_PaymentDueDate);
			AssertEquals(@"Deferred Tax Due Date is empty and should not be calculated when US_PaymentDueDate has changed,
			because Declaration is not tax deferred", ZDateTime.Empty, Declaration.US_DeferredTaxDueDate);

			Declaration.US_TaxDeferIndicator = TaxDeferIndicatorList.Codes.DeferredTax;
			Declaration.JE_EntryAuthorisationDate = new ZDateTime(2009, 06, 8);
			AssertEquals("PaymentDueDate should be re-calculate on Release Date update", new ZDateTime(2009, 06, 22), Declaration.US_PaymentDueDate);
			AssertEquals("Deferred Tax Due Date calculated when US_PaymentDueDate has changed", new ZDateTime(2009, 07, 14), Declaration.US_DeferredTaxDueDate);

			Declaration.US_PresentationDate = new ZDateTime(2009, 06, 3);
			AssertEquals("PaymentDueDate should be re-calculate on Presentation Date change", new ZDateTime(2009, 06, 22), Declaration.US_PaymentDueDate);

			Declaration.US_PresentationDate = new ZDateTime(2009, 06, 9);
			AssertEquals("PaymentDueDate should be re-calculate on release date as it is later than release date", new ZDateTime(2009, 06, 22), Declaration.US_PaymentDueDate);
			AssertEquals("Deferred Tax Due Date calculated when US_PaymentDueDate has changed", new ZDateTime(2009, 07, 14), Declaration.US_DeferredTaxDueDate);

			Declaration.US_FixDefTaxDueDate = true;
			Declaration.US_PaymentDueDate = new ZDateTime(2009, 06, 02);
			AssertEquals(@"Deferred Tax Due Date should not be calculated when US_PaymentDueDate has changed,
			because Def Tax Due Date is locked", new ZDateTime(2009, 07, 14), Declaration.US_DeferredTaxDueDate);
		}

