		public void TestSettingEntryAuthorisationDateLogsCLRIngnoringExistingEstimate_CS00222784()
		{
			Declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			Declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			Declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			Declaration.US_EnableENS = true;
			Declaration.Invoices.AddNew();
			Declaration.InvoiceLines.AddNew();
			Declaration.DoMerge(new SendsMessagesToCustomsShutterUpperer());
			Declaration.ActiveEntryHeaders.EntrySummaryEntry.CH_Status = ImportMessageStatusList.Codes.ClearEntrySummaryOriginal;
			var log = Declaration.Logs.AddNew(Events.CustomsCleared, ZDateTimeOffset.Now.AddHours(1), ZBool.False);
			Declaration.JE_EntryAuthorisationDate = new ZDateTime(2009, 06, 8);
			Factory.Save();
			var logs = Declaration.Logs.GetAllLogs();
			var cccLogs = logs.Find(new ZQuery(StmALogSchema.SL_SE_NKEvent, Events.CustomsCleared.Code));
			AssertEquals(1, cccLogs.Length);

			using (log.LockForUpdatingKeyFieldsForTesting())
			{
				log.SL_IsEstimate = ZBool.True;
			}
			Declaration.JE_EntryAuthorisationDate = new ZDateTime(2009, 06, 9);
			Factory.Save();
			logs = Declaration.Logs.GetAllLogs();
			cccLogs = logs.Find(new ZQuery(StmALogSchema.SL_SE_NKEvent, Events.CustomsCleared.Code));
			AssertEquals(2, cccLogs.Length);
		}

		public void TestPaymentDueDateDoesNotCalculateRepopulatedWhenWithdrawn()
		{
			Declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			Declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			Declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			Declaration.US_EnableENS = true;

			Declaration.US_EstimatedEntryDate = new ZDateTime(2009, 06, 05);
			AssertEquals("PaymentDueDate should be Est. Entry Date + 10 working days", new ZDateTime(2009, 06, 19), Declaration.US_PaymentDueDate);

			Declaration.Invoices.AddNew();
			Declaration.InvoiceLines.AddNew();

			Declaration.DoMerge(new SendsMessagesToCustomsShutterUpperer());

			Declaration.ActiveEntryHeaders.EntrySummaryEntry.CH_Status = ImportMessageStatusList.Codes.ClearEntrySummaryOriginal;
			Declaration.JE_EntryAuthorisationDate = new ZDateTime(2009, 06, 8);
			AssertEquals("PaymentDueDate should be re-calculate on Presentation Date change", new ZDateTime(2009, 06, 22), Declaration.US_PaymentDueDate);
			Factory.Save();

			Declaration.ActiveEntryHeaders.EntrySummaryEntry.CH_Status = ImportMessageStatusList.Codes.ClearEntrySummaryDelete;
			Factory.Save();

			AssertEquals("Payment due date is cleared", ZDateTime.Empty, Declaration.US_PaymentDueDate);

			Declaration.US_EstimatedEntryDate = new ZDateTime(2009, 06, 05);
			AssertEquals("When the entry summary message status is CED(clear entry summery delete).If users change one of the date fields from which CalculatePaymentDueDate is triggered, then it will NOT be repopulated", ZDateTime.Empty, Declaration.US_PaymentDueDate);
		}

		public void TestPaymentDueDateWhenWithdrawnReAdded()
		{
			Declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			Declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			Declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			Declaration.US_EnableENS = true;
			AssertEquals("PaymentDueDate should now be calculated in all cases", ZDateTime.Empty, Declaration.US_PaymentDueDate);

			Declaration.US_EstimatedEntryDate = new ZDateTime(2009, 06, 05);
			AssertEquals("PaymentDueDate should be Est. Entry Date + 10 working days", new ZDateTime(2009, 06, 19), Declaration.US_PaymentDueDate);

			Declaration.Invoices.AddNew();
			Declaration.InvoiceLines.AddNew();

			Declaration.DoMerge(new SendsMessagesToCustomsShutterUpperer());

			Declaration.ActiveEntryHeaders.EntrySummaryEntry.CH_Status = ImportMessageStatusList.Codes.ClearEntrySummaryOriginal;
			Declaration.JE_EntryAuthorisationDate = new ZDateTime(2009, 06, 8);
			AssertEquals("PaymentDueDate should be re-calculate on Presentation Date change", new ZDateTime(2009, 06, 22), Declaration.US_PaymentDueDate);
			Factory.Save();

			var logs = Declaration.Logs.GetAllLogs();
			var cccLogs = logs.Find(new ZQuery(StmALogSchema.SL_SE_NKEvent, Events.CustomsCleared.Code));
			AssertEquals(1, cccLogs.Length);

			Declaration.ActiveEntryHeaders.EntrySummaryEntry.CH_Status = ImportMessageStatusList.Codes.AwaitingEntrySummaryDelete;
			Factory.Save();

			Declaration.ActiveEntryHeaders.EntrySummaryEntry.CH_Status = ImportMessageStatusList.Codes.ClearEntrySummaryDelete;
			Factory.Save();

			AssertEquals("Cleared event should remain as active. No release details change", false, ((StmALog)cccLogs[0]).SL_IsCancelled);

			AssertEquals("Release date should remain", new ZDateTime(2009, 06, 8), Declaration.JE_EntryAuthorisationDate);
			AssertEquals("Payment due date is cleared", ZDateTime.Empty, Declaration.US_PaymentDueDate);

			//re-added
			Declaration.ActiveEntryHeaders.EntrySummaryEntry.CH_Status = ImportMessageStatusList.Codes.AwaitingEntrySummaryOriginal;
			Factory.Save();

			Declaration.ActiveEntryHeaders.EntrySummaryEntry.CH_Status = ImportMessageStatusList.Codes.ClearEntrySummaryOriginal;
			Factory.Save();

			AssertEquals("PaymentDueDate should be re-calculate on acceptance", new ZDateTime(2009, 06, 22), Declaration.US_PaymentDueDate);
		}

