		public void TestUS_IsHMFApplicable()
		{
			new FeeCalculationHelperTest().PrepareFeeAndTexData();
			JobDeclaration declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			declaration.US_EnableENS = true;
			declaration.JE_TransportMode = TransportTypeList.Codes.Sea;
			declaration.US_IsHMFApplicable = YesNoDefaultList.Codes.Yes;
			JobComInvoiceHeader header = declaration.Invoices.AddNew();
			header.JZ_RX_NKInvoice_Currency = JobDeclaration.LocalCurrencyConstantCode;
			JobComInvoiceLine invoiceLine = header.JobComInvoiceLines.AddNew();
			invoiceLine.JI_Weight = 9000m;
			invoiceLine.JI_LinePrice = 10000m;
			invoiceLine.JI_InvoiceQuantity = 10000m;
			invoiceLine.JI_InvoiceUQ = "NO";
			invoiceLine.JI_CustomsQuantity = 70m;

			declaration.MessageInitiator = new SendsMessagesToCustomsShutterUpperer();
			declaration.DoMerge();
			Assert(invoiceLine.FeeCusCodes.ContainsCode(Core.Constants.USCustoms.FeeCodes.HMF));

			declaration.US_IsHMFApplicable = YesNoDefaultList.Codes.No;
			Assert(!invoiceLine.FeeCusCodes.ContainsCode(Core.Constants.USCustoms.FeeCodes.HMF));

			declaration.US_IsHMFApplicable = "M";
			declaration.US_IsHMFApplicable = YesNoDefaultList.Codes.No;
			Assert(!invoiceLine.FeeCusCodes.ContainsCode(Core.Constants.USCustoms.FeeCodes.HMF));
		}

