		public void TestIPPQForm368NoticeOfArrivalSupportableMember()
		{
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.JE_TransportMode = declaration.TransportModeSeaCodeForTesting;
			declaration.JE_MarksAndNumbers = "Marks And Numbers";
			declaration.JE_MasterBill = "MB23423";
			declaration.JE_HouseBill = "HW23423";
			var bill = declaration.PrimaryHouseBill.ChildBills.AddNew();
			bill.CU_BillNum = "SB233";

			declaration.JE_TotalNoOfPacks = 123;
			declaration.JE_TotalNoOfPacksPackType = ABIUnitOfMeasureList.Codes.Packs;
			declaration.JE_TotalWeight = 435m;
			declaration.JE_TotalWeightUnit = "KG";

			declaration.JE_GoodsDescription = "Goods For testing";
			var container1 = declaration.CusContainers.AddNew();
			container1.CO_ContainerNumber = "TURE323432";
			var container2 = declaration.CusContainers.AddNew();
			container2.CO_ContainerNumber = "TURE567899";

			var invoice = declaration.Invoices.AddNew();
			var invoiceLine = invoice.InvoiceLines.AddNew();
			invoiceLine.JI_Tariff = "4407100152";
			invoiceLine.JI_NetWeight = 10;
			invoiceLine.JI_NetWeightUQ = Core.Constants.Weight.Kilograms;

			var invoiceLine2 = invoice.InvoiceLines.AddNew();
			invoiceLine2.JI_Tariff = "3601000000";
			invoiceLine2.JI_NetWeight = 100;
			invoiceLine2.JI_NetWeightUQ = Core.Constants.Weight.OuncesTroy;

			var invoiceLine3 = invoice.InvoiceLines.AddNew();
			invoiceLine3.JI_Tariff = "3601000000";
			invoiceLine3.JI_NetWeight = 0.05;
			invoiceLine3.JI_NetWeightUQ = Core.Constants.Weight.LongTons;

			var invoiceLine4 = invoice.InvoiceLines.AddNew();
			invoiceLine4.JI_Tariff = "3601000000";
			invoiceLine4.JI_NetWeightUQ = Core.Constants.Weight.Kilograms;

			var noticeOfArrivalData = new PPQForm368NoticeOfArrivalData(declaration);
			AssertEquals("PPQForm368Box13A", ZString.Empty, noticeOfArrivalData.US_PPQForm368Box13A);
			AssertEquals("PPQForm368Box13B", ZString.Empty, noticeOfArrivalData.US_PPQForm368Box13B);
			AssertEquals("PPQForm368Box13C", ZString.Empty, noticeOfArrivalData.US_PPQForm368Box13C);

			((IPPQForm368NoticeOfArrivalSupportable)declaration).UpdateDefaultData(noticeOfArrivalData);
			AssertEquals("PPQForm368Box13A", "Marks And Numbers\r\nMB:MB23423\r\nHB:HW23423\r\nSH:SB233", noticeOfArrivalData.US_PPQForm368Box13A);
			AssertEquals("PPQForm368Box13B", "123 Package\r\n63.912694 KG", noticeOfArrivalData.US_PPQForm368Box13B);
			AssertEquals("PPQForm368Box13C", "Goods For testing\r\nTURE323432\r\nTURE567899", noticeOfArrivalData.US_PPQForm368Box13C);
		}

		public void TestIsPPQBox13Compatible()
		{
			Assert("All empty", !Declaration.IsPPQForm368Box13Compatible);

			ZQuery query = new ZQuery(CusAddInfoSchema.B7_ParentID, Declaration.PK);
			query.AddToFilter(CusAddInfoSchema.B7_ParentTableCode, "JE");
			query.AddToFilter(CusAddInfoSchema.B7_Type, CusAddInfoTypeAttribute.Codes.USPPQForm368Data);
			var ppqData = Factory.LoadTop1<PPQForm368Data>(query);
			AssertNull("should not create a row in CusAddInfo when accessing JobDeclaration.IsPPQForm368Box13Compatible", ppqData);

			Declaration.US_PPQForm368Box13A = "ABC";
			Assert("Box A", Declaration.IsPPQForm368Box13Compatible);
			Declaration.US_PPQForm368Box13A = ZString.Empty;
			AssertEquals(ZString.Empty, Declaration.US_PPQForm368Box13A);

			Declaration.US_PPQForm368Box13B = "ABC";
			Assert("Box B", Declaration.IsPPQForm368Box13Compatible);
			Declaration.US_PPQForm368Box13B = ZString.Empty;
			Declaration.US_PPQForm368Box13C = "ABC";
			Assert("Box C", Declaration.IsPPQForm368Box13Compatible);
		}

