		public void TestConsolidatedEntryNumberUpdated_EntryNumberAllocated()
		{
			var releaseDeclaration = Factory.New<JobDeclaration>();
			releaseDeclaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			releaseDeclaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			releaseDeclaration.US_EnableENS = true;
			releaseDeclaration.US_EntryFilerCode = "XJ5";
			releaseDeclaration.ImportEntryNumber = "9342838";
			releaseDeclaration.JE_MergeBy = OrgConstants.MergeInvoiceLines.Tariff;
			var invoice1 = releaseDeclaration.Invoices.AddNew();
			invoice1.JZ_InvoiceNumber = "INV1";
			invoice1.JobComInvoiceLines.AddNew();
			releaseDeclaration.DoMerge(new SendsMessagesToCustomsShutterUpperer());
			Factory.Save();

			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.US_EntryFilerCode = "SV9";
			declaration.US_ConsolACE = true;
			declaration.JE_DeclarationReference = "BX00001";
			var invoice2 = declaration.Invoices.AddNew();
			invoice2.US_ReleaseEntryNumber = "XJ59342838";
			AssertEquals("releaseDeclaration's US_ConsolidatedEntryNumber before allocate", "SV9", releaseDeclaration.US_ConsolidatedEntryNumber);

			declaration.AllocateEntryNumber("TEST3333");
			AssertEquals("Allocate by user entered", "SV9TEST3333", releaseDeclaration.US_ConsolidatedEntryNumber);

			declaration.AllocateEntryNumber("");
			Factory.Save();
			AssertEquals("Allocate by system", "SV9" + declaration.ImportEntryNumber, releaseDeclaration.US_ConsolidatedEntryNumber);

			declaration.ENSEntryNumber.CE_EntryNum = "TEST4444";
			var supporter = declaration.GetAllocateNumberSupporter();
			supporter.OnAllocatedNumberSaved();
			AssertEquals("Entry number updated directly", "SV9TEST4444", releaseDeclaration.US_ConsolidatedEntryNumber);
		}

		public void TestWhenSavingFailsAfterEntryNumberIsAllocated()
		{
			TestDec dec = Factory.New<TestDec>();
			dec.JE_MessageType = JobMessageTypeList.Codes.Import;
			dec.US_EnableENS = true;
			dec.ThrowExceptionOnSaving = false;
			Factory.Save();
			AssertEquals("Saved", true, dec.IsInDatabase);

			dec.AllocateEntryNumber("");
			dec.ThrowExceptionOnSaving = true;

			try
			{
				Factory.Save();
			}
			catch { }

			AssertEquals("entry number generated should have been deleted as number fountain is rolled back", ZString.Empty, dec.ImportEntryNumber);

			dec.ThrowExceptionOnSaving = false;
			Factory.Save();
			AssertEquals("Should not attempt to allocate again as the last attempt failed.", ZString.Empty, dec.ImportEntryNumber);

			AssertEquals(true, dec.LockImportEntryNumberAllocationMutex);
			//try again
			dec.AllocateEntryNumber("");
			Factory.Save();
			AssertNotEquals("Some entry number has been allocated", ZString.Empty, dec.ImportEntryNumber);
		}

		class TestDec : JobDeclaration
		{
			public TestDec(BusinessObjectFactory factory, DataRow row)
				: base(factory, row)
			{
			}

			public bool ThrowExceptionOnSaving;

			protected override void OnFactorySaving()
			{
				base.OnFactorySaving();
				if (ThrowExceptionOnSaving)
				{
					throw new Exception();
				}
			}

			public ZString LocalCurrencyCodeCoreExposed
			{
				get { return LocalCurrencyCodeCore; }
			}

			public override ZBool IsPTTCleared
			{
				get { return true; }
			}

			public override ZBool IsPTTArrivalCleared
			{
				get { return true; }
			}

			public ZString GetCustomLogReferenceSuffix()
			{
				return CustomLogReferenceSuffix;
			}
		}

