		public void TestDecEntryNumberReadOnly()
		{
			Declaration.US_EnableENS = true;
			Declaration.JE_MessageType = JobMessageTypeList.Codes.ImportByExternalBroker;
			AssertEquals(false, Declaration.DecEntryNumberInfo.ReadOnly);

			Declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			Declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			AssertEquals(true, Declaration.DecEntryNumberInfo.ReadOnly);

			Declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACE;
			Declaration.US_EntryFilerCode = "EEB";
			Declaration.US_PSC = true;
			AssertEquals(false, Declaration.DecEntryNumberInfo.ReadOnly);
			Assert(!Declaration.IsEntryFiledByCurrentCompanyForPSC);

			Declaration.Invoices.AddNew();
			Declaration.InvoiceLines.AddNew();
			Declaration.DoMerge(new SendsMessagesToCustomsShutterUpperer());

			var entry = Declaration.ActiveEntryHeaders.EntrySummaryEntry;
			AssertEquals(false, Declaration.DecEntryNumberInfo.ReadOnly);

			entry.CH_Status = ImportMessageStatusList.Codes.ClearEntrySummaryOriginal;
			AssertEquals(true, Declaration.DecEntryNumberInfo.ReadOnly);

			Declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			AssertEquals(true, Declaration.DecEntryNumberInfo.ReadOnly);

			var aceDecLodgedByCompanyToBePSCed = Factory.New<JobDeclaration>();
			aceDecLodgedByCompanyToBePSCed.JE_MessageType = JobMessageTypeList.Codes.Import;
			aceDecLodgedByCompanyToBePSCed.JE_ApplicationCode = JobApplicationCodeList.Codes.ACE;
			aceDecLodgedByCompanyToBePSCed.US_EntryFilerCode = "ABC";
			aceDecLodgedByCompanyToBePSCed.US_EnableENS = true;
			aceDecLodgedByCompanyToBePSCed.JE_EntryAuthorisationDate = ZDateTime.BrettsBirthday;
			Assert(aceDecLodgedByCompanyToBePSCed.IsEntryFiledByCurrentCompanyForPSC);

			aceDecLodgedByCompanyToBePSCed.US_PSC = true;
			AssertEquals("entry number should remain readonly if this entry is lodged by this company in the first place", true, aceDecLodgedByCompanyToBePSCed.DecEntryNumberInfo.ReadOnly);
		}

		public void TestAutoSendCarrierSCAC()
		{
			var scacCode = "XPPX";
			var carrierObj = Factory.New<USCarrierCombined>();
			carrierObj.UI_Code = scacCode;
			Factory.Save();

			JobDeclaration declaration = Factory.New<JobDeclaration>();
			USCarrierCombined carrier = Factory.LoadTop1<USCarrierCombined>(new ZQuery());
			if (carrier != null)
			{
				declaration.US_UI_NKCarrierSCAC = carrier.UI_Code;
				AssertEquals("Declaration has no carrier code as candidate for update", false, declaration.IsCarrierCodeCandidateForUpdate);
				AssertEquals("Declaration has no carrier code marked for request", false, declaration.CarrierCodeMarkedForRequest);
			}

			declaration.US_UI_NKCarrierSCAC = "!";
			AssertEquals("Declaration has no carrier code as candidate for update", false, declaration.IsCarrierCodeCandidateForUpdate);
			AssertEquals("Declaration has no carrier code marked for request", false, declaration.CarrierCodeMarkedForRequest);

			declaration.US_UI_NKCarrierSCAC = scacCode;
			AssertEquals("Declaration has no carrier code as candidate for update", false, declaration.IsCarrierCodeCandidateForUpdate);
			AssertEquals("Declaration has no carrier code marked for request", false, declaration.CarrierCodeMarkedForRequest);

			declaration.US_UI_NKCarrierSCAC = "XKY2";
			AssertEquals("Declaration has carrier code as candidate for update", true, declaration.IsCarrierCodeCandidateForUpdate);
			AssertEquals("Declaration has carrier code marked for request", true, declaration.CarrierCodeMarkedForRequest);

			declaration.US_UI_NKCarrierSCAC = "";
			AssertEquals("Declaration has blank carrier code - this should not generate a query request", false, declaration.IsCarrierCodeCandidateForUpdate);
			AssertEquals("Declaration has no carrier code marked for request", false, declaration.CarrierCodeMarkedForRequest);
		}

		[TestDateIncremental(0, 0, 0, 1)]
		public void TestENSStatusDate()
		{
			Declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			Declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;

			CusEntryHeader borderCargoReleaseEntry = Declaration.ActiveEntryHeaders.AddNew();
			borderCargoReleaseEntry.CH_MessageType = CusEntryHeaderMessageTypeList.Codes.BorderCargoRelease;

			borderCargoReleaseEntry.Messages.Add(CreateMessage(EDIMessage.Direction.Transmit, ApplicationIdentifierCodeList.Codes.BorderCargoRelease));
			Factory.Save();

			borderCargoReleaseEntry.Messages.Add(CreateMessage(EDIMessage.Direction.Receive, ApplicationIdentifierCodeList.Codes.BorderCargoReleaseResponse));
			Factory.Save();

			borderCargoReleaseEntry.Messages.Add(CreateMessage(EDIMessage.Direction.Transmit, ApplicationIdentifierCodeList.Codes.BillofLadingUpdate));
			Factory.Save();

			borderCargoReleaseEntry.Messages.Add(CreateMessage(EDIMessage.Direction.Receive, ApplicationIdentifierCodeList.Codes.BillofLadingUpdateResponse));
			Factory.Save();

			CusEntryHeader formalEntry = Declaration.ActiveEntryHeaders.AddNew();
			formalEntry.CH_MessageType = CusEntryHeaderMessageTypeList.Codes.EntrySummary;

			formalEntry.Messages.Add(CreateMessage(EDIMessage.Direction.Transmit, ApplicationIdentifierCodeList.Codes.EntrySummary));
			Factory.Save();

			MQEDIMessage message = CreateMessage(EDIMessage.Direction.Receive, ApplicationIdentifierCodeList.Codes.EntrySummaryResponse);
			formalEntry.Messages.Add(message);
			Factory.Save();

			ZDateTime expectedDateTime = message.EM_SystemCreateTimeUtc;

			formalEntry.Messages.Add(CreateMessage(EDIMessage.Direction.Transmit, ApplicationIdentifierCodeList.Codes.QueryEntrySummary));
			Factory.Save();

			formalEntry.Messages.Add(CreateMessage(EDIMessage.Direction.Receive, ApplicationIdentifierCodeList.Codes.QueryEntrySummaryResponse));
			Factory.Save();

			AssertEquals(expectedDateTime, Declaration.ENSStatusDate);
		}

