		public void TestBLUL7Records()
		{
			Declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			Declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;

			CusEntryHeader borderCargoReleaseEntry = Declaration.ActiveEntryHeaders.AddNew();
			borderCargoReleaseEntry.CH_MessageType = CusEntryHeaderMessageTypeList.Codes.BorderCargoRelease;

			borderCargoReleaseEntry.Messages.Add(CreateMessage(EDIMessage.Direction.Transmit, ApplicationIdentifierCodeList.Codes.BorderCargoRelease));
			Factory.Save();

			borderCargoReleaseEntry.Messages.Add(CreateMessage(EDIMessage.Direction.Receive, ApplicationIdentifierCodeList.Codes.BorderCargoReleaseResponse));
			Factory.Save();

			borderCargoReleaseEntry.Messages.Add(CreateMessage(EDIMessage.Direction.Transmit, ApplicationIdentifierCodeList.Codes.BillofLadingUpdate));
			Factory.Save();

			MQEDIMessage message = CreateMessage(EDIMessage.Direction.Receive, ApplicationIdentifierCodeList.Codes.BillofLadingUpdateResponse);
			borderCargoReleaseEntry.Messages.Add(message);
			message.EM_MessageText =
"B011102113LS                                                            27444284" +
"L71102113 458843968VZBILL DATA UPDATED AS REQUESTED                             " +
"L71102113 458843968VXBILL RESULTS REQUEST ACCEPTED                              " +
"Y  1102113LS00002";
			Factory.Save();
			var createTime = message.EM_SystemCreateTimeUtc;

			message = CreateMessage(EDIMessage.Direction.Receive, ApplicationIdentifierCodeList.Codes.BillofLadingUpdateResponse);
			if (createTime != ZDateTime.Empty)
			{
				message.EM_SystemCreateTimeUtc = createTime.AddSeconds(10);
			}
			borderCargoReleaseEntry.Messages.Add(message);
			message.EM_MessageText =
"B014601113LS                                                            27444287" +
"L14601113 45733155Y            EGLV     110308                                  " +
"L74601113 457331558WOACTUAL DATE OF ARRIVAL ON FILE                             " +
"L74601113 457331558WQARRIVAL DT 6 DAYS > SELECTVITY DT                          " +
"L74601113 45733155524TRANSACTION DATA REJECTED                                  " +
"Y  4601113LS00004";
			Factory.Save();

			CusEntryHeader formalEntry = Declaration.ActiveEntryHeaders.AddNew();
			formalEntry.CH_MessageType = CusEntryHeaderMessageTypeList.Codes.EntrySummary;

			formalEntry.Messages.Add(CreateMessage(EDIMessage.Direction.Transmit, ApplicationIdentifierCodeList.Codes.EntrySummary));
			Factory.Save();

			formalEntry.Messages.Add(CreateMessage(EDIMessage.Direction.Receive, ApplicationIdentifierCodeList.Codes.EntrySummaryResponse));
			Factory.Save();

			CombineAssertions(() =>
			{
				AssertEquals(3, Declaration.BLUL7Records.Count);
				AssertEquals("8WO", Declaration.BLUL7Records[0].ErrorMessageIdentifier);
				AssertEquals("ACTUAL DATE OF ARRIVAL ON FILE", Declaration.BLUL7Records[0].NarrativeMessage);
			});
		}

