			message.EM_MessageText =
"B018888XJ5WT                                               28934                " +
"101045439041                                                                    " +
"200810171938001001                                                              " +
"9502271 DATA ADDED AS REQUESTED                                                 " +
"Y  8888XJ5WT00003";

			Factory.Save();
			AssertEquals("IT Errors Exist - false", "", Declaration.ITErrorsExist);
			AssertEquals("TOL Records", 1, Declaration.ITWT95TOLRecords.Count);
			AssertEquals("TOL Narrative", "DATA ADDED AS REQUESTED", Declaration.ITWT95TOLRecords[0].NarrativeMessage);
		}

		public void TestITErrorsExist2_TOL()
		{
			declaration = null;
