			invoice1.JZ_OA_SupplierAddress = address1.PK;
			var invoice2 = declaration.Invoices.AddNew();
			invoice2.JZ_OA_SupplierAddress = address2.PK;
			declaration.JE_OH_Supplier = supplier.PK;
			AssertEquals(address1.PK, invoice1.JZ_OA_SupplierAddress);
			AssertEquals(address1.PK, ((IBusinessObjectInternals)invoice1).Row[JobComInvoiceHeader.Schema.JZ_OA_SupplierAddress]);
			AssertEquals(address2.PK, invoice2.JZ_OA_SupplierAddress);
			AssertEquals(System.DBNull.Value, ((IBusinessObjectInternals)invoice2).Row[JobComInvoiceHeader.Schema.JZ_OA_SupplierAddress]);

			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.JE_OH_Supplier = ZGuid.Empty;
			invoice1.JZ_OA_SupplierAddress = address1.PK;
			invoice2.JZ_OA_SupplierAddress = address2.PK;
			declaration.JE_OH_Supplier = supplier.PK;
			AssertEquals(address1.PK, invoice1.JZ_OA_SupplierAddress);
			AssertEquals(System.DBNull.Value, ((IBusinessObjectInternals)invoice1).Row[JobComInvoiceHeader.Schema.JZ_OA_SupplierAddress]);
			AssertEquals(address2.PK, invoice2.JZ_OA_SupplierAddress);
			AssertEquals(address2.PK, ((IBusinessObjectInternals)invoice2).Row[JobComInvoiceHeader.Schema.JZ_OA_SupplierAddress]);

			declaration.JE_MessageType = JobMessageTypeList.Codes.Export;
			declaration.JE_OH_Supplier = ZGuid.Empty;
			declaration.SupplierPickupAddress.E2_OA_Address = address3.PK;
			invoice1.JZ_OA_SupplierAddress = address1.PK;
			invoice2.JZ_OA_SupplierAddress = address2.PK;
			declaration.JE_OH_Supplier = supplier.PK;
			AssertEquals(address1.PK, invoice1.JZ_OA_SupplierAddress);
			AssertEquals(System.DBNull.Value, ((IBusinessObjectInternals)invoice1).Row[JobComInvoiceHeader.Schema.JZ_OA_SupplierAddress]);
			AssertEquals(address2.PK, invoice2.JZ_OA_SupplierAddress);
			AssertEquals(address2.PK, ((IBusinessObjectInternals)invoice2).Row[JobComInvoiceHeader.Schema.JZ_OA_SupplierAddress]);
		}

