		public void TestCSHEventIsLoggedWhenReleaseStatusChangesAndDeclarationIsTransferedFromHVLV()
		{
			var declaration = Factory.New<JobDeclaration>();
			declaration.ReleaseStatus = CRLReleaseStatusList.Codes.EXM;
			Assert("No CHS event when declaration is not transfered from HVLV", !declaration.Logs.HasLogWith(l => l.SL_SE_NKEvent == AutoEvents.ClearanceStatusChangedCode));

			declaration.Logs.AddNew(AutoEvents.Transferred);
			declaration.ReleaseStatus = CRLReleaseStatusList.Codes.NRL;
			Assert("No CHS event when only simple TRF log exists", !declaration.Logs.HasLogWith(l => l.SL_SE_NKEvent == AutoEvents.ClearanceStatusChangedCode));

			var eventParameters = new[]
			{
				new KeyValuePair<string, string>(CargoWise.EventReference.Constants.EventReferenceParameters.Codes.Type, "HVL")
			};
			declaration.Logs.AddNew(AutoEvents.Transferred, eventParameters.ToArray());
			declaration.ReleaseStatus = CRLReleaseStatusList.Codes.EXM;
			Assert("CHS event should be logged", declaration.Logs.HasLogWith(l =>
				l.SL_SE_NKEvent == AutoEvents.ClearanceStatusChangedCode
				&& l.Parameters.TryGetValue(CargoWise.EventReference.Constants.EventReferenceParameters.Codes.SourceModuleId, out var sourceModule)
				&& sourceModule == "HVL"));
		}

