		public void TestJE_EntryAuthorisationDateReadOnly()
		{
			var declaration = Factory.New<JobDeclaration>();
			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			declaration.US_EnableENS = true;
			declaration.US_EnableCRL = true;
			declaration.JE_MessageType = JobMessageTypeList.Codes.Export;
			AssertEquals(true, declaration.JE_EntryAuthorisationDateInfo.ReadOnly);

			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			AssertEquals("Not Readonly, because CRL not certified yet and have no disposition code 22", false, declaration.JE_EntryAuthorisationDateInfo.ReadOnly);

			declaration.JE_MessageType = JobMessageTypeList.Codes.ImportByExternalBroker;
			AssertEquals("Not Readonly, because CRL not certified yet and have no disposition code 22", false, declaration.JE_EntryAuthorisationDateInfo.ReadOnly);

			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_ManEntry = true;
			AssertEquals("Not readonly for manual entry", false, declaration.JE_EntryAuthorisationDateInfo.ReadOnly);

			declaration.JE_MessageType = JobMessageTypeList.Codes.ImportByExternalBroker;
			AssertEquals("Not readonly for manual entry", false, declaration.JE_EntryAuthorisationDateInfo.ReadOnly);

			declaration.US_ManEntry = false;
			var ensEntry = declaration.CustomsEntryHeaders.AddNew();
			ensEntry.CH_MessageType = CusEntryHeaderMessageTypeList.Codes.EntrySummary;

			var crlEntry = declaration.CustomsEntryHeaders.AddNew();
			crlEntry.CH_MessageType = CusEntryHeaderMessageTypeList.Codes.CargoRelease;
			crlEntry.CH_CH_PrimeEntry = ensEntry.PK;

			ensEntry.US_CRLCertStatus = CargoReleaseCertificationStatusList.Codes.Certified;
			AssertEquals("HasCargoReleaseBeenCertified", true, declaration.HasCargoReleaseBeenCertified);
			AssertEquals("Readonly because CRL certified", true, declaration.JE_EntryAuthorisationDateInfo.ReadOnly);

			ensEntry.US_CRLCertStatus = ZString.Empty;
			AssertEquals("HasCargoReleaseBeenCertified", false, declaration.HasCargoReleaseBeenCertified);
			AssertEquals(false, declaration.JE_EntryAuthorisationDateInfo.ReadOnly);

			declaration.DispositionCodes.AddNewIfNotExist(CargoReleaseProcessingResultList.Codes.PaperlessEntry, ZDateTime.Today);
			AssertEquals("Not Readonly, because CRL not certified and has no disposition code 22", false, declaration.JE_EntryAuthorisationDateInfo.ReadOnly);

			declaration.DispositionCodes.AddNewIfNotExist(CargoReleaseProcessingResultList.Codes.ReleaseDateUpdate, ZDateTime.Today);
			AssertEquals("Has 22 Disposition Code", true, declaration.JE_EntryAuthorisationDateInfo.ReadOnly);

			declaration.DispositionCodes.DeleteAll();
			AssertEquals(false, declaration.JE_EntryAuthorisationDateInfo.ReadOnly);
			declaration.DispositionCodes.AddNewIfNotExist(CargoReleaseProcessingResultList.Codes.Released, ZDateTime.Today);
			AssertEquals("Has 98 (Released) Disposition Code", true, declaration.JE_EntryAuthorisationDateInfo.ReadOnly);
		}

		public void TestJE_EntryAuthorisationDateSetUpCorrectReleaseStatus()
		{
			JobDeclaration declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_CertifyCargoRelease = true;
			AssertEquals("Precondition: Release Status should be set to Not Released", CRLReleaseStatusList.Codes.NRL, declaration.ReleaseStatus);

			declaration.JE_EntryAuthorisationDate = ZDateTime.Today;
			AssertEquals("Release Status should be set to Released, because Release Date manually set", CRLReleaseStatusList.Codes.REL, declaration.ReleaseStatus);

			declaration.JE_EntryAuthorisationDate = ZDateTime.Empty;
			AssertEquals("Release Status should be set to Not Released, because US_CertifyCargoRelease flag set", CRLReleaseStatusList.Codes.NRL, declaration.ReleaseStatus);

			declaration.US_CertifyCargoRelease = false;
			declaration.JE_EntryAuthorisationDate = ZDateTime.Today.AddDays(-1);
			AssertEquals("Release Status should be set to Released, because Release Date manually set", CRLReleaseStatusList.Codes.REL, declaration.ReleaseStatus);

			declaration.JE_EntryAuthorisationDate = ZDateTime.Empty;
			AssertEquals("Release Status should be set to empty, because US_CertifyCargoRelease flag not set", ZString.Empty, declaration.ReleaseStatus);
		}

