		[TestDate(2008, 07, 05)]
		public void TestStatementUpdate_SentForFormalEntry()
		{
			SetupStatementData();

			JobDeclaration declaration = Factory.NewWithValidTestData<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EntryFilerCode = "XJ5";
			declaration.US_PaymentType = PaymentTypeList.Codes.BatchedByPeriodicPrintDateAndImporter;
			declaration.US_PreliminaryStatementPrintDate = new ZDateTime(2008, 07, 10);

			CusEntryHeader entry = declaration.ActiveEntryHeaders.AddNew();
			declaration.US_EntryType = "01";
			entry.EntryNumber = "12345";
			entry.CH_MessageType = CusEntryHeaderMessageTypeList.Codes.EntrySummary;
			entry.CH_Status = ImportMessageStatusList.Codes.ClearEntrySummaryOriginal;
			Factory.Save();

			AssertEquals("Pre-condition: Expected messsages count", 0, Factory.GetDatabaseCount(typeof(EDIMessage)));

			CusEntryHeader entryBCR = declaration.ActiveEntryHeaders.AddNew();
			entryBCR.CH_JE = declaration.PK;
			declaration.US_EntryType = "01";
			entryBCR.EntryNumber = "12345";
			entryBCR.CH_MessageType = CusEntryHeaderMessageTypeList.Codes.BorderCargoRelease;
			entryBCR.CH_CH_PrimeEntry = entry.PK;
			entryBCR.CH_Status = ImportMessageStatusList.Codes.ClearBorderCargoReleaseOriginal;
