			declaration.JE_EntryAuthorisationDate = ZDateTime.Empty;
			AssertEquals("No new messages exists", 1, Factory.GetDatabaseCount(typeof(EDIMessage)));
		}

		public void TestICBPEDIMessageMessageTextNumberPlaceHolderFillerMembers()
		{
			DeclarationTestHelper.SetupBranchSpecificFormalEntryNumber("XJ5");
			DeclarationTestHelper.SetupBranchSpecificInBondNumberRanges();
			DbConnection connection = ((IDbConnected)Factory).Connection;
			try
			{
				connection.BeginTransaction();
				JobDeclaration declaration = Factory.New<JobDeclaration>();
				declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
				declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
				declaration.US_EntryFilerCode = "XJ5";
				CusEntryHeader entry = declaration.CustomsEntryHeaders.AddNew();
				entry.CH_MessageType = "ZZZ";
				entry.EntryNumber = "43123121";
				MQEDIMessage message = Factory.New<MQEDIMessage>();
				string messageData = "USENTRYFILERENTRYNUMBERPLACEHOLDER:{1}{0}USENTRYNUMBERPLACEHOLDER:{2}END";
				string defaultMessageText = string.Format(messageData, System.Environment.NewLine, MQEDIMessage.USEntryFilerEntryNumberPlaceHolder, MQEDIMessage.USEntryNumberPlaceHolder);
				message.EM_MessageText = defaultMessageText;
				ICBPEDIMessageMessageTextNumberPlaceHolderFiller filler = declaration;
				AssertEquals("43123121", declaration.DeclarationNumber);
				AssertEquals("", declaration.ImportEntryNumber);
				filler.Fill(message);
				AssertEquals("43123121", declaration.DeclarationNumber);
				AssertEquals("", declaration.ImportEntryNumber);
				AssertEquals(defaultMessageText, message.EM_MessageText);

				declaration.JE_MessageType = JobMessageTypeList.Codes.Drawback;
				declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
				filler.Fill(message);
				AssertEquals("43123121", declaration.DeclarationNumber);
				AssertEquals("", declaration.ImportEntryNumber);
				AssertEquals(string.Format(messageData, System.Environment.NewLine, "XJ5" + declaration.DeclarationNumber, MQEDIMessage.USEntryNumberPlaceHolder), message.EM_MessageText);

				declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACE;
				declaration.ImportEntryNumber = ZString.Empty;
				message.EM_MessageText = defaultMessageText;
				filler.Fill(message);
				AssertEquals("43123121", declaration.DeclarationNumber);
				AssertEquals("", declaration.ImportEntryNumber);
				AssertEquals(string.Format(messageData, System.Environment.NewLine, MQEDIMessage.USEntryFilerEntryNumberPlaceHolder, declaration.DeclarationNumber), message.EM_MessageText);

				declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
				declaration.CustomsEntryHeaders.Remove(entry);
				message.EM_MessageText = defaultMessageText;
				filler.Fill(message);
				AssertNotEquals("43123121", declaration.DeclarationNumber);
				AssertNotEquals("", declaration.DeclarationNumber);
				AssertEquals(declaration.DeclarationNumber, declaration.ImportEntryNumber);
				AssertEquals(string.Format(messageData, System.Environment.NewLine, "XJ5" + declaration.DeclarationNumber, MQEDIMessage.USEntryNumberPlaceHolder), message.EM_MessageText);
				ZString previousDeclarationNumber = declaration.DeclarationNumber;

				declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
				declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
				message.EM_MessageSubType = EM_MessageSubTypeList.Codes.FDAPriorNotice;
				message.EM_MessageType = ACEApplicationIdentifierCodeList.Codes.InbondUpdateTransferofLiability;
				declaration.ImportEntryNumber = ZString.Empty;
				message.EM_MessageText = defaultMessageText;
				filler.Fill(message);
				AssertNotEquals("", declaration.DeclarationNumber);
				AssertNotEquals(previousDeclarationNumber, declaration.DeclarationNumber);
				AssertEquals(declaration.DeclarationNumber, declaration.ImportEntryNumber);
				AssertEquals(string.Format(messageData, System.Environment.NewLine, MQEDIMessage.USEntryFilerEntryNumberPlaceHolder, declaration.ImportEntryNumber), message.EM_MessageText);
			}
			finally
			{
				connection.RollbackTransaction();
			}

			if (ErrorReporter.LastMessageReported.Contains("was used to fill placeholder in a message and now is changed to "))
			{
				ErrorReporter.Clear();
			}
		}

		void ICBPEDIMessageMessageTextNumberPlaceHolderFTZControlNumber_Runner(Action<JobDeclaration, OrgHeader> setOrganisation, string snType, string expectedGeneratedControlNumber)
		{
			DbConnection connection = ((IDbConnected)Factory).Connection;
			try
			{
				connection.BeginTransaction();
				JobDeclaration declaration = Factory.New<JobDeclaration>();

				MQEDIMessage message = Factory.New<MQEDIMessage>();
				string messageData = "FTZCONTROLNUMBERPLACEHOLDER:{0}END";
				string defaultMessageText = string.Format(messageData, MQEDIMessage.USFTZControlNumberPlaceHolder);
				message.EM_MessageText = defaultMessageText;
				ICBPEDIMessageMessageTextNumberPlaceHolderFiller filler = declaration;

				AssertEquals("", declaration.FTZControlNumber);
				filler.Fill(message);
				AssertEquals("", declaration.FTZControlNumber);
				AssertEquals(defaultMessageText, message.EM_MessageText);

				var organisation = Factory.NewWithValidTestData<OrgHeader>();
				var fTZStmNum = Factory.New<OrganisationViewStmNums>();
				fTZStmNum.SN_Type = snType;
				fTZStmNum.SN_ZoneIDPrefix = "1234567";
				fTZStmNum.SN_ClientPrefix = "AAA";
				fTZStmNum.SN_Owner = organisation.PK;
				Factory.Save();

				setOrganisation(declaration, organisation);
				declaration.JE_MessageType = JobMessageTypeList.Codes.FTZ;
				message.EM_MessageType = ACEApplicationIdentifierCodeList.Codes.FTZAdmissionData;
				declaration.FTZZoneID = "1234567";
				AssertEquals(true, declaration.FTZControlNumberIsAutoAllocated);
				message.EM_MessageText = defaultMessageText;
				filler.Fill(message);
				AssertEquals(expectedGeneratedControlNumber, declaration.FTZControlNumber);
				AssertEquals(string.Format(messageData, expectedGeneratedControlNumber), message.EM_MessageText);
			}
			finally
			{
				connection.RollbackTransaction();
			}

			if (ErrorReporter.LastMessageReported.Contains("was used to fill placeholder in a message and now is changed to "))
			{
				ErrorReporter.Clear();
			}
		}

