		public void TestGenAddOnStatusAreRemovedIfEmpty()
		{
			JobDeclaration declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFreeDutiable;
			declaration.US_EnableCRL = true;
			AssertEquals("FDA Msg Status", ZString.Empty, declaration.FDAMsgStatus);

			ZQuery addOnStatusQuery = new ZQuery(GenAddOnColumnSchema.XA_ParentID, declaration.PK);
			addOnStatusQuery.AddToFilter(GenAddOnColumnSchema.XA_ParentTableCode, JobDeclarationSchema.Constants.Prefix);
			addOnStatusQuery.AddToFilter(GenAddOnColumnSchema.XA_Name, JobDeclaration.Constants.GenAddOnColumnFieldName.FDAMsgStatus);
			GenAddOnColumn addOnStatus = Factory.LoadTop1<GenAddOnColumn>(addOnStatusQuery);
			AssertNull("GenAddOnStatus should not exist if status is blank", addOnStatus);

			CusEntryHeader entry = declaration.CustomsEntryHeaders.AddNew();
			entry.CH_MessageType = CusEntryHeaderMessageTypeList.Codes.CargoRelease;
			Factory.Save();
			AssertEquals("FDA Msg Status not yet set", ZString.Empty, declaration.FDAMsgStatus);
			addOnStatus = Factory.LoadTop1<GenAddOnColumn>(addOnStatusQuery);
			AssertNull("GenAddOnStatus should not exist if status is blank", addOnStatus);

			JobComInvoiceHeader invoice = declaration.Invoices.AddNew();
			JobComInvoiceLine invoiceLine = invoice.JobComInvoiceLines.AddNew();
			invoiceLine.JI_Tariff = USCTariff.FDAAdmissibilityReviewRequiredTariff;
			Factory.Save();
			AssertEquals("FDA Msg Status should be set to FDA Required", FDAStatusList.Codes.REQ, declaration.FDAMsgStatus);
			addOnStatus = Factory.LoadTop1<GenAddOnColumn>(addOnStatusQuery);
			AssertNotNull("GenAddOnStatus should now exist as status is not blank", addOnStatus);

			invoiceLine.JI_Tariff = USCTariff.FDAAdmissibilityReviewDONOTSUBMITTariff;
			Factory.Save();
			AssertEquals("Tariff with FDA removed, status no longer required - should be set back to not required", FDAStatusList.Codes.NR, declaration.FDAMsgStatus);
			addOnStatus = Factory.LoadTop1<GenAddOnColumn>(addOnStatusQuery);
			AssertNotNull("GenAddOnStatus should now exist as status is not blank", addOnStatus);

			declaration.FDAMsgStatus = ZString.Empty;
			Factory.Save();
			AssertEquals("FDA Msg Status", ZString.Empty, declaration.FDAMsgStatus);
			addOnStatus = Factory.LoadTop1<GenAddOnColumn>(addOnStatusQuery);
			AssertNull("GenAddOnStatus should have been deleted as status is now blank again", addOnStatus);
		}

