			var org2Rel = part.RelatedOrganisations.AddOrganisationIfNotExist(org2.PK, OrgPartRelation.RelationshipTypes.Owner);
			var pivot1 = part.PivotsForBinding.AddNew();
			pivot1.CI_ChildType = ClassificationTypeList.Codes.HTI;
			pivot1.CI_OH = org1Rel.OU_OH;
			pivot1.CI_CC = classification.PK;
			var pivot2 = part.PivotsForBinding.AddNew();
			pivot2.CI_ChildType = ClassificationTypeList.Codes.HTI;
			pivot2.CI_OH = org2Rel.OU_OH;
			pivot2.CI_CC = classification.PK;

			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_OH_Importer = org1.PK;
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EnableENS = true;
			declaration.US_EntryType = EntryTypeList.Codes.Warehouse;
			AssertEquals(true, declaration.IsWHSUniversalXMLActive);
			AssertEquals(true, declaration.IsInwardBondedWarehousingEnabled);
			declaration.JE_MessageType = JobMessageTypeList.Codes.Export;
			declaration.US_EnableENS = true;
			AssertEquals(false, declaration.IsInwardBondedWarehousingEnabled);
			declaration.JE_MessageType = JobMessageTypeList.Codes.ImportByExternalBroker;
			declaration.US_EnableENS = true;
			AssertEquals(true, declaration.IsInwardBondedWarehousingEnabled);
			declaration.US_EnableENS = false;
			AssertEquals(false, declaration.IsInwardBondedWarehousingEnabled);
			declaration.US_EnableENS = true;
			AssertEquals(true, declaration.IsInwardBondedWarehousingEnabled);
			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionADDCVD;
			AssertEquals(false, declaration.IsInwardBondedWarehousingEnabled);

			foreach (var entryType in new[]
				{
					EntryTypeList.Codes.WarehouseFTZ,
					EntryTypeList.Codes.Warehouse,
					EntryTypeList.Codes.ReWarehouse
				})
			{
				declaration.US_EntryType = entryType;
				declaration.US_EnableENS = true;
				AssertEquals(true, declaration.IsInwardBondedWarehousingEnabled);
			}
			declaration.JE_OH_Importer = org2.PK;
			AssertEquals(false, declaration.IsInwardBondedWarehousingEnabled);
			declaration.JE_OH_Importer = org1.PK;
			AssertEquals(true, declaration.IsInwardBondedWarehousingEnabled);

			declaration = Factory.New<JobDeclaration>();
			declaration.JE_SystemCreateTimeUtc = ZDateTime.Now.AddYears(-1);
			declaration.JE_OH_Importer = org1.PK;
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EnableENS = true;
			declaration.US_EntryType = EntryTypeList.Codes.Warehouse;
			AssertEquals(true, declaration.IsWHSUniversalXMLActive);
			AssertEquals(true, declaration.IsInwardBondedWarehousingEnabled);
		}

