		void AssertMessageErrorOfRequiredFieldsForBondedWarehousing(JobDeclaration declaration, string term, ZString errorMessage, ZString importerCode, bool hasBondedWarehouseAddress, bool hasImporterDocumentAddress, bool hasProduct, bool hasInvoiceQty, bool hasEntryNumber, bool hasWHSPacks, bool hasEntryLineNo, bool hasFTZAdmissionNumber = false, bool hasEntryNumberAndEntryLineNoFromInvoiceLine = false)
		{
			if (hasBondedWarehouseAddress)
			{
				AssertContains(JobDeclaration.BondedWarehouseIsRequiredForBondedWarehousing(term, importerCode), errorMessage);
			}
			else
			{
				AssertNotContains(JobDeclaration.BondedWarehouseIsRequiredForBondedWarehousing(term, importerCode), errorMessage);
			}
			if (hasImporterDocumentAddress)
			{
				AssertContains(declaration.ImporterDocumentaryAddressIsRequiredForBondedWarehousing, errorMessage);
			}
			else
			{
				AssertNotContains(declaration.ImporterDocumentaryAddressIsRequiredForBondedWarehousing, errorMessage);
			}
			if (hasProduct)
			{
				AssertContains(JobDeclaration.InvoiceLineMarkedForBondedWarehousingRequiresAProduct(term), errorMessage);
			}
			else
			{
				AssertNotContains(JobDeclaration.InvoiceLineMarkedForBondedWarehousingRequiresAProduct(term), errorMessage);
			}
			if (hasInvoiceQty)
			{
				AssertContains(JobDeclaration.InvoiceLineMarkedForBondedWarehousingRequiresAnInvoiceQuantityAndUnit(term), errorMessage);
			}
			else
			{
				AssertNotContains(JobDeclaration.InvoiceLineMarkedForBondedWarehousingRequiresAnInvoiceQuantityAndUnit(term), errorMessage);
			}
			if (hasEntryNumber)
			{
				AssertContains(JobDeclaration.WarehouseEntryFilerCodeAndNumberAreRequiredForBondedWarehousing(term), errorMessage);
			}
			else
			{
				AssertNotContains(JobDeclaration.WarehouseEntryFilerCodeAndNumberAreRequiredForBondedWarehousing(term), errorMessage);
			}
			if (hasWHSPacks)
			{
				AssertContains(JobDeclaration.InvoiceLineMarkedForBondedWarehousingLineRequiresWHSPackDetails(term), errorMessage);
			}
			else
			{
				AssertNotContains(JobDeclaration.InvoiceLineMarkedForBondedWarehousingLineRequiresWHSPackDetails(term), errorMessage);
			}
			if (hasEntryLineNo)
			{
				AssertContains(JobDeclaration.BondedWarehousingLineRequiresWHSEntryLine(term), errorMessage);
			}
			else
			{
				AssertNotContains(JobDeclaration.BondedWarehousingLineRequiresWHSEntryLine(term), errorMessage);
			}
			if (hasFTZAdmissionNumber)
			{
				AssertContains(JobDeclaration.FTZAdmissionControlNumberComponentIsRequiredForBondedWarehousing(term), errorMessage);
			}
			else
			{
				AssertNotContains(JobDeclaration.FTZAdmissionControlNumberComponentIsRequiredForBondedWarehousing(term), errorMessage);
			}
			if (hasEntryNumberAndEntryLineNoFromInvoiceLine)
			{
				AssertContains(JobDeclaration.BondedWarehousingLineRequiresWHSEntryNumberAndWHSEntryLine(term), errorMessage);
			}
			else
			{
				AssertNotContains(JobDeclaration.BondedWarehousingLineRequiresWHSEntryNumberAndWHSEntryLine(term), errorMessage);
			}
		}

		public void TestHasABondedWarehousingLineWithoutWHSPackDetails()
		{
			var importer = Factory.New<OrgHeader>();
			importer.OH_Code = "O234";
