		public void TestUNDGsAreDefaultedFromProduct()
		{
			var owner = Factory.New<OrgHeader>();
			owner.OH_IsConsignee = true;
			owner.OH_Code = "OWNER";
			var contact1 = owner.Contacts.AddNew();
			contact1.OC_ContactName = "BOB";
			var contact2 = owner.Contacts.AddNew();
			contact2.OC_ContactName = "JOE";

			var part = Factory.New<OrgSupplierPart>();
			part.OP_PartNum = "PARTZ234";
			part.OP_Desc = "Description";
			OrgPartRelation relation = part.RelatedOrganisations.AddOrganisationIfNotExist(owner.PK, OrgPartRelation.RelationshipTypes.Both);
			var undg1 = part.UNDGs.TryGetOrCreate("3208A", UNDGSubstanceLookups.UNDGSubstanceStandardTypes.IMO);
			undg1.DI_DGFlashPoint = 10m;
			undg1.DI_OC_DGContact = contact1.PK;
			undg1.DI_TechnicalName = "TECH METALLIC SUBSTANCE";
			undg1.DI_MPMarinePollutant = YesNoList.Codes.Yes;
			Factory.Save();

			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_OH_Importer = owner.PK;
			declaration.JE_MessageType = JobMessageTypeList.Codes.Export;
			var invoice = declaration.Invoices.AddNew();
			var invoiceLine = invoice.JobComInvoiceLines.AddNew();
			AssertEquals(0, invoiceLine.UNDGs.Count);
			invoiceLine.JI_PartNo = "PARTZ234";
			AssertEquals(0, invoiceLine.UNDGs.Count);

			invoiceLine.JI_PartNo = "";
			AssertEquals(0, invoiceLine.UNDGs.Count);

			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			invoiceLine.JI_PartNo = "PARTZ234";
			AssertNoWarning(invoiceLine.JI_PartNoInfo, JobComInvoiceLineValidation.WarningPartHasMultipleUNDGRecords);
			AssertEquals(1, invoiceLine.UNDGs.Count);
			var undg = invoiceLine.UNDGs[0];
			AssertEquals("3208a", undg.UNDGSubstance.DG_Code);
			AssertEquals(10m, undg.DI_DGFlashPoint);
			AssertEquals(contact1.PK, undg.DI_OC_DGContact);
			AssertEquals("TECH METALLIC SUBSTANCE", undg.DI_TechnicalName);
			AssertEquals(YesNoList.Codes.Yes, undg.DI_MPMarinePollutant);

			invoiceLine.JI_PartNo = "";
			invoiceLine.UNDGs.DeleteAll();
			var undg2 = part.UNDGs.TryGetOrCreate("2015A", UNDGSubstanceLookups.UNDGSubstanceStandardTypes.IMO);
			undg2.DI_DGFlashPoint = -14m;
			undg2.DI_OC_DGContact = contact2.PK;
			Factory.Save();
			invoiceLine.JI_PartNo = "PARTZ234";
			AssertEquals(0, invoiceLine.UNDGs.Count);
			AssertHasWarning(invoiceLine.JI_PartNoInfo, JobComInvoiceLineValidation.WarningPartHasMultipleUNDGRecords);
		}

		public void TestDateOfArrivalNotUpdatedIfDeclHasDatesUpdatedLog()
		{
			var declaration = Factory.New<JobDeclaration>();
			var routingParent = (ITransportParent)declaration;

			declaration.JE_TransportMode = TransportTypeList.Codes.Sea;
			declaration.JE_VesselName = "BUNGA DELIMA";
			declaration.JE_VoyageFlightNo = "4389";
			declaration.JE_OH_ShippingLine = Factory.NewWithValidTestData<OrgHeader>().PK;
			declaration.JE_RL_NKPortOfLoading = "NZAKL";
			declaration.JE_ExportDate = new ZDateTime(2011, 1, 2);
			declaration.JE_RL_NKPortOfArrival = "USLAX";
			declaration.JE_DateOfArrival = new ZDateTime(2011, 1, 3);
			AssertEquals("Precondition: declaration.Transports.Count", 1, declaration.Transports.Count);

			var transport = declaration.Transports[0];
			AssertEquals("Precondition: transport.JW_ETD", new ZDateTime(2011, 1, 2), transport.JW_ETD);
			AssertEquals("Precondition: transport.JW_ETA", new ZDateTime(2011, 1, 3), transport.JW_ETA);
			transport.JW_IsLinked = true;
			var sailing = transport.Sailing;
			Factory.Save();

			var updateFactory = new BusinessObjectFactory();
			var sailingToUpdate = updateFactory.Load<JobSailing>(sailing.PK);
			sailingToUpdate.Origin.JA_E_DEP = new ZDateTime(2011, 1, 4);
			sailingToUpdate.Destination.JB_E_ARV = new ZDateTime(2011, 1, 5);
			updateFactory.Save();

			var reloadFactory = new BusinessObjectFactory();
			var declarationReloaded = reloadFactory.Load<JobDeclaration>(declaration.PK);
			declarationReloaded.UpdateFromRoutingTabOnLoadIfNoMessagesSentYet();

			var routingParentReloaded = (ITransportParent)declaration;
			AssertEquals("Precondition: declarationReloaded.Transports.Count", 1, declarationReloaded.Transports.Count);
			var transportReloaded = declarationReloaded.Transports[0];
			AssertEquals("Precondition: transportReloaded.JW_ETD", new ZDateTime(2011, 1, 4), transportReloaded.JW_ETD);
			AssertEquals("Precondition: transportReloaded.JW_ETA", new ZDateTime(2011, 1, 5), transportReloaded.JW_ETA);

			AssertEquals("declarationReloaded.JE_ExportDate", new ZDateTime(2011, 1, 4), declarationReloaded.JE_ExportDate);
			AssertEquals("declarationReloaded.JE_DateOfArrival", new ZDateTime(2011, 1, 5), declarationReloaded.JE_DateOfArrival);

			declarationReloaded.Logs.AddNew(Events.ETAUpdateReplacedByARVEvent, JobDeclaration.Constants.UpdatedDatesLog);
			reloadFactory.Save();

			updateFactory = new BusinessObjectFactory();
			var sailingToUpdate2 = updateFactory.Load<JobSailing>(sailing.PK);
			sailingToUpdate2.Origin.JA_E_DEP = new ZDateTime(2011, 1, 6);
			sailingToUpdate2.Destination.JB_E_ARV = new ZDateTime(2011, 1, 7);
			updateFactory.Save();

			reloadFactory = new BusinessObjectFactory();
			var declarationReloaded2 = reloadFactory.Load<JobDeclaration>(declaration.PK);
			declarationReloaded2.UpdateFromRoutingTabOnLoadIfNoMessagesSentYet();

			AssertEquals("Date should not be updated, because Log exists: declarationReloaded2.JE_ExportDate",
				new ZDateTime(2011, 1, 4), declarationReloaded2.JE_ExportDate);

			AssertEquals("Date should not be updated, because Log exists: declarationReloaded2.JE_DateOfArrival",
				new ZDateTime(2011, 1, 5), declarationReloaded2.JE_DateOfArrival);
		}

