			var invoice = dec.Invoices.AddNew();
			var invoiceLine1 = invoice.JobComInvoiceLines.AddNew();
			invoiceLine1.JI_Tariff = "2005999700";
			invoiceLine1.US_SupTariff = "99041711";

			invoiceLine1.FDAs.AddNew();
			invoiceLine1.FDAs[0].US_FDAValue = 1000m;
			invoiceLine1.FDAs[0].US_FDALineNo = 1;

			var invoiceLine2 = invoice.JobComInvoiceLines.AddNew();
			invoiceLine2.JI_Tariff = "2005995040";
			invoiceLine2.US_SupTariff = "99041711";

			invoiceLine2.FDAs.AddNew();
