			dec.ActiveEntryHeaders.EntrySummaryEntry.US_SentLatestFDA = true;
			AssertEquals("Should be Formal Entry", dec.ActiveEntryHeaders.EntrySummaryEntry, dec.GetEntryHeaderForFDA());
		}

