		[TestDate(2011, 01, 01)]
		public void TestISFBillStatusAndDescription()
		{
			var isfJob1 = CreateISFJob("XXXABill1", Common.US.ISF.BillTypeList.Codes.HouseBillOfLading, Common.US.ISF.DispositionCodeList.Codes.S1);
			var isfJob2 = CreateISFJob("XXXABill2", Common.US.ISF.BillTypeList.Codes.OceanBillOfLading, Common.US.ISF.DispositionCodeList.Codes.S2);
			var isfJob3 = CreateISFJob("XXXABill3", Common.US.ISF.BillTypeList.Codes.HouseBillOfLading, Common.US.ISF.DispositionCodeList.Codes.S2);

			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.JE_TransportMode = declaration.TransportModeSeaCodeForTesting;

			Factory.Save();

			AssertEquals("No bill means no status", ZString.Empty, declaration.ISFBillStatus);
			AssertEquals("No bill means no status", ZString.Empty, declaration.ISFBillStatusDescription);

			var masterBill = declaration.Bills.AddNew();
			masterBill.CU_BillType = BillTypeList.Codes.MasterBill;
			masterBill.US_UI_NKBillIssuerSCAC = "XXXA";
			masterBill.CU_BillNum = "Bill2";
			AssertEquals("PreCondition", Common.US.ISF.DispositionCodeList.Codes.S2, masterBill.ISFBillStatus);
			AssertEquals("Should match ISF Bill XXXABill2", Common.US.ISF.DispositionCodeList.Codes.S2, declaration.ISFBillStatus);
			AssertEquals("Should match ISF Bill XXXABill2", Common.US.ISF.DispositionCodeList.Descriptions.S2, declaration.ISFBillStatusDescription);

			var houseBill1 = masterBill.ChildBills.AddNew();
			houseBill1.US_UI_NKBillIssuerSCAC = "XXXA";
			houseBill1.CU_BillNum = "Bill1";
			AssertEquals("PreCondition: it is no longer the lowest bill", ZString.Empty, masterBill.ISFBillStatus);
			AssertEquals("PreCondition", Common.US.ISF.DispositionCodeList.Codes.S1, houseBill1.ISFBillStatus);
			AssertEquals("Should match ISF Bill XXXABill1 based on lowest bill", Common.US.ISF.DispositionCodeList.Codes.S1, declaration.ISFBillStatus);
			AssertEquals("Should match ISF Bill XXXABill1 based on lowest bill", Common.US.ISF.DispositionCodeList.Descriptions.S1, declaration.ISFBillStatusDescription);

			houseBill1.CU_BillNum = "Bill2";
			AssertEquals("PreCondition: it is no longer the lowest bill", ZString.Empty, masterBill.ISFBillStatus);
			AssertEquals("PreCondition", Common.US.ISF.DispositionCodeList.Codes.S2, houseBill1.ISFBillStatus);
			AssertEquals("Should match ISF Bill XXXABill2 based on lowest bill", Common.US.ISF.DispositionCodeList.Codes.S2, declaration.ISFBillStatus);
			AssertEquals("Should match ISF Bill XXXABill2 based on lowest bill", Common.US.ISF.DispositionCodeList.Descriptions.S2, declaration.ISFBillStatusDescription);

			var houseBill2 = masterBill.ChildBills.AddNew();
			houseBill2.US_UI_NKBillIssuerSCAC = "XXXA";
			houseBill2.CU_BillNum = "Bill4";
			AssertEquals("PreCondition: it is no longer the lowest bill", ZString.Empty, masterBill.ISFBillStatus);
			AssertEquals("PreCondition", Common.US.ISF.DispositionCodeList.Codes.S2, houseBill1.ISFBillStatus);
			AssertEquals("PreCondition: No ISF Bill Match", ZString.Empty, houseBill2.ISFBillStatus);
			AssertEquals("Should match ISF Bill XXXABill2 based on lowest bill and also show no status", Common.US.ISF.DispositionCodeList.Codes.S2 + ",No Status", declaration.ISFBillStatus);
			AssertEquals("Should match ISF Bill XXXABill2 based on lowest bill and also show no status", Common.US.ISF.DispositionCodeList.Descriptions.S2 + " Also there is a bill without any status.", declaration.ISFBillStatusDescription);

			houseBill2.CU_BillNum = "Bill3";
			AssertEquals("PreCondition: it is no longer the lowest bill", ZString.Empty, masterBill.ISFBillStatus);
			AssertEquals("PreCondition", Common.US.ISF.DispositionCodeList.Codes.S2, houseBill1.ISFBillStatus);
			AssertEquals("PreCondition", Common.US.ISF.DispositionCodeList.Codes.S2, houseBill2.ISFBillStatus);
			AssertEquals("Should show the status from one of the lowest bill when all lowest bills have the same status", Common.US.ISF.DispositionCodeList.Codes.S2, declaration.ISFBillStatus);
			AssertEquals("Should show the status from one of the lowest bill when all lowest bills have the same status", Common.US.ISF.DispositionCodeList.Descriptions.S2, declaration.ISFBillStatusDescription);

			houseBill2.CU_BillNum = "Bill1";
			AssertEquals("PreCondition: it is no longer the lowest bill", ZString.Empty, masterBill.ISFBillStatus);
			AssertEquals("PreCondition", Common.US.ISF.DispositionCodeList.Codes.S2, houseBill1.ISFBillStatus);
			AssertEquals("PreCondition", Common.US.ISF.DispositionCodeList.Codes.S1, houseBill2.ISFBillStatus);
			AssertEquals("Should show multiple when not all lowest bills have the same status", Common.US.ISF.ISFStatusHelper.Multiple, declaration.ISFBillStatus);
			AssertEquals("Should show multiple when not all lowest bills have the same status", Common.US.ISF.ISFStatusHelper.BillFoundOnMultipleISF, declaration.ISFBillStatusDescription);
		}

