		public void TestAnticipatedLiquidationProperties()
		{
			var declaration = Factory.New<JobDeclaration>();
			declaration.US_EnableENS = true;
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			AssertEquals("US_AnticipatedLiquidationDate", ZDateTime.Empty, declaration.US_AnticipatedLiquidationDate);
			AssertEquals("US_CollectionDate", ZDateTime.Empty, declaration.US_CollectionDate);
			AssertEquals("US_AnticipatedLiquidatedDuty", ZDecimal.Zero, declaration.US_AnticipatedLiquidatedDuty);

			var invoice = declaration.Invoices.AddNew();
			invoice.JobComInvoiceLines.AddNew();
			declaration.DoMerge(new SendsMessagesToCustomsShutterUpperer());
			AssertEquals("US_AnticipatedLiquidationDate", ZDateTime.Empty, declaration.US_AnticipatedLiquidationDate);
			AssertEquals("US_CollectionDate", ZDateTime.Empty, declaration.US_CollectionDate);
			AssertEquals("US_AnticipatedLiquidatedDuty", ZDecimal.Zero, declaration.US_AnticipatedLiquidatedDuty);

			var entry = declaration.ActiveEntryHeaders.EntrySummaryEntry;
			entry.US_ALDate = ZDateTime.Today;
			entry.US_CollectionDate = ZDateTime.Today.AddDays(-2);
			entry.US_ALDuty = 15.2m;

			AssertEquals("US_AnticipatedLiquidationDate", ZDateTime.Today, declaration.US_AnticipatedLiquidationDate);
			AssertEquals("US_CollectionDate", ZDateTime.Today.AddDays(-2), declaration.US_CollectionDate);
			AssertEquals("US_AnticipatedLiquidatedDuty", 15.2m, declaration.US_AnticipatedLiquidatedDuty);
		}

		public void TestAnticipatedLiquidationPropertiesForReconAndDrawback()
		{
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Drawback;
			AssertEquals(ZDecimal.Zero, declaration.US_AnticipatedLiquidatedDuty);
			AssertEquals(ZDateTime.Empty, declaration.US_AnticipatedLiquidationDate);

			declaration.US_ALDate = new ZDateTime(2019, 01, 01);
			declaration.US_ALDuty = 10m;
			AssertEquals(10m, declaration.US_AnticipatedLiquidatedDuty);
			AssertEquals(new ZDateTime(2019, 01, 01), declaration.US_AnticipatedLiquidationDate);

			var provider = (ILiquidationProvider)declaration;
			provider.SetAnticipatedLiquidatedDuty(20m);
			provider.SetAnticipatedLiquidationDate(new ZDateTime(2019, 01, 10));
			AssertEquals(20m, declaration.US_AnticipatedLiquidatedDuty);
			AssertEquals(new ZDateTime(2019, 01, 10), declaration.US_AnticipatedLiquidationDate);

			declaration.JE_MessageType = JobMessageTypeList.Codes.Recon;
			var reconDeclaration = new ReconDeclaration(declaration);
			var entry = reconDeclaration.ReconEntry.GetEntry();
			entry.US_ALDate = new ZDateTime(2019, 07, 10);
			entry.US_ALDuty = 100m;
			AssertEquals(100m, declaration.US_AnticipatedLiquidatedDuty);
			AssertEquals(new ZDateTime(2019, 07, 10), declaration.US_AnticipatedLiquidationDate);
		}

		public void TestIsEstimatedEnteredValueRequired()
		{
			Declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			Declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			Declaration.US_EnableENS = false;
			Declaration.US_EnableCRL = true;
			var invoice = Declaration.Invoices.AddNew();
			var invoiceLine = invoice.InvoiceLines.AddNew();
			Assert(Declaration.IsEstimatedEnteredValueRequired);

			Declaration.US_EnableENS = true;
			Assert(!Declaration.IsEstimatedEnteredValueRequired);

			Declaration.US_EnableENS = false;
			Declaration.US_CargoReleaseType = CargoReleaseTypeList.Codes.BCR;
			Assert(!Declaration.IsEstimatedEnteredValueRequired);

			Declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACE;
			Declaration.US_CargoReleaseType = CargoReleaseTypeList.Codes.SE;
			Assert(Declaration.IsEstimatedEnteredValueRequired);

			invoice.JZ_InvoiceAmount = 156m;
			Assert(!Declaration.IsEstimatedEnteredValueRequired);
		}

