		{
			AssertExceptionThrown<InvalidOperationException>(() => ExecuteModifyingLodgedJobDeclarationScenario(false));
			AssertExceptionThrown<InvalidOperationException>(() => ExecuteModifyingLodgedJobDeclarationScenario(true));
