		void ExecuteModifyingLodgedJobDeclarationScenario(bool isAceMessage)
		{
			var factory = new BusinessObjectFactory();

			var entryNumber = factory.New<CusEntryNumber>();
			entryNumber.CE_EntryType = CusEntryNumberTypes.UnitedStates.EntrySummary;
			entryNumber.CE_RN_NKCountryCode = "US";
			entryNumber.CE_EntryNum = "64002024";

			var jobDeclaration = factory.New<JobDeclaration>();
			jobDeclaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			jobDeclaration.JE_ApplicationCode = isAceMessage ? JobApplicationCodeList.Codes.ACE : JobApplicationCodeList.Codes.ACS;

			entryNumber.Parent = jobDeclaration;

			var formalEntry = jobDeclaration.ActiveEntryHeaders.AddNew();
			formalEntry.CH_MessageType = CusEntryHeaderMessageTypeList.Codes.EntrySummary;

			formalEntry.LogManager.AddAClearLogIfNecessary(
				ImportMessageStatusList.Codes.AwaitingEntrySummaryOriginal,
				ImportMessageStatusList.Codes.ClearEntrySummaryOriginal,
				formalEntry.StatusList);

			factory.Save();

			entryNumber.CE_EntryNum = "27013134";

			factory.Save();
		}

