		public void TestDoNotCreateTasksAndMileStonesIfJobTypeNotMatch()
		{
			var messageTypesToTest = new[] { "IMP", "FTZ", "IMX", "MSC", "EXP" };
			var declaration = Factory.New<JobDeclaration>();
			var workflow = Factory.NewWithValidTestData<ProcessTaskTemplate>();
			workflow.P0_ProcessType = JobInvoicingConsumerTypes.Brokerage.Code;
			var task = workflow.WorkflowItems.Tasks.AddNew();
			task.P9_Description = "IAN TEST TASK";
			var milestone = workflow.WorkflowItems.Milestones.AddNew();
			milestone.P9_Description = "IAN TEST MILESTONE";
			Factory.Save();

			foreach (var subType in messageTypesToTest)
			{
				workflow.P0_SubType2 = subType;
				Factory.Save();

				foreach (var messageType in messageTypesToTest)
				{
					declaration.WorkflowItems.Tasks.RemoveAndDeleteAll();
					declaration.WorkflowItems.Milestones.RemoveAndDeleteAll();

					declaration.JE_MessageType = messageType;
					Factory.Save();

					var matchedTask = declaration.WorkflowItems.Tasks.OfType<ProcessTask>().FirstOrDefault(t => t.P9_Description == "IAN TEST TASK");
					var matchedMilestone = declaration.WorkflowItems.Milestones.OfType<ProcessTask>().FirstOrDefault(t => t.P9_Description == "IAN TEST MILESTONE");

					if (subType == messageType)
					{
						AssertNotNull(matchedTask);
						AssertNotNull(matchedMilestone);
					}
					else
					{
						AssertNull(matchedTask);
						AssertNull(matchedMilestone);
					}
				}
			}
		}

