		public void TestJE_MasterBillIssuerSCAC_ReadOnly()
		{
			var consol = Factory.New<ForwardingConsol>();
			consol.JK_TransportMode = Core.Constants.TransportModes.Sea;
			consol.JK_RL_NKLoadPort = "AUDYD";
			consol.JK_RL_NKDischargePort = "USCHI";
			consol.JK_MasterBillNum = "IANTESTMB";
			var org = Factory.New<OrgHeader>();
			org.OH_Code = "aaa";
			org.OH_FullName = "bbb";
			var cusCode = org.CustomsCodes.AddNew();
			cusCode.OK_CodeType = OrgCusCode.CodeTypes.CarrierCode;
			cusCode.OK_CustomsRegNo = "APLU";
			cusCode.OK_RN_NKCodeCountry = "US";
			consol.MasterBillIssuingPartyDocumentaryAddress.OrganisationPK = org.PK;

			var shipment = consol.Shipments.AddNew();
			shipment.JS_TransportMode = Core.Constants.TransportModes.Sea;
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.JE_TransportMode = Core.Constants.TransportModes.Sea;
			declaration.JE_JS = shipment.PK;

			declaration.ShipmentSynchroniser.Synchronise(new SynchroniseEventArgs(SynchroniseAction.Force));
			AssertEquals("APLU", declaration.JE_MasterBillIssuerSCAC);
			AssertEquals(true, declaration.JE_MasterBillIssuerSCAC_ReadOnly);

			declaration.JE_MasterBillIssuerSCAC = "ABCD";
			Factory.Save();

			var loadedDeclaration = new BusinessObjectFactory().Load<JobDeclaration>(declaration.PK);
			AssertEquals("ABCD", loadedDeclaration.JE_MasterBillIssuerSCAC);

			consol.Numbers.AddNewIfNotExist(CustomsReferenceNumberType.CustomsAdditionalReferenceNumbersCodes.AMS, "AMS00001");
			declaration.ShipmentSynchroniser.Synchronise(new SynchroniseEventArgs(SynchroniseAction.Force));
			AssertEquals("AMS0", declaration.JE_MasterBillIssuerSCAC);
			AssertEquals(true, declaration.JE_MasterBillIssuerSCAC_ReadOnly);

			consol.Numbers.RemoveAndDeleteAll();
			var container = consol.Containers.AddNew();
			container.JC_ContainerNum = "CONT123456";
			container.AdditionalReferenceNumbers.AddNewIfNotExist(CustomsReferenceNumberType.CustomsAdditionalReferenceNumbersCodes.AMS, "CONTAMS1");

			var packLine = shipment.OuterPackLines.AddNew();
			packLine.JL_JC = container.PK;

			declaration.ShipmentSynchroniser.Synchronise(new SynchroniseEventArgs(SynchroniseAction.Force));
			AssertEquals("CONT", declaration.JE_MasterBillIssuerSCAC);
			AssertEquals(true, declaration.JE_MasterBillIssuerSCAC_ReadOnly);
		}

