		public override void TestGetContainerModeForDeclaration()
		{
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			AssertEquals(Core.Constants.ContainerModes.NonContainerised, declaration.GetContainerModeForDeclaration(Core.Constants.TransportModes.Air, ZString.Empty));
			declaration.CusContainers.AddNew();
			AssertEquals(Core.Constants.ContainerModes.Containerised, declaration.GetContainerModeForDeclaration(Core.Constants.TransportModes.Air, ZString.Empty));
			declaration.CusContainers.RemoveAndDeleteAll();
			AssertEquals(Core.Constants.ContainerModes.NonContainerised, declaration.GetContainerModeForDeclaration(Core.Constants.TransportModes.Rail, ZString.Empty));
			declaration.CusContainers.AddNew();
			AssertEquals(Core.Constants.ContainerModes.Containerised, declaration.GetContainerModeForDeclaration(Core.Constants.TransportModes.Rail, ZString.Empty));
			declaration.CusContainers.RemoveAndDeleteAll();
			AssertEquals(Core.Constants.ContainerModes.NonContainerised, declaration.GetContainerModeForDeclaration(Core.Constants.TransportModes.Sea, Core.Constants.ContainerModes.Bulk));
			AssertEquals(Core.Constants.ContainerModes.Containerised, declaration.GetContainerModeForDeclaration(Core.Constants.TransportModes.Sea, Core.Constants.ContainerModes.FCL));
		}

