		public void TestAddInfoPropertySettingSuspended()
		{
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACE;
			declaration.US_EnableENS = true;
			declaration.US_CertifyCargoRelease = true;

			declaration.US_BondType = BondTypeList.Codes.SingleTransactionBond;
			declaration.US_BondAmount = 2000m;
			declaration.US_BondProducerAccNo = "123456";

			AssertEquals(BondTypeList.Codes.SingleTransactionBond, declaration.US_BondType);
			AssertEquals(2000m, declaration.US_BondAmount);
			AssertEquals("123456", declaration.US_BondProducerAccNo);

			using (declaration.SuspendAddInfoPropertySetting())
			{
				declaration.US_BondType = BondTypeList.Codes.ContinuousBond;
				declaration.US_BondAmount = 3000m;
				declaration.US_BondProducerAccNo = "654321";

				AssertEquals(BondTypeList.Codes.SingleTransactionBond, declaration.US_BondType);
