				AssertEquals("123456", declaration.US_BondProducerAccNo);
			}
		}

		public void TestCargoReleaseEntryReleaseStatusChangingSuspended()
		{
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACE;
			declaration.US_EnableENS = true;
			declaration.US_CertifyCargoRelease = true;

			declaration.JE_EntryAuthorisationDate = new ZDateTime(2019, 05, 01);
			AssertEquals(new ZDateTime(2019, 05, 01), declaration.JE_EntryAuthorisationDate);
			AssertEquals(CRLReleaseStatusList.Codes.REL, declaration.ReleaseStatus);

			declaration.JE_EntryAuthorisationDate = ZDateTime.Empty;
			AssertEquals(ZDateTime.Empty, declaration.JE_EntryAuthorisationDate);
			AssertEquals(CRLReleaseStatusList.Codes.NRL, declaration.ReleaseStatus);

			declaration.ReleaseStatus = CRLReleaseStatusList.Codes.RVW;
			AssertEquals(ZDateTime.Empty, declaration.JE_EntryAuthorisationDate);
			AssertEquals(CRLReleaseStatusList.Codes.RVW, declaration.ReleaseStatus);

			using (new JobDeclaration.CargoReleaseEntryReleaseStatusChangingSuspender(declaration))
			{
				declaration.JE_EntryAuthorisationDate = new ZDateTime(2019, 05, 01);
				AssertEquals(new ZDateTime(2019, 05, 01), declaration.JE_EntryAuthorisationDate);
				AssertEquals(CRLReleaseStatusList.Codes.RVW, declaration.ReleaseStatus);

				declaration.JE_EntryAuthorisationDate = ZDateTime.Empty;
				AssertEquals(ZDateTime.Empty, declaration.JE_EntryAuthorisationDate);
				AssertEquals(CRLReleaseStatusList.Codes.RVW, declaration.ReleaseStatus);
			}

			declaration.JE_EntryAuthorisationDate = new ZDateTime(2019, 05, 01);
			AssertEquals(new ZDateTime(2019, 05, 01), declaration.JE_EntryAuthorisationDate);
			AssertEquals(CRLReleaseStatusList.Codes.REL, declaration.ReleaseStatus);

			declaration.JE_EntryAuthorisationDate = ZDateTime.Empty;
			AssertEquals(ZDateTime.Empty, declaration.JE_EntryAuthorisationDate);
			AssertEquals(CRLReleaseStatusList.Codes.NRL, declaration.ReleaseStatus);
		}

		public void TestCannotChangeMessageTypeIfEntryNumberIsLodged()
		{
			var declaration = Factory.NewWithValidTestData<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.US_EnableENS = true;
			var invoiceHeader = declaration.Invoices.AddNew();
			var invoiceLine = invoiceHeader.InvoiceLines.AddNew();
			declaration.DoMerge(new SendsMessagesToCustomsShutterUpperer());
			declaration.ImportEntryNumber = "123456";
			declaration.ActiveEntryHeaders.EntrySummaryEntry.CH_Status = ImportMessageStatusList.Codes.AwaitingEntrySummaryOriginal;
			Factory.Save();

			var messagesRaised = new List<string>();
			declaration.ShowMessageOnGUI += (sender, e) => { messagesRaised.Add(e.Message); };

			declaration.JE_MessageType = JobMessageTypeList.Codes.Export;
			declaration.JE_MessageType = "XXX";

			AssertEquals("You cannot change the message type if the entry number is lodged.", JobMessageTypeList.Codes.Import, declaration.JE_MessageType);
			AssertEquals("Every time you want to change the message type, it should raise an error message.", 2, messagesRaised.Count);
			AssertEquals("You cannot change the shipment type as the entry number ENS 123456 is already lodged at customs.", messagesRaised[0]);
			AssertEquals("You cannot change the shipment type as the entry number ENS 123456 is already lodged at customs.", messagesRaised[1]);

			declaration.ResetToOriginal();
			Factory.Save();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Export;

			AssertEquals("You are now free to set the message type as the entry number is not lodged.", JobMessageTypeList.Codes.Export, declaration.JE_MessageType);
			AssertEquals("It should not raise any error message.", 2, messagesRaised.Count);
		}

