		public void TestBrokerReferenceNumberCore()
		{
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACE;
			Factory.Save();

			declaration.US_EntryFilerCode = "AAA";
			using (USCustomsDataRegistry.Instance.EntryFiler.SetTemporaryValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, new EntryFiler() { EntryFilerCode = "SV9" }))
			{
				declaration.US_PSC = true;
				declaration.US_BRDRefNo = "123456";
				AssertEquals(declaration.BrokerReferenceNumber, declaration.US_BRDRefNo);

				declaration.US_BRDRefNo = ZString.Empty;
				AssertEquals(declaration.BrokerReferenceNumber, declaration.US_BRDRefNo);

				declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
				Factory.Save();
				AssertNotEquals(declaration.BrokerReferenceNumber, declaration.US_BRDRefNo);
				AssertEquals(declaration.BrokerReferenceNumber, declaration.JobNumber);

				declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACE;
				Factory.Save();

				declaration.US_EntryFilerCode = "SV9";
				AssertNotEquals(declaration.BrokerReferenceNumber, declaration.US_BRDRefNo);
				AssertEquals(declaration.BrokerReferenceNumber, declaration.JobNumber);

				declaration.US_EntryFilerCode = "AAA";
				declaration.US_PSC = false;
				AssertNotEquals(declaration.BrokerReferenceNumber, declaration.US_BRDRefNo);
				AssertEquals(declaration.BrokerReferenceNumber, declaration.JobNumber);
			}
		}

