		public void TestDefaultFDADateOnDeclarationLevel()
		{
			var tariff = Factory.New<USCTariff>();
			tariff.UE_Tariff = "1234567890";
			tariff.UE_PGACodes = "FD3";
			tariff.UE_DateFrom = new ZDateTime(2021, 01, 01);
			tariff.UE_DateTo = ZDateTime.Today.AddDays(10);

			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.US_EnableENS = true;
			declaration.US_EntryDate = new ZDateTime(2021, 02, 24);
			AssertEquals(ZDateTime.Empty, declaration.US_FDAADTA);

			var invoice = declaration.Invoices.AddNew();
			var invoiceLine = invoice.JobComInvoiceLines.AddNew();
			((ISupportDataImporting)invoiceLine).IsImportingData = true;
			invoiceLine.JI_Tariff = tariff.UE_Tariff;
			invoiceLine.DefaultFDADateIfRequired();
			AssertEquals(ZDateTime.Empty, declaration.US_FDAADTA);

			((ISupportDataImporting)invoiceLine).IsImportingData = false;
			invoiceLine.DefaultFDADateIfRequired();
			AssertEquals(new ZDateTime(2021, 02, 24), declaration.US_FDAADTA);
		}

