		public void TestUS_SplitShipmentDetail_DeclarationFieldHasChanges()
		{
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.FTZ;
			declaration.US_F_AdmissionType = FTZAdmissionTypeCodeList.Codes.RegularAdmission;
			declaration.JE_TransportMode = TransportTypeList.Codes.Air;
			var houseBill1 = declaration.Bills.AddNew();
			houseBill1.CU_BillType = "HB";
			houseBill1.CU_BillNum = "HB1";
			houseBill1.US_SESplitShip = true;
			var billSplitDetail1 = houseBill1.ITAndSplitDetails.AddNew();
			billSplitDetail1.US_ArrivalDate = new ZDateTime(2021, 04, 28);
			billSplitDetail1.US_CarrierCode = "A2";
			billSplitDetail1.US_FlightNumber = "04A";
			var houseBill2 = declaration.Bills.AddNew();
			houseBill2.CU_BillType = "HB";
			houseBill2.CU_BillNum = "HB2";
			houseBill2.US_SESplitShip = true;
			var billSplitDetail2 = houseBill2.ITAndSplitDetails.AddNew();
			billSplitDetail2.US_ArrivalDate = new ZDateTime(2021, 04, 29);
			billSplitDetail2.US_CarrierCode = "A3";
			billSplitDetail2.US_FlightNumber = "05B";
			var invoice1 = declaration.Invoices.AddNew();
			invoice1.JZ_CU_RelatedHouseBill = houseBill1.PK;
			invoice1.US_SplitShipmentDetail = invoice1.AddInfoLookups.SplitShipmentDetailsList[0].Code;
			AssertNotEquals(ZString.Empty, invoice1.US_SplitShipmentDetail);
			var invoice2 = declaration.Invoices.AddNew();
			invoice2.JZ_CU_RelatedHouseBill = houseBill2.PK;
			invoice2.US_SplitShipmentDetail = invoice2.AddInfoLookups.SplitShipmentDetailsList[0].Code;
			AssertNotEquals(ZString.Empty, invoice1.US_SplitShipmentDetail);

			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			AssertEquals(ZString.Empty, invoice1.US_SplitShipmentDetail);
			AssertEquals(ZString.Empty, invoice2.US_SplitShipmentDetail);

			declaration.JE_MessageType = JobMessageTypeList.Codes.FTZ;
			declaration.US_F_AdmissionType = FTZAdmissionTypeCodeList.Codes.RegularAdmission;
			invoice1.JZ_CU_RelatedHouseBill = houseBill1.PK;
			invoice1.US_SplitShipmentDetail = invoice1.AddInfoLookups.SplitShipmentDetailsList[0].Code;
			AssertNotEquals(ZString.Empty, invoice1.US_SplitShipmentDetail);
			invoice2.JZ_CU_RelatedHouseBill = houseBill2.PK;
			invoice2.US_SplitShipmentDetail = invoice2.AddInfoLookups.SplitShipmentDetailsList[0].Code;
			AssertNotEquals(ZString.Empty, invoice1.US_SplitShipmentDetail);

			declaration.JE_TransportMode = TransportTypeList.Codes.Sea;
			AssertEquals(ZString.Empty, invoice1.US_SplitShipmentDetail);
			AssertEquals(ZString.Empty, invoice2.US_SplitShipmentDetail);

			declaration.JE_TransportMode = TransportTypeList.Codes.Air;
			houseBill1.US_SESplitShip = true;
			billSplitDetail1 = houseBill1.ITAndSplitDetails.AddNew();
			billSplitDetail1.US_ArrivalDate = new ZDateTime(2021, 04, 28);
			billSplitDetail1.US_CarrierCode = "A2";
			billSplitDetail1.US_FlightNumber = "04A";
			houseBill2.US_SESplitShip = true;
			billSplitDetail2 = houseBill2.ITAndSplitDetails.AddNew();
			billSplitDetail2.US_ArrivalDate = new ZDateTime(2021, 04, 29);
			billSplitDetail2.US_CarrierCode = "A3";
			billSplitDetail2.US_FlightNumber = "05B";
			invoice1.JZ_CU_RelatedHouseBill = houseBill1.PK;
			invoice1.US_SplitShipmentDetail = invoice1.AddInfoLookups.SplitShipmentDetailsList[0].Code;
			AssertNotEquals(ZString.Empty, invoice1.US_SplitShipmentDetail);
			invoice2.JZ_CU_RelatedHouseBill = houseBill2.PK;
			invoice2.US_SplitShipmentDetail = invoice2.AddInfoLookups.SplitShipmentDetailsList[0].Code;
			AssertNotEquals(ZString.Empty, invoice1.US_SplitShipmentDetail);

			declaration.US_F_AdmissionType = FTZAdmissionTypeCodeList.Codes.Domestic;
			AssertEquals(ZString.Empty, invoice1.US_SplitShipmentDetail);
			AssertEquals(ZString.Empty, invoice2.US_SplitShipmentDetail);
		}

		public void TestFTZIsPTTCleared()
		{
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.FTZ;

			var permitToTransferMessage = Factory.New<MQEDIMessage>();
			permitToTransferMessage.EM_ApplicationCode = EDIMessage.ApplicationCodes.USCustomsImport;
			permitToTransferMessage.EM_MessageType = ACEApplicationIdentifierCodeList.Codes.ForeignTradeZone;
			permitToTransferMessage.EM_MessageSubType = EM_MessageSubTypeList.Codes.FTZPermitToTransfer;
			permitToTransferMessage.EM_ReceiveTransmit = EDIMessage.Direction.Receive;
			permitToTransferMessage.EM_Status = EDIMessage.Status.Received;
			permitToTransferMessage.EM_SystemCreateTimeUtc = new ZDateTime(2021, 10, 01);
			permitToTransferMessage.EM_MessageText = "B001101SV9NF                                               HYEDUSCMT_342907     90A2050006  21FF0001752704N                                                     91B6 2  08157824211SHAE21100063            2110141922    WA84                   9502116PTT MESSAGE DATA ACCEPTED                                                Y  1101SV9NF00000";
			declaration.Messages.Add(permitToTransferMessage);
			AssertEquals(true, declaration.IsPTTCleared);

			var cancelUnauthorizedMessage = Factory.New<MQEDIMessage>();
			cancelUnauthorizedMessage.EM_ApplicationCode = EDIMessage.ApplicationCodes.USCustomsImport;
			cancelUnauthorizedMessage.EM_MessageType = ACEApplicationIdentifierCodeList.Codes.ForeignTradeZone;
			cancelUnauthorizedMessage.EM_MessageSubType = EM_MessageSubTypeList.Codes.FTZCancelPermitToTransfer;
			cancelUnauthorizedMessage.EM_ReceiveTransmit = EDIMessage.Direction.Receive;
			cancelUnauthorizedMessage.EM_Status = EDIMessage.Status.Received;
			cancelUnauthorizedMessage.EM_SystemCreateTimeUtc = new ZDateTime(2021, 10, 10);
			cancelUnauthorizedMessage.EM_MessageText = "B001101SV9NF                                               HYEDUSCMT_342898     90A2050006  21FF0001752704N                                                     91B6 2  08157824211SHAE21100063            2110141922    WA84                   9501215CANCEL PTT NOT AUTHORIZED                                                Y  1101SV9NF00000";
			declaration.Messages.Add(cancelUnauthorizedMessage);
			AssertEquals(true, declaration.IsPTTCleared);

			var cancelAcceptedMessage = Factory.New<MQEDIMessage>();
			cancelAcceptedMessage.EM_ApplicationCode = EDIMessage.ApplicationCodes.USCustomsImport;
			cancelAcceptedMessage.EM_MessageType = ACEApplicationIdentifierCodeList.Codes.ForeignTradeZone;
			cancelAcceptedMessage.EM_MessageSubType = EM_MessageSubTypeList.Codes.FTZCancelPermitToTransfer;
			cancelAcceptedMessage.EM_ReceiveTransmit = EDIMessage.Direction.Receive;
			cancelAcceptedMessage.EM_Status = EDIMessage.Status.Received;
			cancelAcceptedMessage.EM_SystemCreateTimeUtc = new ZDateTime(2021, 10, 20);
			cancelAcceptedMessage.EM_MessageText = "B001101SV9NF                                               HYEDUSCMT_342898     90A2050006  21FF0001752704N                                                     91B6 2  08157824211SHAE21100063            2110141922    WA84                   9502224CANCEL PTT DATA ACCEPTED                                                 Y  1101SV9NF00000";
			declaration.Messages.Add(cancelAcceptedMessage);
			AssertEquals(false, declaration.IsPTTCleared);
		}

