		public void AssertDocumentaryAddressRequiredForWarehouseValidation(string properityName)
		{
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			declaration.JE_ApplicationCode = JobApplicationCodeList.Codes.ACS;
			declaration.US_EnableENS = false;
			declaration.US_EnableCRL = false;

			Action<string, string, bool> assertGetter = (message, name, value) =>
			{
				var result = (bool)declaration.GetType()
						.GetProperty(name, BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance)
						.GetValue(declaration, null);
				AssertEquals(message, value, result);
			};

			CombineAssertions(() =>
			{
				assertGetter("IsEntrySummaryValidationMode IsFTZAdmissionValidationMode false", properityName, false);
				declaration.US_EnableENS = true;
				assertGetter("IsEntrySummaryValidationMode true", properityName, true);
				declaration.US_EnableENS = false;
				declaration.JE_MessageType = JobMessageTypeList.Codes.FTZ;
				assertGetter("IsFTZAdmissionValidationMode true", properityName, true);
			});
		}

