			Assert("[PreCondition]: IsMessageTypeChangeAnError should be false", !declaration.IsMessageTypeChangeAnError);

			declaration.JE_MessageType = JobMessageTypeList.Codes.FTZ;
			var addOn = Factory.NewWithValidTestData<GenAddOnColumn>();
			addOn.XA_ParentID = declaration.PK;
			addOn.XA_ParentTableCode = JobDeclarationSchema.Constants.Prefix;
			addOn.XA_Name = "US_FTZAdmissionStatus";
			addOn.XA_Type = AddOnColumnDataType.Codes.String;
			addOn.XA_Data = FTZMessageStatusList.Codes.AwaitingFTZAdmissionAdd;
			Factory.Save();

			Assert("IsMessageTypeChangeAnError should be true", declaration.IsMessageTypeChangeAnError);

			declaration = Factory.NewWithValidTestData<JobDeclaration>();
			CusEntryHeader entry = declaration.CustomsEntryHeaders.AddNew();
			entry.CH_MessageType = CusEntryHeaderMessageTypeList.Codes.EntrySummary;

			Assert("[PreCondition]: IsMessageTypeChangeAnError should be false", !declaration.IsMessageTypeChangeAnError);

			declaration.MergeManager.DisablePreSaveMergeRequirementForTesting();
			Factory.Save();

			entry.CH_Status = ImportMessageStatusList.Codes.AwaitingEntrySummaryDelete;
			Factory.Save();

			Assert("IsMessageTypeChangeAnError should be true", declaration.IsMessageTypeChangeAnError);
		}

