		void SetDocAddressForTest(JobDeclaration declaration, string type)
		{
			var orgHeader = Factory.New<OrgHeader>();
			orgHeader.OH_Code = "TESTOH01";

			var orgAddress = Factory.New<OrgAddress>();
			orgAddress.OA_OH = orgHeader.PK;

			var orgCusCode = Factory.New<OrgCusCode>();
			orgCusCode.OK_CodeType = OrgCusCode.USACodeTypes.FIRMSCode;
			orgCusCode.OK_CustomsRegNo = "DCBA";
			orgCusCode.OK_OH = orgHeader.PK;
			orgCusCode.OK_OA_PremisesAddress = orgAddress.PK;
			orgCusCode.OK_RN_NKCodeCountry = Core.Constants.CountryCodes.UnitedStates;

			switch (type)
			{
				case AddressTypes.CTOAddress:
					declaration.ContainerTerminalOperatorDocAddress.E2_OA_Address = orgAddress.PK;
					break;
				case AddressTypes.DepotAddress:
					declaration.DepotDocAddress.E2_OA_Address = orgAddress.PK;
					break;
				case AddressTypes.ContainerYardAddress:
					declaration.ContainerYardDocAddress.E2_OA_Address = orgAddress.PK;
					break;
				default:
					break;
			}
		}

