		public void TestReCalculateENSAction()
		{
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
			var entry = declaration.CustomsEntryHeaders.AddNew();
			entry.CH_MessageType = CusEntryHeaderMessageTypeList.Codes.EntrySummary;
			declaration.ReCalculateENSAction();
			AssertEquals(ZString.Empty, declaration.US_ENSAction);

			var message = Factory.New<MQEDIMessage>();
			message.EM_ApplicationCode = EDIMessage.ApplicationCodes.USCustomsImport;
			message.EM_MessageType = ACEApplicationIdentifierCodeList.Codes.EntrySummaryResponse;
			entry.Messages.Add(message);
			declaration.ReCalculateENSAction();
			AssertEquals(ZString.Empty, declaration.US_ENSAction);

			message = Factory.New<MQEDIMessage>();
			message.EM_ApplicationCode = EDIMessage.ApplicationCodes.USCustomsImport;
			message.EM_ApplicationReference = "Q:";
			message.EM_MessageType = ACEApplicationIdentifierCodeList.Codes.EntrySummaryNotification;
			entry.Messages.Add(message);
			declaration.ReCalculateENSAction();
			AssertEquals(JobDeclaration.Constants.Complete, declaration.US_ENSAction);

			message = Factory.New<MQEDIMessage>();
			message.EM_ApplicationCode = EDIMessage.ApplicationCodes.USCustomsImport;
			message.EM_ApplicationReference = "4:ACTION REQUIRED";
			message.EM_MessageType = ACEApplicationIdentifierCodeList.Codes.EntrySummaryNotification;
			entry.Messages.Add(message);
			declaration.ReCalculateENSAction();
			AssertEquals(JobDeclaration.Constants.Incomplete, declaration.US_ENSAction);

			message.Logs.AddNew(Events.Authorised, "Blah");
			declaration.ReCalculateENSAction();
			AssertEquals(JobDeclaration.Constants.Complete, declaration.US_ENSAction);

			declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Recon;
			entry = declaration.CustomsEntryHeaders.AddNew();
			entry.CH_MessageType = CusEntryHeaderMessageTypeList.Codes.ReconEntry;
			declaration.ReCalculateENSAction();
			AssertEquals(ZString.Empty, declaration.US_ENSAction);

			message = Factory.New<MQEDIMessage>();
			message.EM_ApplicationCode = EDIMessage.ApplicationCodes.USCustomsImport;
			message.EM_MessageType = ACEApplicationIdentifierCodeList.Codes.EntrySummaryResponse;
			entry.Messages.Add(message);
			declaration.ReCalculateENSAction();
			AssertEquals(ZString.Empty, declaration.US_ENSAction);

			message = Factory.New<MQEDIMessage>();
			message.EM_ApplicationCode = EDIMessage.ApplicationCodes.USCustomsImport;
			message.EM_ApplicationReference = "Q:";
			message.EM_MessageType = ACEApplicationIdentifierCodeList.Codes.EntrySummaryNotification;
			entry.Messages.Add(message);
			declaration.ReCalculateENSAction();
			AssertEquals(JobDeclaration.Constants.Complete, declaration.US_ENSAction);

			message = Factory.New<MQEDIMessage>();
			message.EM_ApplicationCode = EDIMessage.ApplicationCodes.USCustomsImport;
			message.EM_ApplicationReference = "4:ACTION REQUIRED";
			message.EM_MessageType = ACEApplicationIdentifierCodeList.Codes.EntrySummaryNotification;
			entry.Messages.Add(message);
			declaration.ReCalculateENSAction();
			AssertEquals(JobDeclaration.Constants.Incomplete, declaration.US_ENSAction);

			message.Logs.AddNew(Events.Authorised, "Blah");
			declaration.ReCalculateENSAction();
			AssertEquals(JobDeclaration.Constants.Complete, declaration.US_ENSAction);

			declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Drawback;
			declaration.ReCalculateENSAction();
			AssertEquals(ZString.Empty, declaration.US_ENSAction);

			message = Factory.New<MQEDIMessage>();
			message.EM_ApplicationCode = EDIMessage.ApplicationCodes.USCustomsImport;
			message.EM_MessageType = ACEApplicationIdentifierCodeList.Codes.EntrySummaryResponse;
			entry.Messages.Add(message);
			declaration.ReCalculateENSAction();
			AssertEquals(ZString.Empty, declaration.US_ENSAction);

			message = Factory.New<MQEDIMessage>();
			message.EM_ApplicationCode = EDIMessage.ApplicationCodes.USCustomsImport;
			message.EM_ApplicationReference = "Q:";
			message.EM_MessageType = ACEApplicationIdentifierCodeList.Codes.EntrySummaryNotification;
			declaration.Messages.Add(message);
			declaration.ReCalculateENSAction();
			AssertEquals(JobDeclaration.Constants.Complete, declaration.US_ENSAction);

			message = Factory.New<MQEDIMessage>();
			message.EM_ApplicationCode = EDIMessage.ApplicationCodes.USCustomsImport;
			message.EM_ApplicationReference = "4:ACTION REQUIRED";
			message.EM_MessageType = ACEApplicationIdentifierCodeList.Codes.EntrySummaryNotification;
			declaration.Messages.Add(message);
			declaration.ReCalculateENSAction();
			AssertEquals(JobDeclaration.Constants.Incomplete, declaration.US_ENSAction);

			message.Logs.AddNew(Events.Authorised, "Blah");
			declaration.ReCalculateENSAction();
			AssertEquals(JobDeclaration.Constants.Complete, declaration.US_ENSAction);
		}

		public void TestReCalculateCRLAction()
		{
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;
