			message.EM_ApplicationReference = ReferenceIdentifierQualifierCodeList.Codes.CMT;
			message.EM_MessageType = ACEApplicationIdentifierCodeList.Codes.CargoReleaseResponse;
			entry.Messages.Add(message);
			declaration.ReCalculateENSAction();
			AssertEquals(ZString.Empty, declaration.US_ENSAction);

			message = Factory.New<MQEDIMessage>();
			message.EM_ApplicationCode = EDIMessage.ApplicationCodes.USCustomsImport;
			message.EM_ApplicationReference = ReferenceIdentifierQualifierCodeList.Codes.CMT;
			message.EM_MessageType = ACEApplicationIdentifierCodeList.Codes.CargoReleaseStatus;
			entry.Messages.Add(message);
