			AssertEquals(JobDeclaration.Constants.Incomplete, declaration.US_CRLAction);

			message.Logs.AddNew(Events.Authorised, "Blah");
			declaration.ReCalculateCRLAction();
			AssertEquals(JobDeclaration.Constants.Complete, declaration.US_CRLAction);
		}

		public void TestAESDispositions()
		{
			MockCusCodes(Core.Constants.Customs.Universal.RefCusCodeListTypes.Codes.AESSeverityIndicator, "W", "X", "Y", "Z");
			MockCusCodes(Core.Constants.Customs.Universal.RefCusCodeListTypes.Codes.AESResponseCode, "11A", "12A", "11B", "12B");

			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Export;
			AssertEquals(ZString.Empty, declaration.AESResponseCode);
			AssertEquals(ZString.Empty, declaration.AESResponseCodeDescription);
			AssertEquals(ZString.Empty, declaration.AESSeverity);
			AssertEquals(ZString.Empty, declaration.AESSeverityDescription);

			declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Export;
			var entry1 = declaration.ActiveEntryHeaders.AddNew();
			entry1.CH_MessageType = declaration.JE_MessageType;
			entry1.EntryNumber = "S40002511";
			var entry2 = declaration.ActiveEntryHeaders.AddNew();
			entry2.CH_MessageType = declaration.JE_MessageType;
			entry2.EntryNumber = "S40002512";
			Factory.Save();
			AssertEquals(ZString.Empty, declaration.AESResponseCode);
			AssertEquals(ZString.Empty, declaration.AESResponseCodeDescription);
			AssertEquals(ZString.Empty, declaration.AESSeverity);
			AssertEquals(ZString.Empty, declaration.AESSeverityDescription);

			declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Export;
			entry1 = declaration.ActiveEntryHeaders.AddNew();
			entry1.CH_MessageType = declaration.JE_MessageType;
			entry1.EntryNumber = "S40002511";
			entry2 = declaration.ActiveEntryHeaders.AddNew();
			entry2.CH_MessageType = declaration.JE_MessageType;
			entry2.EntryNumber = "S40002512";
			var cusDispositions1 = entry1.AESCusDispositions;
			AddCusDisposition(cusDispositions1, "11A", "W", new ZDateTime(2000, 1, 1));
			AddCusDisposition(cusDispositions1, "12A", "X", new ZDateTime(2000, 1, 2));
			Factory.Save();
			AssertEquals("12A", declaration.AESResponseCode);
			AssertEquals("12A", declaration.AESResponseCodeDescription);
			AssertEquals("X", declaration.AESSeverity);
			AssertEquals("X", declaration.AESSeverityDescription);

			declaration = Factory.New<JobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Export;
			entry1 = declaration.ActiveEntryHeaders.AddNew();
			entry1.CH_MessageType = declaration.JE_MessageType;
			entry1.EntryNumber = "S40002511";
			entry2 = declaration.ActiveEntryHeaders.AddNew();
			entry2.CH_MessageType = declaration.JE_MessageType;
			entry2.EntryNumber = "S40002512";
			cusDispositions1 = entry1.AESCusDispositions;
			AddCusDisposition(cusDispositions1, "11A", "W", new ZDateTime(2000, 1, 1));
			AddCusDisposition(cusDispositions1, "12A", "X", new ZDateTime(2000, 1, 2));
			var cusDispositions2 = entry2.AESCusDispositions;
			AddCusDisposition(cusDispositions2, "11B", "Y", new ZDateTime(2000, 2, 1));
			AddCusDisposition(cusDispositions2, "12B", "Z", new ZDateTime(2000, 2, 2));
			Factory.Save();
			AssertEquals("12A, 12B", declaration.AESResponseCode);
			AssertEquals(AES.AESConstants.Multiple, declaration.AESResponseCodeDescription);
			AssertEquals("X, Z", declaration.AESSeverity);
			AssertEquals(AES.AESConstants.Multiple, declaration.AESSeverityDescription);
		}

		public void TestIsMasterBillSCACRequired()
		{
			var declaration = Factory.New<JobDeclaration>();
			declaration.JE_TransportMode = TransportTypeList.Codes.Sea;
			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFTZ;
			AssertEquals(true, declaration.IsMasterBillSCACRequired);

			declaration.US_EntryType = EntryTypeList.Codes.ReWarehouse;
			AssertEquals(false, declaration.IsMasterBillSCACRequired);

			declaration.US_EntryType = EntryTypeList.Codes.ConsumptionFTZ;
			declaration.JE_TransportMode = TransportTypeList.Codes.Road;
			AssertEquals(false, declaration.IsMasterBillSCACRequired);
		}

		public void TestAddUSLowValueTransferedLog()
		{
			var lowValueReference = "USLV001";
			var jobDeclaration = Factory.New<JobDeclaration>();
			jobDeclaration.AddUSLowValueTransferredLog(lowValueReference);
 
			var transferedLog = jobDeclaration.Logs.MostRecentLogByEventTime(AutoEvents.Transferred);

			CombineAssertions(() =>
			{
				AssertNotNull("Transferred Log should be added", transferedLog);
				AssertEquals("Expected Log Type", "USLV", transferedLog.Parameters[EventReferenceParameters.Codes.Type]);
				AssertEquals("Expected Job Number", lowValueReference, transferedLog.Parameters[EventReferenceParameters.Codes.JobNumber]);
			});
		}

		public void TestIsCreatedFromUSLowValue_WhenHasNoLog_ShouldReturnFalse()
		{
			var jobDeclaration = Factory.New<JobDeclaration>();
			Assert(!jobDeclaration.IsCreatedFromUSLowValue);
		}

		public void TestIsCreatedFromUSLowValue_WhenHasNoTransferredLogWithUSLVType_ShouldReturnFalse()
		{
			var jobDeclaration = Factory.New<JobDeclaration>();

			jobDeclaration.Logs.AddNew(AutoEvents.RequestCreated,
			[
				new KeyValuePair<string, string>(EventReferenceParameters.Codes.Type, "USLV"),
				new KeyValuePair<string, string>(EventReferenceParameters.Codes.JobNumber, "LV001")
			]);

			jobDeclaration.Logs.AddNew(AutoEvents.Transferred,
			[
				new KeyValuePair<string, string>(EventReferenceParameters.Codes.Mode, "USLV"),
				new KeyValuePair<string, string>(EventReferenceParameters.Codes.JobNumber, "LV001"),
			]);

			jobDeclaration.Logs.AddNew(AutoEvents.Transferred,
			[
				new KeyValuePair<string, string>(EventReferenceParameters.Codes.JobNumber, "LV001"),
				new KeyValuePair<string, string>(EventReferenceParameters.Codes.Type, "OTH")
			]);

			Assert(!jobDeclaration.IsCreatedFromUSLowValue);
		}

		public void TestIsCreatedFromUSLowValue_WhenHasTransferedLogWithUSLVType_ShouldReturnTrue()
		{
			var jobDeclaration = Factory.New<JobDeclaration>();

			jobDeclaration.Logs.AddNew(AutoEvents.Transferred,
			[
				new KeyValuePair<string, string>(EventReferenceParameters.Codes.JobNumber, "LV001"),
				new KeyValuePair<string, string>(EventReferenceParameters.Codes.Type, "USLV")
			]);

			Assert(jobDeclaration.IsCreatedFromUSLowValue);
		}

