		void MockCusCodes(ZString cusCodeType, params ZString[] codes)
		{
			var newFactory = new BusinessObjectFactory();
			var cusCodeHelper = new UniversalReferenceTestDataHelper(newFactory);
			cusCodeHelper.CreateNewOrGetExistingCusCodeType(cusCodeType, cusCodeType);

			foreach (var code in codes)
			{
				cusCodeHelper.CreateNewOrGetExistingCusCodeList(Core.Constants.CountryCodes.UnitedStates, cusCodeType,
					code, code, ZDateTime.Today.AddYears(-1), ZDateTime.Today.AddYears(1));
			}

			newFactory.Save();
		}

		void AddCusDisposition(CusDispositionCollection cusDispositions, ZString status, ZString statusKey,
			ZDateTime systemCreateTimeUtc)
		{
			var disposition = cusDispositions.AddNew();
			disposition.CDI_Status = status;
			disposition.CDI_StatusDate = ZDateTime.Today;
			disposition.CDI_StatusKey = statusKey;
			disposition.CDI_Sequence = (short)cusDispositions.Count;
			disposition.CDI_SystemCreateTimeUtc = systemCreateTimeUtc;
		}

